class Main {
  import java.io._
  import java.util.StringTokenizer

  import scala.collection.mutable
  import scala.util.Sorting
  import math.{abs, max, min}
  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N, K = ni()
    val A = na(N)

    // iの部分は左右どっちにも１個空いてる
    // kは左に１こあけたかったけど、数値を表現してるときに+1するとむずかしくなるので使うところで工夫する
    val R = Array.ofDim[Int](N + 2, K + 1)
    R(N + 1)(0) = 1
    REP_r(N) { i =>
      REP(K + 1) { k =>
        R(i + 1)(k) |= R(i + 2)(k)
        if (k - A(i) >= 0) R(i + 1)(k) |= R(i + 2)(k - A(i))
      }
    }

//    REP(N + 2) { i =>
//      debug(R(i))
//    }

    REP(N + 2) { i =>
      REP(K) { k =>
        R(i)(k + 1) += R(i)(k)
      }
    }

//    debug("print cum")
//    REP(N + 2) { i =>
//      debug(R(i))
//    }

    // intだとRと合わせて4 * 25 * 10^6 * 2 でやばい
    val L= Array.ofDim[Boolean](N + 2, K + 1)
    L(0)(0) = true

    var ans = 0
    REP(N) { i =>
      var need = false
      REP(K) { k =>
        // １個前
        if (L(i)(k)) {
          // R = [low, up)
          val up = K - k
          val low = K - (A(i) + k)
//          debug(s"i:$i k:$k [$low $up)")
          val cnt = R(i + 2)(up - 1) - (if (low - 1 >= 0) R(i + 2)(low - 1) else 0)
          if (cnt > 0) need = true
        }

        L(i + 1)(k) |= L(i)(k)
        if (k - A(i) >= 0) L(i + 1)(k) |= L(i)(k - A(i))
      }

      if (!need) ans += 1
    }

//    debug("print L")
//    REP(N + 2) { i =>
//      debug(L(i))
//    }

    out.println(ans)
  }


