int n, ar[1000001], k, u[1000001];

int main()
{
    cin >> n >> k;
    for(int i = 1; i <= n; i++)
    {
        scanf("%d", &ar[i]);
        ar[i] = min(ar[i], k);
    }


    for(int i = 1; i <= n; i++)
    {
        int r = 1, sum = 0;
        for(int j = 1; j <= n; j++)
        {
            while(r <= n && sum < k)
            {
                sum += ar[r];
                r++;
            }
            if(r == n + 1 && sum < k)
                break;

            if(i >= j && j < r)
            {
                if(sum - ar[i] < k)
                    u[i] = 1;
            }
            //cout << j << " " << r << endl;
            sum -= ar[j];
        }
    }

    int ans = 0;
    for(int i = 1; i <= n; i++)
        if(u[i] == 0)
            ans += 1;

    cout << ans;
    return 0;
}

