	l = -1;
	r = N;
	while(r - l > 1){
		m = (r+l)/2;
		is_necessary = 0;
		if(A[m] >= K){
			is_necessary = 1;
		}else{
			int dp[N][K];
			for (int i = 0; i < N; ++i){
				for (int j = 0; j < K; ++j){
					if (j == 0){
						dp[i][j] = 1;
					}else{
						dp[i][j] = 0;
					}
				}
			}

			for (int i = 0; i < N; ++i){
				if(i == 0){
					if(m != 0 && A[0] < K){
						dp[0][A[0]] = 1;
					}
				}else if(i == m){
					for (int j = 0; j < K; ++j){
						dp[i][j] = dp[i-1][j];
					}
				}else if(A[i] >= K){
					break;
				}else{
					a = A[i];
					for (int j = 0; j < K; ++j){
						if(dp[i-1][j] == 1 && j + a < K){
							dp[i][j+a] = 1;
							if(j + a >= K - A[m]){
								is_necessary = 1;
							}
						}
						if(dp[i][j] == 0){
							dp[i][j] = dp[i-1][j];
						}
