class FFT {
	static void fft(vector<com>& vec, int inv) {
		int s = vec.size();
		if (s == 1) return;
		vector<com> veca, vecb;
		for (int i = 0; i < s / 2; i++) {
			veca.pb(vec[2 * i]);
			vecb.pb(vec[2 * i + 1]);
		}
		fft(veca, inv);
		fft(vecb, inv);
		com x = 1;
		com z = polar(1.0, 2 * inv * PI / s);
		int t = s / 2 - 1;
		for (int i = 0; i < s; i++) {
			vec[i] = veca[i&t] + x * vecb[i&t];
			x *= z;
		}
	}
public:
	template<class T>
	static vector<int> multiply(vector<T> f, vector<T> g) {
		int s = 1;
		while (s < f.size() + g.size()) {
			s *= 2;
		}
		f.resize(s); g.resize(s);
		fft(f, 1); fft(g, 1);
		for (int i = 0; i < s; i++) f[i] *= g[i];
		fft(f, -1);
		vector<int> res;
		for (int i = 0; i < s; i++) {
			double d = f[i].real() / s;
			res.pb((int)(d + 0.5));
		}
		return res;
	}
};

