int is_unnecessary(int i)
{
    vector<int> L; L.reserve(k);
    vector<int> R; R.reserve(k);
    for(int s = 0; s < k; s++)
    {
        if(formableL[i-1][s])
            L.push_back(s);
        if(formableR[i+1][s])
            R.push_back(s);
