        //find the smallest ri such that K-a[i] <= L[li]+R[ri]
        if(k-a[i] <= L[li]+R.back())
            for(; ri > 0; ri--)
                if(k-a[i] <= L[li]+R[ri] && !(k-a[i] <= L[li]+R[ri-1]))
                    break;

        if(k-a[i] <= L[li]+R[ri] && L[li]+R[ri] < k)
            return 0;
        //cout<<L[li]<<"+"<<R[ri]<<endl;
    }
    return 1;
}
