            else rdp[i][j]|=rdp[i-1][j];
    }
    rep(i,n)rep(j,k){
        if (j==0) rsum[i][j]=rdp[i][j];
        else rsum[i][j]=rsum[i][j-1]+rdp[i][j];
    }
    int cnt=0;
    int lnum=0;
    rep(i,n){
        if (k-a[i]<=0){
            cnt+=1;
            continue;
        }
        rep(j,k){
            if (i==0) lnum=0;
            else if (i==n-1){
                if (ldp[i-1][j] && a[i]+j>=k){
                    cnt+=1;
                    break;
                }
                continue;
            }
            else{
                if (ldp[i-1][j]) lnum=j;
                else continue;
            }
            if (k-a[i]-lnum<=0){
                cnt+=1;
                break;
            }
            if (rsum[n-2-i][k-1-lnum]-rsum[n-2-i][k-a[i]-lnum-1]){
                cnt+=1;
                break;
            }
        }
    }
    cout << n-cnt << endl;
}

