bool judge(const V<ll> &alist, ll n, ll k, ll idx)
{
    bitset<5005> bs;
    bs.set(0);

    rep (i, n) {
        if (i == idx) continue;
        ll a = alist[i];
        bitset<5005> bs_orig = bs;
        bs <<= a;
        bs |= bs_orig;
    }

    srep (i, k-alist[idx], k) {
        if (bs.test(i)) return false;
    }

    return true;
}

