    S V<ll> alist; llina(alist, n);

    alist.pb(0LL);
    n++;
    sort(alist);

    ll left = 0LL;
    ll right = n-1LL;
    ll now = (left + right) / 2LL;
    ll ans = 0LL;

    for ( ; left <= right; now = (left + right) / 2LL) {
        if (judge(alist, n, k, now)) {
            ans = max(ans, now);
            left = now + 1LL;
        }
        else {
            right = now - 1LL;
        }
    }

    cout << ans << endl;
}

