int N, K;
int A[5001];
int Asum[5002];

void insertionSort(int g) {
	for (int i = g; i < N; i++) {
		int v = A[i];
		int j = i - g;

		while (j >= 0 && A[j] > v) {
			A[j + g] = A[j];
			j -= g;
		}
		A[j + g] = v;
	}
}

void shellSort() {
	vector<int>G;
	for (int h = 1;;) {
		if (h > N)break;
		G.push_back(h);
		h = 3 * h + 1;
	}

	for (int i = G.size() - 1; i >= 0; i--) {
		insertionSort(G[i]);
	}
}

int BinarySearch(int max, int right) {
	int l = 0, r = right;
	int m;
	while (l < r) {
		m = (l + r) / 2;

		if (Asum[right] - Asum[m] < max)r = m;
		else l = m + 1;
	}

	if (r == 0)return right;
	else if (r == right) {
		l = 0, r = right;
		while (l < r) {
			m = (l + r) / 2;

			if (A[m] < max)l = m + 1;
			else r = m;
		}

		return BinarySearch(max, r);
	}
	else return BinarySearch(max - (Asum[right] - Asum[r]), r);
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
	}
	shellSort();

	for(int i=0;i<N;i++)Asum[i + 1] = Asum[i] + A[i];

	cout << BinarySearch(K, N) << endl;

    return 0;
}

