int l, r, n, s, k;
bool calc(int idx, int sum) {
	if (sum >= l && sum <= r)
		return true;
	if (idx == n)
		return false;
	bool &ret = dp[idx][sum];
	if (vis[idx][sum] == VIS)
		return ret;
	vis[idx][sum] = VIS;
	ret = calc(idx + 1, sum);
	if (idx != s && sum + arr[idx] <= r)
		ret = ret || calc(idx + 1, sum + arr[idx]);
	return ret;
}
bool can(int idx) {
	++VIS;
	s = idx;
	l = k - arr[idx];
	return !calc(0, 0);
}
