int needs(int index) {
	int i, j;

	// 最初と飛ばすの行のみ初期化
	for (j = 0; j < K; j++) {
		dp[0][j] = 0;
		dp[index][j] = 0;	
	}
	if (index != 0) dp[0][a[0]] = 1;
	dp[0][0] = 1;

	for (i = 1; i < N; i++) {
		for (j = 0; j < K; j++) {
			dp[i][j] = dp[i - 1][j];
			if (i != index && j - a[i] >= 0)
				dp[i][j] |= dp[i - 1][j - a[i]];
		}
	}

	for (j = K - a[index]; j < K; j++) {
		if (dp[N - 1][j] == 1)
			return 1;
	}
	return 0;
}

