        for (int j = k - val - 1; j >= 0; -- j) {
            if (pref[i - 1][j] - (j ? pref[i - 1][j - 1] : 0)) {
                pref[i][j + val] = 1;
            }
        }
        for (int j = 0; j < k; ++ j) {
            if (pref[i - 1][j] - (j ? pref[i - 1][j - 1] : 0)) {
                pref[i][j] = 1;
            }
            if (j) {
                pref[i][j] += pref[i][j - 1];
            }
        }
    }
    for (int i = 0; i < k; ++ i) {
        suf[n + 1][i] = 1;
    }
    for (int i = n; i >= 1; -- i) {
        int val = v[i - 1];
