#include <bits/stdc++.h>
using namespace std;
const int N=100005;
int a[N];
bitset<N> sum;
int n,k;
bool judge(int mid)
{
	if(a[mid]>=k) return  1;
	sum.reset();sum[0]=1;
	for(int i=1;i<=n;i++)
	{
		if(i!=mid)
			sum|=(sum<<a[i]);//求a[i]的前缀和sum1，即把sum的前sum1位均赋值1
	}
	for(int i=k-a[mid];i<=k-1;i++)
	{
		 if(sum[i]) return 1;
	}
	return 0;

}
int main()
{

	scanf("%d%d",&n,&k);
	for(int i=1;i<=n;i++)
		scanf("%d",&a[i]);
	sort(a+1,a+n+1);
	int l=1,r=n+1;
	while(l<r)
	{
		int mid=(l+r)>>1;
		if(judge(mid))
			r=mid;
		else
			l=mid+1;
	}
	cout<<l-1<<endl;
    return 0;
}

