    for (int j=1;j<=n;++j)
    {
        int x;
        cin>>x;
        if (x>=goo) continue;
        ++a[x];
    }
    VPII v;
    int sum=0;
    for (int j=1;j<=goo;++j)
    {
        if (a[j])
        {
            for (int k=1;k<=a[j];++k)
                v.PB(MP(j,1));
        }
        sum+=j*a[j];
    }
    sort(v.begin(),v.end());
    int have=0;
    int ans=0;
    dp[0]=1;
    for (int j=v.size()-1;j>=0;--j)
    {
        have+=v[j].X;
        int last=sum-have;
        bool flag=0;
        if (last+v[j].X>=goo) flag=1;
        for (int k=goo-v[j].X;k<goo;++k)
            if (dp[k]) flag=1;
        for (int k=1;k<=goo;++k)
        {
            if (dp[k]==0) continue;
            int la=goo-k;
            if (v[j].X<la&&v[j].X+last>=la) flag=1;
        }
        if (!flag) ans+=v[j].Y;
        for (int k=1;k<=v[j].Y;++k)
        {
            for (int l=goo-1;l>=v[j].X;--l)
                if (dp[l-v[j].X]) dp[l]=1;
        }
        have+=v[j].X*(v[j].Y-1);
    }
    cout<<ans<<endl;
    return 0;
}

