#include <bits/stdc++.h>

using namespace std;

#define ll long long
#define up(i,j,n)		for (int i = j; i <= n; i++)
#define down(i,j,n)	for (int i = j; i >= n; i--)
#define cmax(a,b)		a = max (a, b)
#define cmin(a,b)		a = min (a, b)

const int MAXN = 5005;
const int oo = 0x3f3f3f3f;

int N, K, a[MAXN], num[MAXN], top = 0, ans = 0;
bitset<MAXN> F;

bool vaild(int o){
	bool ok = 1;
	F.reset();
	F[0] = 1;
	up (i, 1, N) {
		if (a[i] == num[o] && ok) {
			ok = 0;
			continue;
		}
		F |= F << a[i];
	}
	up (i, K - num[o], K - 1) if (F[i]) return 1;
	return 0;
}

int main(){
	scanf("%d%d", &N, &K);
	up (i, 1, N) scanf("%d", &a[i]);
	up (i, 1, N) if (a[i] < K) num[++top] = a[i];
	if (!top) {
		puts("0");
		return 0;
	}
	N = top;
	up (i, 1, N) a[i] = num[i];
	sort(num + 1, num + top + 1);
	top = unique(num + 1, num + top + 1) - (num + 1);
	num[top + 1] = oo;
	int le = 1, ri = top, mi;
	while (le + 1 < ri) {
		mi = (le + ri) >> 1;
		if (vaild(mi)) 	ri = mi;
		else 			le = mi;
	}
	int o = top + 1;
	if (vaild(le)) o = le;
	else if (vaild(ri)) o = ri;
	up (i, 1, N) if (a[i] < num[o]) ans++;
	printf("%d\n", ans);
	return 0;
}

