using namespace std;
typedef long long ll;
const int N = 5e3 + 5;
bool f[N][N], g[N][N];
int a[N];
int main()
{
  int n, k;
  cin >> n >> k;
  for (int i = 1; i <= n; ++i)
   scanf("%d", &a[i]);
  sort(a + 1, a + n + 1);
  int ans = n;
  for (int i = 1; i <= n; ++i)
  {
    if (a[i] >= k)
    {
      n = i - 1;
      ans = n;
      break;
    }
  } 

  for (int i = 0; i <= n + 1; ++i)
    f[i][0] = g[i][0] = true;

  for (int j = 1; j < k; ++j)
  {
    for (int i = 1; i <= n; ++i)
    {
      f[i][j] = f[i - 1][j];
      if (j >= a[i])
        f[i][j] |= f[i - 1][j - a[i]];
    }

    for (int i = n; i >= 1; --i)
    {
      g[i][j] = g[i + 1][j];
      if (j >= a[i])
        g[i][j] |= g[i + 1][j - a[i]];
    }
  }

  //O(nk)
  for (int i = 1; i <= n; ++i)
  {
    int l = k - 1, x = 0;
    while (l >= 0 and !f[i - 1][l])
      --l;

    x = max(x, l);
    for (int r = 1; r < k; ++r)//O(2k) 
    {
      if (!g[i + 1][r])
        continue;

      while (l >= 0 and l + r >= k and f[i - 1][l])//r递增 l+r>=k 则l肯定要减小 
        --l;
      x = max(x, l + r);
    }
    if (x >= k - a[i])
    --ans; 
  }

  cout << ans << endl;
}

#include <bits/stdc++.h>
#define ll long long
using namespace std;

const int MAX = 5555;

int n, k;

ll sum;

int a[MAX];

bool pr[MAX][MAX], suf[MAX][MAX];

vector <int> v1, v2;

void init() {
    if (a[0] < MAX)
        pr[0][a[0]] = true;
    for (int i = 1; i < n; ++i) {
        for (int j = MAX - 1; j >= 0; --j) {
            if (pr[i - 1][j]) {
                if (j + a[i] < MAX)
                    pr[i][j + a[i]] = true;
                pr[i][j] = true;
            }
        }
    }
    if (a[n - 1] < MAX)
        suf[n - 1][a[n - 1]] = true;
    for (int i = n - 2; i >= 0; --i) {
        for (int j = MAX - 1; j >= 0; --j) {
            if (suf[i + 1][j]) {
                if (j + a[i] < MAX)
                    suf[i][j + a[i]] = true;
                suf[i][j] = true;
            }
        }
    }
}

bool gg(int id) {
    int l = max(0, k - a[id]);
    v1.clear();
    v2.clear();
    if (id > 0) {
        for (int i = 0; i < MAX; ++i) {
            if (pr[id - 1][i]) {
                if (l <= i && i < k)
                    return false;
                v1.push_back(i);
            }
        }
    }
    if (id < n - 1) {
        for (int i = 0; i < MAX; ++i) {
            if (suf[id + 1][i]) {
                if (l <= i && i < k)
                    return false;
                v2.push_back(i);
            }
        }
    }
    for (int i = 0; i < (int)v1.size(); ++i) {
        vector <int>::iterator it = lower_bound(v2.begin(), v2.end(), l - v1[i]);
        if (it != v2.end() && l <= v1[i] + *it && v1[i] + *it < k)
            return false;
    }
    return true;
}

int main() {
#ifdef LOCAL
    freopen("xxx.in", "r", stdin);
    freopen("xxx.out", "w", stdout);    
#endif
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    init();
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (gg(i))
            ans++;
    }
    cout << ans;
    return 0;
}

