    vl A(N); rep(i, N) cin >> A[i]; sort(ALL(A));

    ll KK = K+10;
    vvb dpl(N+1, vb(KK, false)); rep(i, N+1) dpl[i][0] = true;
    for (ll i = N-1; i >= 0; i--) {
        rep(k, KK){
            if(dpl[i+1][k] && k+A[i] <= KK){
                dpl[i][k+A[i]] = true;
            }
            dpl[i][k] = dpl[i][k] || dpl[i+1][k];
        }
    }

    auto AA = A; reverse(ALL(AA));
    vvb dpr(N+1, vb(KK, false)); rep(i, N+1) dpr[i][0] = true;
    for (ll i = N-1; i >= 0; i--) {
        rep(k, KK){
            if(dpr[i+1][k] && k+AA[i] <= KK){
                dpr[i][k+AA[i]] = true;
            }
            dpr[i][k] = dpr[i][k] || dpr[i+1][k];
        }
    }

