            if(dpl[i+1][k]) ls.insert(k);
            if(dpr[j+1][k]) rs.insert(k);
        }

        ll mn = LINF;
        for(ll l : ls){
            auto it = rs.lower_bound(K-A[i]-l);
            chmin(mn, *it+l);
            if(mn >= K){
                ans++; break;
            }
        }
    }

    cout << ans << endstr;
    return 0;
}

