#define rep(i,n) for(int i=0;i<n;++i)
int N,K,a[5000];

bool need(int x) {
	if(a[x]>=K) return true;
	set<int> sum;
	stack<int> temp;
	sum.insert(0);
	rep(i,N) if(i!=x) {
		for(auto s:sum){
			temp.push(s+a[i]);
			if(K<=s+a[i])break;
		}
		while(temp.size()){
			sum.insert(temp.top());
			temp.pop();
		}
	}
	auto it = sum.lower_bound(K-a[x]);
	return it!=sum.end() && *it<K;
}

int main() {
	cin>>N>>K;
	rep(i,N) cin>>a[i];
	sort(a,a+N);
	int l=0,r=N;
	while(l<r){
		int mid = (l+r)/2;
		if(need(mid)) r = mid;
		else l = mid+1;
	}
	cout<<l<<endl;
	return 0;
}

