int pref[maxN];
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
//    freopen("input.txt", "r", stdin);
    cin >> n >> k;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    dp[0][0] = true;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= k - 1; j++) {
            if (!dp[i][j]) continue;
            dp[i + 1][j] = true;
            if (j + a[i + 1] < k) dp[i + 1][j + a[i + 1]] = true;
        }
    }
    dpSuf[n + 1][0] = true;
    for (int i = n + 1; i > 1; i--) {
        for (int j = 0; j <= k - 1; j++) {
            if (!dpSuf[i][j]) continue;
            dpSuf[i - 1][j] = true;
            if (j + a[i - 1] < k) dpSuf[i - 1][j + a[i - 1]] = true;
        }
    }
    int c = 0;
    for (int who = 1; who <= n; who++) {
        pref[0] = dpSuf[who + 1][0];
        for (int j = 1; j <= k - 1; j++) {
            pref[j] = pref[j - 1] + (int)dpSuf[who + 1][j];
        }
        int l = max(0, k - a[who]);
        int r = k - 1;
        bool imp = false;
        for (int sz = 0; sz <= k - 1; sz++) {
            if (!dp[who - 1][sz]) continue;
            int hisl = max(l - sz, 0);
            int hisr = r - sz;
            if (hisl == 0 && pref[hisr] > 0) {
                imp = true;
                break;
            }
            if (hisl > 0 && pref[hisr] > pref[hisl - 1]) {
                imp = true;
                break;
            }
        }
        if (!imp) c++;
    }
    cout << c;
    return 0;
}

