const int maxn = 5005;
bool pre[maxn][maxn], suf[maxn][maxn];
int presuf[maxn][maxn];
int a[maxn];
int n, k;
int main(){
    cin >> n >> k;
    for(int i = 1;i <= n;i++){
        scanf("%d", &a[i]);
        a[i] = min(a[i], k);
    }
    pre[0][0] = 1;
    suf[n + 1][0] = 1;
    for(int i = 1;i <= n;i++){
        for(int j = 0;j <= k;j++){
            pre[i][j] |= pre[i - 1][j];
            if(j >= a[i]){
                pre[i][j] |= pre[i - 1][j - a[i]];
            }
            //cout << i << " " << j << " " << pre[i][j] << endl;
        }
    }
    for(int i = n;i >= 1;i--){
        for(int j = 0;j <= k;j++){
            suf[i][j] |= suf[i + 1][j];
            if(j >= a[i]){
                suf[i][j] |= suf[i + 1][j - a[i]];
            }
            //cout << i << " " << j << " " << suf[i][j] << endl;
        }
    }
    for(int i = n + 1;i >= 1;i--){
        presuf[i][0] = suf[i][0];
        for(int j = 1;j <= k;j++){
            presuf[i][j] = presuf[i][j - 1] + suf[i][j];
        }
    }
    int ans = 0;
    for(int i = 1;i <= n;i++){
        bool flag = false;
        for(int j = 0;j <= k;j++){
            if(pre[i - 1][j] == false)
                continue;
            int lower;
            if(k - j - a[i] - 1 < 0)
              lower = 0;
            else
              lower = presuf[i + 1][k - j - a[i] - 1];  
            int upper;
            if(k - j - 1 < 0)
                upper = 0;
            else
                upper = presuf[i + 1][k - j - 1];
            if(upper - lower > 0){
                //cout << i << " " << j << endl;
                flag = true;
                break;
            }
        }
        //cout << i << " " << flag << endl;
        ans += (flag == false);
    }
    cout << ans << endl;
    return 0;
}

