	rep (i, n) cin >> a[i];
	sort(all(a));
	bool dp_left[n + 1][k + 1] = {}, dp_right[n + 1][k + 1] = {};
	dp_left[0][0] = true;
	dp_right[n][0] = true;
	rep (i, n) {
		rep (j, k + 1) {
			if (j - a[i] >= 0) dp_left[i + 1][j] |= dp_left[i][j - a[i]];
			dp_left[i + 1][j] |= dp_left[i][j];
		}
	}
	reprev (i, n) {
		rep (j, k + 1) {
			if (j - a[i] >= 0) dp_right[i][j] |= dp_right[i + 1][j - a[i]];
			dp_right[i][j] |= dp_right[i + 1][j];
		}
	}
	int ng = -1, ok = n;
	while (ok - ng > 1) {
		int med = (ok + ng) / 2;
		bool ch = false;
		if (a[med] >= k) ch = true;
		else {
			repp (j, k - a[med], k) {
				rep (l, j + 1) {
					ch |= dp_left[med][l] && dp_right[med + 1][j - l];
				}
			}
		}
		if (ch) ok = med;
		else ng = med;
	}
	cout << ok << endl;
	return 0;
}

