#define FOR(i,a,b) for (int i=(a);i<(b);++i)
#define RFOR(i,a,b) for (int i=(b)-1;i>=(a);--i)
#define REP(i,n) for (int i=0;i<(n);++i)

using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    REP(i, N) cin >> a[i];

    unordered_map<int, cpp_int> d;
    d[0] = 1;
    for (int x: a) {
        RFOR(i, 1, K) {
            if (i >= x) {
                d[i] += d[i - x];
            }
        }
    }

    vector<vector<bool>> alt_sum_is_positive(K, vector<bool>(K));
    FOR(step, 1, K) {
        REP(start, step) {
            int n = start;
            cpp_int alt_sum = 0;
            while (n < K) {
                alt_sum = d[n] - alt_sum;
                alt_sum_is_positive[n][step] = (alt_sum > 0);
                n += step;
            }
        }
    }

    int need = 0;
    for (int x: a) {
        if (x >= K) {
            ++need;
        } else {
            FOR(s, K - x, K) {
                if (d[s] > 0) {
                    if (alt_sum_is_positive[s][x]) {
                        ++need;
                        break;
                    }
                }
            }
        }
    }
    int no_need = N - need;
    cout << no_need << endl;
    return 0;
}

