bool solve(int idx){
	rep(j, 5010) dp[j] = 0;
	dp[0] = 1;
	rep(i, N)REP(j, K + 1){
		if(dp[j] == 0) continue;
		if(i == idx) continue;
		if(j + a[i] > K) continue;
		dp[j + a[i]] = 1;
	}
	reps(i, max(0, K - a[idx]), K){
		if(dp[i]) return true;
	}
	return false;
}

