int k;
vi small;

bool solve(int mid){ // small[mid]を使わない
  vector<bool> dp(k,false);
  dp[0] = true;
  rep(i,small.size())
    if(i != mid)
      ROF(j,k-small[i],0)
	dp[j+small[i]] = dp[j+small[i]] or dp[j];

  bool res = false;
  FOR(i,k-small[mid],k) res |= dp[i];
  return res;
}

int bs(int _ok, int _ng){
  int ok = _ok;
  int ng = _ng;

  while(abs(ok - ng) > 1){
    int mid = (ok + ng) / 2;
    if(solve(mid)){
      ok = mid;
    }else{
      ng = mid;
    }
  }
  return ok;
}

