bool chk(int v) {
    if (v >= k) return true;
    seen.reset();
    seen[0] = true;

    for (int i = 1; i <= n; ++i) {
        if (i == v) continue;
        seen |= (seen << in[i]);
    }

    //assert(k - in[v] >= 0);
    for (int i = max(0, k - in[v]); i < k; ++i) if (seen[i]) return true;
    return false;
}

