const int MAX = 6666;

int n, k;

int a[MAX];

bool pr[MAX][MAX], suf[MAX][MAX];

vector <int> v1, v2;

void init() {
    pr[0][0] = true;
    if (a[0] < MAX)
        pr[0][a[0]] = true;
    for (int i = 1; i < n; ++i) {
        for (int j = MAX - 1; j >= 0; --j) {
            if (pr[i - 1][j]) {
                if (j + a[i] < MAX)
                    pr[i][j + a[i]] = true;
                pr[i][j] = true;
            }
        }
    }
    suf[n - 1][0] = true;
    if (a[n - 1] < MAX)
        suf[n - 1][a[n - 1]] = true;
    for (int i = n - 2; i >= 0; --i) {
        for (int j = MAX - 1; j >= 0; --j) {
            if (suf[i + 1][j]) {
                if (j + a[i] < MAX)
                    suf[i][j + a[i]] = true;
                suf[i][j] = true;
            }
        }
    }
}

bool gg(int id) {
    int l = max(0, k - a[id]);
    v1.clear();
    v2.clear();
    if (id > 0) {
        for (int i = 0; i < MAX; ++i) {
            if (pr[id - 1][i]) {
                if (l <= i && i < k)
                    return false;
                v1.push_back(i);
            }
        }
    }
    if (id < n - 1) {
        for (int i = 0; i < MAX; ++i) {
            if (suf[id + 1][i]) {
                if (l <= i && i < k)
                    return false;
                v2.push_back(i);
            }
        }
    }
    for (int i = 0; i < (int)v1.size(); ++i) {
        vector <int>::iterator it = lower_bound(v2.begin(), v2.end(), l - v1[i]);
        if (it != v2.end() && l <= v1[i] + *it && v1[i] + *it < k)
            return false;
    }
    return true;
}

