#define R register
#define maxn 5010
int a[maxn], b[maxn], ans, K;
std::bitset<maxn> f[20];
void solve(R int o, R int l, R int r)
{
	if (l > r) return ;
//	printf("%d %d %d\n", o, l, r);
	if (l == r)
	{
		R bool flag = 1;
		for (R int i = K - b[l]; flag && i < K; ++i)
		{
//			printf("%d\n", i);
			if (f[o][i]) flag = 0;
		}
		ans += flag;
		return ;
	}
	R int mid = l + r >> 1;
	f[o + 1] = f[o];
	for (R int i = l; i <= mid; ++i)
		f[o + 1] |= f[o + 1] << b[i];
	solve(o + 1, mid + 1, r);

	f[o + 1] = f[o];
	for (R int i = mid + 1; i <= r; ++i)
		f[o + 1] |= f[o + 1] << b[i];
	solve(o + 1, l, mid);
}
int main()
{
	R int n, m = 0; scanf("%d%d", &n, &K);
	for (R int i = 1; i <= n; ++i)
	{
		scanf("%d", &a[i]);
		a[i] < K ? b[++m] = a[i] : 0;
	}
	f[1][0] = 1; solve(1, 1, m);
	printf("%d\n", ans);
	return 0;
}
