    alist = alist_new;
    ll acount = alist.size();

    summap[0].set(0);
    rep(i, acount) {
        bitset<BIT_WIDTH> lsummap = summap[i] << alist[i];
        summap[i+1] = summap[i] | lsummap;
    }
    debug_printf("---- summap[2]\n");
    debug_print(summap[2]);

    summap_rev[0].set(0);
    rrep(i, acount) {
        bitset<BIT_WIDTH> lsummap = summap_rev[acount-i-1] << alist[i];
        summap_rev[acount-i] = summap_rev[acount-i-1] | lsummap;
    }
    debug_printf("---- summap_rev[2]\n");
    debug_print(summap_rev[2]);


    bitset<BIT_WIDTH> masks[5005];
    rep(i, 5004) {
        masks[i+1] = masks[i];
        masks[i+1].set(i);
    }
    debug_printf("---- masks[7]\n");
    debug_print(masks[7]);

    ll a_left = 0LL;
    ll a_right = acount-1LL;
    ll a_idx = (a_left + a_right) / 2LL;
    ll max_idx = -1LL;
    for ( ; a_left <= a_right; a_idx = (a_left + a_right) / 2LL) {
        ll a = alist[a_idx];
        bool need = false;

        for (ll lsum = 0LL; lsum < k; ++lsum) {
            if (!(summap[a_idx].test(lsum))) continue;
            bitset<BIT_WIDTH> lsummap = summap_rev[acount-a_idx-1LL];
            lsummap >>= ((k - a) - lsum);
            lsummap &= masks[a];
            if (lsummap.any()) {
                need = true;
                break;
            }
        }

        if (need) {
            a_right = a_idx - 1LL;
        }
        else {
            a_left = a_idx + 1LL;
            max_idx = max(max_idx, a_idx);
        }
    }

