class Main {
public:

	int getAns(vector<int> cards, int thr) {
		vector<bool> needed(cards.size(), false);
		rep(i, cards.size()) {
			if (cards[i] >= thr) {
				needed[i] = true;
				continue;
			}
			rep(j, i) {
				if (cards[j] < thr && cards[i] < thr && cards[i] + cards[j] >= thr) {
					needed[i] = true;
					needed[j] = true;
				}
			}
		}

		int count = 0;
		rep(i, cards.size()) {
			if (!needed[i]) count++;
		}

		return count;
	}
};


