    cin >> a[i];
    a[i] = min(a[i], k);
  }
  vector<Mint> dp(2 * k + 1, 0);
  dp[0] = 1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j <= 2 * k - a[i]; j++) {
      dp[j + a[i]] += dp[j];
    }
  }
  int ans = 0;
  for (int i = 0; i < n; i++) {
