      dp[j + a[i]] -= dp[j];
    }
    bool any = false;
    for (int j = k-1; j >= k - a[i]; j--) if (dp[j] != 0) { any = true; break; }
    if (!any) ans++;
  }
  cout << ans << '\n';
  return 0;
}

