		cout << 0 << endl;
		return;
	}
	if (!isok(N-1)) {
		cout << N << endl;
		return;
	}
	int ok = N-1;
	int ng = 0;
	while (ok - ng > 1) {
		int mid = (ok + ng) / 2;
		if (isok(mid)) ok = mid;
		else ng = mid;
	}
	cout << ok << endl;
}

