typedef long long ll;
const int maxn=5000+5;
int n,k;
ll a[maxn];
bool dp[maxn];
bool cal(int mid)
{
    if(a[mid]>=k) return false;
    memset(dp,0,sizeof(dp));
    dp[0]=true;
    for(int i=1;i<=n;i++)
    {
        if(i==mid) continue;
        for(int j=k;j>=0;j--)
        {
            if(!dp[j]) continue;
            if(j+a[i]<k){
                dp[j+a[i]]=true;
            }
        }
    }
    for(int i=k-1;i>=max(0ll,(ll)k-a[mid]);i--)
        if(dp[i]) return false;
    return true;
}
int main()
{
    scanf("%d%d",&n,&k);
    for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
    int l=0,r=n+1;
    while(r-l>1){
        int mid=l+(r-l)/2;
        if(cal(mid)) l=mid;
        else r=mid;
    }
    printf("%d\n",l);
    return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
const int MAXN = 5100;

int N, K;
int arr[MAXN];
int pdp[MAXN][MAXN];
int sdp[MAXN][MAXN];

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N >> K;
    for (int i = 0; i < N; i++)
    {
        cin >> arr[i];
        if (arr[i] > K) arr[i] = K;
    }

    pdp[0][0] = 1;
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j <= K; j++)
            pdp[i+1][j] = pdp[i][j];

        for (int j = 0; j <= K - arr[i]; j++)
            pdp[i+1][j+arr[i]] |= pdp[i][j];
    }
    sdp[0][0] = 1;
    for (int i = 0; i < N; i++)
    {
        for (int j = 0; j <= K; j++)
            sdp[i+1][j] = sdp[i][j];

        for (int j = 0; j <= K - arr[N-1-i]; j++)
            sdp[i+1][j+arr[N-1-i]] |= sdp[i][j];
    }

    int ans = 0;
    for (int i = 0; i < N; i++)
    {
        int ploc = i, sloc = N - 1 - i;

        int ggoal = K - arr[i];
        int cloc = 0;
        for (int j = K; j >= 0; j--)
        {
            if (cloc + j < ggoal)
                cloc = ggoal - j;
            while (cloc < K && !sdp[sloc][cloc])
                cloc++;

            if (pdp[ploc][j] && sdp[sloc][cloc] && (j + cloc >= ggoal) && (j + cloc < K))
            {
                ans++;
                break;
            }
        }
    }
    cout << N - ans << "\n";
}

