int N, K;
int64_t vals[5005];

int64_t DPT[405][405][405];

int64_t howclose(int i, int K, int nope) {
	if (K <= 0)
		return 1e18;
	if (i == N) {
		return K;
	}
	if (DPT[i][K][nope] != -1) {
		return DPT[i][K][nope];
	}
	if (i == nope) {
		return howclose(i+1, K, nope);
	}
	int64_t ans = min(howclose(i+1, K-vals[i], nope), howclose(i+1, K, nope));
	return DPT[i][K][nope] = ans;
}

