static SQWORD countNeedCards(
    const vector<SQWORD> &vsqA, 
    SQWORD sqK)
{
    /* dp(i)[j]  i枚目までを考慮したとき、合計がjになるような場合の数 */
    vector<MODINT> vsqDp(sqK, MODINT(0));

    vsqDp[0] = 1;
    for (SQWORD sqCardIdx = 0; sqCardIdx < vsqA.size(); sqCardIdx++) {
        for (SQWORD sqDpIdx = vsqDp.size() - 1; 0 <= sqDpIdx; sqDpIdx--) {
            SQWORD sqNextIdx = sqDpIdx + vsqA[sqCardIdx];

            if (sqNextIdx < sqK) {
                vsqDp[sqNextIdx] += vsqDp[sqDpIdx];
            }
        }
    }
#if 0
    printf("DP\n");
    printVector(vsqDp);
#endif

    /* k番目のカードがない場合の逆算をする 
    *       dp(k+1)[j] = dp(k)[j]   + dp(k)[j-A[k+1]]
    *       dp(k)[j]   = dp(k+1)[j] - dp(k)[j-A[k+1]]
    */
    SQWORD sqAns = 0;
    for (auto a: vsqA) {
        vector<MODINT> vsqDp2(sqK, MODINT(0));

        for (SQWORD sqDp2Idx = 0; sqDp2Idx < vsqDp2.size(); sqDp2Idx++) {
            if (sqDp2Idx < a) {
                vsqDp2[sqDp2Idx] = vsqDp[sqDp2Idx];
            } else {
                vsqDp2[sqDp2Idx] = vsqDp[sqDp2Idx] - vsqDp2[sqDp2Idx - a];
            }
        }
//        printVector(vsqDp2);

        if (vsqDp2.size() < a) {
            sqAns++;
        } else {
            for (SQWORD sqDp2Idx = vsqDp2.size() - a; sqDp2Idx < vsqDp2.size(); sqDp2Idx++) {
                if (0 != vsqDp2[sqDp2Idx].getVal()) {
//                    printf(">>%lld\n", a);
                    sqAns++;
                    break;
                }
            }
        }

    }
    return sqAns;
}

static void solve(SQWORD sqN, SQWORD sqK, const vector<SQWORD> &vsqA)
{
    SQWORD sqNeeded = countNeedCards(vsqA, sqK);
    printf("%lld\n", sqN - sqNeeded);       
}

int main(void)
{
    SQWORD sqN = inputSQWORD();
    SQWORD sqK = inputSQWORD();

    vector<SQWORD> vsqA;
    for (SQWORD sqIdx = 0; sqIdx < sqN; sqIdx++) {
        vsqA.emplace_back(inputSQWORD());
    }

    solve(sqN, sqK, vsqA);

    return 0;
}

