#define REP(i, n) for (int i = 0; i < (n); ++i)
#define REPR(i, n) for (int i = (n)-1; i >= 0; --i)
#define FOR(i, n, m) for (int i = (n); i < (m); ++i)

const int MAX = 5010;

int N, K;
vi A;
ll dp[MAX];

bool need(int mid) {
  ll x = A[mid];
  if (x >= K) return true;

  bool res = false;
  FOR (i, 1, MAX) dp[i] = 0;
  dp[0] = 1;
  REP (i, N) if (i != mid) {
    REPR (k, K) {
      if (dp[k]!=0 && k+A[i] < K) {
        dp[k+A[i]] = 1;
        if (k+A[i]+x >= K) res = true;
      }
    }
  }

  return res;
}

