bool req[5101] = {false};

bool solve(int index, int N, int K, const VI& seq, int sum){
  int nsum = sum + seq[index];
  if(req[index]){
    return req[index];
  }
  if(nsum >= K){
    req[index] = true;
    solve(index+1, N, K, seq, sum);
    return req[index];
  }
  REP(i, index+1, N){
    req[index] = solve(i, N, K, seq, nsum) || req[index];
    if(!req[index]){
      break;
    }
  }
  return req[index];
}

