		vector<bitset<5010>> dp(n + 1);
		dp[0].set(0);
		rep(i,n){
			if(i == mid - 1) dp[i + 1] |= dp[i];
			else dp[i + 1] |= dp[i] | (dp[i] << a.at(i));
		}
		bool flg = false;
		for(int i = k - a.at(mid - 1); i < k; i++){
			if(dp[n][i]){
				flg = true;
				break;
			}
		}
		if(flg) ok = mid;
		else ng = mid;
	}
	cout << ng << endl;
}

