bitset <5010> dp;
int n, k;
int a[5010];

bool check(int mid) {
	dp.reset(), dp.set(0);
	for (int i = 0; i < n; i++) {
		if (a[i] <= k && i != mid) dp = dp | dp << a[i];
	}
	for (int i = max(0, k - a[mid]); i < k; i++) {
		if (dp[i]) return 0;
	}
	return 1;
}

int main () {
	scanf("%d%d", &n, &k);
	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
	}
	sort(a, a + n);
	int l = 0, r = n - 1;
	while (l < r) {
		int mid = l + r + 1 >> 1;
		if (check(mid)) l = mid;
		else r = mid - 1;
	}
	printf("%d\n", l + 1);
	return 0;
}

