    return *this;
  }
  S002& operator >= (double& x) {
    if( scanf("%lf", &x) <= 0 ) exit(0);
    return *this;
  }
  S002& operator >= (std::string& s) {
    if( not (std::cin >> s) ) exit(0);
    return *this;
  }
  template<typename a>
  S002& operator >= (std::vector<a>& v) {
    v.resize(n);
    for(long i = 0; i < n; ++i) {
      *this >= v[i];
    }
    return *this;
  }
  template<typename a, std::size_t s>
  S002& operator >= (std::array<a, s>& x) {
    for(long i = 0; i < (long)s; ++i) {
      *this >= x[i];
    }
    return *this;
  }
};

struct Solver {
  long n, k;
  std::vector<long> xs;
  Solver() {
    S002 reader;
    reader >= n >= k >n>= xs;
  }
  void solve() {
    std::sort(xs.begin(), xs.end());
    long dp[10000] = {};
    dp[0] = 1;
    for(long ai : xs) {
      if( ai >= 5000 ) continue;
      for(long j = 5000; j >= 0; --j) { 
        if( j - ai >= 0 ) {
          dp[j] = dp[j] + dp[j-ai];
        }
        else {
          dp[j] = dp[j];
        }
      }
    }
    // for(long i = 0; i < 20; ++i) {
    //   dumpll(i, dp[i]);
    // }
    long temp[10000] = {};
    long res = (long)xs.size();
    for(long ai : xs) {
      if( ai >= 5000 ) {
        res -= 1;
        continue;
      }
      for(long j = 0; j <= 5000; ++j) {
        if( j >= k ) break;
        if( j - ai >= 0 ) temp[j] = dp[j] - temp[j-ai];
        else temp[j] = dp[j];
        if( temp[j] != 0 and k <= j + ai ) {
          res -= 1;
          break;
        }
      }
    }
    printf("%ld\n", res);
  }
};

int main() {
  for(;;) std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

