signed main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	int n, k;
	cin >> n >> k;

	//ai が 必要 => aiを除いて 総和xが (k - ai) <= x < k を満たす集合が存在する
	//
	//ai >= k は絶対必要　<= 取り除いてよい

	vector<int> a;
	for (int i = 0; i < n; i++) {
		int t;
		cin >> t;
		if (t < k) {
			a.push_back(t);
		}
	}

