	sort(all(a));

	int ans = 0;


	auto ok = [&](int i) {

		clr(vis);
		mclr(dp);

		function<void(int, int)> dfs = [&](int t, int sum) {
			if (t == n) {
				return;
			}
			if (t == i) {
				dfs(t + 1, sum);
				return;
			}
			if (sum >= k)return;
			if (dp[t][sum] != -1)return;
			dp[t][sum] = 1;

			dfs(t + 1, sum);

			if (sum + a[t] < k) {
				vis[sum + a[t]] = 1;
				dfs(t + 1, sum + a[t]);
			}

		};

		vis[0] = 1;
		dfs(0, 0);


		bool need = false;
		for (int j = k - a[i]; j < k; j++) {
			if (vis[j]) need = true;
		}
		return need;
	};

	int l = -1, r = n-1;
	while(r - l > 1) {
		int m = (r + l) / 2.0;
		if (!ok(m)) {
			l = m;
		}
		else {
			r = m;
		}
	}

	cout << r << endl;


	return 0;
}

