int N,K;
const int MAX_N = 5005;
int a[MAX_N];
int dp[MAX_N][MAX_N],dp2[MAX_N];

int main(){
	ios::sync_with_stdio(false);

	cin >> N >> K;
	for(int i=1;i<=N;i++){
		cin >> a[i]; 
	}

	dp[0][0] = 1;
	for(int i=1;i<=N;i++){
		for(int j=0;j<K;j++){
			dp[i][j] = dp[i-1][j];
			if(j>=a[i])dp[i][j] |= dp[i-1][j-a[i]];
		}
	}
	for(int i=0;i<=N;i++){
		for(int j=1;j<K;j++){
			dp[i][j] += dp[i][j-1];
		}
	}

	int ans = 0;
	dp2[0] = 1;
	for(int i=N;i>=1;i--){
		bool ok = a[i]<K;
		if(a[i]<K){
			for(int j=0;j<K;j++){
				if(!dp2[j])continue;
				if(dp[i-1][K-j-1]-(K>=j+a[i]+1?dp[i-1][K-j-a[i]-1]:0) > 0){
					ok = false;
					break;
				}
			}
		}
		if(ok)ans++;
		for(int j=K-1;j>=a[i];j--){
			dp2[j] |= dp2[j-a[i]];
		}
	}

	cout << ans << endl;

	return 0;
}

