bool isNeeded(int id, int K, int M, vector<int> &b){
    vector<bool> dp(5001, 0);
    dp[0] = true;
    for(int i=0; i<M; i++){
        if(i == id) continue;
        for(int j=5000; j>=b[i]; j--)
            if(dp[j-b[i]]) dp[j] = true;
    }

    for(int i=K - b[id]; i<K; i++){
        if(dp[i]) return true;
    }

    return false;
}
int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    for(int i=0; i<N; i++) cin >> a[i];

    vector<int> b;
    for(int i=0; i<N; i++)
        if(a[i] < K) b.push_back(a[i]);

    int M = b.size();
    if(M == 0){
        cout << 0 << endl;
        return 0;
    }
    sort(b.begin(), b.end());

    int lb = 0;
    int ub = M - 1;
    if(!isNeeded(ub, K, M, b)){
        cout << M << endl;
        return 0;
    }
    if(isNeeded(lb, K, M, b)){
        cout << 0 << endl;
        return 0;
    }

    while(ub - lb > 1){
        int mid = (lb + ub) / 2;
        if(!isNeeded(mid, K, M, b)) lb = mid;
        else ub = mid;
    }
    cout << ub << endl;

    return 0;
}

