    }

    for (int m = 0; m < N; ++m) {
        std::vector <int> vv(N);
        std::copy(v.begin(), v.end(), vv.begin());
        vv.erase(vv.begin() + m);

        std::vector<std::vector<int>> ok;
    ok.resize(N - 1);
        for (int n = 0; n < N - 1; ++n) {
            ok[n].resize(K);
        }
    for (int l = 0; l < K; ++l) {
        if(vv[0] == l)
            ok[0][l] = 1;
        else
            ok[0][l] = 0;
    }
        for (int j = 1; j < N - 1; ++j) {
        for (int k = 0; k < K; ++k) {
            if (k >= vv[j]) {
                ok[j][k] = ok[j - 1][k] || ok[j - 1][k - vv[j]];
            } else {
                if (ok[j - 1][k])
                    ok[j][k] = 1;
                else
                    ok[j][k] = 0;
            }
        }
    }
        if(v[m] > K)
            Ans[m] = true;
        else {
            for (int i = K - v[m]; i < K; ++i) {
                if (ok[N - 2][i])
                    Ans[m] = true;
            }
        }
    }

    int Answer = 0;

    for (int i1 = 0; i1 < N; ++i1) {
        //std::cout << Ans[i1] << std::endl;
        if(!Ans[i1])
            Answer++;
    }
    std::cout << Answer << std::endl;
    return 0;
}

