    for(int i=0; i<n; i++) {
        prefix[i+1] = set<int>(prefix[i].begin(), prefix[i].end());
        for(set<int>::iterator it=prefix[i].begin(); it != prefix[i].end(); it++) {
            int v = *it;
            if(v+a[i] <=k){
                prefix[i+1].insert(v + a[i]);
            }
        }
    }

    suffix[n].insert(0);
    for(int i=n-1; 0<=i; i--) {
        suffix[i] = suffix[i+1];
        for(set<int>::iterator it=suffix[i+1].begin(); it!=suffix[i+1].end(); it++) {
            int v = *it;
            if(v+a[i]<=k) {
                suffix[i].insert(v+a[i]);
            }
        }
    }

    // cumulative sums
    int c_suffix_i_plus_1[5001];

    int res = 0;
    for(int i=0; i<n; i++) {
        if(k<=a[i])
            continue;
        c_suffix_i_plus_1[0] = 0;
        for(int j=0; j<k; j++) {
            bool is_in = suffix[i+1].find(j) != suffix[i+1].end();
            c_suffix_i_plus_1[j+1] = c_suffix_i_plus_1[j] + is_in;
        }
        bool ok = true;
        for(set<int>::iterator it=prefix[i].begin(); it!=prefix[i].end(); it++) {
            int s = *it;
            int start = k-a[i]-s;
            if(start<0) start = 0;
            int stop = k-s;
            if (c_suffix_i_plus_1[stop] - c_suffix_i_plus_1[start] > 0){
                ok = false;
                break;
            }
        }
        if(ok)
            res++;
    }
    cout << res << endl;

}

