bool unnecessary(int l){
    memset(dp,0,sizeof(dp));
    if(0<k && 0>=k-x[l])
        return 0;
    for(int i=0;i<n;i++){
        dp[i][0]=1;
        if(i==0)
            continue;
        if(i==l){
            for(int j=1;j<k;j++)
                dp[i][j]|=dp[i-1][j];
            continue;
        }
        for(int j=1;j<k;j++){
            if(j>=x[l])
                dp[i][j]|=(dp[i-1][j] | dp[i-1][j-x[l]]);
            else
                dp[i][j]|=dp[i-1][j];
            if(j<k && j>=k-x[l] && dp[i][j])
                    return 0;
        }
    }
    return 1;
}
