template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;
struct nap
{
	std::array<int, 5000> memo;
	int target;
	std::vector<int> const& vec;
	nap(int t, std::vector<int>const& v) :memo{}, target{ t }, vec{ v }
	{
		for (int i{}; i < 5000; ++i)
		{
			memo[i] = -1;
		}
	}
	int run(int index, int K)
	{
		if (memo[K] != -1)
		{
			return memo[K];
		}
		if (index == target)
		{
			return run(index + 1, K);
		}
		if (index == vec.size())
		{
			return 0;
		}
		if (vec[index] < K)
		{
			memo[K] = std::max(run(index + 1, K - vec[index]) + vec[index], run(index + 1, K));
		}
		else
		{
			memo[K] = run(index + 1, K);
		}
		return memo[K];
	}
};

int main()
{
	int N, K;
	std::cin >> N >> K;
	std::vector<int> vec;
	int count{};
	for (int i{}; i < N; ++i)
	{
		int v;
		std::cin >> v;
		if (v < K)
		{
			vec.emplace_back(v);
		}
	}
	for (int i{}; i < vec.size(); ++i)
	{
		nap n{ i,vec };
		if (n.run(0, K) + vec[i] < K)
		{
			++count;
		}
	}
	std::cout << count << std::endl;
}

