template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;
struct nap
{
	std::array<int, 5000> memo;
	int target;
	std::vector<int> const& vec;
	nap(int t, std::vector<int>const& v) :memo{}, target{ t }, vec{ v }
	{
		for (int i{}; i < 5000;++i)
		{
			memo[i] = -1;
		}
	}
	int run(int index, int v, int K)
	{
		if (memo[v] != -1)
		{
			return memo[v];
		}
		if (index == target)
		{
			return run(index + 1, v, K);
		}
		if (index == vec.size())
		{
			memo[v] = v;
		}
		else if (v + vec[index] < K)
		{
			memo[v] = std::max(run(index + 1, v + vec[index], K), run(index + 1, v, K));
		}
		else
		{
			memo[v] = run(index + 1, v, K);
		}
		return memo[v];
	}
};

int main()
{
	int N, K;
	std::cin >> N >> K;
	std::vector<int> vec;
	int count{};
	for (int i{}; i < N; ++i)
	{
		int v;
		std::cin >> v;
		if (v < K)
		{
			vec.emplace_back(v);
		}
	}
	for (int i{}; i < vec.size(); ++i)
	{
		nap n{ i,vec };
		if (n.run(0, 0, K) + vec[i] < K)
		{
			++count;
		}
	}
	std::cout << count << std::endl;
}

