bool necessary(int K, const vector<int>& A, int i)
{
    if (A[i] >= K) return true;
    bitset<5001> bits;
    bits.set(0);
    REP(j, A.size()) {
        if (i == j) continue;
        bits |= bits << A[j];
        bits.set(0);
    }
    for (int j = max(0, K - A[i]); j < K; j++) {
        if (bits[j]) {
            return true;
        }
    }
    return false;
}
int main()
{
    int N, K; cin >> N >> K;
    vector<int> A(N); REP(i, N) cin >> A[i];
    sort(A.begin(), A.end());
    if (necessary(K, A, 0)) {
        cout << 0 << endl;
        return 0;
    }
    if (!necessary(K, A, N-1)) {
        cout << N << endl;
        return 0;
    }
    int lo = 0, hi = N-1;
    while (hi - lo > 1) {
        int mid = (lo + hi) / 2;
        if (necessary(K, A, mid)) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    cout << hi << endl;
    return 0;
}

