	s.push_back(a[0]);
	for(int i = 1; i < N; ++i) {
		s.push_back(s.back());
		s.back() += a[i];
	}
	if(s.back() < K) {
		cout << N << '\n';
		return 0;
	}
	if(K <= s[0]) {
		cout << "0\n";
		return 0;
	}

	int m;
	int L = 0;
	int R = N - 1;
	m = (R + L) / 2;
	while(!(s[m - 1] < K && K <= s[m])) {
		if(s[m] < K) {
			L = m;
			m = (R + L) / 2 + 1;
		} else {
			R = m;
			m = (R + L) / 2;
		}
	}

	int n;
	L = 0, R = m - 1;
	n = (R + L) / 2;
	while(!(s[m] - s[n + 1] < K && K <= s[m] - s[n])) {
		if(K <= s[m] - s[n]) {
			L = n;
			n = (R + L) / 2 + 1;
		} else {
			R = n;
			n = (R + L) / 2;
		}
	}

	int result = n;
	while(s[result] == s[result + 1]) {
		--result;
	}
	cout << (result + 1) << '\n';

