LL dp[MAXN];

void insert(int x){
	for(int j=K;j>=x;j--){
		dp[j] += dp[j-x];
	}
}

void remove(int x){
	for(int j=x;j<=K;j++){
		dp[j] -= dp[j-x];
	}
}

bool chk(int x){
	if(x > K) return 0;
	for(int j=K-x;j<K;j++){
		if(dp[j]) return 0;
	}
	return 1;
}

