using namespace std;

int n,k;
int a[nmax];
bool pre[nmax][nmax]={}, suf[nmax][nmax]={};


int main(){
	cin >> n >> k;
	for(int i=1;i<=n;i++){
		cin >> a[i];
		a[i]=min(a[i],k);
	}

	pre[0][0]=1;
	for(int i=1;i<=n;i++){
		for(int j=0;j<k;j++){
			pre[i][j]=pre[i-1][j];
			if(j>=a[i]){
				pre[i][j]|=pre[i-1][j-a[i]];
			}
		}

		for(int j=0;j<=k;j++){
			if(pre[i-1][j] &&j+a[i]>=k){
				pre[i][k]=1;
			}
		}
	}
	suf[n+1][0]=1;
	for(int i=n;i>=1;i--){
		for(int j=0;j<k;j++){
			suf[i][j]=suf[i+1][j];
			if(j>=a[i]){
				suf[i][j]|=suf[i+1][j-a[i]];
			}
		}

		for(int j=0;j<=k;j++){
			if(suf[i+1][j] &&j+a[i]>=k){
				suf[i][k]=1;
			}
		}
	}

	int ans=0;
	for(int i=1;i<=n;i++){
		if(a[i]==k){
			continue;
		}

		int req = k-a[i];
		vector<int> v;
		for(int j=0;j<=k;j++){
			if(suf[i+1][j]){
				v.push_back(j);
			}
		}
		int val = INT_MAX;
		for(int j=0;j<=k;j++){
			if(pre[i-1][j]){
				auto it = lower_bound(v.begin(),v.end(), req-j);
				if(it!=v.end()){
					val=min(val,j+(*it));
				}
			}
		}
		if(val>=k){
			ans++;
		}
	}
	cout << ans << endl;
	return 0;
}

