const double EPS = 1e-10;
ll dpL[5001][5001];
ll dpR[5001][5001];
int a[5001];
int main() {
	int N, K;
	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		cin >> a[i];
		a[i] = min(a[i], K);
	}
	dpL[0][0] = 1;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j <= K; j++) {
			dpL[i + 1][j] |= dpL[i][j];
			dpL[i + 1][min(j + a[i], K)] |= dpL[i][j];
		}
	}
	dpR[N][0] = 1;
	for (int i = N; i > 0; i--) {
		for (int j = 0; j <= K; j++) {
			dpR[i - 1][j] |= dpR[i][j];
			dpR[i - 1][min(j + a[i - 1], K)] |= dpR[i][j];
		}
	}
	for (int i = 0; i <= N; i++) {
		for (int j = 1; j <= K; j++) dpR[i][j] += dpR[i][j - 1];
	}
	int ans = 0;
	for (int i = 0; i < N; i++) {
		bool need = 0;
		for (int j = 0; j < K; j++) {
			if (!dpL[i][j]) continue;
			int s = dpR[i + 1][K - 1 - j];
			if (K - a[i] - j > 0) s -= dpR[i + 1][K - a[i] - j - 1];
			if (s > 0) {
				need = 1;
				break;
			}
		}
		if (need) ans++;
	}
	cout << N - ans << endl;
}

