int main(){
  int n,k; cin >> n >> k;
  vi in(n);
  rep(i,n) cin >> in[i];

  rep(i,n+1)  dp1[i][0] = 1,dp2[i][0] = 1;
  rep(i,n)rep(j,k){
    if(dp1[i][j]){
      dp1[i+1][j] = 1;
      if(j + in[i] <= k)
        dp1[i+1][j+in[i]] = 1;
    }
  }
  for(int i = n; i > 0; i--)rep(j,k){
    if(dp2[i][j]){
      dp2[i-1][j] = 1;
      if(j + in[i-1] <= k)
        dp2[i-1][j+in[i-1]] = 1;
    }
  }
  int ans = n;
  rep(i,n){
    [&](){
    set<int> table;
    //rep(j,k+1) cerr << i << " " << j << " " << dp2[i+1][j] << endl;
    rep(j,k+1) if(dp2[i+1][j]) table.insert(j);
    rep(j,k+1){
      if(dp1[i][j]){
        auto itr = table.lower_bound(k - (j + in[i]));
        if(itr != table.end() && *itr + j < k){
          //cerr << i << " " << j << endl;
          ans--;
          return;
        }
      }
    }
    }();
  }
  cout << ans << endl;
}

