bool is_i_needed(ll N, ll K, vector<ll>& As, int i) {
    // 任意のカードの組み合わせで作成可能な数を列挙
    // ただしK未満
    bool flip = true;
    vector<vector<int>> possible(K, vector<int>(2));
    possible[0][flip] = 1;
    REP(j, N) {
        if (i == j) continue;
        flip = !flip;
        auto a = As[j];
        vector<int> added(K);
        REP(j, K) {
            if (possible[j][!flip]) {
                possible[j][flip] = 1;
            }
            if (possible[j][!flip] && (j + a) < K) {
                possible[j + a][flip] = 1;
            }
        }
    }

    FOR(j, max(0LL, K - As[i]), K) {
        if (possible[j][flip]) {
            return true;
        }
    }
    return false;
}


int main(void)
{
    cin.sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<ll> As(N);
    REP(n, N) cin >> As[n];

    if (N > 400 || K > 400) return 0;

    int no_need = 0;
    REP(i, SIZE(As)) {
        no_need += !is_i_needed(N, K, As, i);
    }
    cout << no_need << endl;
    return 0;
}

