int n,k;
int arr[5020];

bool valid(int idx){
	if(arr[idx] >= k)return true;

	int memo[5020];
	reset(memo, 0);
	memo[0] = 1;	
	FOR(j,n){
		if(idx == j)continue;
		for(int l = k-1;l>=0;l--){
			if(!memo[l])continue;
			if(l + arr[j] <= k)memo[l+arr[j]] = memo[l];
		}
	}

	for(int j = k-arr[idx];j<k;j++){
		if(memo[j])return true;
	}

	return false;
}

int main(void){
	sc(n);sc(k);
	FOR(i,n)sc(arr[i]);
	sort(arr, arr + n);

	int lo = 0;
	int hi = n-1;
	while(lo < hi){
		int mid = lo + (hi - lo + 1)/2;
		if(valid(mid)){
			hi = mid - 1;
		}else{
			lo = mid;
		}
	}
	if(lo > 0)
		cout << (lo+1) << endl;
	else if(valid(lo)){
		cout << 0 << endl;
	}else cout << 1 << endl;
    return 0;

}

