  for (int i = 1; i <= n; i++) {
    cin >> a[i];
  }
  vector<bitset<K>> dp_front(n + 2);
  vector<bitset<K>> dp_back(n + 2);
  dp_front[0][0] = 1;
  for (int i = 1; i <= n; i++) {
    dp_front[i] = dp_front[i - 1] | (dp_front[i - 1] << a[i]);
  }
  dp_back[n + 1][0] = 1;
  for (int i = n; i >= 1; i--) {
    dp_back[i] = dp_back[i + 1] | (dp_back[i + 1] << a[i]);
  }
  int ans = 0;
  auto eval = [] (const vector<int>& v, int left, int right) {
    if (left <= 0) return v[right] > 0;
    return (v[right] - v[left - 1]) > 0;
  };
  for (int i = 1; i <= n; i++) {
    vector<int> f(K);
    vector<int> b(K);
    for (int j = 0; j < K; j++) {
      f[j] = dp_front[i - 1][j];
      if (j > 0) f[j] += f[j - 1];
    }
    for (int j = 0; j < K; j++) {
      b[j] = dp_back[i + 1][j];
      if (j > 0) b[j] += b[j - 1];
    }
    bool need = false;
    for (int j = 0; j < k; j++) {
      if ((dp_front[i - 1][j] || dp_back[i + 1][j]) && (j >= max(0, k - a[i]))) need = true;
      if (dp_front[i - 1][j] && eval(b, k - j - a[i], k - 1 - j)) need = true;
      if (dp_back[i + 1][j] && eval(f, k - j - a[i], k - 1 - j)) need = true;
    }
    if (!need) ans++;
  }
  cout << ans << '\n';
  return 0;
}

