        dp[0] = true;
        REP(x, N) if(x != i) {
            bool ndp[MAX_K] = {};
            REP(y, K+1) {
                ndp[y] = (dp[y] || (y-A[x] >= 0 && dp[y-A[x]]));
            }
            REP(y, K+1) dp[y] = ndp[y];
        }
        REP(y, K) if(dp[y] && K <= y + A[i] && y < K) {
            answer[i] = true;
        }
    }
    return answer;
