int N, K;
int A[5000];

bool Judge(int omit) {
	bitset<5001> dp;
	dp[0] = 1;

	REP(i, 0, N) {
		if (i == omit) continue;
		dp |= dp << A[i];
	}

	bool ng = 0;
	REP(i, max(K - A[omit], 0), K) {
		ng |= dp[i];
	}
	return !ng;
}

int main() {
	cin >> N >> K;
	REP(i, 0, N) {
		cin >> A[i];
	}
	sort(A, A + N);

	int lo = -1;
	int hi = N;
	while (hi - lo > 1) {
		int mid = (hi + lo) / 2;
		if (Judge(mid)) {
			lo = mid;
		} else {
			hi = mid;
		}
	}

	cout << hi << endl;
	return 0;
}

