#include <cstdio>
const int MAXN = 5005, mod = 1e9 + 7;
inline int addmod(int a, int b) { return (a + b) % mod; }
int n, k, a[MAXN];
int cnt[MAXN * 2];
int main() {
	scanf("%d%d", &n, &k);
	for(int i = 0; i < n; i++) scanf("%d", &a[i]);
	cnt[0] = 1;
	for(int i = 0; i < n; i++) {
		for(int j = 2 * k - a[i]; j >= 0; j--) cnt[j + a[i]] = addmod(cnt[j + a[i]], cnt[j]);
	}
	int ans = n;
	for(int i = 0; i < n; i++) {
		if(a[i] >= k) ans--;
		else {
			for(int j = a[i]; j <= 2 * k; j++) cnt[j] = addmod(cnt[j], mod - cnt[j - a[i]]);
			for(int j = k - a[i]; j < k; j++) if(cnt[j] > 0) {
				ans--;
				break;
			}
			for(int j = 2 * k - a[i]; j >= 0; j--) cnt[j + a[i]] = addmod(cnt[j + a[i]], cnt[j]);
		}
	}
	printf("%d\n", ans);
	return 0;
}

