static const int MAXN = 5004;
static const int MAXK = 5004;

int n, k, a[MAXN];
bool f[MAXN][MAXK] = {{ false }}, g[MAXN][MAXK] = {{ false }};
int f_lte_max[MAXN][MAXK];

int main()
{
    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; ++i) scanf("%d", &a[i]);

    f[0][0] = true;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= k; ++j)
            f[i][j] = (f[i - 1][j] || (j >= a[i] && f[i - 1][j - a[i]]));
    }
    g[n + 1][0] = true;
    for (int i = n; i >= 1; --i) {
        for (int j = 0; j <= k; ++j)
            g[i][j] = (g[i + 1][j] || (j >= a[i] && g[i + 1][j - a[i]]));
    }

    for (int i = 0; i <= n; ++i) {
        f_lte_max[i][0] = 0;
        for (int j = 1; j <= k; ++j)
            f_lte_max[i][j] = (f[i][j] ? j : f_lte_max[i][j - 1]);
    }

    int ans = 0;
    for (int i = 1; i <= n; ++i) {
        if (a[i] >= k) continue;
        int max = -1;
        for (int j = 0; j <= k - 1; ++j) if (g[i + 1][j])
            max = std::max(max, j + f_lte_max[i - 1][k - 1 - j]);
        if (max < k - a[i]) ++ans;
    }

    printf("%d\n", ans);
    return 0;
}

