const int N = 5005;
int dp[N][N], n, k, a[N], tmp, x;
int sol(int i, int cur)
{
	if(n == 1 || a[i-1] < x) return cur;
	int &ret = dp[i][cur];
	if(ret != -1) return ret;
	ret = sol(i-1, cur);
	if(cur + a[i] < k && tmp != i) return max(ret, sol(i-1, cur+a[i]));
	return ret;
}
bool check(int i)
{
	x = a[i];
	if(x >= k) return 1;
	memset(dp, -1, sizeof dp);
	tmp = i;
	if(sol(n-1, 0) >= k-x) return 1;
	return 0;
}
int main()
{
	cin >> n >> k;
	for(int i=0; i<n; i++) scanf("%d", &a[i]);
