#include <bits/stdc++.h>

using namespace std;

const int MAX_N = 5010;

int n, k;
vector<int> a;
int dp1[MAX_N][MAX_N], dp2[MAX_N][MAX_N];
int pref[MAX_N][MAX_N];

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> k;
    for (int i = 0; i < n; i++) {
        int t;
        cin >> t;
        if (t < k) {
            a.push_back(t);
        }
    }
    n = a.size();
    dp1[0][0] = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= k; j++) {
            if (dp1[i][j]) {
                dp1[i + 1][j] = 1;
                if (j + a[i] <= k) {
                    dp1[i + 1][j + a[i]] = 1;
                }
            }
        }
    }
    dp2[0][0] = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= k; j++) {
            if (dp2[i][j]) {
                dp2[i + 1][j] = 1;
                if (j + a[n - 1 - i] <= k) {
                    dp2[i + 1][j + a[n - 1 - i]] = 1;
                }
            }
        }
    }
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= k; j++) {
            pref[i][j + 1] = pref[i][j] + dp2[i][j];
        }
    }
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= k; j++) {
            if (dp1[i][j]) {
                int x = pref[n - 1 - i][k - j];
                if (k >= a[i] + j) {
                    x -= pref[n - 1 - i][k - a[i] - j];
                }
                if (x > 0) {
                    break;
                }
            }
            if (j == k) {
                cnt++;
            }
        }
    }
    cout << cnt << "\n";
}

