	auto ok = [&](int i) {

		function<bool(int, int)> dfs = [&](int t, int sum) {
			if (t == n) {
				return false;
			}
			if (t == i) {
				return dfs(t + 1, sum);
			}
			if (sum >= k)return false;
			if (dp[t][sum] == i)return false;
			dp[t][sum] = i;

			if (dfs(t + 1, sum))return true;

			if (sum + a[t] < k) {
				if (sum + a[t] >= k - a[i])return true;
				return dfs(t + 1, sum + a[t]);
			}

			return false;
		};

		return dfs(0, 0);
	};

	int l = -1, r = n;
	while(r - l > 1) {
		int m = (r + l) / 2.0;
		if (!ok(m)) {
			l = m;
		}
		else {
			r = m;
		}
	}

	cout << r << endl;


	return 0;
}

