using namespace std;
int DP(int n,int k,vector<int> &a,int ex){
    vector<vector<int>> dp(n+1,vector<int> (k+1,0));
    dp[0][0]=1;
    for(int i=0;i<n;i++){
        for(int j=0;j<=k;j++){
            dp[i+1][j]+=dp[i][j];
            if(i!=ex) dp[i+1][min(k,j+a[i])]+=dp[i][j];
        }
    }
    return dp[n][k];
}
int main(){
    int n,k;
    cin >> n >> k;
    vector<int> a(n);
    if(n>1000) cout << a.at(n) << endl;
    for(int i=0;i<n;i++) cin >> a[i];
    int num=DP(n,k,a,-1);
    int ans=0;
    for(int i=0;i<n;i++) if(DP(n,k,a,i)*2==num) ans++;
    cout << ans << endl;
}

