// usage: https://csacademy.com/submission/1676084/

int BinarySearch(int ng, int ok, function<bool(int)> func) {
    while (abs(ok - ng) > 1) {
        int mid = (ng + ok) / 2;
        (func(mid) ? ok : ng) = mid;
    }
    return ok;
}

bool solve(int i) {
    // a[i] を含み，和が最小となる"良い集合"から a[i] を除いた集合も"良い集合"なら a[i] は捨てて良い
    int tmp = a[i];
    a[i] = 0;
    vector<vector<bool>> dp(N + 1, vector<bool>(K, false));
    dp[0][0] = true;
    for (int n = 0; n < N; n++) {
        for (int k = 0; k < K; k++) {
            if (dp[n][k]) {
                dp[n + 1][k] = true;
                if (k + a[n] < K)
                    dp[n + 1][k + a[n]] = true;
            }
        }
    }
    a[i] = tmp;
    bool flag = true;
    for (int k = max(0LL, K - a[i]); k < K; k++) {
        if (dp[N][k]) {
            flag = false;
            break;
        }
    }
    return flag;
}

