int ans=0;
int main(){
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	int n, K;
	cin>>n>>K;
	long long sum=0;
	for(int i=1;i<=n;i++){
		cin>>a[i];
		sum+=a[i]; 
	} 
	sort(a+1, a+n+1);
	if(n==1) {
		if(a[1]>=K) cout<<0<<endl;
		else cout<<1<<endl;
		return 0;
	}
	if(sum<K) {
		cout<<n<<endl;
		return 0;
	}
	if(sum==K) {
		cout<<0<<endl;
		return 0;
	}
//	if(sum<K) { // no way to achieve good set
//		cout<<n<<endl;
//		return 0;
//	}
	dp[1][0]=0;
	int limit=min(a[1], K);
	for(int i=1;i<=limit;i++) dp[1][i]=1;
	for(int i=1;i<=n;i++){
		for(int k=1;k<=K;k++){
			dp[i][k]=dp[i-1][k];
			if(k>a[i] && dp[i-1][k-a[i]]>0) {
				dp[i][k]+=dp[i-1][k-a[i]]; //从上一组开始
				for(const auto& x : use[k-a[i]]) {
					if(!v[k][x]){
						v[k][x]=1;
						use[k].push_back(x);
					}
				}
				if(!v[k][i]){
					v[k][i]=1;
					use[k].push_back(i);
				}
			}
			if(a[i]>=k) {
				dp[i][k]++;
				if(!v[k][i]){
					v[k][i]=1;
					use[k].push_back(i);
				}
			}
		}
	}
	cout<<n-use[K].size()<<endl;
	return 0;
}

