const int N = 5000+1;
bool dp[N][N];
int vis[N][N];
int arr[N];
int VIS;
int l, r, n, s, k;
bool calc(int idx, int sum) {
	if (sum >= l && sum <= r)
		return true;
	if (sum > r)
		return false;
	if (idx == n)
		return false;
	bool &ret = dp[idx][sum];
	if (vis[idx][sum] == VIS)
		return ret;
	vis[idx][sum] = VIS;
	if (idx == s)
		return ret = calc(idx + 1, sum);
	return ret = calc(idx + 1, sum) || calc(idx + 1, sum + arr[idx]);
}
bool can(int idx) {
	++VIS;
	s = idx;
	l = k - arr[idx];
	r = k - 1;
	return !calc(0, 0);
}
int main() {

	//freopen("myfile.in", "r", stdin);
