using namespace std;

int N, K;

bool sub(vector<int> &a, int m) {
	vector<vector<bool> > dp(K, vector<bool>(N, false)); //dp[y][x] : can one make y with {a[0], ..., a[x]} - {a[m]} ?
	for(int y = 0; y < K; ++y) {
		for(int x = 0; x < N; ++x) {
			if(y == 0) {
				dp[y][x] = true;
			} else if(x == 0) {
				if(x == m) {
					dp[y][x] = false;
				} else {
					dp[y][x] = (a[0] == y);
				}
			} else {
				if(x == m || y < a[x]) {
					dp[y][x] = dp[y][x - 1];
				} else {
					dp[y][x] = (dp[y][x - 1] || dp[y - a[x]][x - 1]);
				}
			}
			//cout << "dp[" << x << "][" << y << "] = " << dp[y][x] << '\n';
		}
	}
	bool is_necessary = false;
	for(int k = 1; k <= a[m] && k < K; ++k) {
		if(dp[K - k][N - 1]) {
			is_necessary = true;
		}
	}
	return is_necessary;
}

