	int L = 0, R = N - 1;
	int m = (L + R) / 2;
	nec[0].first = true;
	nec[0].second = sub(a, 0);
	if(nec[0].second) {
		cout << "0\n";
		return 0;
	}
	nec[N - 1].first = true;
	nec[N - 1].second = sub(a, N - 1);
	while(!(nec[m].first && nec[m + 1].first && !nec[m].second && nec[m + 1].second)) {
		//cout << "m = " << m << '\n';
		nec[m].first = true;
		nec[m].second = sub(a, m);
		if(nec[m].second) {
			R = m;
			m = (L + R) / 2;
		} else {
			L = m;
			m = (L + R) / 2;
		}
	}
	cout << R << '\n';

	return 0;
}

