        rep(i, n - 1) {
            rep(s, K + 1) {
                if(s - AA[i] >= 0)
                    dp[i + 1][s] = dp[i][s] | dp[i][s - AA[i]];
                else
                    dp[i + 1][s] |= dp[i][s];
            }
        }
        FOR(s, max(0,K - A[c]), K+1) {
            if(dp[n - 1][s]) {
                --ans;
                break;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

