bool LSI(Point p1,Point p2,Point q1,Point q2){
	if( (p2-p1).rot(q1-p1) * (p2-p1).rot(q2-p1) < 0 ){
		if( (q2-q1).rot(p1-q1) * (q2-q1).rot(p2-q1) < 0 ){
			return true;
