    for(int i = 0; i < (int)A2.size(); i++){
        for(int j = 0; j < K; j++){
            dp1[i + 1][j] |= dp1[i][j];
            if(dp1[i][j]){
                dp1[i + 1][min(K, j + A2[i])] |= 1;
            }
        }
    }
    dp2[(int)A2.size()][0] = 1;
    for(int i = (int)A2.size() - 1; i >= 0; i--){
        for(int j = 0; j < K; j++){
            dp2[i][j] |= dp2[i + 1][j];
            if(dp2[i + 1][j]){
                dp2[i][min(K, j + A2[i])] |= 1;
            }
        }
    }

    for(int i = 0; i < (int)A2.size(); i++){
        // [K - A2[i], K - 1] の範囲で値を探す
        int sums[5010] = {};
        for(int j = 0; j < K; j++){
            sums[j + 1] = sums[j] + dp1[i][j];
        }
        for(int j = 0; j < K; j++){
            if(dp2[i + 1][j]){
                // [K - A2[i] - j, K - 1 - j] の範囲で値を探す
                if(sums[K - j] - sums[max(0, K - A2[i] - j)] > 0){
                    ans++;
                    break;
                }
            }
        }
    }


    cout << N - ans << endl;

    return 0;
}

