int N, K;
int const NMAX = 5005;
bool dp1[NMAX][NMAX];
bool dp2[NMAX][NMAX];
int main() {
  cin >> N >> K;
  vector<int> a(N+1);
  for (int i=1; i<=N; i++) {
    cin >> a.at(i);
  }

  rep(i, NMAX) {
    rep(j, NMAX) {
      dp1[i][j] = false;
      dp2[i][j] = false;
    }
  }

  dp1[0][0] = true;
  dp2[0][0] = true;
  for (int i=1; i<=N; i++) {
    for (int j=K; j>=0; j--) {
      if (j >= a.at(i)) {
        dp1[i][j] = dp1[i - 1][j] || dp1[i - 1][j - a.at(i)];
      } else {
        dp1[i][j] = dp1[i-1][j];
      }
    }
  }
  for (int i=1; i<=N; i++) {
    for (int j=K; j>=0; j--) {
      if (j >= a.at(N-i+1)) {
        dp2[i][j] = dp2[i - 1][j] || dp2[i - 1][j - a.at(N-i+1)];
      } else {
        dp2[i][j] = dp2[i-1][j];
      }
    }
  }

  int ans = 0;
  for (int i=1; i<=N; i++) {
    bool found = false;
    if (a.at(i) >= K) {
      continue;
    }

    int pos2 = 0;
    for (int j=K-1; j>=0; j--) {
      if (dp1[i-1][j]) {
        for (int k=max(pos2, K-j-a.at(i)); k<=K-j-1; k++) {
          if (k < 0) {
            continue;
          }
          if (dp2[N-i][k]) {
            found = true;
            break;
          }
        }
        pos2 = K-j;
      }
      if (found) {
        break;
      }
    }

    if (!found) {
      ans++;
    }
  }
  cout << ans << endl;
}

