bool need(int index,int N,int K,const vector<ll>& a){
    vector<bool> e(K+1,false);
    e[0] = true;
    for(int i=0;i<N;i++){
        if(i==index) continue;
        for(int j=K;j>=0;j--){
            if(e[j] and j+a[i]<=K) e[j+a[i]]=true;
        }
    }
    for(int i=max<ll>(0,K-a[index]);i<K;i++) if(e[i]) return true;
    return false;
}

int main(){
    int N,K;
    cin >> N >> K;
    vector<ll> a(N);
    rep(i,N) cin >> a[i];
    sort(all(a));

    if(need(0,N,K,a)){
        cout << 0 << endl;
        return 0;
    }
    if(!need(N-1,N,K,a)){
        cout << N << endl;
        return 0;
    }

    int l,r;    // l : NG , r : OK
    l = -1;     // NG
    r = N-1;    // OK
    while(r-l>1){
        int mid=(l+r)/2;
        bool ret = need(mid,N,K,a);
        if(ret){
            r = mid;
        }else{
            l = mid;
        }
    }
    cout << l+1 << endl;
}

