  for (int i = N - 1; i >= 0; i--) {
    for (int j = K; j >= 0; j--) {
      //cout << i << ' ' << j << endl;
      if (j - A[i] >= 0 and dp_right[j - A[i]] and not dp_right[j]) {
        dp_right[j] = true;
        prev[j] = i;
      }
    }
  }
  dp_left.add(0, 1);

  int ans = 0;
  REP(i, N) {
    bool flag = true;
    for (int j = K; j >= 0; j--) {
      if (prev[j] == i) dp_right[j] = false;
      if (dp_right[j] and dp_left.sum(max(0, K - A[i] - j), K - j) > 0) {
        flag = false;
      }
    }
    if (flag) ans++;
    for (int j = K; j >= 0; j--) {
      if (j - A[i] >= 0 and dp_left.index(j - A[i]) == 1 and dp_left.index(j) == 0) {
