	for(j++; j < maxn; j += j & -j)
		loga[i][j] += v;
}

int query(int i, int j){
	if(j < 0) return 0;
	int ret = 0;
	for(j++; j > 0; j -= j & -j)
		ret += loga[i][j];
	return ret;
}

