vector<vector<bool>> dp(5010,vector<bool>(5010));

bool check(int p){
    if(v[p]>=k) return true;
    // without v[p], make x s.t. k-v[p]<=x<k
    // dp[i][j] := v[i]迄でjを作る
    for(int i=0;i<=n;i++){
        for(int j=0;j<=k;j++){
            dp[i][j]=false;
        }
        dp[i][0]=true;
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=k;j++){
            dp[i][j]=dp[i-1][j];
            if(i!=p && j-v[i]>=0){
                dp[i][j] =  dp[i][j] | dp[i-1][j-v[i]];
            }
        }
    }
    bool f=false;
    for(int i=max(0LL,k-v[p]);i<k;i++) f |= dp[n][i];
    return f;
}

