  for(int i=0;i<n;i++) u2[i][0]=true;

  for(int i=0;i<n;i++) {
    if (i!=0) {
      for(int j=0;j<k;j++) u[i][j]=u[i-1][j];
    }
    for(int j=k-1;j>=0;j--) {
      if (!u[i][j]) continue;
      if (j+a[i]>k) continue;
      u[i][j+a[i]]=true;
    }
  }

  for(int i=n-1;i>=0;i--) {
    if (i!=n-1) {
      for(int j=0;j<k;j++) u2[i][j]=u2[i+1][j];
    }
    for(int j=k-1;j>=0;j--) {
      if (!u2[i][j]) continue;
      if (j+a[i]>k) continue;
      u2[i][j+a[i]]=true;
    }
  }

  int an=n;
  for(int i=0;i<n;i++) {
    vector<int> v, v2;
    if (i==0) {
      for(int j=0;j<k;j++) if (u2[i+1][j]) v2.push_back(j);

      auto it = lower_bound(v2.begin(), v2.end(), k-a[i]);
      //cout<<*it<<endl;
      if (it != v2.end() && *it <= k-1) an--;
    } else if (i==n-1) {
      for(int j=0;j<k;j++) if (u[i-1][j]) v.push_back(j);

      auto it = lower_bound(v.begin(), v.end(), k-a[i]);
      if (it != v.end() && *it <= k-1) an--;
    } else {
      for(int j=0;j<k;j++) if (u[i-1][j]) v.push_back(j);
      for(int j=0;j<k;j++) if (u2[i+1][j]) v2.push_back(j);

      for(int x:v) {
        auto it = lower_bound(v2.begin(), v2.end(), k-a[i]-x);
        if (it != v2.end() && *it <= k-1-x) {an--; break;}
      }
    }
  }
  cout<<an<<endl;
}

