      for (auto k = K-1; k >= 0; --k) {
        if (memo[k] && k + a[j] < K) {
          memo[k + a[j]] = true;
        }
      }
    }
    for (auto j = K - a[i]; j < K; ++j) {
      if (memo[j]) {
        unneed = true;
        // cerr << "a[" << i << "] = " << a[i] << ", " << "j = " << j << endl;
        break;
      } 
    }
    if (unneed) ++ans;
  }
  cout << N - ans << endl;
}

