void run() {
	int N, K;
	cin >> N >> K;
	vector<int> a(N);
	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}
	std::sort(begin(a), end(a));

	int left = 0;
	int right = N;
	while (left < right) {
		int mid = (left + right) / 2;
		bool check = false;

		vector<bool> dp(K, false);
		dp[0] = true;
		REP(i, N) {
			if (i == mid) continue;
			for (int j = K - 1; j >= 0; j--) {
				if (dp[j] && (j + a[i]) < K)
					dp[j + a[i]] = true;
			}
		}

		FOR(j, max(0, K - a[mid]), K) {
			if (dp[j]) {
				check = true;
				break;
			}
		}

		if (check) right = mid;
		else left = mid + 1;
	}

	cout << right << endl;

}

