typedef long long ll;

bool dp[5010][5010];

int main() {

    ll N,K; cin >> N >> K;
    vector<ll> a(N);
    REP(i,N) cin >> a[i];

    REP(i,5010)REP(j,5010) dp[i][j] = false;
    REP(i,N) {
        if(i != 0) {
            RREP(j,5010) {
                if(j - a[i] >= 0) {
                    if(dp[i][j-a[i]]) dp[i][j] = true;
                }
            }
        }
        dp[i][a[i]] = true;
    }

    int ans = 0;
    REP(i,N) {
        if(a[i] >= K) {
            ans++;
            goto nextf;
        } else {
            for(ll j=K-a[i]; j<K; j++) {
                if(dp[N-1][j]) {
                    ans++;
                    goto nextf;
                }
            }
        }
    nextf:;
    }

    cout << N - ans << endl;

    return 0;
}

