#include <iostream>
#define maxn 5009
using namespace std;
int a[maxn];
bool dp[maxn][maxn];
int main(){
	int n,k;
	scanf("%d%d", &n, &k);
	int m = 0;
	for(int i = 1; i <= n; i++){
		int x;
		scanf("%d", &x);
		if(x >= k)
			continue;
		a[++m] = x;
	}
	sort(a + 1, a + m + 1);
	dp[m + 1][0] = 1;
	for(int i = m; i >= 1; i--){
		for(int j = 0; j <= k; j++){
			dp[i][j] = dp[i + 1][j];
			if(j >= a[i])
				dp[i][j] |= dp[i + 1][j - a[i]];
		}
	}
	int ans = 0;
	int sum = 0;
	for(int i = 1; i <= m; i++){
		int x = 0;
		for(int j = k - 1; j >= 0; j--){
			if(dp[i + 1][j]){
				x = j;
				break;
			}
		}
		if(x + sum < k - a[i]){
			ans++;
		}
		sum += a[i];
	}
	cout << ans << endl;
	return 0;
}

