typedef long long ll;
set<int> DP[5001];

int main()
{
	int N, K; cin >> N >> K;
	vector<ll>a(N);
	vector<bool>b(N);

	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}
	sort(a.begin(), a.end());
	reverse(a.begin(), a.end());

	for (int i = 0; i < N; i++) {
		if (a[i] >= K) {
			b[i] = true;
			continue;
		}
		for (int j = K-1; i && j >= a[i-1]; j--) {
			if (DP[j].size() != 0) {
				if (j + a[i] >= K) {
					while(DP[j].size()){
						if (*DP[j].begin() == -1) {
							DP[j].erase(DP[j].begin());
							continue;
						}
						b[*DP[j].begin()] = true;
						DP[j].erase(DP[j].begin());
					}
					b[i] = true;
					DP[j].insert(-1);
					break;
				}
				else {
					for (auto itr = DP[j].begin(); itr != DP[j].end(); ++itr) {
						DP[j + a[i]].insert(*itr);
					}
					DP[j + a[i]].insert(i);
					break;
				}
			}
		}
		DP[a[i]].insert(i);
	}

	int ans = 0;
	for (int i = 0; i < N; i++)if (b[i] == false) {
		ans++;
	}
	cout << ans << endl;

    return 0;
}

