    if(i==n-1){
      for(int x=max(k-a[i],0);x<k;x++){
        if(dpf[n-2][x]){
          ans--;
          break;
        }
      }
    }

    bool flag=false;
    for(int x=max(k-a[i],0);x<k;x++){
      for(int y=0;y<=x;y++){
        if(dpf[i-1][y] && dpe[i+1][x-y]){
          ans--;
          flag = true;
          break;
        }
      }
      if(flag){
        flag = false;
        break;
      }
    }
  }
  cout<<ans<<endl;
  return 0;
}

