template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;

struct nap
{
	std::set<int> flags;
	int target;
	std::vector<int> const& search;
	nap(int t, std::vector<int> const&s) :flags{}, target(t), search(s)
	{
		flags.emplace(0);
	}

	bool run(int index, int K)
	{
		if (index == target)
		{
			return run(index + 1, K);
		}
		if (index == search.size())
		{
			return flags.size() != 0 && *(flags.rbegin()) + search[target] >= K;
		}
		std::set<int> next;
		for (auto v : flags)
		{
			if (v + search[index] < K)
			{
				next.emplace(v + search[index]);
			}
		}
		flags.insert(next.begin(), next.end());
		return run(index + 1, K);
	}
};

int main()
{
	int N, K;
	std::cin >> N >> K;
	int count{};
	std::vector<int> vec(N);
	for (auto& v : vec)
	{
		std::cin >> v;
	}

	for (int i{}; i < N; ++i)
	{
		nap n{ i,vec };
		count += !n.run(0, K);
	}

	std::cout << count << std::endl;
}

