struct Num {
	int x, y, z;
	Num(int val = 0) {
		x = val, y = val, z = val;
	}
	Num operator + (const Num & t) {
		Num res;
		res.x = x + t.x;
		if (res.x >= MOD[0]) res.x -= MOD[0];
		res.y = y + t.y;
		if (res.y >= MOD[1]) res.y -= MOD[1];
		res.z = z + t.z;
		if (res.z >= MOD[2]) res.z -= MOD[2];
		return res;
	}
	Num operator - (const Num & t) {
		Num res;
		res.x = x - t.x;
		if (res.x < 0) res.x -= MOD[0];
		res.y = y - t.y;
		if (res.y < 0) res.y -= MOD[1];
		res.z = z - t.z;
		if (res.z < 0) res.z -= MOD[2];
		return res;
	}
	bool operator == (const Num & t) {
		return x == t.x && y == t.y && z == t.z;
	}
};

int n, k, a[N];
Num dp[N];

void add(int x) {
	for (int i = k - 1; i >= x; i--)
		dp[i] = dp[i] + dp[i - x];
}

void del(int x) {
	for (int i = x; i < k; i++)
		dp[i] = dp[i] - dp[i - x];
}

