		for(int j = 0; j <= k-1; j++){
			if(!ldp[i-1][j]) continue;
			llint l = max(0LL, k-a[i]-j), r = k-1-j;
			llint s = sum[r];
			if(l > 0) s -= sum[l-1];
			if(s > 0){
				ans++;
				break;
			}
		}
	}

	cout << n-ans << endl;

	return 0;
}

