namespace FFT {
struct comp {
  double x, y;

  inline comp() {}
  inline comp(const double &a, const double &b) : x(a), y(b) {}
  inline comp operator+(const comp &o) { return comp(x + o.x, y + o.y); }
  inline comp operator-(const comp &o) { return comp(x - o.x, y - o.y); }
  inline comp operator*(const comp &o) {
    return comp(x * o.x - y * o.y, x * o.y + y * o.x);
  }
};

int n, m;
comp a[N], b[N];
int bitrev[N];
int len, d;

void fft(comp *y, int op) {
  for (int i = 0; i < len; i++) {
    if (i < bitrev[i]) swap(y[i], y[bitrev[i]]);
  }

  for (int h = 2; h <= len; h <<= 1) {
    comp wn(cos(2 * PI / h), op * sin(2 * PI / h));
    for (int i = 0; i < len; i += h) {
      comp w(1, 0);
      for (int j = i; j < i + h / 2; j++) {
        comp u = y[j], v = w * y[j + h / 2];
        y[j] = u + v, y[j + h / 2] = u - v;
        w = w * wn;
      }
    }
  }

  if (op == -1) {
    for (int i = 0; i < len; i++) y[i].x /= len;
  }
}

void init() {
  n = k, m = k;
  len = 1;
  while (len < (n + m - 1)) len <<= 1, d++;
  for (int i = 0; i < len; i++) {
    bitrev[i] = (bitrev[i >> 1] >> 1) | ((i & 1) << (d - 1));
  }
}
int solve(bitset<N> &l, bitset<N> &r, int curv) {
  for (int i = 0; i <= len; i++) a[i].x = 0, a[i].y = 0, b[i].x = 0, b[i].y = 0;
  for (int i = 0; i < n - 1; i++) a[i].x = l.test(i);
  for (int i = 0; i < m; i++) b[i].x = r.test(i);
  fft(a, 1), fft(b, 1);
  for (int i = 0; i < len; i++) a[i] = a[i] * b[i];
  fft(a, -1);
  // for (int i = 0; i <= len; i++) cout << (int)round(a[i].x);
  for (int i = k - curv; i < k; i++)
    if ((int)round(a[i].x)) return 1;
  return 0;
}
}

