void insertionSort(int g) {
	for (int i = g; i < N; i++) {
		int v = A[i];
		int j = i - g;

		while (j >= 0 && A[j] > v) {
			A[j + g] = A[j];
			j -= g;
		}
		A[j + g] = v;
	}
}

void shellSort() {
	vector<int>G; G.reserve(10);
	for (int h = 1;;) {
		if (h > N)break;
		G.push_back(h);
		h = 3 * h + 1;
	}

	for (int i = G.size() - 1; i >= 0; i--) {
		insertionSort(G[i]);
	}
}

int BinarySearch(int max, int right) {
	int l = 0, r = right;

	while(A[r - 1] < max) {
		--r;
		max -= A[r];
		if (r == 0)return right;
	}

	int m;
	while (l < r) {
		m = (l + r) / 2;

		if (A[m] < max)l = m+1;
		else r = m;
	}

	if (r == 0)return 0;

	return BinarySearch(max, r);
}

