{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> K;
	for (int i = 0; i < N; i++) {
		cin >> A[i];
	}
	shellSort();

	cout << BinarySearch(K, N) << endl;

    return 0;
}

