bool check(int idx) {   //不必要ならばtrue
    LL sum = a[idx];
    if (cnt[a[idx]] * a[idx] >= K) {
         return false;
    }
    int moveIdx = idx + 1;
    int equalCnt = 0;
    while (sum < K && moveIdx < N + 1) {
        if (a[idx] != a[moveIdx]) {
            sum += a[moveIdx++];
        } else {
            ++equalCnt;
            ++moveIdx;
            if (sum + a[idx] >= K) {
                return false;
            }
        }
    }
    moveIdx = 0;
    while (sum < K && moveIdx < idx) {
        if (a[idx] != a[moveIdx]) {
            sum += a[moveIdx++];
        } else {
            ++equalCnt;
            ++moveIdx;
            if (sum + a[idx] >= K) {
                return false;
            }
        }
    }
    //DEBUG(equalCnt)
    if (sum < K) {
        if (sum + equalCnt * a[idx] >= K) {
            return false;
        } else {
            return true;
        }
    }
    return sum - a[idx] >= K;
}

