bool bubunwa(int x, const vector<int> &A) {
	int N = A.size();
	vector<int> dp(x, -1);
	dp[0] = 0;
	int ma = 0;
	for (int i = 0; i < N; i++) {
		for (int j = ma; j >= 0; j--) {
			if (dp[j] != -1) {
				int jai = j + A[i];
				if (jai < x && dp[jai] == -1) {
					dp[jai] = i;
					if (jai > ma) ma = jai;
				}
				if (jai == x) {
					return true;
				}
			}
		}
	}
	return false;
}

ll solve() {
	int n = ri(), k = ri();

	vector<int> A(n);
	rep(i, n) A[i] = ri();

	sort(all(A));
	out(n, k, A);

	vi C(k);
	int oc = 0;
	forr(a, A) {
		if (a >= k) {
			oc++;
		}
		else {
			C[a]++;
		}
	}
	out(A, C);

	int m = n - oc;
	out(m, A);

	auto check = [&](int mid) -> bool {
		vi Z;
		rep(i, m) if (i != mid) Z.emplace_back(A[i]);
		rep(x, max(0, k-A[mid]), k) {
			if (bubunwa(x, Z)) {
				return true;
			}
		}
		return false;
	};

	int ok = m;
	int ng = -1;

	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		out(ok, ng, mid, A[mid]);
		C[A[mid]]--;
		bool c = check(mid);
		C[A[mid]]++;
		out(ok, ng, mid, A[mid], c);
		if (c) ok = mid;
		else ng = mid;
	}

	return ok;
}

void Main() {
	cout << solve() << endl;
}

