#include <bits/stdc++.h>
using namespace std;
#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)
typedef long long ll;

const int MAX_N=5e3,MAX_K=5e3;

int N,K,A[MAX_N];

bool dp[MAX_N+1][MAX_K+1];

bool C(int x){
	fill(dp[0],dp[0]+K+1,false);
	dp[0][0]=true;
	REP(j,N){
		fill(dp[j+1],dp[j+1]+K+1,false);
		int a;
		if (x==j){
			a=0;
		}else{
			a=A[j];
		}
		REP(k,K+1){
			dp[j+1][k]|=dp[j][k];
			dp[j+1][min(k+a,K)]|=dp[j][k];
		}
	}
	FOR(j,max<ll>(K-A[x],0LL),K){
		if (dp[N][j]){
			return false;
		}
	}
	return true;
}

void solve(){
	ll sum=0;
	REP(i,N){
		sum+=A[i];
	}
	if (sum<K){
		cout<<N<<endl;
		return;
	}
	sort(A,A+N);
	int lb=0,ub=N;
	while(ub-lb>1){
		int mid=(lb+ub)/2;
		if (C(mid)){
			lb=mid;
		}else{
			ub=mid;
		}
	}
	cout<<ub<<endl;
}

int main(){
	cin>>N>>K;
	REP(i,N){
		cin>>A[i];
	}
	solve();
	return 0;
}

