using namespace std;
int N, K;
int a[5000];

bool is_needed(int i){

   if(a[i]>=K) return true;

   int memo[N+1][K];
   for(int j=0; j<N+1; j++)for(int k=0; k<K; k++) memo[j][k]=0;
   memo[0][0]=1;
   for(int j=0; j<N; j++){
      for(int k=0; k<K; k++){
         memo[j+1][k]|=memo[j][k];
         if(i!=j and k+a[j]<K) memo[j+1][k+a[j]]|=memo[j][k];
      }
   }
   bool need=false;
   for(int k=K-a[i]; k<K; k++) need|=memo[N][k];

   return need;
}

int main(){

   cin>> N>> K;
   for(int i=0; i<N; i++) cin>> a[i];

   int l=0, u=N;
   while(u-l>1){
      int m=(u+l)/2;
      if(is_needed(m)) u=m;
      else l=m;
   }

   cout<< l+1<< endl;

   return 0;
}

