vector<vector<int> > ccp;
int dpp(int n, int k) {
    if(n == -1) return k == 0;
    int &ret = ccp[n][k];
    if(ret != -1) return ret;

    return ret = (arr[n] <= k && dpp(n - 1, k - arr[n])) | dpp(n - 1, k);
}
vector<vector<int> > ccs;
int dps(int n, int k) {
    if(n == N) return k == 0;
    int &ret = ccs[n][k];
    if(ret != -1) return ret;

    return ret = (arr[n] <= k && dps(n + 1, k - arr[n])) | dps(n + 1, k);
}
struct BIT {
    int tree[20002];
    void init() {
        memset(tree, 0, sizeof(tree));
    }
    void upd(int idx, int val, int l, int r, int n) {
        if(idx < l || r < idx) return;
        if(l == r) {
            tree[n] = val;
            return;
        }
        int m = (l + r)>>1;
        upd(idx, val, l, m, 2*n);
        upd(idx, val, m + 1, r, 2*n + 1);
        tree[n] = tree[2*n] | tree[2*n + 1];
    }
    int quer(int a, int b, int l, int r, int n) {
        if(b < l || r < a) return 0;
        if(a <= l && r <= b) return tree[n];
        int m = (l + r)>>1;
        int L = quer(a, b, l, m, 2*n);
        int R = quer(a, b, m + 1, r, 2*n + 1);
        return L | R;
    }
};
BIT B[5002];

