    for(int i = 0; i < N; i++) {
        B[i].init();
        for(int j = 0; j < K; j++) B[i].upd(j, dps(i, j), 0, K - 1, 1);
    }
    int cnt = N;
    for(int i = 0; i < N; i++) {
        int lb = max(0, K - arr[i]);
        for(int j = 0; j < K; j++) {
            if(j == 0 || (i != 0 && dpp(i - 1, j))) if(max(0, lb - j) == 0 || (i != N - 1 && B[i + 1].quer(lb - j, K - 1 - j, 0, K - 1, 1))) {
                cnt--;
                break;
            }
        }
    }
    printf("%d", cnt);
}

