			for(ll k=K-1; k>=0; k--){
				dp[min(k+a[j],K)] = dp[k] || dp[min(k+a[j],K)];
			}
		}
		bool flag = false;
		REP(j,max(K-a[i],1LL),K){
			if(dp[j]){
				flag = true;
				break;
			}
		}
		if(!flag) ans++;
	}
	cout << ans << endl;
}

