int main(){

    int ans, maxn;
    int i, j, p1, p2;
    SCC(n, k);
    int big = 0;
    int num = 0;
    FF(i, 1, n){
        SC(a[++num]);
        if(a[i] >= k){
            ++big;
            --num;
        }
    }
    f[0][0] = 1;
    FF(i, 1, num){
        FF(j, 0, k - a[i]){
            if(f[i - 1][j])f[i][j + a[i]] = 1;
        }
        FF(j, 0, k)if(f[i - 1][j])f[i][j] = 1;
    }
    for(i = 0; i <= num + 1; ++i)
        g[i][0] = 1;
