        FF(j, 0, k - a[i]){
            if(g[i + 1][j])g[i][j + a[i]] = 1;
        }
        FF(j, 0, k)if(g[i + 1][j])g[i][j] = 1;
    }

    ans = big;

    for(i = 1; i <= num; ++i)
    {
        p2 = k - 1;
