bool isneed(VL a, ll x, ll k){
    if (x >= k) return true;
    int n = a.size();
    VVL dp(n+1, VL(k+1));
    dp[0][0] = 1;
    REP(i,n){
        REP(j,k){
            dp[i+1][j] |= dp[i][j];
            if (j + a[i] <= k) dp[i+1][j+a[i]] |= dp[i][j];
        }
    }
    bool f = false;
    FOR(j,k-x,k-1) f |= dp[n][j];
    // printf("check %d, %d\n", x, f);
    // REP(i,n) cout << a[i] << " ";
    // cout << endl;
    // REP(j,k+1) cout << dp[n][j] << " ";
    // cout << endl;
    return f;
}

int main() {
    int n;
    ll k;
    cin >> n >> k;
    VL a(n);
    REP(i,n) scanf("%lld", &a[i]);
    if (n == 1){
        int ans = 1;
        if (a[0] >= k) ans = 0;
        cout << ans << endl;
        return 0;
    }
    sort(ALL(a));
    int l = -1, h = n;
    while (h - l > 1){
        int m = (h+l)/2;
        VL b(a);
        b.erase(b.begin()+m);
        if (isneed(b, a[m], k)) h = m;
        else l = m;
    }
    cout << l+1 << endl;
    return 0;
}

