        if (k == 0) memo_l[n][k] = 1;
        else if (n == 0) memo_l[n][k] = 0;
        else {
            memo_l[n][k] = memo_l[n-1][k];
            if (ar[n] <= k) memo_l[n][k] = max(memo_l[n][k], memo_l[n-1][k-ar[n]]);
        }
    }

    for (int k = 0; k <= K; ++k) for (int n = 1; n <= N+1; ++n) {
        if (k == 0) memo_r[n][k] = 1;
        else if (n == N+1) memo_r[n][k] = 0;
        else {
            memo_r[n][k] = memo_r[n+1][k];
            if (ar[n] <= k) memo_r[n][k] = max(memo_r[n][k], memo_r[n+1][k-ar[n]]);
        }
    }

    for (int n = 1; n <= N+1; ++n) for (int k = 1; k <= K; ++k)
        memo_r[n][k] += memo_r[n][k-1];

    int ans = 0;
    for (int n = 1; n <= N; ++n) {
