int n,k,a[10005],b[10005];
bool dpa[5005][5005],dpb[5005][5005],aa[5005][5005],bb[5005][5005],temp[5005],tem2[5005];
int main(){
	scanf("%d%d",&n,&k);
	int xb,x2;
	for(xb=0;xb<n;xb++) {
		scanf("%d",&a[xb]);
		a[xb]=MIN(a[xb],k);
	}
	memcpy(b,a,sizeof(a));
	reverse(b,b+n);
	dpa[0][a[0]]=1;
	dpa[0][0]=1;
	for(xb=1;xb<n;xb++){
		for(x2=0;x2<k;x2++){
			dpa[xb][x2]=dpa[xb-1][x2];
			if(x2>=a[xb]){
				dpa[xb][x2]|=dpa[xb-1][x2-a[xb]];
			}
		}
		dpa[xb][k]=dpa[xb-1][k];
		for(x2=0;x2<k;x2++){
			if(x2+a[xb]>=k) dpa[xb][k]|=dpa[xb-1][x2];
		}
	}
	dpb[0][b[0]]=1;
	dpb[0][0]=1;
	for(xb=1;xb<n;xb++){
		for(x2=0;x2<k;x2++){
			dpb[xb][x2]=dpb[xb-1][x2];
			if(x2>=b[xb]){
				dpb[xb][x2]|=dpb[xb-1][x2-b[xb]];
			}
		}
		dpb[xb][k]=dpb[xb-1][k];
		for(x2=0;x2<k;x2++){
			if(x2+b[xb]>=k) dpb[xb][k]|=dpb[xb-1][x2];
		}
	}
	int cnt=0;
	memcpy(aa,dpa,sizeof(dpa));
	memcpy(bb,dpb,sizeof(dpb));
	for(xb=0;xb<n;xb++){
		for(x2=k-3;x2>=0;x2--){
			dpa[xb][x2]|=dpa[xb][x2+1];
			dpb[xb][x2]|=dpb[xb][x2+1];
		}
	}
	for(xb=0;xb<n;xb++){
		int tar=MAX(0,k-a[xb]);
		if(xb==0){
			if(!dpb[n-2][tar]) cnt++;
			continue;
		}
		if(xb==n-1){
			if(!dpa[n-2][tar]) cnt++;
			continue;
		}
		memset(temp,0,sizeof(temp));
		bool *sor=bb[n-2-xb];
		int CNT=0;
		for(x2=0;x2<a[xb];x2++) CNT+=sor[x2];
		if(CNT) temp[0]=1;
		for(x2=1;x2+a[xb]<=k;x2++){
			CNT-=sor[x2-1];
			CNT+=sor[x2+a[xb]-1];
			if(CNT) temp[x2]=1;
		}
		// F: k-a[xb]-v~~~~k-1-v 
		bool ok=1;
		for(x2=0;x2<=k-a[xb];x2++){
			if(aa[xb-1][x2]&&temp[k-a[xb]-x2]){
				ok=0;
				break;
			}
		}
		if(ok){
			bool got=0;
			for(x2=k-1;x2>=k-a[xb]+1;x2--){
				got|=sor[k-1-x2];
				if(aa[xb-1][x2]&&got){
					ok=0;
					break;
				}
			}
		}
		if(ok)cnt++;
	}
	printf("%d\n",cnt);
	return 0;
}

