int N, K, lowerThanK;
int v[5005];
bitset <5005> dp;

bool unnecessary(int pos)
{
    if(v[pos] >= K) return false;

    dp.reset();
    dp[0] = 1;
    for(int i = 1; i <= N; i++)
    {
        if(i == pos)    continue;
        for(int j = K; j >= v[i]; j--)
            if(dp[j - v[i]])
                dp[j] = 1;
    }

    for(int i = K - 1; i >= K - v[pos]; i--)
        if(dp[i])
            return false;
    return true;
}

int main()
{
    #ifdef FILE_IO
    freopen("1.in", "r", stdin);
    freopen("1.out", "w", stdout);
    #endif

    scanf("%d%d", &N, &K);
    for(int i = 1; i <= N; i++)
        scanf("%d", &v[i]);
    sort(v + 1, v + N + 1);

    int p = 1;
    int u = N;
    int ans = 0;
    while(p <= u)
    {
        int mij = p + (u - p) / 2;

        if( unnecessary(mij) )
        {
            ans = mij;
            p = mij + 1;
        }
        else
            u = mij - 1;
    }

    printf("%d\n", ans);

    return 0;
}

