        dp1[i][min(k, j+a[i-1])] |= dp1[i-1][j] & ~bitset<5000>(1<<(i-1));
      }
    }
  }

  vector<vector<bitset<5000>>> dp2(n+1, vector<bitset<5000>>(k+1));
  FOR(i, 1, n+1) {
    REP(j, k+1) {
      if(j == 0 || dp2[i-1][j] != bitset<5000>(0)) {
        dp2[i][j] |= dp2[i-1][j];
        dp2[i][min(k, j+a[i-1])] |= dp2[i-1][j] | bitset<5000>(1<<(i-1));
      }
    }
  }

  int cnt = 0;
  REP(i, n) {
    FOR(j, k-a[i], k) {
      if(dp1[n][j][i]) {
        cnt++;
        break;
      }
    }
  }
  cout << cnt << endl;

  // cout << dp1[n][k] << endl;
  // cout << dp2[n][k] << endl;

  // cout << dp[n][k] << endl;
  // cout << (dp2[n][k] & ~dp1[n][k]).count() << endl;
}

