int answer() {
	if (accumulate(a, a + N, 0ll) < K)
		return N;

	sort(a, a + N);
	vis[0] = true;
	int ans = N;
	for (int i = N - 1; i >= 0; i--) {
		for (int j = max(0, K - a[i]); j < K; j++) {
			if (vis[j]) {
				ans = i;
				break;
			}
		}
		for (int j = K - a[i] - 1; j >= 0; j--)
			vis[j + a[i]] |= vis[j];
	}
	return ans;
}

