	for(int i = 1;i <= k;i++)dp[i] = dp2[n-mid][i];
	for(int i = 1;i <= k;i++){
		if(dp1[mid-1][i] == 0)continue;
		int x = i;
		for(int j = k;j >= 1;j--){
			if(j-x >= 0)dp[j] += dp2[n-mid][j-x];
			dp[j] = !!dp[j];
		}
	}
	for(int i = k;i >= 1;i--)dp[i] += dp[i+1];
	if(dp[k-a[mid]] > 0)return 1;
	return 0;
