signed main() {
    int N, K;
    cin >> N >> K;
    vi A(N);
    cin >> A;

    vector<bitset<5003>> dpl(N), dpr(N);
    dpl[0] = bitset<5003>(1) << A[0];
    dpr[N - 1] = bitset<5003>(1) << A[N - 1];
    REPF(i, 1, N) dpl[i] = dpl[i - 1] | (dpl[i - 1] << A[i]);
    REPR(i, N - 2) dpr[i] = dpr[i + 1] | (dpr[i + 1] << A[i]);

    int ans = N;
    REP(i, N) {
        bitset<5003> tmp(1);
        if (i < N - 1) tmp = dpr[i + 1];

        vi sum(5003, 0);
        sum[0] = 1;
        REPF(j, 1, 5003) {
            sum[j] = sum[j - 1];
            if (tmp[j]) {
                sum[j]++;
            }
        }

        tmp = bitset<5003>(1);
        if (i > 0) tmp = dpl[i - 1];

        bool found = false;
        REP(j, K) {
            if (tmp[j]) {
                int r = K - j - 1;
                int l = max(0LL, K - A[i] - j);
                if (sum[r] - (l > 0 ? sum[l - 1] : 0) > 0) {
                    found = true;
                    break;
                }
            }
        }
        if (found) {
            ans--;
        }
    }
    cout << ans << endl;
    return (0^_^0);
