void solve(){
	int N;//カード枚数
	int K;//閾値
	cin >> N >> K;

	vector<LL> A(N);
	for(int i=0;i<N;++i){
		cin >> A[i];
	}
	sort(A.begin(),A.end());
	LL sum = 0;
	int pos = 0;
	while(pos < N && sum < K ){
		sum += A[pos];
		++pos;
	}

	if( pos >= N ){
		if( sum < K ){
			cout << N << endl;return;
		}else{
			cout << 1 << endl;return;
		}
	}
	int ans = 0;
	int L = 0;//K>=1
	int R = N-1;
	int Mid;
	while(R-L>1){//使わない数index
		Mid = (L+R)/2;
		if( K<=A[Mid] ){
			R = Mid;
			continue;
		}

		vector< bool > dp(K+1,false);
		dp[0] = true;
		for(int i=0;i<N;++i){
			if( i == Mid ) continue;
			for(int j=K;j>=0;--j){
				if( dp[j] == false)continue;
				if( A[i] + j > K ) continue;
				dp[(int)(A[i]+j)] = true;
			}
		}
		bool flag = false;

		for(int in=K-(int)A[Mid];in<K;++in){
			if( dp[in] ){
				flag = true;
				break;
			}
		}
		if( flag == false ){
			L = Mid;
			++ans;
		}else{
			R = Mid;
		}
	}

	cout << Mid << endl;
}

