bool check(int c, int K, const vector<int> &a) {
	memset(dp, 0, sizeof(dp));

	dp[0] = true;
	for(int i = 0; i < a.size(); ++i) {
		if(i == c) continue;
		for(int j = K; j >= 0; --j) {
			dp[j] |= dp[j - a[i]];
		}
	}

	//cout << a[c] << ":";
	//for(int i = 0; i <= K; ++i) cout << dp[i];
	//cout << endl;
	for(int i = max(K - a[c], 0LL); i < K; ++i) {
		if(dp[i]) return true;
	}
	return false;
}

