int n, k;
vi a;

bool core(int key) {
	if (a[key] >= k) return true;
	vector<bool> dp(k, false), dp2(k, false);
	dp[0] = true;
	Loop(i, n) {
		Loop(j, k) {
			if (dp[j]) {
				dp2[j] = true;
				if (i != key && j + a[i] < k) {
					dp2[j + a[i]] = true;
				}
			}
		}
		dp = dp2;
	}
	for (int j = k - a[key];j < k;++j) {
		if (dp[j]) return true;
	}
	return false;
}

int binary_search(int left, int right) {
	if (left + 1 >= right) return left;
	int mid = (left + right) / 2;
	int judge = core(mid);
	if (judge) return binary_search(left, mid);
	else return binary_search(mid, right);
}

int main() {
	cin >> n >> k;
	a.resize(n);
	Loop(i, n) cin >> a[i];
	sort(a.begin(), a.end());
	//[left, right)は、不必要なもののうち最大のものを含む
	bool judge; //必要ならtrue
	int k = binary_search(0, n);
	int ans;
	if (k == 0) {
		if (core(0)) ans = 0;
		else ans = 1;
	}
	else {
		ans = k + 1;
	}
	cout << ans << endl;
	return 0;
}

