		for (int j = 0; j <= k-1; j++){
			if (pr[j]){
				int lef = need - j;
				int rig = k - 1 - j;
				lef = max(lef, 0);
				int F = im[rig];
				if (lef)F -= im[lef - 1];
				if (F){
					ok = true;
				}
			}
		}
		if (ok==false){
			ans++;
		}
	}
	cout << ans << endl;
	return 0;
}

