    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; i++) scanf("%d", a + i);
    sort(a + 1, a + n + 1);
    for (; a[n] >= k; n--) { }

    dp[0][0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < k; j++) dp[0][i][j] = dp[0][i - 1][j];
        for (int j = a[i]; j < k; j++) dp[0][i][j] |= dp[0][i - 1][j - a[i]];
    }
    dp[1][n + 1][0] = 1;
    for (int i = n; i >= 1; i--) {
        for (int j = 0; j < k; j++) dp[1][i][j] = dp[1][i + 1][j];
        for (int j = a[i]; j < k; j++) dp[1][i][j] |= dp[1][i + 1][j - a[i]];
    }

    for (int i = 0; i <= n; i++)
        for (int j = 0; j < k; j++)
            if (dp[0][i][j]) vc[i].emplace_back(j);

    for (int i = 1; i <= n; i++)
        for (int j = 0; j < k; j++)
            if (dp[1][i + 1][j]) {
                int en = upper_bound(vc[i - 1].begin(), vc[i - 1].end(),
                                     k - j) - 1 - vc[i].begin();
                int st = lower_bound(vc[i - 1].begin(), vc[i - 1].end(),
                                     k - a[i] - j) - vc[i].begin();
