using namespace std;

int N, K;
vector<int> arr;

int currNum;
short memo[5005][5005];

short dp(int currN, int currSum)
{
	if(memo[currN][currSum] != -1)
		return memo[currN][currSum];

	if(currN == 0)
	{
		memo[currN][currSum] = (K - currNum <= currSum && currSum < K);
		return memo[currN][currSum];
	}

	memo[currN][currSum] = dp(currN - 1, currSum);
	if(currSum + arr[currN] < K)
		memo[currN][currSum] = max(memo[currN][currSum], dp(currN - 1, currSum + arr[currN]));

	return memo[currN][currSum];
}

void printMemo()
{
	for(int i = 0; i < N + 5; i++)
	{
		for(int j = 0; j < K + 5; j++)
			printf("memo[%d][%d] = %d\n", i, j, (int)(memo[i][j]));
	}
}

short isNecessary(int pos)
{
	currNum = arr[pos];
	//printf("arr[%d] = %d\n", pos, currNum);

	arr.erase(arr.begin() + pos);

	for(int i = 0; i < N + 5; i++)
	{
		for(int j = 0; j < K + 5; j++)
			memo[i][j] = -1;
	}

	short ans = dp( (int)(arr.size()) - 1, 0);
	arr.insert(arr.begin() + pos, currNum);

	//printMemo();
	//printf("\n");

	return ans;
}

int main()
{
	scanf("%d%d", &N, &K);

	arr.push_back(0);

	long long sum = 0;
	for(long long i = 1; i <= N; i++)
	{
		int ai;
		scanf("%d", &ai);
		arr.push_back(ai);

		sum += ai;
	}

	if(sum < (long long)(K) )
	{
		printf("%d", N);
		return 0;
	}

	sort(arr.begin(), arr.end());

	int startPtr = 1, endPtr = N, ans = 0;
	while(startPtr <= endPtr)
	{
		int mid = startPtr + (endPtr - startPtr) / 2;
		int necessary = isNecessary(mid);

		if(necessary)
			endPtr = mid - 1;

		else
		{
			startPtr = mid + 1;
			ans = mid;
		}
	}

	printf("%d", ans);
}

