using namespace std;
int dp[5005][5005];
int fn[5005][5005];
int a[5555];

int main() {
    ios_base :: sync_with_stdio (false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;

    int ans = 0;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
    }

    dp[0][0] = 1;
    for(int i = 1; i <= n; i++) {
        for(int j = 0; j <= k; j++) {
            dp[i][j] |= dp[i - 1][j];
            if(j >= a[i]) dp[i][j] |= dp[i - 1][j - a[i]];
        }
    }
    fn[n + 1][0] = 1;
    for(int i = n; i >= 1; i--) {
        for(int j = 0; j <= k; j++) {
            fn[i][j] |= fn[i + 1][j];
            if(j >= a[i]) fn[i][j] |= fn[i + 1][j - a[i]];
        }
    }
    for(int i = 1; i <= n; i++) {
        bool good = false;
        for(int j = 0; j <= k; j++) {
            if(dp[i - 1][j] == 0) continue;
            for(int x = 0; x <= k; x++) {
                if(fn[i + 1][x] == 0) continue;
                int s = j + x;
                if(k - a[i] <= s && s < k) {
                    good = true;
                    break;
                }
            }
            if(good) break;
        }
        ans += good;
    }
    ans = n - ans;
    cout << ans << endl;
    return 0;
}

