uint64_t buf[80];
void shift_or(int n) {
	int big = n >> 6;
	int small = n & 63;
	if (small) {
		int ismall = 64 - small;
		for (int i = 78 - big; i >= 0; i--) {
			uint64_t cur = buf[i];
			buf[i + big] |= cur << small;
			buf[i + big + 1] |= cur >> ismall;
		}
	} else {
		for (int i = 78 - big; i >= 0; i--)
			buf[i + big] |= buf[i];
	}
}

int main() {
	int n = ri(), k = ri();
	int a[n];
	for (int i = 0; i < n; i++) a[i] = ri();
	int cnt = 0;
	uint64_t bak[80] = { 0 };
	buf[0] = 1;
	bak[0] = 1;
	for (int i = 0; i < n; i++) {
		if (i) {
			memcpy(buf, bak, sizeof(buf));
			shift_or(a[i - 1]);
			memcpy(bak, buf, sizeof(buf));
		}
		memcpy(buf, bak, sizeof(buf));
		for (int j = i + 1; j < n; j++) shift_or(a[j]);
		for (int j = std::max(0, k - a[i]); j < k; j++) if (buf[j >> 6] >> (j & 63) & 1) {
			cnt++;
			break;
		}
	}
	std::cout << n - cnt << std::endl;
	return 0;
}

