#include <bits/stdc++.h>
using namespace std;

int N, K;
vector<int> arr;

int currNum;
//short memo[5005][5005];

bitset<5005 * 5005> memo, isSet;

short dp(int currN, int currSum)
{
	if(isSet.test(currN * 5005 + currSum))
		return memo.test(currN * 5005 + currSum);

	if(currN == 0)
	{
		memo.set(currN * 5005 + currSum, (K - currNum <= currSum && currSum < K));
		isSet.set(currN * 5005 + currSum, 1);
		return memo.test(currN * 5005 + currSum);
	}

	memo.set(currN * 5005 + currSum, dp(currN - 1, currSum));
	if(currSum + arr[currN] < K)
		memo.set(currN * 5005 + currSum, memo.test(currN * 5005 + currSum) | dp(currN - 1, currSum + arr[currN]));

	isSet.set(currN * 5005 + currSum, 1);
	return memo.test(currN * 5005 + currSum);
}

short isNecessary(int pos)
{
	currNum = arr[pos];
	arr.erase(arr.begin() + pos);

	isSet.reset();

	short ans = dp( (int)(arr.size()) - 1, 0);
	arr.insert(arr.begin() + pos, currNum);
	return ans;
}

int main()
{
	scanf("%d%d", &N, &K);

	arr.push_back(0);

	long long sum = 0;
	for(long long i = 1; i <= N; i++)
	{
		int ai;
		scanf("%d", &ai);
		arr.push_back(ai);

		sum += ai;
	}

	if(sum < (long long)(K) )
	{
		printf("%d", N);
		return 0;
	}

	sort(arr.begin(), arr.end());

	int startPtr = 1, endPtr = N, ans = 0;
	while(startPtr <= endPtr)
	{
		int mid = startPtr + (endPtr - startPtr) / 2;
		int necessary = isNecessary(mid);

		if(necessary)
			endPtr = mid - 1;

		else
		{
			startPtr = mid + 1;
			ans = mid;
		}
	}

	printf("%d", ans);
}

