int n, k;

void make_dp(unsigned a[5010], int skip, unsigned dp[5010]) {
    memset(dp, 0, sizeof(unsigned) * 5010);
    dp[0] = 1;
    rep (i, n) {
        if (i == skip) continue;
        static unsigned ndp[5010];
        memset(ndp, 0, sizeof(unsigned) * 5010);
        for (int j = 0; j <= k; ++j){
            ndp[j] += dp[j];
            ndp[min<unsigned>(k,j+a[i])] += dp[j];
        }
        memcpy(dp, ndp, sizeof(unsigned) * 5010);
    }
}

int main() {
    while(cin >> n >> k){
        unsigned a[5010];
        rep(i, n) scanf("%ud", a + i);
        sort(a, a + n);
        unsigned org[5010];
        make_dp(a, -1, org);
        auto check = [&](int i){
            int x = a[i];
            unsigned rem[5010];
            make_dp(a, i, rem);
            for (int j = 0; j < k; ++j) {
                if (rem[j] != 0 && j + x >= k) {
                    return false;
                    break;
                }
            }
            return true;
        };
        int l = -1, r = n;
        while (l + 1 < r) {
            int m = l + (r - l) / 2;
            if (check(m)) l = m;
