void solve(){
	int n, k, m = 1, ans = 0;
	scanf("%d%d", &n, &k);
	REPN(i, 1, n){
		scanf("%d", &v[m]);
		if (v[m] < k){
			m++;
		}
	}
	dp_pref[0][0] = 1;
	REP(i, 1, m){
		REP(j, 0, k){
			dp_pref[i][j] = dp_pref[i - 1][j];
			if (j >= v[i]){
				dp_pref[i][j] |= dp_pref[i - 1][j - v[i]];
			}
		}
	}
	dp_suf[m][0] = 1;
	for(int i = m - 1; i > 0; i--){
		REP(j, 0, k){
			dp_suf[i][j] = dp_suf[i + 1][j];
			if (j >= v[i]){
				dp_suf[i][j] |= dp_suf[i + 1][j - v[i]];
			}
		}
	}
	REP(i, 1, m){
		int fl = 0;
		for(int l = 0, r = k - 1; l < k && r >= 0; l++){
			if (dp_pref[i - 1][l] == 0){
				continue;
			}
			for(r = min(r, k - l - 1); r >= 0 && r >= k - l - v[i]; r--){
				if (dp_suf[i + 1][r]){
					fl = 1;
					break;
				}
			}
			if (fl){
				break;
			}
		}
		ans += 1 - fl;
	}
