/*
sort by descending order

for every element, dp[i][s] = true or false
dp[i][s] can come from dp[i-1][s-A[i]<k] or dp[i][s]
if(dp[i][>=k]) then i is useful

*/

int N, K;

int A[5010];
bool dp[5010][5010];

void solve() {
	cin >> N >> K;
	rep(i, 1, N + 1) cin >> A[i];
	sort(A, A + N + 1);
	dp[N][min(K, A[N])] = true;
	dp[N][0] = true;
	for(int i = N - 1; i >= 1; i--) {
		int a = -1;
		for(int j = K; j >= 0; j--) {
			if(j - A[i] >= 0) dp[i][j] = max(dp[i + 1][j], dp[i + 1][j - A[i]]);
			else dp[i][j] = dp[i + 1][j];
			if(a == -1 && dp[i + 1][j]) a = j;
		}
		if(K - a <= A[N]) dp[i][K] = true;
		//debug(i, vec(dp[i], dp[i] + K + 1));
		if(!dp[i][K] || A[N - 1] == A[N]) continue;
		bool ok = false;
		for(int j = K - 1; j >= K - A[i - 1]; j--) {
			if(dp[i][j]) {
				ok = true;
				break;
			}
		}
		if(!ok) {
			cout << i - 1 << "\n";
			return;
		}

	}
	if(dp[1][K]) {
		cout << "0\n";
	}
	else cout << N << "\n";
}

