bool is_i_needed(ll N, ll K, vector<ll>& As, int i) {
    // 任意のカードの組み合わせで作成可能な数を列挙
    // ただしK未満
    set<int> possible;
    possible.insert(0);
    REP(j, N) {
        if (i == j) continue;
        auto a = As[j];
        set<int> added;
        for(auto v: possible) {
            if ((v + a) < K) {
                added.insert(v + a);
            }
        }
        for(auto v: added) possible.insert(v);
    }

    FOR(j, max(0LL, K - As[i]), K) {
        if (possible.count(j)) {
            return true;
        }
    }
    return false;
}


int main(void)
{
    cin.sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<ll> As(N);
    REP(n, N) cin >> As[n];

    if (N > 400 || K > 400) return 0;

    int no_need = 0;
    REP(i, SIZE(As)) {
        no_need += !is_i_needed(N, K, As, i);
    }
    cout << no_need << endl;
    return 0;
}

