const int NMAX = 5000;

typedef long long I64;

int v[NMAX+2], Ans = 0;
bool up[NMAX+2][NMAX+2], dw[NMAX+2][NMAX+2];
int N, K, NN;
I64 sum = 0;

int main() {
    cin >> N >> K;
    for( int i = 1;  i <= N;  ++i ) {
        cin >> v[i];
        sum += v[i];
    }
    sort( v+1, v+N+1 );
    dw[0][0] = 1;
    for( int i = 1;  i <= N;  ++i ) {
        if( v[i] >= K ) {
            ++Ans;
            continue;
        }

        NN = i;
        dw[i][0] = 1;
        for( int j = v[i];  j <= K;  ++j ) {
            if( dw[i-1][ j - v[i] ] ) dw[i][j] = 1;
        }
    }

    up[NN+1][0] = 1;
    for( int i = NN;  i >= 1;  --i ) {
        if( v[i] >= K ) continue;

        up[i][0] = 1;
        for( int j = v[i];  j <= K;  ++j ) {
            if( up[i+1][ j - v[i] ] ) up[i][j] = 1;
        }
    }

    for( int i = 1;  i <= NN;  ++i ) {
        int lst[NMAX+2], ind = 0;
        for( int j = 0;  j < K;  ++j ) {
            if( up[i+1][j] ) lst[ ++ind ] = j;
        }

        bool nuseles = 0;
        for( int gr = 0;  gr < K;  ++gr ) {
            if( !dw[i-1][ gr ] ) continue;
            while( ind > 0 && gr + lst[ind] >= K ) {
                --ind;
            }

            if( gr + lst[ind] < K && gr + lst[ind] >= K - v[i] ) nuseles = 1;
        }

        ///if( sum < K ) nuseles = 1;
        Ans += nuseles;
    }

    Ans = N - Ans;

    cout << Ans << '\n';

    return 0;
}

