void solve(){
	int N;//カード枚数
	LL K;//閾値
	cin >> N >> K;

	vector<LL> A(N);
	LL sum = 0;
	for(int i=0;i<N;++i){
		cin >> A[i];
	}
	sort(A.begin(),A.end());
	int pos = 0;
	while(pos < N && sum<K){
		sum += A[pos];
		++pos;
	}
	if( sum < K ){
		cout << N << endl;
		return;
	}

	int NG = 0;//K>=1
	int OK = N-1;

	int Mid = (NG+OK)/2;
	while(OK-NG>1){//使わない数index
		Mid = (NG+OK)/2;
		if( K<=A[Mid] ){
			OK = Mid;
			continue;
		}

		vector< bool > dp((int)K,false);
		dp[0] = true;
		for(int i=0;i<N;++i){
			if( i == Mid ) continue;
			for(int j=(int)K-1;j>=0;--j){
				if( dp[j] == false)continue;
				if( A[i] + j >= K ) continue;
				dp[ (int)A[i] + j ] = true;
			}
		}
		bool flag = false;

		for(int in=(int)(K-A[Mid]);in<K;++in){
			if( dp[in] ){
				flag = true;
				break;
			}
		}
		if( flag == false ){
			NG = Mid;
		}else{
			OK = Mid;
		}
	}

	cout << OK << endl;
}

