        break;
      } 
    }
    if (!flag) {
      ++ans;
    }
    sum -= a[i];
    for (int j = k - 1; j >= a[i]; --j) {
      dp[j] |= dp[j - a[i]];
    }
  }
  printf("%d\n", ans);
  return 0;
}

