void solve(){
	int N;//カード枚数
	int K;//閾値
	cin >> N >> K;

	vector<LL> A(N);
	for(int i=0;i<N;++i){
		cin >> A[i];
	}
	sort(A.begin(),A.end());
	vector<bool> use(N,false);
	int ans = 0;
	for(int a=0;a<N;++a){//使わない数index
		if( K<=A[a] ){
			use[a] = true;
			break;
		}
		if( a> 0 && A[a-1] == A[a] ){
			if( use[a-1] == false ){
				use[a] = false;
				++ans;
			}else{
				use[a] = true;
			}
			continue;
		}
		vector< bool > dp(K+1,false);
		dp[0] = true;
		for(int i=0;i<N;++i){
			if( i == a ) continue;
			for(int j=K;j>=0;--j){
				if( dp[j] == false)continue;
				if( A[i] + j > K ) continue;
				dp[(int)(A[i]+j)] = true;
			}
		}
		bool flag = false;

		for(int in=K-(int)A[a];in<K;++in){
			if( dp[in] ){
				flag = true;
				break;
			}
		}
		if( flag == false ){
			use[a] = false;
			++ans;
		}else{
			use[a] = true;
		}
	}

	cout << ans << endl;
}

