ll dfs(ll n, ll k, set<ll> &st) {
  if(n == 0 || k == 0) return 1;
  ll ret = 0;
  if(!st.count(n - 1)) {
    if(dp[n][k] & 2) st.insert(n - 1);
    if(dp[n][k] & 1) ret += dfs(n - 1, k, st);
    if(dp[n][k] & 2) ret += dfs(n - 1, k - A[n - 1], st);
  }
  return ret;
}

