  dp[0][0] = 1;

  REP(i, 0, N) REP(j, 0, K) if(dp[i][j]) {
    dp[i + 1][j] |= 1;
    if(j + A[i] < K) dp[i + 1][j + A[i]] |= 2;
  }

  REP(i, 0, K) cnt[i] = 0;
  REP(i, 0, K) if(dp[N][i]) cnt[i] = dfs(N, i, st[i]);

  ll ans = N;
