        ldp[i][0]=1;rdp[i][0]=1;
        if (a[i]<k) ldp[i][a[i]]=1;
        if (a[n-1-i]<k) rdp[i][a[n-1-i]]=1;
    }
    rep2(i,1,n)rep(j,k){
            if (j-a[i]>=0) ldp[i][j]|=ldp[i-1][j-a[i]]|ldp[i-1][j];
            else ldp[i][j]|=ldp[i-1][j];
            if (j-a[n-1-i]>=0) rdp[i][j]|=rdp[i-1][j-a[n-1-i]]|rdp[i-1][j];
            else rdp[i][j]|=rdp[i-1][j];
