int vis[5001];
int dp[5001][5001];

signed main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	int n, k;
	cin >> n >> k;

	//ai が 必要 => aiを除いて 総和xが (k - ai) <= x < k を満たす集合が存在する
	//
	//ai >= k は絶対必要　<= 取り除いてよい

	vector<int> a;
	for (int i = 0; i < n; i++) {
		int t;
		cin >> t;
		if (t < k) {
			a.push_back(t);
		}
	}

	n = a.size();

	sort(all(a));

	int ans = 0;


	auto ok = [&](int i) {

		clr(vis);
		mclr(dp);

		function<void(int, int)> dfs = [&](int t, int sum) {
			if (t == n) {
				return;
			}
			if (t == i) {
				dfs(t + 1, sum);
				return;
			}
			if (sum >= k)return;
			if (dp[t][sum] != -1)return;
			dp[t][sum] = 1;

			dfs(t + 1, sum);

			if (sum + a[t] < k) {
				vis[sum + a[t]] = 1;
				dfs(t + 1, sum + a[t]);
			}

		};

		vis[0] = 1;
		dfs(0, 0);


		bool need = false;
		for (int j = k - a[i]; j < k; j++) {
			if (vis[j]) need = true;
		}
		return !need;
	};

	int l = 0, r = n;
	while(r - l > 1) {
		int m = (r + l) / 2.0;
		if (ok(m)) {
			l = m;
		}
		else {
			r = m;
		}
	}

	cout << r << endl;


	return 0;
}

