inline int read(){
	char ch = getchar(); int x = 0;
	while (ch < '0' || '9' < ch) ch = getchar();
	while ('0' <= ch && ch <= '9') { x = x*10+ch-'0'; ch = getchar(); }
	return x;
}

bool check(int k){
	x.reset(); x[0] = 1;
	for (int i=1; i<=n; i++)
		if (i != k) x = x | (x << a[i]);
	for (int i=max(0, K-a[k]); i<=K-1; i++)
		if (x[i]) return false;
	return true;
}

int main(){
	n = read(); K = read();
	for (int i=1; i<=n; i++) a[i] = read();
	sort(a+1, a+n+1);
	l = 0; r = n;
	while (l < r){
		mid = (l + r + 1) >> 1;
		if (check(mid)) l = mid;
		else r = mid-1;
	}
	printf("%d\n", l);
	return 0;
}

