bool f(int x){
    for(int i=0;i<w;i++){
        fill(d[i], d[i]+k+1, false);
    }
    d[0][0]=true;
    if(x>0)d[0][v[0]]=true;
    for(int i=1;i<w;i++){
        for(int j=0;j<k;j++){
            d[i][j]=d[i-1][j];
            if(i!=x&&j-v[i]>=0){
                if(d[i-1][j-v[i]])d[i][j]=true;
            }
        }
    }
    for(int j=k-v[x];j<k;j++){
        if(d[w-1][j])return true;
    }
    return false;
}
