int isNG(int p, int *as) {
    if (as[p] >= k) {
        return 0;
    }
    int dp[k+1] = {};
    dp[0] = 1;
    rep(i,n) for (int j = k; j >= 0; j--) {
        if (i == p) {
            continue;
        }
        if (dp[j] != 0 && j + as[i] <= k) {
            dp[j+as[i]] = 1;
        }
    }
    for (int i = k - as[p]; i < k; i++) {
        if (dp[i] == 1) return 0;
    }
    return 1;
}

