#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 5e3 + 5;
bool f[N][N] = {0}, g[N][N] = {0};
int a[N];
int main()
{
	int n, k;
	cin >> n >> k;
	for (int i = 1; i <= n; ++i)
		cin >> a[i];
	sort(a + 1, a + n + 1);
	int ans = n;
	for (int i = 1; i <= n; ++i)
	{
		if (a[i] >= k)
		{
			n = i - 1;
			ans = n;
			break;
		}
	}	

	for (int i = 0; i <= n + 1; ++i)
		f[i][0] = g[i][0] = true;

	for (int j = 1; j < k; ++j)
	{
		for (int i = 1; i <= n; ++i)
		{
			f[i][j] = f[i - 1][j];
			if (j >= a[i])
				f[i][j] |= f[i - 1][j - a[i]];
		}

		for (int i = n; i >= 1; --i)
		{
			g[i][j] = g[i + 1][j];
			if (j >= a[i])
				g[i][j] |= g[i + 1][j - a[i]];
		}
	}

 	//O(nk)
	for (int i = 1; i <= n; ++i)
	{
		int l = k - 1, x = 0;
		while (l >= 0 and !f[i - 1][l])
			--l;

		x = max(x, l);
		for (int r = 1; r < k; ++r)//O(2k) 
		{
			if (!g[i + 1][r])
				continue;

			while (l >= 0 and l + r >= k and f[i - 1][l])//r递增 l+r>=k 则l肯定要减小 
				--l;
			x = max(x, l + r);
		}
		if (x >= k - a[i])
		--ans; 
	}

	cout << ans << endl;
}

