const int maxn = 5005;

int n, k, a[maxn];
int32_t dp[2][maxn][maxn], pref[2][maxn][maxn];
int32_t main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> k;
    for(int i = 1; i <= n; i++)
        cin >> a[i];
    dp[0][0][0] = dp[1][n + 1][0] = 1;
    pref[0][0][0] = pref[1][n + 1][0] = 1;
    for(int i = 0; i < n; i++)
        for(int j = 0; j <= k; j++)
            if(dp[0][i][j])
            {
                dp[0][i + 1][min(j + a[i + 1], k)] = 1;
                dp[0][i + 1][j] = 1;
            }
    for(int i = n + 1; i > 1; i--)
        for(int j = 0; j <= k; j++)
            if(dp[1][i][j])
            {
                dp[1][i - 1][min(j + a[i - 1], k)] = 1;
                dp[1][i - 1][j] = 1;
            }
    for(int l = 0; l < 2; l++)
        for(int i = 1; i <= n; i++)
        {
            pref[l][i][k] = dp[l][i][k];
            for(int j = k - 1; j >= 0; j--)
                pref[l][i][j] = pref[l][i][j + 1] + dp[l][i][j];
        }
    int ans = n;
    for(int i = 1; i <= n; i++)
    {
        int useful = 0;
        for(int lsum = 0; lsum < k; lsum++)
            if(dp[0][i - 1][lsum])
            {
                int sub = k - lsum;
                int add = max(sub - a[i], 0ll);
                assert(add < sub);
                if(pref[1][i + 1][add] - pref[1][i + 1][sub] > 0)
                    useful = 1;
            }
        ans -= useful;
    }
    cout << ans << "\n";
    return 0;
}

