const int MOD = 1e9+7;
int DP(int n,int k,vector<int> &a,int ex){
    vector<vector<int>> dp(n+1,vector<int> (k+1,0));
    dp[0][0]=1;
    for(int i=0;i<n;i++){
        for(int j=0;j<=k;j++){
            dp[i+1][j]+=dp[i][j];
            if(i!=ex) dp[i+1][min(k,j+a[i])]+=dp[i][j];
            dp[i+1][j]%=MOD;
            dp[i+1][min(k,j+a[i])]%=MOD;
        }
    }
    return dp[n][k];
}
int main(){
    int n,k;
    cin >> n >> k;
    vector<int> a(n);
