    for(int i=0;i<n;i++) cin >> a[i];
    int num=DP(n,k,a,-1);
    int ans=0;
    for(int i=0;i<n;i++) if(DP(n,k,a,i)*2%MOD==num) ans++;
    cout << ans << endl;
}

