#include <bits/stdc++.h>

using namespace std;

int N, K;
int vals[5005];

int DPT[405][405];

int howclose(int i, int K, int nope) {
	if (K <= 0)
		return 1e9+10;
	if (i == N) {
		return K;
	}
	if (DPT[i][K] != -1) {
		return DPT[i][K];
	}
	if (i == nope) {
		return howclose(i+1, K, nope);
	}
	int ans = min(howclose(i+1, K-vals[i], nope), howclose(i+1, K, nope));
	return DPT[i][K] = ans;
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> N >> K;
	for (int i = 0; i < N; ++i) {
		cin >> vals[i];
	}
	int cnt = 0;
	for (int i = 0; i < N; ++i) {
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j <= K; ++j) {
				DPT[i][j] = -1;
			}
		}
		int close = howclose(0, K, i);
		if (close > vals[i]) {
			++cnt;
		}
	}
	cout << cnt << endl;
}

