template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;
struct nap
{
	std::vector<int> memo;
	int target;
	std::vector<int> const& vec;
	int shift;
	nap(int t, std::vector<int>const& v, int K) :memo(K*v.size(), -1), target{ t }, vec{ v }, shift{ K }
	{

	}
	int run(int index, int K)
	{
		if (memo[index*shift + K] != -1)
		{
			return memo[K];
		}
		if (index == target)
		{
			return run(index + 1, K);
		}
		if (index == vec.size())
		{
			return 0;
		}
		if (vec[index] <= K)
		{
			memo[index*shift + K] = std::max(run(index + 1, K - vec[index]) + vec[index], run(index + 1, K));
		}
		else
		{
			memo[index*shift + K] = run(index + 1, K);
		}
		return memo[index*shift + K];
	}
};

int main()
{
	int N, K;
	std::cin >> N >> K;
	std::vector<int> vec;
	int count{};
	for (int i{}; i < N; ++i)
	{
		int v;
		std::cin >> v;
		if (v < K)
		{
			vec.emplace_back(v);
		}
	}
	for (int i{}; i < vec.size(); ++i)
	{
		nap n{ i,vec,K };
		if (n.run(0, K - 1) + vec[i] < K)
		{
			++count;
		}
	}
	std::cout << count << std::endl;
}

