uint64_t buf[80];
void shift_or(int n) {
	int big = n >> 6;
	int small = n & 63;
	if (small) {
		int ismall = 64 - small;
		for (int i = 78 - big; i >= 0; i--) {
			uint64_t cur = buf[i];
			buf[i + big] |= cur << small;
			buf[i + big + 1] |= cur >> ismall;
		}
	} else {
		for (int i = 78 - big; i >= 0; i--)
			buf[i + big] |= buf[i];
	}
}

