      dp1[i + 1][j] = true;
    }
  }
  dp2[n][0] = true;
  rrep(i, n, 0) {
    rep(j, 0, k + 1) {
      if (!dp2[i][j]) continue;
      if (j + a[i - 1] <= k) dp2[i - 1][j + a[i - 1]] = true;
