#define repi(i,a,b) for(int i=(a);i<(b);++i)
#define rep(i,a) repi(i,0,a)
#define all(a) (a).begin(), (a).end()
#define clr(a,v) memset((a),(v),sizeof(a))

constexpr int MAX_N = 5000;

int N, K;
int a[MAX_N];
bool dp[MAX_N+1][5001];
int ans;

bool C( int idx )
{
  clr( dp, false );

  dp[0][0] = true;
  rep( i, N ) rep( k, K+1 )
  {
    dp[i+1][k] |= dp[i][k];

    if( k-a[i] >= 0 && i != idx )
      dp[i+1][k] |= dp[i][k-a[i]];
  }

  for( int k = K-a[idx]; k < K; ++k ) if( dp[N][k] )
    return true;

  return false;
}

int main()
{
  scanf( "%d%d", &N, &K );
  rep( i, N )
    scanf( "%d", a+i );

  ans = N;

  std::sort( a, a+N );

  int lb = 0, ub = N;
  while( ub-lb > 1 )
  {
    int mid = lb+ub>>1;

    if( C(mid) )
      ub = mid;
    else
      lb = mid;
  }

  printf( "%d\n", ub );

  return 0;
}

