int n, k, v[5010], a[5010], d[5010];
void solve(int x, int s) {
	if (s >= k) {
		for (int i = 0; i < n; i++) {
			if (v[i]) {
				d[i] = min(d[i], s);
			}
		}
		return;
	} 
	if (x >= n) {
		return;
	}
	for (int i = x; i < n; i++) {
		if (!v[i]) {
			v[i] = 1;
			solve(x + 1, s + a[i]);
			v[i] = 0;		
		}
	}
}

