using namespace std;
int n, k, a[5005], pre[5005][5005], suf[5005][5005], ans;

int main()
{
	scanf("%d%d",&n,&k);
	for(int i=1;i<=n;i++) {
		scanf("%d",&a[i]);
	}
	pre[0][0] = 1; suf[n+1][0] = 1;
	for(int i=1;i<=n;i++) {
		for(int j=0;j<=k;j++) {
			pre[i][j] |= pre[i-1][j];
			if(j >= a[i]) pre[i][j] |= pre[i-1][j-a[i]];
		}
	}
	for(int i=n;i>=1;i--) {
		for(int j=0;j<=k;j++) {
			suf[i][j] |= suf[i+1][j];
			if(j >= a[i]) suf[i][j] |= suf[i+1][j-a[i]];
		}
	}
	for(int i=1;i<=n+1;i++) {
		for(int j=1;j<=k;j++) suf[i][j] += suf[i][j-1];
	}
	for(int i=1;i<=n;i++) {
		for(int j=0;j<k;j++) {
			int X = k-j-a[i]-1;
			if(pre[i-1][j] && suf[i+1][k-j-1] - (X < 0 ? 0 : suf[i+1][X])) {ans++; break;}
		}
	}
	printf("%d\n",n-ans);
}

