void solve(){
  int n,k;
  cin>>n>>k;
  vector<int>a(n);
  rep(i,n)cin>>a[i];
  sort(a.begin(),a.end());
  int need=0;
  vector<vector<int>>dp(n+1,vector<int>(5005));//dp[i][j]:=先頭からiまで見てjが作れるか
  vector<vector<int>>rdp(n+1,vector<int>(5005));//rdp[i][j]*:=末尾からiまで見てjが作れるか
  dp[0][0]=1;rdp[0][0]=1;
  rep(i,n){
    rep(j,5001){
      if(j-a[i]>=0)dp[i+1][j]=dp[i+1][j]|dp[i][j-a[i]];
      dp[i+1][j]=dp[i+1][j]|dp[i][j];
    }
  }
  rep(i,n){
    rep(j,5001){
      if(j-a[n-1-i]>=0)rdp[i+1][j]=rdp[i+1][j]|rdp[i][j-a[n-1-i]];
      rdp[i+1][j]=rdp[i+1][j]|rdp[i][j];
    }
  }
  vector<vector<int>>sum(n+1,vector<int>(5005));//iにおいて0からjまででいくつ作ることができるか
  rep(i,n+1){
    sum[i][0]=1;
    rep(j,5000){
      sum[i][j+1]=sum[i][j]+dp[i][j+1];
    }
  }
  rep(i,n){
    bool flag=false;
    rep(j,k+1){
      if(rdp[n-1-i][j]){
        if(sum[i][k-j-1]-sum[i][max(0,k-j-a[i]-1)]>0)flag=true;
      }
    }
    if(flag)++need;
  }
  cout<<n-need;
}

