using namespace std;
int N, K, a[5009]; bool dp[5009];
bool solve(int x) {
	if (x < 0) return false;
	if (x >= N) return true;
	fill(dp, dp + K, false); dp[0] = true;
	for (int i = 0; i < N; i++) {
		if (i == x) continue;
		for (int j = K - 1; j >= a[i]; j--) {
			if (dp[j - a[i]]) dp[j] = true;
		}
	}
	for (int i = max(K - a[x], 0); i < K; i++) {
		if (dp[i]) return true;
	}
	return false;
}
int main() {
	scanf("%d %d", &N, &K);
	for (int i = 0; i < N; i++) scanf("%d", &a[i]);
	sort(a, a + N);
	int l = 0, r = N;
	while (r - l > 1) {
		int m = (l + r) >> 1;
		if (solve(m)) r = m;
		else l = m;
	}
	for (int i = l - 3; i <= l + 3; i++) {
		if (solve(i)) {
			cout << i << endl;
			break;
		}
	}
	return 0;
}

