const int maxn = 5005;
int arr[maxn], n, k;
bool can(int excl) {
	bitset<maxn> dp; 
	dp[0] = 1;
	for(int i=0; i<n; i++) 
		if(i != excl) 
			dp |= (dp << arr[i]);
	for(int i=k-1; i>=max(0, k-arr[excl]); i--) 
		if(dp[i]) return 1;
	return 0;
}
int main(int argc, char const *argv[]) {
	cin>>n>>k;
	for(int i=0; i<n; i++) 
		cin>>arr[i];
	sort(arr, arr+n);
	int lo = 0, hi = n; 
	while(lo < hi) {
		int mid = lo + hi >> 1;
		if(can(mid)) hi = mid; 
		else lo = mid+1;
	} cout<<lo<<endl;
}

