vector<int> plusing(vector<int> a, vector<int> b) {
	int itr1 = 0, itr2 = 0;
	vector<int> ans;
	while (itr1 != a.size() || itr2 != b.size()) {
		if (itr1 == a.size()) {
			for (int q = itr2;q < b.size();++q) {
				ans.push_back(b[q]);
			}
			itr2 = b.size();
		}else if(itr2 == b.size()){
			for (int q = itr1;q < a.size();++q) {
				ans.push_back(a[q]);
			}
			itr1 = a.size();
		}
		else {
			if (a[itr1] < b[itr2]) {
				ans.push_back(a[itr1]);
				itr1++;
			}
			else if(a[itr1] > b[itr2]) {
				ans.push_back(b[itr2]);
				itr2++;
			}
			else {
				ans.push_back(a[itr1]);
				itr1++;
				itr2++;
			}
		}
	}
	return ans;
}
