bool dp1[5002][5000], dp2[5002][5000];
int n, k;
int a[5001], sum[5000];

void dfs(int pos, int sum, bool f) {
	if (sum >= k) return;

	int npos = pos;
	if (!f) {
		if (dp1[pos][sum]) return;
		dp1[pos][sum] = true;
		npos++;
	}
	else {
		if (dp2[pos][sum]) return;
		dp2[pos][sum] = true;
		npos--;
	}

	if (npos == 0 || npos == n + 1) return;

	dfs(npos, sum + a[npos], f);
	dfs(npos, sum, f);
}

int main() {
	cin >> n >> k;
	REP(i, n) scanf("%d", a + i + 1);

	dfs(0, 0, false);
	dfs(n + 1, 0, true);

	int ans = n;
	FOR(i, 1, n + 1) {
		if (a[i] >= k) {
			ans--;
			continue;
		}

		fill(sum, sum + k, 0);
		REP(j, k) if (dp2[i + 1][j]) sum[j]++;
		FOR(j, 1, k) sum[j] += sum[j - 1];

		bool ok = false;

		REP(j, k) if (dp1[i - 1][j]) {
			int l = k - a[i] - j;
			if (l < 0) break;

			int r = k - j - 1;

			if (sum[r] - sum[l] >= 1) ok = true;
		}

		if (ok) ans--;
	}

	cout << ans << endl;

	return 0;
}

