#define all(x) (x).begin(), (x).end()
using lli = long long int;
using pii = pair<int, int>;

int main() {
  ios_base::sync_with_stdio(false);
  int n, k;
  cin >> n >> k;
  map<int, int> m;
  vector<int> v;
  int answer = 0;
  lli sum = 0;
  for (int i = 0; i < n; ++i) {
    int a;
    cin >> a;
    sum += a;
    if (a < k) {
      v.push_back(a);
      m[a]++;
    } else {
      answer++;
    }
  }
  sort(all(v));
  //if (sum < k) {
    //cout << n;
    //return 0;
  //}
  vector<set<int>> parents(k);
  for (int i = 0; i < v.size(); ++i) {
    for (int ki = 0; ki + v[i] < k; ++ki) {
      if (ki == 0 || parents[ki].size()) {
        parents[ki + v[i]].insert(i);
      }
    }
  }
  for (auto& p : m) {
    vector<int> d(k);
    priority_queue<pii, vector<pii>, greater<pii>> q;
    for (int j = k - p.first; j < k; ++j) {
      d[j] = 1;
      q.push(make_pair(j, -v.size()));
    }
    while (!q.empty() && !d[0]) {
      int source = q.top().first;
      auto start = parents[source].lower_bound(-q.top().second);
      q.pop();
      if (start == parents[source].begin()) continue;
      --start;
      for (auto it = start; ; ) {
        int to = source - v[*it];
        if (v[*it] != p.first && !d[to]) {
          d[to] = 1;
          if (to == 0) break;
          q.push(make_pair(to, -(*it)));
        }
        if (it == parents[source].begin()) break;
        --it;
      }
    }
    if (d[0] || p.first * 1ll * p.second >= k) {
      answer += p.second;
    }
  }
  cout << n - answer;
  return 0;
}

