	for (int i = 0; i < n; i++) {
		del(a[i]);
		for (int j = max(0, k - a[i]); j < k; j++) {
			if (dp[j] == 0) continue;
			res--;
			break;
		}
		add(a[i]);
	}
	cout << res;
}

