	if(mid == len) return 1;
	memset(cur, 0, sizeof(cur));
	cur[0] = 1;
	for(int i = 0; i < len; i ++){
		if(i == mid) continue;
		for(int s = k; s >= 0 ; s --){
			if(!cur[s]) continue;
			if(s + x[i] <= k) cur[s + x[i]] = 1;
		}
	}
	for(int s = k - x[mid]; s < k; s ++) if(cur[s]) return 1;
	return 0;
}

