  for(int j = 0; j < k; j++) {
    dp2[n][j] = 0;
  }
  for(int i = n - 1; i >= 0; i--) {
    for(int j = 0; j < k; j++) {
      if (j < a[i]) {
        dp2[i][j] = dp2[i + 1][j];
      } else {
        dp2[i][j] = max(dp2[i + 1][j], dp2[i + 1][j - a[i]] + a[i]);
      }
    }
  }
  int ans = n;
