bool solve(int t) {
	for (int i = 0; i < k; i++)
		dp[i] = 0;
	dp[0] = 1;
	for (int i = 0; i < n; i++) {
		for (int x = 0; x < r[i] + (i == t ? -1 : 0); x++) {
			for (int j = k; j >= v[i]; j--) {
				if (dp[j - v[i]]) dp[j] = 1;
			}
		}
	}
	bool l = 0;
	for (int i = k - v[t]; i < k; i++)
		if (dp[i]) l = 1;
	return l;
}
signed main() {
