  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n, k; std::cin >> n >> k;
  std::vector< lint > a(n); std::cin >> a;
  std::vector< lint > dp(k, 0);
  dp.at(0) = 1;
  for (lint x : a) {
    if (k < x) continue;
    for (int i = k - x - 1; i >= 0; i--) {
      dp.at(i+x) += dp.at(i);
    }
    debug(fmt(0)(dp));
  }
  int ans = 0;
  for (lint x : a) {
    if (k < x) continue;
    auto v = dp;
    for (int i = 0; i < k - x; i++) {
      v.at(i+x) -= v.at(i);
    }
    bool ok = std::none_of(v.begin() + k - x, v.end(), [](auto x){ return x; });
    debug(x, fmt(0)(v), ok);
    ans += ok;
  }
  std::cout << ans << std::endl;
  return 0;
}

