bool C(int x){

    for(int i=std::max(k-x,0);i<k;++i){
        if(dp[n-1][i])
            return true;
    }
    return false;
}

int main() {

    std::cin>>n>>k;

    for(int i=0;i<n;++i)
        std::cin>>a[i];

    std::sort(a,a+n);

    int lb=-1,ub=n;

    while(ub-lb>1){

        int mid=(lb+ub)/2;

        std::memset(dp,false,sizeof(dp));

        dp[0][0]=true;

        if(mid!=0)
            dp[0][a[0]]=true;

        for(int i=1;i<n;++i){
            for(int j=0;j<k;++j){

                if(!(dp[i][j]=dp[i-1][j])
                    &&i!=mid&&j>=a[i])
                    dp[i][j]=dp[i-1][j-a[i]];
            }
        }

        if(C(a[mid]))
            ub=mid;
        else
            lb=mid;
    }

    std::cout<<ub<<std::endl;

