int n, k;
int a[5010];

bool ok[5010];

bool check(int m) {
    memset(ok, false, sizeof(ok));
    ok[0] = true;
    for (int i = n-1; i >= 0; i--) {
        if (i == m) continue;
        for (int j = k-1; j >= 0; j--) {
            if (ok[j] && j+a[i] < k)
                ok[j+a[i]] = true;
        }
    }

    for (int i = k-1; i >= 0; i--) {
        if (ok[i]) {
            return i+a[m] >= k;
        }
    }
    return false;
}

int solve() {
    sort(a, a+n);
    int lb = -1, ub = n;
    while (ub - lb > 1) {
        int mid = (lb + ub) / 2;
        if (check(mid)) {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    return lb + 1;
}

