using ll = long long;

int N, K, A[5000];

char dp[5001];

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N >> K;
    for (int i = 0; i < N; ++i) cin >> A[i];
    sort(A, A+N);
    for (int n = 0; n < N; ++n) if (A[n] >= K) { N = n; break; }

    int l = 0, r = N;
    while (l < r) {
        int m = (l + r) / 2;

        fill(dp, dp+K+1, 0); dp[0] = 1;

        for (int i = 0; i < N; ++i) {
            if (i == m) continue;
            for (int j = K; j >= A[i]; --j) {
                dp[j] |= dp[j-A[i]];
            }
        }

        bool ok = false;
        for (int i = K-A[m]; i < K; ++i) {
            if (dp[i]) {
                ok = true;
            }
        }

        if (ok) r = m;
        else    l = m+1;
    }

    cout << r << endl;
    return 0;
}

