#define Fin(i,f,t) for(int i=f;i<=t;++i)
#define Fde(i,f,t) for(int i=f;i>=t;--i)
#define MAXN 5050
using namespace std;
typedef long long LL;

int Num[MAXN],N,K,cnt;
bool Used[MAXN];
bool Dfs(int cho,LL value){
    if(value >= K) return true;
    bool flag = false;
    Fde(i,cho,1) if(!Used[MAXN]){
        if(Dfs(i-1,value+Num[i])){
            Used[i] = true;
            flag = true;
        }
    }
    return flag;
}
int main(void)
{
    //freopen("D:\\test.txt","r",stdin);
    //freopen("D:\\tsst.txt","w",stdout);
    while(~scanf("%d %d",&N,&K)){
        cnt = 0;
        Fin(i,1,N){
            int a;
            scanf("%d",&a);
            if(a<K)
                Num[++cnt]=a;
        }
        sort(Num+1,Num+cnt+1);
        memset(Used,false,sizeof(Used));
        Dfs(cnt,0);
        int ans = 0;
        Fin(i,1,cnt)
            if(!Used[i])
                ++ans;
        printf("%d\n",ans);
    }
    return 0;
}

