using namespace std;

int N,K,ans;
int a[5002];
bool check[5002];

int main(){
	scanf("%d %d",&N,&K);
	for(int i=1; i<=N; i++) scanf("%d",&a[i]);
	int t = 0; lld sum = 0;
	for(int i=1; i<=N; i++){
		if(t < i){
			sum = a[i];
			t = i;
		}
		while(1){
			if(t == N || sum >= K) break;
			sum += a[++t];
		}
		if(sum < K) break;
		for(int j=i; j<=t; j++){
			if(sum-a[j] < K) check[j] = true;
		}
		lld tsum = sum;
		for(int j=t+1; j<=N; j++){
			tsum += a[j];
			if(tsum-a[j] < K) check[j] = true;
		}
	}
	for(int i=1; i<=N; i++) if(!check[i]) ans++;
	printf("%d\n",ans);

	return 0;
}

