int main(){
	const int MAX=5001;
	int N,K;
	cin>>N>>K;
	int a[MAX]={};
	for(int i=1;i<=N;i++)
		cin>>a[i];
	//ソートする
	sort(a+1,a+N+1);
	//カードiを除いた集合から、コストK未満K-a[i]以上の組み合わせが作れるかどうかを試していく
	//作れるなら、iは必要なカード
	//カードiが不要なとき、iよりも数字が小さい（前の）カードは全部不要である
	//二分探索
	int high=N+1,low=1;
	while(high-low>1){
		int mid=(high+low)/2;
		//動的計画法
		//dp[j][k]=mid以外のj枚目までの集合で、コストkの集合を作れるか？
		bool dp[MAX][MAX]={};
		dp[0][0]=1;
		//j枚目までの集合では、j-1枚目までで作れるコストと、それらにa[j]を足したコストの集合が作れる
		for(int j=1;j<=N;j++){
			for(int k=0;k<=K;k++){
				if(dp[j-1][k]){
					dp[j][k]=1;
					if(k+a[j]<MAX && j!=mid)
						dp[j][k+a[j]]=1;
				}
			}
		}
		bool need=0;
		for(int i=K-a[mid];i<K;i++){
			if(dp[N][i])
				need=1;
		}
