using namespace std;

int N, K;
int a[5000];
int dp[5000][5000];

int func(int n, int k) //nまで使ったとき総和をkにできるか
{
	if (dp[n][k] >= 0)
	{
		return dp[n][k];
	}

	if (n == 0)
	{
		return (a[0] == k) ? 1 : 0;
	}

	int res = 0;
	if (func(n - 1, k) == 1)
	{
		res = 1;
	}
	if (k >= a[n])
	{
		if (func(n - 1, k - a[n]) == 1)
		{
			res = 1;
		}
	}
	dp[n][k] = res;
	return res;
}

bool is_need(int m)
{
	int temp = a[m];
	a[m] = 0;
	memset(dp, -1, sizeof(dp));
	bool found = false;
	for (int j = MAX(0, K - temp); j < K; j++)
	{
		if (func(N - 1, j) == 1)
		{
			found = true;
			break;
		}
	}
	a[m] = temp;
	return found;
}

signed main()
{
	cin >> N >> K;
	for (int i = 0; i < N; i++)
	{
		cin >> a[i];
	}

	ARY_SORT(a, N);

	if (is_need(0))
	{
		cout << 0 << endl;
		return 0;
	}
	if (!is_need(N - 1))
	{
		cout << N << endl;
		return 0;
	}

	int l = 0;
	int r = N - 1;
	while (l + 1 < r)
	{
		int mid = ((r - l) / 2) + l;
		if (is_need(mid))
		{
			r = mid;
		}
		else
		{
			l = mid;
		}
	}

	cout << r << endl;
}

