using namespace std;
using ll = long long;

bitset<5010> dp1[5010], dp2[5010];

int main() {
  int N, K;
  cin >> N >> K;
  vector<int> a(N);
  for (int i = 0; i < N; i++) {
    cin >> a[i];
  }
  dp1[0].set(0);
  for (int i = 0; i < N; i++) {
    dp1[i+1] = dp1[i] | (dp1[i] << a[i]);
  }
  dp2[N].set(0);
  for (int i = N - 1; i >= 0; i--) {
    dp2[i] = dp2[i+1] | (dp2[i+1] << a[i]);
  }
  int res = 0;
  for (int i = 0; i < N; i++) {
    int L = max(0, K - a[i]), R = K - 1;
    int cnt = 0;
    for (int k = L; k <= R; k++) {
      cnt += dp2[i+1][k];
    }
    bool need = false;
    for (int k = 0; k < K; k++) {
      if (dp1[i][k] && cnt > 0) {
        need = true;
        break;
      }
      if (L > 0) {
        cnt += dp2[i+1][L-1];
        --L;
      }
      if (R > 0) {
        cnt -= dp2[i+1][R];
        --R;
      }
    }
    if (!need) {
      ++res;
    }
  }
  cout << res << endl;
  return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int nmax = 5005;

int pre[nmax][nmax], suf[nmax][nmax];
int n, k;
int a[nmax];

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cin >> n >> k;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
  }

  pre[0][0] = 1;
  suf[n + 1][0] = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= k; j++) {
      pre[i][j] = pre[i - 1][j];
      if (j >= a[i])
        pre[i][j] |= pre[i - 1][j - a[i]];
    }
  }
  for (int i = n; i >= 1; --i) {
    for (int j = 0; j <= k; j++) {
      suf[i][j] = suf[i + 1][j];
      if (j >= a[i])
        suf[i][j] |= suf[i + 1][j - a[i]];
    }
  }

  auto has = [&](int x, int l, int r) {
    if (l <= 0) return suf[x][r] >= 1;
    return suf[x][r] - suf[x][l - 1] >= 1;
  };

  int ans = n;
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= k; j++) {
      suf[i + 1][j] += suf[i + 1][j - 1];
    }

    if (a[i] > k) {
      ans--;
      continue;
    }

    for (int j = 0; j < k; j++) {
      int left = k - a[i] - j;
      int right = k - j - 1;

      if (pre[i - 1][j] && has(i + 1, left, right)) {
        --ans;
        break;
      }
    }
  }

  cout << ans << '\n';
  return 0;
}

