using namespace std;
const int N = 5005;
int dp[N][N], n, k, a[N], tmp, x, z[N];
int sol(int i, int cur)
{
	if(i == n || cur >= k-x) return cur;
	int &ret = dp[i][cur];
	if(ret != -1) return ret;
	ret = sol(i+1, cur);
	if(ret >= k-x) return ret;
	if(cur + a[i] < k && tmp != i) return max(ret, sol(i+1, cur+a[i]));
	return ret;
}
bool check(int i)
{
	x = a[i];
	if(z[x] != -1) return z[x];
	if(x >= k) return z[x] = 1;
	tmp = i;
