using namespace std;

const int max_n = 5000;
int a[max_n];
bitset<max_n + 1> s[2 * max_n + 1];
bool t[2 * max_n + 1];
int n;
int k;
int result = 0;

int main() {
    cin >> n >> k;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i <= 2 * k; i++) {
        s[i].reset();
    }
    fill(t, t + 2 * k + 1, false);

    t[0] = true;
    for (int i = 0; i < n; i++) {
        int x = min(k, a[i]);

        for (int j = k - 1; j >= 0; j--) {
            if (t[j]) {
                t[j + x] = true;
                s[j + x] |= s[j];
                s[j + x][x] = true;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        int x = a[i];

        if (x < k) {
            bool found = false;
            for (int j = k; j < k + x && !found; j++) {
                found |= s[j][x];
            }

            if (!found) {
                result++;
            }
        }
    }

    cout << result << "\n";

    return 0;
}

