#define INF (1LL)<<60
typedef long long ll;
ll dp[5001][5001];

int N, K;
vector<ll> a;

ll dfs(int x, ll y, int select){
  if(y >= K)
    return y;
  if(x == N) return INF;
  if(dp[x][y] != -1) return dp[x][y];
  ll res = INF;  
  res = min(res, dfs(x+1, y+a[x], select));
  if(x != select)
    res = min(res, dfs(x+1, y, select));
  dp[x][y] = res;
  //  cout << x << " " << y << " " << res << endl;;
  return res;
}

int C(int i){
  for(int i=0;i<N;i++) for(int j=0;j<K;j++) dp[i][j] = -1;
  ll ret = dfs(0, 0, i);
  //  cout << a[i] << " " << ret << endl;
  return (ret - a[i]) < K;
}

int main(){
  cin >> N >> K;
  for(int i=0;i<N;i++){
    ll x; cin >> x;
    a.push_back(x);
  }
  sort(a.begin(), a.end());
  int mini = 0, maxi = N-1;
  int mid = (mini+maxi)/2;
  while(mini <= maxi){
    //    cout << mini << " " << maxi << " " << mid<< endl;
    if(C(mid))
      maxi = mid-1;
    else
      mini = mid+1;
    mid = (maxi+mini)/2;
  }
  //  cout << mid - (mid != N)<< endl;
  if(mid == 0 && C(mid)) cout << 0 << endl;
  else cout << mid+1 << endl;
  return 0;
}

