ll N,K,a[5010],ans=0;
bool dp[5010],dp2[5010];

bool can(int x){
	reg(i,0,K)dp[i]=false;
	dp[0]=true;
	rep(i,N){//i枚目までで
		if(i==x)continue;//midは使わない
		reg(j,0,K)dp2[j]=false;
		reg(j,0,K){
			if(dp[j])dp2[j]=true;
			if(a[i]>K)continue;
			dp2[a[i]]=true;
			if(j+a[i]>K)continue;
			if(dp[i+a[i]])dp2[i+a[i]]=true;
		}
		reg(j,0,K)dp[j]=dp2[j];
	}
	bool ok=true;
	int begin = 0;
	if(begin<K-a[x])begin = K-a[x];
	reg(i,begin,K-1){
		if(dp[i]){//条件を満たすような和が１つでもあれば
			ok=false;
			break;
		}
	}
	return ok;
}

