using namespace std;
typedef long long ll;


const int MAXN = 5005;
const int MAXK = 5005;


bool dp_pre[MAXN][MAXK];
bool dp_suf[MAXN][MAXK];
int a[MAXN];

int main()
{
    int n, k;
    cin >> n >> k;

    for (int i = 1; i <= n; i++)
    {
        cin >> a[i];
    }

    dp_pre[0][0] = 1;
    for (int i = 1; i <= n; i++)
    {
        for (int j = 0; j < k; j++)
        {
            if (dp_pre[i-1][j])
            {
                dp_pre[i][j] = 1;
                if (j + a[i] < k)
                    dp_pre[i][j+a[i]] = 1;
            }
        }
    }

    dp_suf[n+1][0] = 1;
    for (int i = n; i >= 1; i--)
    {
        for (int j = 0; j < k; j++)
        {
            if (dp_suf[i+1][j])
            {
                dp_suf[i][j] = 1;
                if (j + a[i] < k)
                    dp_suf[i][j+a[i]] = 1;
            }
        }
    }

    int ans = n;

    for (int i = 1; i <= n; i++)
    {
        int l = 0; int r = k-1;
        while( l < k && !dp_pre[i-1][l]) l++;
        while(r >= 0 && !dp_suf[i+1][r]) r--;

        while(l < k && r >= 0)
        {
            if (l + r + a[i] < k)
            {
                l++;
                while( l < k && !dp_pre[i-1][l]) l++;
            }
            else if (l + r >= k)
            {
                r--;
                while(r >= 0 && !dp_suf[i+1][r]) r--;
            }
            else
            {
                ans--;
         //       cout << i << " ";
                break;
            }
        }
    }

    cout << ans;

    return 0;
}

