#include <bits/stdc++.h>
using namespace std;
#define LL long long
#define pb push_back
const int N = 5000;
inline int read()
{
	int x = 0, f = 1; char ch = getchar();
	while (ch < '0' || ch > '9') { if (ch == '-') f = -1; ch = getchar(); }
	while (ch >= '0' && ch <= '9') { x = x * 10 + ch - '0'; ch = getchar(); }
	return x * f;
}
int n, k;
vector<int> a;
bitset<N> t, t2;

int main()
{
	n = read();
	k = read();
	int ans = n;
	LL suma = 0;
	for (int i = 0; i < n; i ++)
	{
		int x;
		x = read();
		suma += x;
		if (x >= k) ans --;
		else a.pb(x);
	}

	if (suma < k)
	{
		cout << n << endl;
		return 0;
	}
	else if (suma == k)
	{
		cout << 0 << endl;
		return 0;
	}
	n = (int)a.size();

	t.set(0);
	for (int i = 0; i < n; i ++)
	{
		if (i) t = (t << a[i - 1]) | t;
		t2 = t;
		bool f = 0;
		for (int j = i + 1; j < n; j ++)
		{
			t2 = (t2 << a[j]) | t2;
			if (~j & 31)
            {
				for (register int l = k - a[i]; l < k; l ++)
					if (t2.test(l))
					{
						f = 1;
						break;
					}

				if (f) break;
			}
		}
		for (register int j = k - a[i]; j < k; j ++)
			if (t2.test(j))
			{
				f = 1;
				break;
			}

		ans -= f;
	}

	cout << ans << endl;

	return 0;
}

