bool judge(const V<ll> &alist, ll n, ll k, ll idx)
{
    bitset<5005> bs;
    bs.set(0);
    bitset<5005> bs_orig;

    rep (i, n) {
        if (i == idx) continue;
        ll a = alist[i];
        bs_orig = bs;
        bs <<= a;
        bs |= bs_orig;
    }

    if (k < alist[idx]) return false;

    srep (i, k-alist[idx], k) {
        if (bs.test(i)) return false;
    }

    return true;
}

