		for(int j = 0; j < k; j++) {
			if(i && L[i - 1][j] && j + a[i] >= k) flag = false;
			if(i < n - 1 && R[i + 1][j] && j + a[j] >= k) flag = false;
			if(i < n - 1 && R[i + 1][j]) vec.push_back(j);
		}
		if(!flag) continue;
		if(i) for(int j = 0; j + a[i] < k; j++) {
			if(L[i - 1][j]) {
				int p = lower_bound(vec.begin(), vec.end(), k - j) - vec.begin(); p--;
				if(p >= 0) {
					if(vec[p] + j + a[i] >= k) {
						flag = false;
						break;
					}
				}
			}
		}
		res += flag;
	}
	printf("%d\n", res);
	return 0;
}

