s64 N;
s64 K;

vector<s64> A;

template<typename T, size_t N, size_t... NS>
struct ArrayStruct {
    using type = array<typename ArrayStruct<T,NS...>::type,N>;
};

template<typename T, size_t N>
struct ArrayStruct<T,N> {
    using type = array<T,N>;
};

template<typename T, size_t N, size_t... NS>
using Array = typename ArrayStruct<T,N,NS...>::type;

Array<bool,5001,5001> dp1 {};
Array<bool,5001,5001> dp2 {};

template<typename T>
void do_dp(T& dp)
{
    dp[0][0] = true;

    FOR(i, 1, N) REP(j, K+1) {
        s64 a = A[i-1];
        dp[i][j] = dp[i-1][j];
        if(j >= a)
            dp[i][j] = dp[i][j] || dp[i-1][j-a];
    }
}

void solve()
{
    if(N == 1) {
        s64 ans = A[0] >= K;
        PRINTLN(ans);
        return;
    }

    do_dp(dp1);

    ALL(reverse, A);
    do_dp(dp2);
    ALL(reverse, A);

#ifdef DEBUG
    DPRINTLN("[dp1]");
    REP(i, N+1) {
        REP(j, K+1) {
            DPRINT(dp1[i][j]);
            DPRINT(" ");
        }
        DPRINTLN();
    }

    DPRINTLN("[dp2]");
    REP(i, N+1) {
        REP(j, K+1) {
            DPRINT(dp2[i][j]);
            DPRINT(" ");
        }
        DPRINTLN();
    }
#endif

    s64 ans = 0;
    REP(i, N) {
        s64 a = A[i];
        bool need = false;
        if(i == 0) {
            FOR(j, max<s64>(0,K-a), K) {
                if(dp2[N-1][j]) {
                    need = true;
                    break;
                }
            }
        }
        else if(i == N-1) {
            FOR(j, max<s64>(0,K-a), K) {
                if(dp1[N-1][j]) {
                    need = true;
                    break;
                }
            }
        }
        else {
            FOR(j, max<s64>(0,K-a), K) {
                REP(s, j+1) {
                    s64 t = j - s;
                    if(dp1[i][s] && dp2[N-1-i][t]) {
                        need = true;
                        goto finish;
                    }
                }
            }
finish: ;
        }
        if(!need)
            ++ans;
    }

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    A.resize(N);
    RD(K);

    REP(i, N) {
        RD(A[i]);
    }

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

