typedef long long ll;

const int N = 5005;

ll a[N];

int main()
{
	int n, k;
	scanf("%d%d", &n, &k);
	for(int i = 0; i < n; i++)
		scanf("%lld", &a[i]);
	sort(a, a + n, greater<ll>() );
	int cnt = 0, tmp = 0;
	ll sum = 0;
	for(int i = 0; i < n; i++){
		sum += a[i];
		tmp ++;
		if(sum >= k){
