using namespace std;

class NoNeed
{
private:
	int n, k;
	int sum;
	vector<vector<bool> > l_dp;
	vector<vector<bool> > r_dp;
	vector<int> a;
public:
	NoNeed(){
		cin >> n >> k;
		a.resize(n);
		sum = 0;
		for (int i = 0; i < n; ++i)
		{
			cin >> a[i];
			sum += a[i];
		}
		l_dp = vector<vector<bool> >(n, vector<bool>(k+1, false));
		r_dp = vector<vector<bool> >(n, vector<bool>(k+1, false));
	}

	void exec(){
		sort(a.begin(), a.end());
		if(sum < k){
			cout << n << endl;
			return;
		}

		if(n == 1){
			cout << 0 << endl;
			return;
		}

		l_dp[0][0] = true;
		l_dp[0][a[0]] = true;
		for (int i = 1; i < n; ++i)
		{
			for (int j = 0; j <= k; ++j)
			{
				if(l_dp[i-1][j] || (j - a[i] >= 0 && l_dp[i-1][j - a[i]]) ){
					l_dp[i][j] = true;
				}
			}
		}
		r_dp[n-1][0] = true;
		r_dp[n-1][a[n-1]] = true;
		for (int i = n-2; i >= 0; --i)
		{
			for (int j = 0; j <= k; ++j)
			{
				if(r_dp[i+1][j] || (j -  a[i] >= 0 && r_dp[i+1][j - a[i]]) ){
					r_dp[i][j] = true;
				}
			}
		}

		int left = 0;
		int right = n-1;
		while(left + 1 < right){
			int mid = (left + right) / 2;
			if(a[mid] >= k){
				right = mid;
				continue;	
			}
			// cout << mid << endl;
			bool check = false;
			for (int i = k - a[mid]; i < k; ++i)
			{
				if(mid == 0){
					if(r_dp[1][i]) check = true;
					break;
				}

				if(mid == n-1){
					if(l_dp[n-2][i]) check = true;
					break;
				}

				for (int j = 0; j <= i; ++j)
				{
					if(l_dp[mid-1][j] && r_dp[mid+1][i-j]){
						check = true;
						break;
					}
				}
			}
			if(check){
				right = mid;
			}else{
				left = mid+1;
			}
		}
		cout << right - 1 << endl;

	}
};


int main(){
	NoNeed nn = NoNeed();
	nn.exec();
}

