ll pow1(ll n, ll p, int MOD){
  ll r, c;
  r = 1;
  c = n;
  while(p){
    if(p & 1){
      (r *= c) %= MOD;
    }
    (c *= c) %= MOD;
    p /= 2;
  }
  return r;
}
int n, k;
int calc(int r[], int s, int MOD){

  int cnt1 = 0;
  for(int i = 0;i < k;i++)
    cnt1 += r[i], (cnt1 >= MOD && (cnt1 -= MOD));
  cnt1 = (pow1(2, s, MOD) - cnt1 + MOD) % MOD;
  return cnt1;
}
int main(){
  cin >> n >> k;
  int a[n + 1];
  for(int i = 1;i <= n;i++)
    cin >> a[i];
  cnt[0][0] = 1;

  for(int i = 1;i <= n;i++){
    for(int j = 0;j <= 10000;j++){
      cnt[i][j] = cnt[i - 1][j];
      if(a[i] <= j)
        cnt[i][j] += cnt[i - 1][j - a[i]];
      if(cnt[i][j] >= MOD)
        cnt[i][j] -= MOD;
    }
  }
  int cnt1 = calc(cnt[n], n, MOD);
  int cnt11 = calc(cnt[n], n, MOD2);

  int ans = 0;
  for(int i = 1;i <= n;i++){
    for(int j = 0;j <= 10000;j++){
      res[j] = cnt[n][j];
    }
    for(int j = a[i];j <= 10000;j++){
