const int MAX = 5050;
int N, K;
int a[MAX];

bool check(int idx) {   //不必要ならばtrue
    LL sum = a[idx];
    int moveIdx = idx + 1;
    while (sum < K && moveIdx < N + 1) {
        sum += a[moveIdx++];
    }
    moveIdx = 0;
    while (sum < K && moveIdx < idx) {
        sum += a[moveIdx++];
    }
    //DEBUG(sum)
    if (sum < K) return true;
    return sum - a[idx] >= K;
}

int main(void) {
    scanf("%d%d", &N, &K);
