        cout << N << endl;
        return 0;
    }
    int high = N, low = 0;
    while (high - low > 1) {
        const int mid = (high + low) / 2;
        //DEBUG(mid)DEBUG(check(mid))
        (check(mid) ? low : high) = mid;
    }
    cout << low << endl;
}

