typedef long long ll;
int n,K,A[N];
ll Sum[N];
int mem[N][N],used[N][N],ans[N];

ll dfs(int pos,ll sum){
  if(sum>=K) return sum;
  if(used[pos][sum]++) return mem[pos][sum];
  if(Sum[pos+1]+sum<K)return 1LL<<30;
  if(Sum[pos+1]+sum==K) {
    for(int i=0;i<=pos;i++) ans[i]=1;
    return K;
  }


  ll a=dfs(pos-1,sum+A[pos]);
  if(a>=K&&a-A[pos]<K)ans[pos]=1;
  ll b=dfs(pos-1,sum);
  if(b<a&&b>=K)a=b;
  return mem[pos][sum]=a;
}

int main(){
  cin>>n>>K;
  for(int i=0;i<n;i++)cin>>A[i];
  sort(A,A+n);
  for(int i=1;i<=n;i++) Sum[i]=A[i-1]+Sum[i-1];

  dfs(n-1,0);
  int cnt=0;
  for(int i=0;i<n;i++) if(ans[i])cnt++;
  cout<<n-cnt<<endl;
  return 0;
}

