        vector<ll> x,y;
        rep(j,0,k+1){
            if(b[i-1][j]) x.pb(j);
            if(c[i+1][j]) y.pb(j);
        }
        rep(j,0,sz(x)){
            if(lb(y,k-a[i]-x[j])!=y.end()&&x[j]+*lb(y,k-a[i]-x[j])<k){
                break;
            }
            if(j==sz(x)-1) ans++;
        }
    }
    cout <<ans<<"\n";
}

