		for(x2=1;x2+a[xb]<=k+1;x2++){
			CNT-=sor[x2-1];
			CNT+=sor[x2+a[xb]-1];
			if(CNT) temp[x2]=1;
		}
		// F: k-a[xb]-v~~~~k-1-v 
		bool ok=1;
		for(x2=0;x2<=k-a[xb];x2++){
			if(aa[xb-1][x2]&&temp[k-a[xb]-x2]){
				ok=0;
				break;
			}
		}
		if(ok){
			bool got=0;
			for(x2=k-1;x2>=k-a[xb];x2--){
				got|=sor[k-1-x2];
				if(aa[xb-1][x2]&&got){
					ok=0;
					break;
				}
			}
		}
		if(ok)cnt++;
	}
	printf("%d\n",cnt);
	return 0;
}

