	}
	R int mid = l + r >> 1;
	f[o + 1] = f[o];
	for (R int i = l; i <= mid; ++i)
		f[o + 1] |= f[o] << b[i];
	solve(o + 1, mid + 1, r);

	f[o + 1] = f[o];
	for (R int i = mid + 1; i <= r; ++i)
		f[o + 1] |= f[o] << b[i];
	solve(o + 1, l, mid);
}
