        }
        sort(a, a + n);
        int id;
        for(int i = 0; i < n; i++) {
            if(a[i] < k) id = i;
        }
        memset(dp, 0, sizeof dp);
        dp[0][0] = dp[0][a[0]] = 1;
        for(int i = 1; i <= id; i++) {
            for(int j = 0; j <= k; j++) {
                if(dp[i - 1][j]) { dp[i][j] = 1; break; }
                if(j - a[i] < 0) continue;
                if(dp[i - 1][j - a[i]]) { dp[i][j] = 1; break; }
            }
        }
        int tal = 0;
        for(int i = 0; i <= id; i++) {
            for(int s = k - a[i]; s < k; s++) {
                if(can_sum(s, i, id)) { tal++; break; }
            }
        }
        if(sum < k) tal = n;
        printf("%d\n", tal);
    }
    return 0;
}

