// Begin FFT Library

typedef complex<double> CD;
const double PI = 4 * atan(1);

const int LOG = 13;
const int S = 1 << LOG;

CD w[S]; int rev[S];

void initFFT() {
    for (int i = 0; i < S; i++) w[i] = CD(cos(2 * PI * i / S), sin(2 * PI * i / S));

    rev[0] = 0;

    for (int mask = 1; mask < S; mask++) {
        int k = 0;
        while(((mask >> k) & 1) == 0) k++;
        rev[mask] = rev[mask ^ (1 << k)] ^ (1 << (LOG - 1 - k));
    }
}

CD F[2][S];

void FFT(CD* A, int k) {
    int L = 1 << k;
    for (int i = 0; i < L; i++) F[0][rev[i] >> (LOG - k)] = A[i];

    int t = 0, nt = 1;
    for (int lvl = 0; lvl < k; lvl++) {
        int len = 1 << lvl;
        for (int st = 0; st < L; st += (len << 1)) {
            for (int i = 0; i < len; i++) {
                CD ad = F[t][st + len + i] * w[i << (LOG - 1 - lvl)];
                F[nt][st + i] = F[t][st + i] + ad;
                F[nt][st + len + i] = F[t][st + i] - ad;
            }
        }
        swap(t, nt);
    }

    for (int i = 0; i < L; i++) A[i] = F[t][i];
}

// End FFT Library

CD x[S], y[S];

