	rep(i, 5010)rep(j, 5010) dp[i][j] = 0;
	dp[0][0] = 1;
	rep(i, N)rep(j, K + 1){
		if(dp[i][j] == 0) continue;
		dp[i + 1][j] = 1;
		if(i == idx) continue;
		if(j + a[i] > K) continue;
		dp[i + 1][j + a[i]] = 1;
	}
	reps(i, max(0, K - a[idx]), K){
		if(dp[N][i]) return true;
	}
	return false;
}

int main(void){
