int N, K, arr[5000];

bool isPos[5000];

bool judge(int ex) {
    memset(isPos, false, sizeof isPos);
    isPos[0] = true;
    if(K == 1 && arr[ex])
        return true;
    for(int v = K-1; v >= 0; v--) {
        for(int i = 0; i < N; i++) {
            if(i != ex && v + arr[i] < K && isPos[v]) {
                isPos[v + arr[i]] = true;
                if(v + arr[i] >= K - arr[ex])
                    return true;
            }
        }
    }

    return false;
}

int main () {
    scanf("%d %d", &N, &K);
    for(int n = 0; n < N; n++) {
        scanf("%d", arr + n);
    }
    sort(arr, arr + N);

    int bot = -1, top = N;
    while(bot + 1 < top) {
        int mid = (bot + top) / 2;
//        printf("%d %d %d %d\n", bot, mid, top, judge(mid));
        if(judge(mid)) {
            top = mid;
        }
        else{
            bot = mid;
        }
    }

    printf("%d\n", bot+1);

    return 0;
}

