	VEC(int, a, n);
	std::sort(ALL(a));
	ll sum = 0;
	REP(i, n) {
		sum += a[i];
	}
	if (sum < k) {
		OUT(n)BR;
		return 0;
	}
	int cnt = 0;
	std::vector<int> toset;
	toset.reserve(k);
	REP(i, n) {
		if (a[i] >= k) continue;
		std::set<int> set;
		bool in = false;
		toset.resize(0);
		REP(j, n) {
			if (i == j) continue;
			if (a[j] >= k) continue;
			if (IN(k - a[i], a[j], k)) {
				in = true;
				break;
			}
			toset.emplace_back(a[j]);
			for (const auto& x : set) {
				if (a[j] + x >= k) continue;
				if (IN(k - a[i], a[j] + x, k)) {
					in = true;
					break;
				}
				toset.emplace_back(a[j] + x);
			}
			if (in) break;
			for (const auto& x : toset) {
				set.insert(x);
			}
		}
		if (!in) ++cnt;
	}
	OUT(cnt)BR;
	return 0;
}

