const int borne = 5005;
int tab[borne];
bool pref[borne][borne];
bool suff[borne][borne];
int n,k;

void solve()
{
	cin >> n >> k;
	form(i, n) cin >> tab[i];
	pref[0][0] = suff[n-1][0] = true;
	form(i, n) {
		form(v, k) {
			pref[i+1][v] |= pref[i][v];
			if (v >= tab[i]) pref[i+1][v] |= pref[i][v - tab[i]];
		}
	}
	ford(i, n) if (i > 0) {
		form(v, k) {
			suff[i-1][v] |= suff[i][v];
			if (v >= tab[i]) suff[i-1][v] |= suff[i][v - tab[i]];
		}
	}

	int cnt = 0;
	form(i, n) {
		bool estUtile = false;
		int c2 = k-1;
		form(c1, k) {
			while (c1+c2 >= k || suff[i][c2] == false) --c2;
			if (pref[i][c1] && c1+c2+tab[i] >= k) { estUtile = true; break; }
		}
		if (!estUtile) ++cnt;
	}
	cout << cnt << "\n";
}

