using namespace std;

const int MAX_N = 5005, MAX_V = 5005;
int N, K, dp[MAX_N][MAX_V], a[MAX_N];

int main(){
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> N >> K;
    for(int i=0;i<N;i++) cin >> a[i];

    sort(a, a+N);

    int left = -1, right = N;
    while(1<right-left){
        int mid = (left+right) / 2;
        if(K<=a[mid]) {right = mid; continue;}

        for(int i=0;i<=N;i++) for(int j=0;j<=K;j++) dp[i][j] = 0;
        dp[0][0] = 1;
        swap(a[mid], a[N-1]);
        for(int i=0;i<N-1;i++){
            for(int j=0;j<=K;j++){
                dp[i+1][j] |= dp[i][j];
                if(a[i]<=j) dp[i+1][j] |= dp[i][j-a[i]];
            }
        }
        swap(a[mid], a[N-1]);
        bool ok = false;
        for(int i=max(0, K-a[mid]);i<K;i++) if(dp[N-1][i]) ok = true;
        if(ok) right = mid;
        else left = mid;
    }

    cout << left + 1 << endl;
    return 0;
}

