int main() {
//  freopen("in.cpp","r",stdin);
  cin>>n>>m;
  for(int i=1; i<=n; i++)cin>>a[i];
  L[0][0]=1;
  for(int i=0; i<n; i++)
    for(int j=0; j<=m; j++) {
      if(!L[i][j])continue;
      L[i+1][j]=1;
      int nj=min(j+a[i+1],m);
      L[i+1][nj]=1;
    }
  R[n+1][0]=1;
  for(int i=n+1; i>1; i--)
    for(int j=0; j<=m; j++) {
      if(!R[i][j])continue;
      R[i-1][j]=1;
      int nj=min(j+a[i-1],m);
      R[i-1][nj]=1;
    }
  int ret=0;
  for(int i=1; i<=n; i++) {
    int mx = 0,r=-1;
    bool sign=0;
    for(int j=m-1;j>=0;j--){
      if(!R[i+1][j])continue;
      while(r+1+j<m){
        if(L[i-1][r+1])mx=r+1;
        r++;
      }
      if(mx!=-1&&mx+j<m&&mx+j+a[i]>=m){
        sign=1;
        break;
      }
    }
    if(sign)ret++;
  }
  cout<<n-ret<<endl;
  return 0;
}

