#include <bits/stdc++.h>
using namespace std;
bitset<5005> pref[5005], suff[5005];
int a[5005];
int main(){
    int n, k;
    scanf("%d%d", &n, &k);
    pref[0][0] = suff[n+1][0] = 1;
    for(int i=1;i<=n;i++){
        scanf("%d", &a[i]);
        for(int j=0;j<=k;j++){
            if(pref[i-1][j]){
                if(j+a[i] <= k) pref[i][j+a[i]] = 1;
                pref[i][j] = 1;
            }
        }
    }
    for(int i=n;i>=1;i--){
        for(int j=0;j<=k;j++){
            if(suff[i+1][j]){
                if(j+a[i] <= k) suff[i][j+a[i]] = 1;
                suff[i][j] = 1;
            }
        }
    }
    int ans = 0;
    for(int i=1;i<=n;i++){
        if(a[i] >= k) continue;
        int l = k-a[i], r = k-1, sum = 0, ok = 1;
        for(int j=l;j<=r;j++) if(suff[i+1][j]) sum++;
        for(int j=0;j<=k-1;j++){
            if(pref[i-1][j] && sum > 0){
                ok = 0;
                break;
            }
            if(l > 0){
                l--;
                if(suff[i+1][l]) sum++;
            }
            if(suff[i+1][r]) sum--;
            r--;
        }
        if(ok) ans++;
    }
    printf("%d\n", ans);
}

