class BinaryIndexedTree
{
private:
    int n;
    vector<int> data;
public:
    BinaryIndexedTree(int n){ // コンストラクタ
        this->n = n;
        data.assign(n+1, 0);
    }
    void add(int k, int x){ // k番目の要素にxを加算する
        ++ k;
        while(k <= n){
            data[k] += x;
            k += k & -k;
        }
    }
    int sum(int k){ // 区間[0,k]の総和を返す
        ++ k;
        int ret = 0;
        while(k > 0){
            ret += data[k];
            k -= k & -k;
        }
        return ret;
    }
    int sum(int a, int b){ // 区間[a,b]の総和を返す
        return sum(b) - sum(a-1);
    }
};

int main()
{
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for(int i=0; i<n; ++i)
        cin >> a[i];

    vector<BinaryIndexedTree> dp1(n+1, BinaryIndexedTree(k+1));
    vector<BinaryIndexedTree> dp2(n+1, BinaryIndexedTree(k+1));
    dp1[0].add(0, 1);
    dp2[0].add(0, 1);
    for(int i=0; i<n; ++i){
        for(int j=0; j<=k; ++j){
            if(dp1[i].sum(j, j) > 0){
                dp1[i+1].add(j, 1);
                int j2 = min(k, j + a[i]);
                dp1[i+1].add(j2, 1);
            }
            if(dp2[i].sum(j, j) > 0){
                dp2[i+1].add(j, 1);
                int j2 = min(k, j + a[n-1-i]);
                dp2[i+1].add(j2, 1);
            }
        }
    }

    int ans = n;
    for(int i=0; i<n; ++i){
        for(int x=0; x<k; ++x){
            if(dp1[i].sum(x, x) > 0 && dp2[n-1-i].sum(k-x-a[i], k-x-1)){
                -- ans;
                break;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

