typedef long long ll;

const int MAX_N=400,MAX_K=400;

int N,K,A[MAX_N];

bool dp[MAX_N+1][MAX_K+1];
bool flg[MAX_N];

void solve(){
	ll sum=0;
	REP(i,N){
		sum+=A[i];
	}
	if (sum<K){
		cout<<N<<endl;
		return;
	}
	sort(A,A+N);
	reverse(A,A+N);
	int ans=0;
	REP(i,N){
		if (flg[i]) continue;
		fill(dp[0],dp[0]+K+1,false);
		dp[0][0]=true;
		REP(j,N){
			fill(dp[j+1],dp[j+1]+K+1,false);
			int a;
			if (i==j){
				a=0;
			}else{
				a=A[j];
			}
			REP(k,K+1){
				dp[j+1][k]|=dp[j][k];
				dp[j+1][min(k+a,K)]|=dp[j][k];
			}
		}
		int x=-1;
		FOR(j,max<ll>(K-A[i],0LL),K+1){
			if (dp[N][j]){
				x=j;
				break;
			}
		}
		if (x>=K){
			ans++;
			for(int k=N-1;k>0;k--){
				if (i==k) continue;
				if (!dp[k][x]){
					flg[k]=true;
					if (k>i){
						ans++;
					}
					x-=A[k];
				}
			}
		}
	}
	cout<<ans<<endl;
}

