ll dp[N][N];

bool evaluate(vector<pll> &vt, ll idx, ll k){
	ll n = vt.size();
	memset(dp, 0, sizeof(dp));
	dp[0][0]=1;

	for(int i=0 ; i<n ; i++) { 
		for(int cur_sum = 0 ; cur_sum <=k ; cur_sum++){

			dp[i+1][cur_sum] = dp[i][cur_sum];

			ll cur = vt[i].first;
			if(cur <= cur_sum && i != idx){
				dp[i+1][cur_sum] |= dp[i][cur_sum-cur];
			}

		}
	}

	for(int i = max(0ll, k-vt[idx].first) ; i<= k-1 ; i++){
		if(dp[n][i]){
			return true;
		}
	}

	return false;
}

ll subset_sum(vector<pll> &vt, ll k){
	ll n = vt.size();
	ll s = 0;
	ll e = n-1;
	ll ans = -1;

	while(s<=e){
		ll mid = (s+e)/2;
		if(evaluate(vt, mid, k)==0){
			ans = mid;
			s = mid+1;
		} else {
			e = mid-1;
		}
	}

	return ans;
}


