using namespace std;
#define MAXN 5100

//尺取法
int n,k;
ll data[MAXN];
ll sum[MAXN];

int main(){
	sum[0] = 0;
	//freopen("D.txt","r",stdin);

	scanf("%d %d",&n,&k);
	for(int i = 1;i <= n;i++)
		scanf("%lld",&data[i]);

	sort(data+1,data+n+1);
	for(int i = 1;i <= n;i++)
		sum[i] = sum[i-1] + data[i];

	ll ans[MAXN]; ms(ans);
	int lpos,rpos;	//每次循环末尾,[lpos,rpos]的区间必定为good set,且rpos-lpos最小
	lpos = rpos = n; 
	while(lpos > 0  &&  rpos > 0){
		if(sum[rpos] - sum[lpos-1] >= k){
			while(sum[rpos] - sum[lpos-1] >= k) rpos--;
			rpos++;
		}else{
			while(sum[rpos] - sum[lpos-1] < k) lpos--;
		}
		if(lpos < 1  ||  rpos < 1) break;
		for(int i = lpos;i <= rpos;i++)
			ans[i]++;
		rpos--;
	}

	int realans = 0;
	for(int i = 1;i <= n;i++)
		if(!ans[i])
			realans++;

	cout << realans << endl;

	return 0;
}

