int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n >> k;
	for(int i=1; i<=n; ++i) cin >> a[i];
	sort(a+1, a+n+1);
	int l = 0, r = n+1;
	while(l+1 != r){
		int m = (l + r) / 2;
		int v[5010] = {};
		for(int i=1; i<=n; ++i){
			if(i < m) v[i] = a[i];
			if(i > m) v[i-1] = a[i];
		}
//		cout << m << "\n";
//		for(int i=1; i<=n-1; ++i) cout << i << " " << v[i] << "\n";
		ull dp[5010][80] = {{}};
		dp[0][0] = 1;
		for(int i=1; i<=n-1; ++i){
			int x = v[i] / 64, y = v[i] % 64;
			dp[i][0] |= 1;
			if(x < 80) dp[i][x] |= 1 << y;
			for(int j=0; j+x<80; ++j){
				dp[i][j+x] |= dp[i-1][j+x] | (dp[i-1][j] << y);
				dp[i][j+x+1] |= dp[i-1][j+x+1] | (dp[i-1][j] >> (64 - y));
			}
		}
		bool f = false;
//		for(int i=0; i<n; ++i) cout << i << " " << bitset<64>(dp[i][0]) << "\n";
		for(int i=max(0, k-a[m]); i<=k-1; ++i){
			if((dp[n-1][i/64] >> (i%64)) % 2 == 1) f = true;
		}
		if(f) r = m;
		else l = m;
	}
	cout << l << "\n";
}

