signed main() {
    int n, k;
    cin >> n >> k;
    if (n > 20) return -1;
    int a[n];
    for (int i = 0; i < n; i++) cin >> a[i];
    int f[n] = {};
    for (int i = 1; i < 1LL << n; i++) {
        int sum = 0;
        for (int j = 0; j < n; j++) {
            if (i & (1LL << j)) {
                sum += a[j];
            }
        }
        if (sum < k) continue;
        for (int j = 0; j < n; j++) {
            if (i & (1LL << j)) {
                if (sum - a[j] < k) {
                    f[j] = 1;
                }
            }
        }
    }
    int ans = n;
    for (int i = 0; i < n; i++) ans -= f[i];
    cout << ans << endl;
    return 0;
}

