        cin >> a[i];
        a[i] = min(a[i], 5000);
    }
    pre[1][0] = 1;
    pre[0][0] = 1;
    for(int i = 0 ; i < n ; i++ ) {
        pre[i+1] |= pre[i+1] << a[i];
        pre[i+2] = pre[i+1];
    }
    suf[0][0] = 1;
    suf[1][0] = 1;
    for(int i = 0 ; i < n ; i++ ) {
        suf[i+1] |= suf[i+1] << a[n - i - 1];
        suf[i+2] =  suf[i+1];
    }
    int ans = 0;
    for(int i = 0 ; i < n ; i++ ) {
        set<int>s;
        s.clear();
        for(int j = 0 ; j <= 5000 ; j++ ) {
            if(suf[n-i-1][j]) s.insert(j);
        }
        /*cout << '\t' << i << '\n';
        for(int u: s) cout << u << ' ' ;
        cout << '\n';*/
        bool ok = 1;
        for(int j = 0 ; j <= 5000 ; j++ ) {
            if(pre[i][j]) {
                auto it = s.lower_bound(k - j - a[i]);
               // cout << j << ' ' << (it == s.end()) << ' ' << *it<< '\n';
                if(it != s.end()) {
                    if(*it + j < k) {
                        ok = 0;
                    }
                }
            }
        }
        ans+=ok;
    }
    cout << ans;
}

