int C(int x)
{
    bitset<5005> dp;
    if(a[x]>=k) return 1;
    dp[0]=1;
    for(int i=0;i<n;++i)
    {
        if(i==x) continue;
        dp|=(dp<<a[i]);
    }
    for(int i=k-1;i>=k-a[x];--i)
        if(dp[i]) return 1;
    return 0;
}

