#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}
void read_cr() {
    fgets(_buf, 256, stdin);
}

ll solve(int N,int K,vi& a) {
    int cap = K*2;
    rep(i,N) a[i] = min(cap, a[i]);
    cap = min(K + *max_element(ALL(a)), cap);

    vvi pre(N+1, vi(1+cap, 0)),
         post(N+1, vi(1+cap, 0));
    vvi pre_(N+1, vi());
    vvi post_(N+1, vi());

    pre[0][0] = 1;
    pre_[0].pb(0);
    for (int i=0; i<N; ++i){
        int d = a[i];
        rep(j,1+cap){
            if (!pre[i][j]) continue;
            pre[i+1][j] |= 1;
            if (j+d <= cap) pre[i+1][j+d] |= 1;
        }
        rep(j,1+cap) {
            if (pre[i+1][j]) pre_[i+1].pb(j);
        }
        // cerr << pre_[i+1] << endl;
    }

    post[0][0] = 1;
    post_[0].pb(0);
    for (int i=0; i<N; ++i){
        int d = a[N-1-i];
        rep(j,1+cap){
            if (!post[i][j]) continue;
            post[i+1][j] |= 1;
            if (j+d <= cap) post[i+1][j+d] |= 1;
        }
        rep(j,1+cap) {
            if (post[i+1][j]) post_[i+1].pb(j);
        }
        // cerr << post_[i+1] << endl;
    }

    int ans = 0;
    for (int i=0; i<N; ++i) {
        if (a[i] >= K) {
            // needed = true;
            continue;
        }
        bool needed = false;
#ifdef DEBUG
        cerr << a[i] << pre_[i] << post_[N-1-i] << endl;
        fprintf(stderr, " looking for [%d-%d, %d)\n", K,a[i],K);
#endif
        for (int p : pre_[i]){
            // [k-ai, k) を探してて
            // pを引くから
            // [k-p-ai, k-p)
            auto it = lower_bound(ALL(post_[N-1-i]), K-p-a[i]);
            auto jt = lower_bound(ALL(post_[N-1-i]), K-p);
            if (it != jt) { needed = true; break; }
        }
        if (!needed) ++ans;
    }

    return ans;
}

int main() {
    int N,K; cin >> N >> K;
    read_cr();
    vi a(N);
    loadvec(a,N);
    cout << solve(N,K,a) << endl;
    // cout << (solve(N,a) ? "Yes":"No") << endl;
    return 0;
}

