#include <bits/stdc++.h>

using namespace std;

const int N = 5009;

int n, k, a[N]; 
int acc2[N][N], dp1[N][N], dp2[N][N]; 

void readInput() {

    scanf("%d %d", &n, &k);
    for(int i = 1; i <= n; i ++) {
        scanf("%d", &a[i]);
    }
}

void preProcess() {

    dp1[0][0] = 1;
    for(int i = 0; i < n; i ++) {
        for(int j = 0; j <= k; j ++) {
            if(dp1[i][j]) {
                dp1[i + 1][min(k, j + a[i + 1])] = 1;
                dp1[i + 1][j] = 1;
            }
        }
    } 

    dp2[n + 1][0] = 1;
    for(int i = n + 1; i; i --) {
        for(int j = 0; j <= k; j ++) {
            if(dp2[i][j]) {
                dp2[i - 1][min(k, j + a[i - 1])] = 1;
                dp2[i - 1][j] = 1;
            }
        }
    }

    for(int i = 0; i <= n + 1; i ++) {
        for(int j = 0; j <= k; j ++) {
            if(dp2[i][j]) {
                acc2[i][j] ++;
            }
        } 
        for(int j = 1; j <= k; j ++) {
            acc2[i][j] += acc2[i][j - 1];
        }
    }
}

int main(int argc, char const *argv[]) {

    readInput();
    preProcess();

    int ans = 0;

    for(int i = 1; i <= n; i ++) {
        bool found = false;
        for(int leftSum = 0; leftSum < k; leftSum ++) {
            if(dp1[i - 1][leftSum]) {
                int rightSumLow = max(0, k - a[i] - leftSum);
                int rightSumHigh = k - 1 - leftSum;
                if(rightSumHigh < rightSumLow) {
                    continue;
                }
                if(acc2[i + 1][rightSumHigh] - (rightSumLow ? acc2[i + 1][rightSumLow - 1] : 0) > 0) {
                    found = true;
                    break;
                }
            }
        }
        if(!found) {
            ans ++;
        }
    }

    printf("%d\n", ans);

    return 0;
}

