signed main() {
	INIT;
	VAR(int, n, k);
	VEC(int, a, n);
	std::sort(ALL(a));
	int sum = 0;
	REP(i, n) {
		sum += a[i];
	}
	if (sum < k) {
		OUT(n)BR;
		return 0;
	}
	int cnt = 0;
	REP(i, n) {
		if (a[i] >= k) continue;
		std::set<int> set;
		bool in = false;
		REP(j, n) {
			if (i == j) continue;
			if (a[j] >= k) continue;
			if (IN(k - a[i], a[j], k)) {
				in = true;
				break;
			}
			std::set<int> toset;
			toset.insert(std::min(a[j], k));
			for (const auto& x : set) {
				if (IN(k - a[i], a[j] + x, k)) {
					in = true;
					break;
				}
				if (a[j] + x >= k) continue;
				toset.insert(std::min(a[j] + x, k));
			}
			if (in) break;
			for (const auto& x : toset) {
				set.insert(x);
			}
		}
		if (!in) ++cnt;
	}
	OUT(cnt)BR;
	return 0;
}

