		int j = i;
		while (j < n&&a[i] == a[j]) j++;
		v.push_back(a[i]);
		r.push_back(j - i);
		i = j;
	}
	n = v.size();
	int s = 0, e = n, t;
	while (e - s > 1) {
		t = (s + e) / 2;
		if (solve(t)) s = t;
		else e = t;
	}
