int n,k;
bool dp[5001][5001];
map<int,int> sum;
vector<int> x;
bool unnecessary(int l){
    memset(dp,0,sizeof(dp));
    if(0<k && 0>=k-x[l])
        return 0;
    for(int i=0;i<n;i++){
        dp[i][0]=1;
        if(i==0)
            continue;
        if(i==l){
            for(int j=1;j<k;j++)
                dp[i][j]|=dp[i-1][j];
            continue;
        }
        for(int j=1;j<k;j++){
            if(j>=x[l])
                dp[i][j]|=(dp[i-1][j] | dp[i-1][j-x[l]]);
            else
                dp[i][j]|=dp[i-1][j];
            if(j<k && j>=k-x[l] && dp[i][j])
                    return 0;
        }
    }
    return 1;
}
int main(){
    cin>>n>>k;
    for(int i=0;i<n;i++){
        int b;
        cin>>b;
        x.push_back(b);
    }
    sort(x.begin(),x.end());
    for(int i=0;i<n;i++)
        sum[x[i]]++;
    unique(x.begin(),x.end());
    int lb=0,ub=n;
    while(lb<ub){
        int mid=(lb+ub)>>1;
        if(unnecessary(mid))
            lb=mid+1;
        else
            ub=mid;
    }
    int ans=0;
    for(int i=0;i<lb;i++)
        ans+=sum[x[i]];
    cout<<ans<<endl;
    return 0;
}

