const double DINF = std::numeric_limits<double>::infinity();
const int MOD = 1000000007;
#define MAX_N 5010

bool dp[MAX_N][MAX_N] = {};
bool maked[MAX_N][MAX_N] = {};     // グループ内の数の組み合わせで i 抜きで j が作れるなら true
int N, K;
int A[MAX_N];
map<int, bool> isChecked;
map<int, int> valToInd;

// 今 i を見ていて、現在の数が j のとき
// ただし A[skip] は加算せずにとばす
void dfs(int i, int j, int skip) {
    if(i >= N) { return; }
    if(dp[i][j]) { return; }
    dfs(i+1, j, skip);
    if(i != skip && j + A[i] < K) {
        maked[skip][j + A[i]] = true;
        dfs(i+1, j + A[i], skip);
        valToInd[A[i]] = i;
    }
    dp[i][j] = true;
}

signed main()
{
    cin >> N >> K;
    REP(i, N) { cin >> A[i]; }
    REP(i, N) {
        if(isChecked.count(A[i]) != 0) { continue; }
        ZERO(dp);
        dfs(0, 0, i);
        isChecked[A[i]] = true;
    }
    ll ans = N;
    REP(i, N) {
        for(int j = K - A[i]; j < K; ++j) {
            int ind = valToInd[A[i]];
            if( j <= 0 || maked[ind][j]) {
                ans--;
                break;
            }
        }
    }
    printf("%lld\n", ans);
    return 0;
}

