bool solve(int x){
    memset(f,false,sizeof f);
    f[0]=true;
    for(int i=0;i<n;i++)if(i!=x){
        assert(a[i]<k);
        for(int j=k-1;j>=0;j--)if(f[j] && j+a[i]<k)f[j+a[i]]=true;
    }
    int curr=k;
    for(int j=0;j<k;j++)if(f[j])curr=min(curr,k-j);
    return a[x]<=curr; // Un
}

int main(){
    scanf("%d %d",&n,&k);
    for(int i=0;i<n;i++)scanf("%d",a+i);
    sort(a,a+n);
    while(n>0 && a[n-1]>=k)n--;
    int first=0,last=n-1;
    while(first<=last){
        int mid=(first+last)/2;
        if(solve(mid))first=mid+1;
        else last=mid-1;
    }
    for(int res=max(0,first-5);res<=min(n,first+5);res++){
        if(res>=n || !solve(res)){
            printf("%d\n",res);
            return 0;
        }
    }
    assert(false);
    return 0;
}

