int n, k;

// NB: prefixDP[i][j] takes the first j terms of possibility on prefix
// NB: 0 is the first term
int prefixDP[5005][5005];
int suffixDP[5005][5005];

bool prefixPossible[5005][5005];
bool suffixPossible[5005][5005];


/*
isPossiblePrefix(n, k) -> true if there is a subset of the first
n integers that sums to k
isPossibleSuffix(n, k) -> true ...


[prefix] (idx) [suffix]



*/
int l[5005];

bool isUnnecessary(int idx) {
  for(int prefSum = 0; prefSum <= k; prefSum++) {
    if(!prefixPossible[idx][prefSum]) continue;
    // prefSum + suffSum < k <= prefSum + suffSum + l[idx]
    int minSuffSum = max(0, k - prefSum - l[idx]);
    int maxSuffSum = k - prefSum - 1;
    if(minSuffSum > maxSuffSum || maxSuffSum < 0) continue;
    if(suffixDP[n-idx-1][maxSuffSum + 1] - suffixDP[n-idx-1][minSuffSum]) {
      return false;
    }
  }
  return true;
}

void fillPrefix() {
  prefixPossible[0][0] = true;
  for(int i = 0; i < n; i++) {
    for(int j = 0; j <= k; j++) {
      prefixPossible[i+1][j] |= prefixPossible[i][j];
      prefixPossible[i+1][min(k, j + l[i])] |= prefixPossible[i][j];
    }
  }
  for(int i = 0; i < n; i++) {
    for(int j = 0; j <= k; j++) {
      prefixDP[i][j+1] = prefixDP[i][j];
      if(prefixPossible[i][j]) {
        prefixDP[i][j+1]++;
      }
    }
  }
}

void fillSuffix() {
  suffixPossible[0][0] = true;
  for(int i = 0; i < n; i++) {
    for(int j = 0; j <= k; j++) {
      suffixPossible[i+1][j] |= suffixPossible[i][j];
      suffixPossible[i+1][min(k, j + l[n-1-i])] |= suffixPossible[i][j];
    }
  }
  for(int i = 0; i < n; i++) {
    for(int j = 0; j <= k; j++) {
      suffixDP[i][j+1] = suffixDP[i][j];
      if(suffixPossible[i][j]) {
        suffixDP[i][j+1]++;
      }
    }
  }
}

int main() {
  scanf("%d%d", &n, &k);
  for(int i = 0; i < n; i++) {
    scanf("%d", &l[i]);
  }
  fillPrefix();
  fillSuffix();
  int ret = 0;
  for(int i = 0; i < n; i++) {
    if(isUnnecessary(i)) {
      ret++;
    }
  }
  printf("%d\n", ret);
}

