void read()
{
	scanf("%d%d", &n, &m);
	fi(n)
		scanf("%d", &a[i]);
}

void go(int sid)
{
	__(dp);
	dp[0] = 1;
	sums[sid][0].pb(0);
	fi(n)
	{
		fd(j, m, 0)
		{
			if (dp[j])
				dp[j + a[i]] = 1;
		}
		fj(m + 1)
		{
			if (dp[j])
				sums[sid][i + 1].pb(j);
		}
	}
}

bool solve()
{
	sort(a, a + n);
	fi(n)
	{
		if (a[i] >= m)
		{
			n = i;
			break;
		}
	}
	go(0);
	reverse(a, a + n);
	go(1);
	reverse(a, a + n);
	int res = 0;
	fi(n)
	{
		int sl = i, sr = n - i - 1;
		int l = 0, r = sz(sums[1][sr]) - 1;
		int lb = m - a[i];
		bool ok = false;
		while (true)
		{
			if (l >= sz(sums[0][sl]) || r < 0)
				break;
			int ss = sums[0][sl][l] + sums[1][sr][r];
			if (ss >= m)
				r--;
			else if (ss < lb)
				l++;
			else
			{
				ok = true;
				break;
			}
		}
		if (!ok)
			res++;
	}
	printf("%d\n", res);
	return false;
}

