	for(int i=0;i<n;i++){
		for(int j=0;j<k;j++){
			if(dp[i][j]==0)	continue;
			dp[i+1][j]+=dp[i][j];
			if(j+a[i]<k)	dp[i+1][j+a[i]]+=dp[i][j];
		}
	}
	//rdp[i][j]:i〜(n-1)までの要素を用いて和がjになる集合の数
	rdp[n][0]=1;
	for(int i=n-1;i>=0;i--){
		for(int j=0;j<k;j++){
			if(rdp[i+1][j]==0)	continue;
			rdp[i][j]+=rdp[i+1][j];
			if(j+a[i]<k)	rdp[i][j+a[i]]+=rdp[i+1][j];
		}
	}
	for(int i=n-1;i>=0;i--){
		bool flag=true;
		if(i==n-1){
			for(int j=k-a[i];j<k;j++){
				if(dp[i][j]!=0){
					flag=false;
					break;
				}
			}
		}
		else if(i==0){
			for(int j=k-a[i];j<k;j++){
				if(rdp[1][j]!=0){
					flag=false;
					break;
				}
			}
		}
		else{
			ll sum=0;
			//[k-a[i],k-1]に無ければ不要
			for(int l=k-1;l>=0;l--){
				sum+=rdp[i+1][k-1-l];
				if(k-a[i]>=l)	sum-=rdp[i+1][k-a[i]-l];
				if(dp[i][l]==0||sum==0)	continue;
				flag=false;
				break;
			}
		}
		if(flag){
			cout<<i+1<<endl;
			return 0;
		}
	}
	cout<<0<<endl;
	return 0;
}

