bool sub(vector<int> &a, int m) {
	if(K <= a[m]) {
		return true;
	}
	vector<vector<bool> > dp(K, vector<bool>(N, false)); //dp[y][x] : can one make y with {a[0], ..., a[x]} - {a[m]} ?
	for(int y = 0; y < K; ++y) {
		for(int x = 0; x < N; ++x) {
			if(y == 0) {
				dp[y][x] = true;
			} else if(x == 0) {
				if(x == m) {
					dp[y][x] = false;
				} else {
					dp[y][x] = (a[0] == y);
				}
			} else {
				if(x == m || y < a[x]) {
					dp[y][x] = dp[y][x - 1];
				} else {
					dp[y][x] = (dp[y][x - 1] || dp[y - a[x]][x - 1]);
				}
			}
			//cout << "dp[" << y << "][" << x << "] = " << dp[y][x] << '\n';
		}
	}
	for(int b = K - a[m]; b < K; ++b) {
		if(dp[b][N - 1]) {
			return true;
		}
	}
	return false;
}

