		for (ll x = 0; x <= k; ++x)
		{
			dp[1][p][x] = dp[1][p + 1][x];
			if (x - a[p] >= 0)
				dp[1][p][x] |= dp[1][p + 1][x - a[p]];
		}
	}
	ll ans = 0;
	for (ll s = 0; s < n; ++s)
	{
		ll lef = s;
		ll rht = s + 1;
		ll bot = k - a[s];//下限
		if (bot <= 0)bot = 1;
		ll range = k - bot;
		bool ismake = false;

		vector<ll>rimos;
		rimos.reserve(k);
		rimos.push_back(0);
		for (ll x = 0; x <= k; ++x)
		{
			rimos.push_back(rimos.back() + dp[1][rht][x]);
		}
		for (ll col = 0; col <= bot; ++col)
		{
			ll now = dp[0][lef][col];
			if (now && (rimos[bot - col + range] - rimos[bot - col]))
			{
				ismake = true;
			}
		}
		//残り(コーナー)
		for (ll col = bot + 1; col <= k; ++col)
		{
			ll now = dp[0][lef][col];
			if (now && (rimos[bot - col + range] - rimos[0]))
			{
				ismake = true;
			}
		}
		if (!ismake)++ans;
	}
	cout << ans << endl;
	return 0;
}

