        cin >> a[i];
    }

    vector< vector<int> > l(N+2, vector<int>(K)), r(N+2, vector<int>(K));
    l[0][0] = 1;
    r[N+1][0] = 1;
    for(int i=1; i<=N; i++) {
        for(int j=0; j<K; j++) {
            l[i][j] += l[i-1][j];
            if(j + a[i] >= K) continue;
            l[i][j + a[i]] += l[i-1][j];
        }
    }
    for(int i=N; i; i--) {
        for(int j=0; j<K; j++) {
            r[i][j] += r[i+1][j];
            if(j + a[i] >= K) continue;
            r[i][j + a[i]] += r[i+1][j];
        }
    }

    int need = 0;
    for(int i=1; i<=N; i++) {
        partial_sum(r[i+1].begin(), r[i+1].end(), r[i+1].begin());
        for(int j=0; j<K; j++) {
            if(l[i-1][j] == 0) continue;
            if(K-a[i] <= j && j < K) {
                ++need;
                break;
            }
            if(r[i+1][K-1-j] - r[i+1][max(K-a[i]-1-j, 0)]) {
                need++;
                break;
            }
        }
    }

    cout << N - need << endl;
    return 0;
}

