                    dp[i + 1][j + A[i]] += dp[i][j];
                }
                rep(j, K - A[i] + 1, K + 1) {
                    dp[i + 1][K] += dp[i][j];
                }
            }
        }

        bool b = false;
        rep(i, K - A[mid], K) {
            if (dp[M][i] > 0) b = true;
        }

        if (b) ok = mid;
        else ng = mid;
    }

    write(ok);
}

