bool isValid(int target, const std::vector<int>& a, int K, int sum) {
    // calc minimum value X which satisfies X >= K
    // if X - a[target] >= K, card[target] is invalid.

    std::vector<int> mins;
    mins.reserve(4096);
    mins.push_back(sum);

    for (int i = a.size()-1; i >= 0; i--) {
        if (i == target)
            continue;

        int size = mins.size();
        for (int j = 0; j < size; j++) {
            if (mins[j] - a[i] >= K) {
                mins.push_back(mins[j] - a[i]);
            }
        }
    }

    for (int j = 0; j < mins.size(); j++) {
        if (mins[j] - a[target] < K) {
            return true;
        }
    }

    return false;
}

