        std::cout << N << std::endl;
        return 0;
    }

    int ninvalid = 0;
    for (int i = 0; i < N; i++) {
        if (isValid(i, a, K, sum)) {
            break;
        } else {
            ninvalid++;
        }
    }

    std::cout << ninvalid << std::endl;
}

