int main() {
	int n, k;
	scanf("%d%d", &n, &k);
	vector<int> A(n);
	for (int i = 0; i < n; ++i) {
		scanf("%d", &A[i]);
		A[i] = min(A[i], k);
	}
	vector<vector<bool>> dp(n + 1, vector<bool>(k + 1));
	vector<vector<bool>> dp2(n + 1, vector<bool>(k + 1));
	vector<int> S(k + 1);
	dp[n][0] = 1;
	for (int i = n - 1; i >= 0; --i) {
		dp[i] = dp[i + 1];
		for (int j = A[i]; j <= k; ++j) {
			dp[i][j] = dp[i][j] || dp[i + 1][j - A[i]];
		}
	}
	dp2[0][0] = 1;
	for (int i = 0; i < n; ++i) {
		dp2[i + 1] = dp2[i];
		for (int j = A[i]; j <= k; ++j) {
			dp2[i + 1][j] = dp2[i + 1][j] || dp2[i][j - A[i]];
		}
	}
	int ans = 0;
	for (int i = 0; i < n; ++i) {
		// Get sum in [k-A[i], k-1].
		bool nec = false;
		S[0] = dp[i + 1][0];
		for (int j = 1; j <= k; ++j) {
			S[j] = S[j - 1] + dp[i + 1][j];
		}
		for (int j = 0; j <= k; ++j) {
			if (!dp2[i][j]) continue;
			int lo = k - A[i] - j;
			int hi = k - 1 - j;
			if (hi < 0) continue;
			int v = S[hi];
			if (lo - 1 >= 0) v -= S[lo - 1];
			if (v >= 1) {
				nec = true;
				break;
			}
		}
		if (!nec) ++ans;
	}
	printf("%d\n", ans);
}

