		for(int j=0;j<k;j++){
			pre[i][j]=pre[i-1][j];
			if(j>=a[i]){
				pre[i][j]|=pre[i-1][j-a[i]];
			}
		}

		for(int j=0;j<=k;j++){
			if(pre[i-1][j] &&j+a[i]>=k){
				pre[i][k]=1;
			}
		}
	}
	suf[n+1][0]=1;
	for(int i=n;i>=1;i--){
		for(int j=0;j<k;j++){
			suf[i][j]=suf[i+1][j];
			if(j>=a[i]){
				suf[i][j]|=suf[i+1][j-a[i]];
			}
		}

		for(int j=0;j<=k;j++){
			if(suf[i+1][j] &&j+a[i]>=k){
				suf[i][k]=1;
			}
		}
	}

	int ans=0;
	for(int i=1;i<=n;i++){
		if(a[i]==k){
			continue;
		}

		int req = k-a[i];
		int val = INT_MAX, ind=0;
		for(int j=k;j>=0;j--){
			if(pre[i-1][j]){
				while(ind<=k && ((!suf[i+1][ind]) || j+ind<req)){
					ind++;
				}
				if(ind<=k){
					val=min(val,j+ind);
				}
			}
		}
		if(val>=k){
			ans++;
		}
	}
	cout << ans << endl;
	return 0;
}

