using ll = long long;

const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(5e3) + 17;

int n, k;
int a[MAXN];
bool dp_l[MAXN][MAXN], dp_r[MAXN][MAXN];

bool read() {
    if (!(cin >> n >> k))
        return false;

    forn (i, n)
        cin >> a[i + 1];

    return true;
}

void solve() {
    dp_l[0][0] = 1;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j <= k + 1; ++j) {
            dp_l[i + 1][j] |= dp_l[i][j];
            dp_l[i + 1][min(k + 1, j + a[i + 1])] |= dp_l[i][j];
        }

    dp_r[n + 1][0] = 1;

    for (int i = n + 1; i > 1; --i)
        for (int j = 0; j <= k + 1; ++j) {
            dp_r[i - 1][j] |= dp_r[i][j];
            dp_r[i - 1][min(k + 1, j + a[i - 1])] |= dp_r[i][j];
        }

    int ans = 0;

    for (int i = 1; i <= n; ++i) {
        int sum = 0;

        for (int j = max(0, k - a[i]); j < k; ++j)
            sum += dp_r[i + 1][j];

        bool nec = false;

        for (int s_l = 0, l = k - a[i], r = k - 1; s_l <= k; ++s_l, --l, --r) {
            if (dp_l[i - 1][s_l] && sum > 0) {
                nec = true;
                break;
            }

            if (l - 1 >= 0)
                sum += dp_r[i + 1][l - 1];

            if (r >= 0)
                sum -= dp_r[i + 1][r];
        }

        ans += !nec;
    }

    cout << ans << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

