  sort(a, a+n);
  for (ll i = 0; i < n; i++) if (a[i] >= k) counter++;
  n -= counter;
  dp[0] = 1;
  for (ll i = 0; i < n; i++) for (ll j = k; j >= a[i]; j--) dp[j] = (dp[j] + dp[j - a[i]]) % mod;
  for (ll i = 0; i < n; i++) {
    for (ll j = 0; j < k; j++) cp[j] = dp[j];
    for (ll j = a[i]; j < k; j++) {
      cp[j] -= cp[j - a[i]];
      while (cp[j] < 0) cp[j] += mod;
    }
    for (ll j = max(0ll, k - a[i]); j < k; j++) if (cp[j] != 0) {
      ans++;
      break;
    }
  }
  printf("%lld\n", n - ans);
}

#include <cstdio>
#include <algorithm>
using namespace std;

int N, K, arr[5000];

bool isPos[5000];

bool judge(int ex) {
    memset(isPos, false, sizeof isPos);
    isPos[0] = true;
    if(K == 1 && arr[ex])
        return true;
    for(int v = K-1; v >= 0; v--) {
        for(int i = 0; i < N; i++) {
            if(i != ex && v + arr[i] < K && isPos[v]) {
                isPos[v + arr[i]] = true;
                if(v + arr[i] >= K - arr[ex])
                    return true;
            }
        }
    }

    return false;
}

int main () {
    scanf("%d %d", &N, &K);
    for(int n = 0; n < N; n++) {
        scanf("%d", arr + n);
    }
    sort(arr, arr + N);

    int bot = -1, top = N;
    while(bot + 1 < top) {
        int mid = (bot + top) / 2;
//        printf("%d %d %d %d\n", bot, mid, top, judge(mid));
        if(judge(mid)) {
            top = mid;
        }
        else{
            bot = mid;
        }
    }

    printf("%d\n", bot+1);

    return 0;
}

