typedef long long ll;

int n,k;
vector<ll> v(5555);
vector<vector<bool>> dp(5010,vector<bool>(5010));

bool check(int p){
    if(v[p]>=k) return true;
    // without v[p], make x s.t. k-v[p]<=x<k
    // dp[i][j] := v[i]迄でjを作る
    for(int i=0;i<=n;i++) dp[0][i]=false;
    for(int i=0;i<=n;i++) dp[i][0]=true;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=k;j++){
            dp[i][j]=dp[i-1][j];
            if(i!=p && j-v[i]>=0){
                dp[i][j] =  dp[i][j] | dp[i-1][j-v[i]];
            }
        }
    }
    bool f=false;
    for(int i=max(0LL,k-v[p]);i<k;i++) f |= dp[n][i];
    return f;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

    cin>>n>>k;
    vector<ll> a(n);
    for(int i=0;i<n;i++) cin>>a[i];
    sort(a.rbegin(),a.rend());
    for(int i=1;i<=n;i++) v[i]=a[i-1];
    int low=1,high=n;
    for(int i=0;i<14;i++){
        int mid=(low+high)/2;
        if(check(mid)) low=mid;
        else high=mid;
    }
    if(!check(low)) cout<<n-low+1<<endl;
    else if(!check(high)) cout<<n-low<<endl;
    else cout<<n-high<<endl;
}

