  int n, k; cin >> n >> k;
  vector<int> a(n); for (int i = 0; i < n; i++) cin >> a[i];
  sort(a.begin(), a.end());
  vector< vector<bool> > dp1(n + 1, vector<bool>(k, false));
  vector< vector<bool> > dp2(n + 1, vector<bool>(k, false)); 
  dp1[0][0] = dp2[n][0] = true;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < k; j++) {
      dp1[i + 1][j] = dp1[i][j] or j - a[i] >= 0 and dp1[i][j - a[i]];
    }
  }
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j < k; j++) {
      dp2[i][j] = dp2[i + 1][j] or j - a[i] >= 0 and dp2[i + 1][j - a[i]];
    }
  }
  auto needed = [&](int i) {
    if (a[i] >= k) return true;
    for (int j = k - a[i]; j < k; j++) {
      if (dp1[i][j] or dp2[i + 1][j]) return true;
    }
    for (int j = k - a[i]; j < k; j++) {
      for (int l = 0; l <= j; l++) {
        if (dp1[i][l] and dp2[i + 1][j - l]) return true;
      }
    }
    return false;
  };
  int l = -1, r = n;
  while (true) {
    int m = (l + r) / 2;
    if (needed(m)) r = m;
    else l = m;
    if (r - l == 1) break;
  }
  cout << r << '\n';
  return 0;
}

