    REP(i, Nu) dp[i][0] = true;
    REP(i, Nu){
        REP(i2, Nu){
            if(i2 == i) continue;
            REP(j, a0[i2].size()){
                vector<bool> dptmp = dp[i];
                REP(k, K - a0[i2][j]){
                    if(dp[i][k]) dptmp[k + a0[i2][j]] = true;
                }
                dp[i] = dptmp;
            }
        }
    }

    int ans = 0;
    vec calced(K, 0);
    REP(i, Nu){
        REP(j, a0[i].size()){
            if(a0[i][j] >= K) continue;
            if(calced[a0[i][j]] == 1){
                ans++;
                continue;
            }else if(calced[a0[i][j]] == 2){
                continue;
            }
            vector<bool> dptmp = dp[i];

            bool noneed = true;

            FOR(k, K - a0[i][j], K){
                if(dptmp[k]){
                    noneed = false;
                    break;
                }
            }
            if(!noneed){
                calced[a0[i][j]] = 2;
                continue;
            }

            REP(j2, a0[i].size()){
                if(j2 == j) continue;
                vector<bool> dptmp2 = dptmp;
                REP(k, K - a0[i][j2]){
                    if(dptmp[k]) dptmp2[k + a0[i][j2]] = true;
                }
                dptmp = dptmp2;
            }

            FOR(k, K - a0[i][j], K){
                if(dptmp[k]){
                    noneed = false;
                    break;
                }
            }
            if(noneed){
                ans++;
                calced[a0[i][j]] = 1;
            }else{
                calced[a0[i][j]] = 2;
            }
        }
    }

    cout << ans;

    return 0;
}


