	if (dp[i][MIN].first != INF) {
		return dp[i][MIN];
	}

	auto pata = func(i + 1, MIN);
	if (i == ignore) {
		return dp[i][MIN] = std::move(pata);
	}
	auto patb = func(i + 1, MIN - a[i]);
	if (pata.first < patb.first) {
		return dp[i][MIN] = std::move(pata);
	}
	else {
		//patb.second.push_back(i);
		return dp[i][MIN] = std::move(patb);
	}
}

