using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')

const int N_MAX = 5000;
const int K_MAX = 5000;

int N, K;
int a[N_MAX];
int dp[2][K_MAX + 1];

void solve() {
  sort(a, a + N, greater<int>());

  int ans = N;
  int *cur = dp[0], *nxt = dp[1];
  cur[0] = 1;
  REP(i, N) {
    fill(nxt, nxt + K + 1, 0);
    bool need = false;
    REP(j, K + 1) {
      if (cur[j] > 0 && j < K && j + a[i] >= K) need = true;
      nxt[j] |= cur[j];
      nxt[min(j + a[i], K)] |= cur[j];
    }
    if (need) ans = N - 1- i;
    // printf("a: %d, need: %s\n", a[i], need ? "true" : "false");
    // DUMP(nxt, K + 1);
    swap(cur, nxt);
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) scanf("%d", a + i);
}

int main() {
  input();
  solve();
  return 0;
}

