const int maxn = 5007;

typedef bitset<maxn> Bit;
Bit pre[maxn];
Bit suf[maxn];
int n;
int K;
int a[maxn];
int main(){
	scanf("%d%d",&n,&K);
	for(int i = 1; i <= n; ++i)scanf("%d",&a[i]);
	pre[0] = 1;
	for(int i = 1; i <= n; ++i){
		pre[i] = pre[i - 1];
		if(a[i] <= K)
			pre[i] |= (pre[i] << a[i]);
	}
	suf[n + 1] = 1;
	for(int i = n; i >= 1; --i){
		suf[i] = suf[i + 1];
		if(a[i] <= K)
			suf[i] |= (suf[i] << a[i]);
	}
	int ans = 0;
	for(int i = 1; i <= n; ++i){
		bool SUC = 0;
		Bit cur = (pre[i - 1] | suf[i + 1]);
		for(int j = max(1,K - a[i]); j <= K - 1 && !SUC; ++j)
			if(cur[j])SUC = 1;
		ans += SUC;
	}
	printf("%d\n",n - ans);
	return 0;
}

