vi v;
int n, k, x, ig, dp1[N][N] = { }, dp2[N][N] = { };
int rig(int idx, int rem) {
	if (rem <= 0)
		return 0;
	if (idx >= (int) v.size())
		return 1e9;
	int &ret = dp1[idx][rem];
	if (ret != -1)
		return ret;
	ret = 1e9;
	ret = min(ret, rig(idx + 1, rem - v[idx]) + v[idx]);
	ret = min(ret, rig(idx + 1, rem));
	return ret;
}
int lef(int idx, int rem) {
	if (rem <= 0)
		return 0;
	if (idx <= 0)
		return 1e9;
	int &ret = dp2[idx][rem];
	if (ret != -1)
		return ret;
	ret = 1e9;
	ret = min(ret, lef(idx - 1, rem - v[idx]) + v[idx]);
	ret = min(ret, lef(idx - 1, rem));
	return ret;
}
