s64 N;
s64 K;

vector<s64> A;

bool need(int n)
{
    vector<s64> v(A);
    v.erase(begin(v)+n);

    // i枚目までで総和jを作れるか
    vector<deque<bool>> dp(N, deque<bool>(K+1, false));
    dp[0][0] = true;

    FOR(i, 1, N) REP(j, K+1) {
        s64 a = v[i-1];
        dp[i][j] = dp[i][j] || dp[i-1][j];
        if(j >= a) {
            dp[i][j] = dp[i][j] || dp[i-1][j-a];
        }
    }

    FOR(j, max<s64>(0,K-A[n]), K) {
        if(dp[N-1][j]) return true;
    }

    return false;
}

void solve()
{
    assert(N <= 400 && K <= 400);

    s64 ans = 0;

    REP(i, N) {
        if(!need(i))
            ++ans;
    }

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    A.resize(N);
    RD(K);

    REP(i, N) {
        RD(A[i]);
    }

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

