vector<int> v;

bool check(int x) {
        if(x == 0)
                return false;

        memset(dp,0,sizeof(dp));
        dp[0] = 1;

        for (int i = 0; i < v.size(); i ++) {
                if(i + 1 == x)
                        continue;
                for (int j = k - v[i]; j >= 0; j --) {
                        if(dp[j] == 1)
                                dp[j + v[i]] = 1;
                }
        }
        if(x > 0)
                for (int i = k - v[x - 1]; i <= k - 1; i ++) {
                        if(dp[i] == 1)
                                return true;
                }
        return false;
