#define REP(i,n) for(long long i = 0;i < n;++i)
vector<long long> a;
long long n, x;
int judge(int skip) {
	int found[10001] = {};
	found[0] = true;
	for (int i = 0;i < a.size();++i) {
		if (i != skip) {
			for (int q = x - 1;q >= 0;--q) {
				if (found[q]) {
					found[a[i] + q] = true;
				}
			}
		}
	}
	for (int i = 1;i <= a[skip] && x - i >= 0;++i) {
		if (found[x - i]) return false;
	}
	return true;
}
int main() {
	iostream::sync_with_stdio(false);
	cin >> n >> x;
	REP(i, n) {
		long long tmp = 0;
		cin >> tmp;
		if (tmp < x)
			a.push_back(tmp);
	}
	sort(a.begin(), a.end());
	int top = a.size()-1;
	int bot = 0;
	while (top - bot > 1) {
		int mid = top + bot;
		mid /= 2;
		if (judge(mid)) {
			bot = mid;
		}
		else top = mid;
	}
	if (judge(top)) {
		cout << top+1 << endl;
	}
	else if (judge(bot)) {
		cout << bot+1 << endl;
	}

return	 0;
}

