int n, k, a[5055], dpl[5055][5055], dpr[5055][5055], ps[5055][5055], ans, to;

int sum(int ind, int lb, int ub) {
	if (ub < 0) return 0;
	if (lb <= 0) return ps[ind][ub];

	return ps[ind][ub] - ps[ind][lb - 1];
}

int main () {

	scanf("%d%d", &n, &k);

	FOE(i, 1, n) scanf("%d", a + i);

	FOE(i, 1, n) if (a[i] > k) a[i] = k;

	FOE(i, 0, n + 1) dpl[i][0] = dpr[i][0] = 1;

	FOE(i, 1, n) {
		FOE(j, 0, k) {
			if (dpl[i - 1][j]) {
				to = j + a[i];
				if (to > k) to = k;

				assert(to < 5055 && to >= 0);

				dpl[i][to] = 1;
			}
		}
	}

	FOD(i, n, 1) {
		FOE(j, 0, k) {
			if (dpr[i + 1][j]) {
				to = j + a[i];
				if (to > k) to = k;

				assert(to < 5055 && to >= 0);

				dpr[i][to] = 1;
			}
		}
	}

	FOE(i, 1, n + 1) {
		ps[i][0] = dpr[i][0];
		FOE(j, 1, k) ps[i][j] = ps[i][j - 1] + dpr[i][j];
	}

	FOE(i, 1, n) {
		bool flag = 0;

		FOR(j, 0, k) if (dpl[i - 1][j]) {
			if (sum(i + 1, k - j - a[i], k - 1 - j) > 0)
				flag = 1;
		}

		if (flag) ans++;
	}

	printf("%d\n", n - ans);

	return 0;

}

