vector<int> v;
int n,k;

bool C(int x){
	bool res[10001];
	fill(res,res+10001,false);
	for(int i=0;i<=v.size();i++){
		for(int j=10000;j>=0;j--){
			if(i-1==x) continue;
			else if(i==0&&j==0) res[j] = true;
			else if((i==0||j-v[i-1]<0||!res[j-v[i-1]])&&!res[j]) res[j] = false;
			else res[j] = true;
		}
	}
	for(int i=k-v[x];i<k;i++){
		if(res[i]) return true;
	}
	return false;
}

int main(){
	scanf("%d %d",&n,&k);
	for(int i=0;i<n;i++){
		int x;
		scanf("%d",&x);
		if(x<k) v.push_back(x);
	}
	sort(v.begin(),v.end());
	n = v.size();
	int lb = -1,ub = n;
	while(ub-lb>1){
		int mid = (ub + lb) / 2;
		if(C(mid)) ub = mid; // need
		else lb = mid;
	}
	printf("%d\n",ub);
}

