using namespace std;

int N, K, A[5000];
bool dp1[5002][5001];
int dp2[5002][5001];


int main()
{
  cin >> N >> K;
  for(int i = 0; i < N; i++) {
    cin >> A[i];
    A[i] = min(A[i], K);
  }

  dp1[0][0] = true;
  for(int i = 0; i < N; i++) {
    for(int j = K; j >= A[i]; j--) {
      dp1[i + 1][j] |= dp1[i][j - A[i]];
    }
    for(int j = K; j >= 0; j--) {
      dp1[i + 1][j] |= dp1[i][j];
    }
  }

  dp2[N][0] = true;
  for(int i = N - 1; i >= 0; i--) {
    for(int j = K; j >= A[i]; j--) {
      dp2[i][j] |= dp2[i + 1][j - A[i]] > 0;
    }
    for(int j = K; j >= 0; j--) {
      dp2[i][j] |= dp2[i + 1][j] > 0;
    }
  }
  for(int i = 0; i <= N; i++) {
    for(int j = 1; j <= K; j++) {
      dp2[i][j] += dp2[i][j - 1];
    }
  }

  int ret = N;
  for(int i = 1; i <= N; i++) {
    bool flag = false;
    for(int j = 0; j < K; j++) {
      if(dp1[i - 1][j]) {
        int x = K - A[i - 1] - j; // 以上
        int y = K - j; // 未満
        if(dp2[i][y - 1] - (x <= 0 ? 0 : dp2[i][x - 1]) > 0) {
          flag = true;
        }
      }
    }

    ret -= flag;
  }

  cout << ret << endl;
}

