    dec(i, N, 1) {
        rep(j, K) {
            DP2[i - 1][j] |= DP2[i][j];
            if (j + A[i - 1] < K) {
                DP2[i - 1][j + A[i - 1]] |= DP2[i][j];
            }
        }
