bool func(int v){
	if(a[v]>=k)return false;
	memset(dp,false,sizeof(dp));
	memset(dp2,false,sizeof(dp2));
	dp[0][0]=true;
	dp2[0][0]=true;
	for(int i=0;i<n;i++){
		for(int j=0;j<k;j++){
			if(dp[i][j]){
				dp[i+1][j]=true;
				if(j+a[i]<k && i>v)dp[i+1][j+a[i]]=true;
			}
		}
	}
	for(int i=0;i<=v;i++){
		for(int j=0;j<k;j++){
			if(dp2[i][j]){
				dp2[i+1][j]=true;
				if(j+a[i]<k)dp2[i+1][j+a[i]]=true;
			}
		}
	}
	for(int j=k-1;j>=1;j--){
		if(dp2[v+1][j])dp2[v+1][j-1]=true;
	}
	for(int i=k-1;i>=1;i--){
		if(dp[n][i] && dp2[v+1][k-i])return false;
	}
	return true;
}

