const int NMAX = 5005;

int n, k, a[NMAX];
bitset<NMAX>pref[NMAX], suf[NMAX];
int sum[2][NMAX];

void Knapsack()
{
	int i, j;

	//prefix
	pref[0][0] = 1;
	for (i = 1; i <= n; i++)
		for (j = 0; j < NMAX; j++)
		{
			pref[i][j] = pref[i - 1][j];
			if (j >= a[i] && pref[i - 1][j - a[i]])
				pref[i][j] = 1;
		}

	//sufix
	suf[n + 1][0] = 1;
	for (i = n ; i >= 1; i--)
		for (j = 0; j < NMAX; j++)
		{
			suf[i][j] = suf[i + 1][j];
			if (j >= a[i] && suf[i + 1][j - a[i]])
				suf[i][j] = 1;
		}
}

int main()
{
  //  freopen("input","r",stdin);
  //  freopen("output","w",stdout);
    cin.sync_with_stdio(false);

	int i;
	cin >> n >> k;
	for (i = 1; i <= n; i++) cin >> a[i];

	Knapsack();

	//answer
	int j, ans = 0;
	for (i = 1; i <= n; i++)
	{
		int st = max(0, k - a[i]), dr = k - 1; //the interval to search

		//partial sums
		for (j = 0; j < NMAX; j++) 
			{
				sum[0][j] = pref[i - 1][j];
				sum[1][j] = suf[i + 1][j];
			}

		for (j = 1; j < NMAX; j++)
			for (int l = 0; l <= 1; l++)
				sum[l][j] += sum[l][j - 1];


		bool ok = 0;
		for (j = 0; j <= dr; j++)
			if (pref[i - 1][j] != 0) //search for other
			{
				int left = max(0, st - j), right = dr - j;

				int minus = 0;
				if (left > 0) minus = sum[1][left - 1];
				if (sum[1][right] - minus > 0) ok = 1;
			}

		if (!ok) ans++;
	}	
	cout << ans << "\n";

    return 0;   
}

