vi a;
int k;
bool check(int dust){
  bool dp[a.size()+1][k+1];
  for(int i=0;i<a.size()+1;i++)for(int j=0;j<k+1;j++)dp[i][j]=false;
  dp[0][0]=true;
  for(int i=0;i<a.size();i++){
    for(int j=0;j<=k;j++){
      if(i==dust){
	dp[i+1][j]=dp[i][j];
      }else{
	if(dp[i][j]){
	  dp[i+1][j]=true;
	  if(j+a[i]<=k)
	    dp[i+1][j+a[i]]=true;
	}
      }
    }
  }
  if(k<a[dust])return false;

  for(int i=k-a[dust];i<k;i++){
    if(dp[a.size()-1][i])return true;
  }
  return false;
}
