int N, K;
int a[5010];

bool dp[5010][5010]; //dp[i][j] := i番目までを考えて,合計がjの時があるなら1
bool solve(int idx){
	rep(i, 5010)rep(j, 5010) dp[i][j] = 0;
	dp[0][0] = 1;
	rep(i, N)rep(j, K + 1){
		if(dp[i][j] == 0) continue;
		dp[i + 1][j] = 1;
		if(i == idx) continue;
		if(j + a[i] > K) continue;
		dp[i + 1][j + a[i]] = 1;
	}
	reps(i, max(0, K - a[idx]), K){
		if(dp[N][i]) return true;
	}
	return false;
}

int main(void){
	cin >> N >> K;
	rep(i, N) cin >> a[i];
	sort(a, a + N);
	int l = -1, r = N;
	while(r - l > 1){
		int m = (l + r) / 2;
		// printf("m %d\n",m );
		if(!solve(m)) l = m;
		else r = m;
	}
	printf("%d\n", l + 1);
	return 0;
}

