struct data{
	bool type;
	int value0, value1;
};

int dp_cache[5001][5001]= {};
int a[5001]= {};
vector<data> use[5001]= {};
bool v[5001][5001]= {};
bool tmpv[5001] ={}; 
int parsev[5001] ={};

int n, K;

__attribute__((optimize("-O3")))
int dp(int i, int k) {
    if(i==0) return 0;
    int &cache = dp_cache[i][k];
    if(cache!=-1) return cache;

    int ans=dp(i-1, k);


    if(k>a[i]) {
        int xx = dp(i-1, k-a[i]);
        if(xx>0){
	        ans+=xx;
	        use[k].push_back({1, k-a[i], use[k-a[i]].size()-1});
            use[k].push_back({0, i});
        	if(a[i]>=k) {
        		ans++;
        		return cache=ans;
			}
    	}
    } 
	if(a[i]>=k) {
        ans++;
        use[k].push_back({0, i});
    }

    return cache=ans;
}

void parse(int k, int r) {
	//cout<<"parsing "<<k<<", "<<r<<endl;
	int l = max(0, parsev[k]+1);
	for(int i=l;i<=r;i++){
		const auto& x=use[k][i];
		if(x.type==0) {
			tmpv[x.value0]=1;
		} else {
			parse(x.value0, x.value1);
		}
	}
	parsev[k]=max(parsev[k], r);
}

