using namespace std;
using namespace std::chrono;

int main() {
  auto start = high_resolution_clock::now();

  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; ++i)
    cin >> a[i];
  sort(a.begin(), a.end());

  int ans = 0;
  while (a.size() > 0 && a.back() >= k)
    a.pop_back();
  n = a.size();

  vector<vector<bool>> le(n, vector<bool>(k, false));
  for (int i = 0; i < n; ++i) {
    if (i > 0)
      le[i] = le[i - 1];
    else
      le[i][0] = true;

    int val = a[i];
    for (int pos = k - 1; pos >= 0; --pos)
      if (le[i][pos] && pos + val < k)
        le[i][pos + val] = true;
  }

  vector<vector<int>> pref(n, vector<int>(k, 0));
  vector<vector<bool>> ge(n, vector<bool>(k, false));
  for (int i = n - 1; i < n; ++i) {
    if (i < n - 1)
      ge[i] = ge[i + 1];
    else
      ge[i][0] = true;

    int val = a[i];
    for (int pos = k - 1; pos >= 0; --pos)
      if (ge[i][pos] && pos + val < k)
        ge[i][pos + val] = true;

    pref[i][0] = 1;
    for (int pos = 1; pos < k; ++pos)
      pref[i][pos] = pref[i][pos - 1] + ge[i][pos];
  }

  for (int i = 0; i < n; ++i) {
    int val = a[i];
    bool exist = false;

    for (int j = 0; j < k; ++j) {
      if (!le[i][j])
        continue;

      int tmp = val + j;
      if (tmp >= k) {
        exist = true;
        break;
      }

      int l = k - tmp;
      int r = k - j - 1;

      int sum = 0;
      if (i + 1 < n) {
        sum += pref[i + 1][r];
        sum -= pref[i + 1][l - 1];
      }

      if (sum) {
        exist = true;
        break;
      }
    }

    ans += !exist;
  }

  cout << ans << endl;

  cerr << "Total execution time : " << duration_cast<milliseconds>(high_resolution_clock::now() - start).count() << " ms" << endl;

  return 0;
}

