int sol(int i, int cur)
{
	if(i == n || cur >= k-x) return cur;
	int &ret = dp[i][cur];
	if(ret != -1) return ret;
	ret = 0;
	if(cur + a[i] < k && tmp != i) ret = sol(i+1, cur+a[i]);
	if(ret >= k-x) return ret;
	ret = max(ret, sol(i+1, cur));
