      if( dp[i][k-a[i]] )
        vs[i+1].insert( k );
    }
  }

  rdp[N][0] = true;
  rvs[N].insert( 0 );
  for( int i = N-1; i >= 0; --i ) rep( k, K+1 )
  {
    rdp[i][k] |= rdp[i+1][k];

    if( rdp[i+1][k] )
      rvs[i].insert( k );

    if( k-a[i] >= 0 )
    {
      rdp[i][k] |= rdp[i+1][k-a[i]];

      if( rdp[i+1][k-a[i]] )
        rvs[i].insert( k );
    }
  }

  rep( i, N )
  {
    rep( k, K )
    {
      auto j = rvs[i+1].lower_bound( K-a[i]-k );

      if( j == rvs[i+1].end() )
        continue;

      if( vs[i].count(k) && *j < K-k )
      { --ans; break; }
    }
  }

  printf( "%d\n", ans );

  return 0;
}

