#define int ll

bool f(const vector<int> &A, int index, int K) {
	unordered_set<int> dp;
	for (int i = 0; i < A.size(); ++i) if (i != index) {
		unordered_set<int> memo;
		for (auto &a : dp) {
			if (a + A[i] >= K) break;
			memo.insert(a + A[i]);
			if (K - A[index] <= a + A[i] and a + A[i] <= K - 1) {
				return true;
			}
		}
		for (auto &a : memo) {
			dp.insert(a);
		}
	}
	return false;
}

void solve() {
	int N, K; cin >> N >> K;
	vector<int> A(N); for (auto &a : A) cin >> a;
	sort(A.begin(), A.end());
	int low = 0;
	int high = lower_bound(A.begin(), A.end(), K) - A.begin();
	while(high - low > 1) {
		int mid = (high + low) / 2;
		if (f(A, mid, K)) high = mid;
		else low = mid;
	}
	cout << high << endl;
}

