ll dfs(int x, ll y, int select){
  if(y >= K)
    return y;
  if(x == N) return INF;
  if(dp[x][y] != INF) return dp[x][y];
  ll res = INF;
  res = min(res, dfs(x+1, y+a[x], select));
  if(x != select)
    res = min(res, dfs(x+1, y, select));
  dp[x][y] = res;
  //  cout << x << " " << y << " " << res << endl;;
  return res;
}

int C(int i){
  for(int i=0;i<N;i++) for(int j=0;j<K;j++) dp[i][j] = INF;
  ll ret = dfs(0, 0, i);
  //  cout << a[i] << " " << ret << endl;
  return (ret - a[i]) < K;
}

