#include<bits/stdc++.h>
#define maxn 5005
using namespace std;
int arr[maxn];
int pre[maxn][maxn],suf[maxn][maxn];
void build(int n,int k,int (*dp)[maxn]) {
	dp[0][0] = 1;
	for(int i=1;i<=n;i++) {
		for(int j=0;j<k;j++)
			dp[i][j] = dp[i-1][j];
		if(arr[i] >= k)	continue;
		for(int j=k-1;j>=arr[i];j--)
			if(dp[i][j-arr[i]] == 1)
				dp[i][j] = 1;
	}
}
int query(int i,int l,int r) {
	return suf[i][r] - (l == 0 ? 0 : suf[i][l-1]);
}
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n,k;
	cin >> n >> k;
	for(int i=1;i<=n;i++)
		cin >> arr[i];
	build(n,k,pre);
	reverse(arr+1,arr+1+n);
	build(n,k,suf);
	reverse(arr+1,arr+1+n);
	reverse(suf,suf+1+n+1);
	for(int i=2;i<=n+1;i++)
		for(int j=1;j<k;j++)
			suf[i][j] += suf[i][j-1];

	int ans = n;
	for(int i=1;i<=n;i++) {
		if(arr[i] >= k) {
			ans--;
			continue;
		}
		for(int j=0;j<k;j++)
			if(pre[i-1][j] == 1) {
				int l = max(0,k - arr[i] - j) , r = k - 1 - j;
				if(query(i+1,l,r) > 0) {
					ans--;
					break;
				}
			}
	}
	cout << ans << endl;
	return 0;
}

