bool isValid(int idx, const std::vector<int>& a, int K, int sum) {
    // calc minimum value X which satisfies X >= K
    // if X - a[i] >= K, card i is invalid.

    int X = sum;
    for (int i = a.size()-1; i >= 0; i--) {
        if (i == idx)
            continue;

        if (X - a[i] >= K) {
            X -= a[i];
        }
    }

    return (X - a[idx] < K);
}

