const int N = 5001;

int n, k, dp[N], mod = 1e9 + 7;
vector <int> a;

void add(int x){
    for(int i = k ; i >= x ; i--){
        dp[i] += dp[i - x];
        if(dp[i] >= mod) dp[i] -= mod;
    }
}
void del(int x){
    for(int i = x ; i <= k ; i++){
        dp[i] -= dp[i - x];
        if(dp[i] < 0) dp[i] += mod;
    }
}
