using namespace std;

void trace(const vector<int>& a, long K, long sum, int now, vector<bool>& visits, vector<bool>& answers)
{
  if (now >= a.size()) return;
  for (int i = now; i < a.size(); ++i) {
    long new_sum = sum + a[i];
    if (new_sum >= K) {
      for (int i = 0; i < visits.size(); ++i) if (visits[i]) answers[i] = true;
      answers[i] = true;
    } else {
      visits[i] = true;
      trace(a, K, new_sum, i + 1, visits, answers);
      visits[i] = false;
    }
  }
}

int main()
{
  int N, K;
  cin >> N >> K;
  vector<int> a(N);
  vector<bool> answers(N, false);
  vector<bool> visits(N, false);
  for (int i = 0; i < N; ++i) cin >> a[i];
  sort(a.begin(), a.end(), [](int a, int b) { return b < a; });
  trace(a, K, 0, 0, visits, answers);
  int count = 0;
  // for (int i = 0; i < N; ++i) if (answers[i]) cerr << a[i] << endl;
  for (auto answer: answers) if (!answer) ++count;
  cout << count << endl;
  return 0;
}

