    SQWORD sqN;
};

static bool isNeeded(
    SQWORD sqTest,
    const PARAMS *pstParams)
{
    vector<SQWORD> vsqDp(pstParams->sqK, 0);

    if (sqTest < 0) {
        return false;
    }
    if (pstParams->vsqA.size() <= sqTest) {
        return true;
    }

    if (pstParams->sqK <= pstParams->vsqA[sqTest]) {
        return true;
    }

    vsqDp[0] = 1;
    for (SQWORD sqCardIdx = 0; sqCardIdx < pstParams->vsqA.size(); sqCardIdx++) {
        if (sqCardIdx != sqTest) {
            for (SQWORD sqDpIdx = vsqDp.size() - 1; 0 <= sqDpIdx; sqDpIdx--) {
                SQWORD sqNextIdx = sqDpIdx + pstParams->vsqA[sqCardIdx];

                if (sqNextIdx < pstParams->sqK) {
                    vsqDp[sqNextIdx] += vsqDp[sqDpIdx];
                    if ((0 < vsqDp[sqDpIdx]) && (pstParams->sqK - pstParams->vsqA[sqTest] <= sqNextIdx)) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

static SQWORD binarySearch(
    bool (*pfJudge)(SQWORD, const PARAMS*),
    SQWORD sqInitLower, 
    SQWORD sqInitUpper, 
    const PARAMS *pstParam)
{
    SQWORD sqOk = sqInitUpper;
    SQWORD sqNg = sqInitLower;

    while (1LL < sqOk - sqNg) {
        SQWORD sqMid = (sqNg + sqOk) / 2LL;
        if (pfJudge(sqMid, pstParam)) {
            sqOk = sqMid;
        } else {
            sqNg = sqMid;
        }
    }
    return sqOk;
}



