int sum[5001];

inline int GetSum(int left, int right) {
  if (right < 0) return 0;
  if (left < 0) left = 0;
  if (left == 0) return sum[right];
  return sum[right] - sum[left - 1];
}

int main() {
#ifdef LOCAL_DEFINE
  show(MOD);
#endif
  // テキトー考察
  //
  // a[i]以外の数で実現する事ができる和が高速に求まれば、良いのだけど...
  // ということで、解説pdfのdpを前からと後ろからやるといい事を知る(頭いいなあ)
  // そうすると、事前に2回dpしておけば、後々dpする必要なくて計算量が落ちる.
  // あとは、a[i]が必要であるならば、k - a[i]からk - 1までの数のうち最低一つが
  // a[i]以外の数で実現されていれば必要、そうじゃなきゃ必要ないので
  // 累積和使って実現できるか否か調べれば良い.
  //
  // 前からと後ろからのdpって知ったとき、感動したわ.
  // たしかに、これならある数を使わずに実現できる数を速く知ることができるよね.
  // いやー、この問題最高.好き.
  cin >> n >> k;
  rep(i, 0, n) cin >> a[i];
  dp1[0][0] = true;
  rep(i, 0, n) {
    rep(j, 0, k + 1) {
      if (!dp1[i][j]) continue;
      if (j + a[i] <= k) dp1[i + 1][j + a[i]] = true;
      dp1[i + 1][j] = true;
    }
  }
  dp2[n][0] = true;
  rrep(i, n, 0) {
    rep(j, 0, k + 1) {
      if (!dp2[i][j]) continue;
      if (j + a[i - 1] <= k) dp2[i - 1][j + a[i - 1]] = true;
      dp2[i - 1][j] = true;
    }
  }
  int ans = 0;
  rep(i, 0, n) {
    fill(sum, sum + 5001, 0);
    rep(j, 0, k + 1) if (dp2[i + 1][j]) sum[j]++;
    rep(j, 1, k + 1) sum[j] = sum[j] + sum[j - 1];
    int left = k - a[i];
    int right = k - 1;
    bool need = false;
    rep(j, 0, k + 1) {
      if (dp1[i][j]) {
        if (GetSum(left - j, right - j) > 0) {
          need = true;
          break;
        }
      }
    }
    if (!need) ans++;
  }
  cout << ans << endl;
#ifdef  LOCAL_DEFINE
  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << "s." << endl;
#endif
  return 0;
}

