    while (r - l > 1) {
        int mid = (r + l) / 2;
        if (A[mid] >= k) {
            r = mid;
            continue;
        }
        vector<int> dp(k + 1); dp[0] = 1;
        vector<int> ndp(k + 1); ndp[0] = 1;
        rep (i, n) {
            if (i == mid) continue;
            rep (j, k + 1) {
                if (dp[j]) {
                    ndp[j] = 1;
                    ndp[min(j + A[i], k)] = 1;
                }
            }
            rep (j, k + 1) dp[j] = ndp[j];
        }
        bool flag = false;
        FOR (i, k - A[mid], k) {
            if (dp[i]) flag = true;
        }
        if (flag) r = mid;
        else l = mid;
    }
    cout << r << endl;
    return;
}

