ll pow1(ll n, ll p, int MOD){
  ll r, c;
  r = 1;
  c = n;
  while(p){
    if(p & 1){
      (r *= c) %= MOD;
    }
    (c *= c) %= MOD;
    p /= 2;
  }
  return r;
}
int n, k;
int calc(int r[], int s, int MOD){

  int cnt1 = 0;
  for(int i = 0;i < k;i++)
    cnt1 += r[i], (cnt1 >= MOD && (cnt1 -= MOD));
  cnt1 = (pow1(2, s, MOD) - cnt1 + MOD) % MOD;
  return cnt1;
}
