void solve() {
    int n, k; cin >> n >> k;
    vi A(n); rep (i, n) cin >> A[i];
    sort(all(A));
    int l = 0, r = n;
    while (r - l > 1) {
        int mid = (r + l) / 2;
        if (A[mid] >= k) {
            r = mid;
            continue;
        }
        vector<int> dp(k + 1); dp[0] = 1;
        vector<int> ndp(k + 1);
        rep (i, n) {
            if (i == mid) continue;
            rep (j, k + 1) {
                if (dp[j]) {
                    ndp[j] = 1;
                    ndp[min(j + A[i], k)] = 1;
                }
            }
            rep (i, k + 1) dp[i] = ndp[i];
        }
        bool flag = false;
        FOR (i, k - A[mid], k) {
            if (dp[i]) flag = true;
        }
        if (flag) r = mid;
        else l = mid;
    }
    cout << l + 1 << endl;
    return;
}

