bool dp[maxn];

int v[maxn];
int n,k;

bool check(int idx)
{
	memset(dp,0,sizeof(dp));
	dp[0] = 1;
	for(int i = 1 ; i <= n; i++)
	{
		if(i == idx)
			continue;
		for(int j = k - v[i]; j >= 0; j--)
			dp[j+v[i]] |= dp[j];
	}
	for(int i = max(0,k-v[idx]); i < k; i++)
		if(dp[i])
			return true;
	return false;
}

int main()
{
	scanf("%d %d",&n,&k);
	for(int i = 1 ; i <= n ; i++)
	{
		scanf("%d",&v[i]);
	}

	sort(v+1,v+n+1);	

	int lo = 1;
	int hi = n;
	int ans = 0;
	while(lo <= hi)
	{
		int mid = (lo + hi) >> 1;
		if(check(mid))
		{
			hi = mid - 1;
		}
		else
		{
			ans = mid;
			lo = mid+1;
		}
	}
	printf("%d\n",ans);

	return 0;
}

