void solve(){
	int N;//カード枚数
	int K;//閾値
	cin >> N >> K;

	vector<int> A(N);
	LL sum = 0;
	for(int i=0;i<N;++i){
		cin >> A[i];
		sum += A[i];
	}
	if( sum < K ){
		cout << N << endl;
		return;
	}
	sort(A.begin(),A.end());

	int L = 0;//K>=1
	int R = N-1;
	int Mid;
	while(R-L>1){//使わない数index
		Mid = (L+R)/2;
		if( K<=A[Mid] ){
			R = Mid;
			continue;
		}

		vector< bool > dp(K,false);
		dp[0] = true;
		for(int i=0;i<N;++i){
			if( i == Mid ) continue;
			for(int j=K-1;j>=0;--j){
				if( dp[j] == false)continue;
				if( A[i] + j >= K ) continue;
				dp[ A[i] + j ] = true;
			}
		}
		bool flag = false;

		for(int in=K-A[Mid];in<K;++in){
			if( dp[in] ){
				flag = true;
				break;
			}
		}
		if( flag == false ){
			L = Mid;
		}else{
			R = Mid;
		}
	}

	cout << Mid << endl;
}

