using namespace std;

const int N = 5e3+5;

int n, k;
int A[N];

int main() {
    scanf("%d %d", &n, &k);
    for(int i = 1; i <= n; i++) scanf("%d", A + i);
    sort(A + 1, A + n + 1);
    int l = 0, r = n;
    while(l < r) {
        int mid = (l + r + 1) >> 1;
        vector<vector<int> > dp(n + 1, vector<int>(k + 1, 0));
        dp[0][0] = 1;
        for(int i = 1; i <= n; i++) for(int j = 0; j <= k; j++) {
            dp[i][j] |= dp[i-1][j];
            if(i != mid && j - A[i] >= 0)
                dp[i][j] |= dp[i-1][j - A[i]];
        }
        bool valid = false;
        for(int i = max(0, k - A[mid]); i <= k; i++) valid |= dp[n][i];
        if(valid) l = mid;
        else r = mid - 1;
    }
    printf("%d\n", l);

    return 0;
}

