using namespace std;

#define INF (1LL)<<60
typedef long long ll;
ll dp[5001][5001];

int N, K;
vector<ll> a;

inline ll dfs(int x, ll y, int select){
  if(y >= K) return y;
  if(x == N) return INF;
  if(dp[x][y] != -1) return dp[x][y];
  ll res = INF;  
  res = min(res, dfs(x+1, y+a[x], select));
  if(x != select)
    res = min(res, dfs(x+1, y, select));
  dp[x][y] = res;
  return res;
}

int C(int i){
  //  memset(dp, -1, sizeof(dp));
  for(int i=0;i<N;i++) for(int j=0;j<K;j++) dp[i][j] = -1;
  ll ret = dfs(0, 0, i);
  return (ret - a[i]) < K;
}

int main(){
  cin >> N >> K;
  a.resize(N);
  for(int i=0;i<N;i++) cin >> a[i];
  sort(a.begin(), a.end());
  int mini = 0, maxi = N-1;
  int mid = (mini+maxi)/2;
  while(mini <= maxi){
    if(C(mid))
      maxi = mid-1;
    else
      mini = mid+1;
    mid = (maxi+mini)/2;
  }
  if(mid == 0 && C(mid)) cout << 0 << endl;
  else cout << mid+1 << endl;
  return 0;
}

