bitset<5000> bits;

bool nibu(int n)
{
    bits.reset();
    bits.set(0);
    for (int i = 0; i < N; i++)
    {
        if (i != n)
        {
            bits |= (bits << a[i]);
        }
    }
    for (int i = 0; i < min(a[n], (lint)K); i++)
    {
        if (bits[K-i-1]) return false;
    }
    return true; // 必要
}

