{
    cin >> N >> K;
    a.resize(N);
    for (auto &v : a) cin >> v;
    sort(a.begin(), a.end());

    int l = 0, r = N;
    while(r - l > 0)
    {
        if (nibu((l+r)/2))
        {
            l = (l + r) / 2 + 1;
        }
        else
        {
            r = (l + r) / 2;
        }
    }
    cout << l << endl;
}

