    vector<int> A; A.reserve(N);
    for (int i = 0; i < N; ++i){
        int Ai;
        scanf("%d", &Ai); getchar();
        if (Ai >= K){
            ++need;
        }else{
            A.emplace_back(Ai);
        }
    }
    sort(A.begin(), A.end(), greater<int>());
    for (int i = 0; i < A.size(); ++i){
        unordered_set<int> sum;
        sum.emplace(0);
        bool flag = false;
        for (int j = 0; j < A.size(); ++j){
            if (j == i) continue;
            unordered_set<int> next_sum;
            for (auto& s : sum){
                const int temp = s + A[j];
                if (sum.count(temp) == 0 && temp < K){
                    if (K - A[i] <= temp){
                        flag = true;
                        break;
                    }
                    next_sum.emplace(temp);
                }
            }
            if (flag) break;
            sum.insert(next_sum.begin(), next_sum.end());
        }
        if (flag) ++need;
    }
    printf("%d\n", N - need);
}

