			dp1[i + 1][j] += dp1[i][j];
			if (j + a[i] < k)dp1[i + 1][j + a[i]] += dp1[i][j];
		}
	}
	dp2[n][0] = 1;
	dp2[n - 1][0] = 1;
	if (a[n - 1] < k)dp2[n - 1][a[n - 1]] = 1;
	for (int i = n - 1; i > 0; i--) {
		for (int j = 0; j < k; j++) {
			dp2[i - 1][j] += dp2[i][j];
			if (j + a[i - 1] < k)dp2[i - 1][j + a[i - 1]] += dp2[i][j];
		}
	}
	rep(i, n + 1) {
		for (int j = 1; j < k; j++) {
			dp2[i][j] += dp2[i][j - 1];
		}
	}
