const int maxn = 5000 + 5;
int n, k;
int a[maxn];
bitset<maxn> prf[maxn];
bitset<maxn> suf[maxn];

void solve() {
	cin >> n >> k;
	long long sum = 0;
	FOR(i, 1, n + 1) cin >> a[i], sum += a[i];
	if (sum < k) {
		cout << n << "\n";
		return;
	}
	prf[0][0] = suf[n + 1][0] = 1;
	FOR(i, 1, n + 1) {
		prf[i] = prf[i - 1] | (prf[i - 1] << a[i]);
	}
	FORd(i, n + 1, 1) {
		suf[i] = suf[i + 1] | (suf[i + 1] << a[i]);
	}
	int ans = 0;
	FOR(i, 1, n + 1) {
		bitset<maxn> l = prf[i - 1];
		bitset<maxn> r = suf[i + 1];
		static int sum[maxn];
		FOR(j, 1, maxn) {
			sum[j] = sum[j - 1] + r[j];
		}
		FOR(j, 0, maxn) if (l[j]) {
			int lo = max(0, k - a[i] - j);
			int hi = min(maxn - 1, k - j - 1);
			if (lo <= hi) {
				int tot = sum[hi];
				if (lo) tot -= sum[lo - 1];				
				if (tot) {
					ans++;
					break;
				}
			}
		}
	}
	cout << ans << "\n";
}

