    std::ios::sync_with_stdio(false);
    std::cin.tie(0);

    int N, K;
    cin >> N >> K;
    if (N > 400 || K > 400) return 0;

    vector<int> a(N);
    cin >> a;

    sort(all(a));

    // a[i] を含み，和が最小となる"良い集合"から a[i] を除いた集合も"良い集合"なら a[i] は捨てて良い
    int ans = 0;
    for (int i = 0; i < N; i++) {
        int tmp = a[i];
        a[i] = 0;
        vector<vector<bool>> dp(N + 1, vector<bool>(K, false));
        dp[0][0] = true;
        for (int n = 0; n < N; n++) {
            for (int k = 0; k < K; k++) {
                if (dp[n][k]) {
                    dp[n + 1][k] = true;
                    if (k + a[n] < K)
                        dp[n + 1][k + a[n]] = true;
                }
            }
        }

        a[i] = tmp;
        bool flag = true;
        for (int k = max(0LL, K - a[i]); k < K; k++) {
            if (dp[N][k]) {
                flag = false;
                break;
            }
        }
        if (flag) ans++;
    }

    cout << ans << endl;

    return 0;
}

