    vector<bool> dp(k+x+10, false);
    dp[0] = true;
    int len = dp.size();
    for (int j=0;j<n;j++) {
	if (i==j) continue;
	for (int val=k+x; val>=0; val--) {
	    if (!dp[val]) continue;
	    if (val+v[j]<len) {
		dp[val+v[j]]=true;
