bool judge(int x)
{
    vector<vector<bool>> dp(5010, vector<bool>(5010));
    dp[0][0] = true;
    for(int i = 1; i <= n; i++)
    {
        for(int j = 0; j <= K; j++)
        {
            if(i == x)
            {
                dp[i][j] = dp[i][j] || dp[i-1][j];
            }
            else
            {
                dp[i][j] = dp[i][j] || dp[i-1][j];
                if(dp[i-1][j] && j + a[i] <= K)
                {
                    dp[i][j+a[i]] = true;
                }
            }
        }
    }
    bool flag = false;
    for(int i = K-a[x]; i <= K - 1; i++)
    {
        if(dp[n][i])
        {
            flag = true;
        }
    }
    return flag;
}
