int cmp(int a, int b) { return b < a;}
int no_unneccessary(int n, int k, vector<int> nums);

int main()
{
	int n, k;
	cin >> n >> k;

	vector<int> nums;
	int tmp;
	for(int i=0; i<n; i++) {
		cin >> tmp;
		nums.push_back(tmp);
	}
	cout << no_unneccessary(n, k, nums) << endl;
	return 0;
}

int no_unneccessary(int n, int k, vector<int> nums)
{
	int idx = 0;
	sort(nums.begin(), nums.end(), cmp);

	for(int i=0; i<n; i++) {
		int sum = 0;
		for(int j=i; j<n; j++) {
			sum += nums[j];
			if(sum >= k) {
				idx = max(idx, j+1);
				sum -= nums[j];
			}
		}
	}
	return n-idx;
}

