int N, K;
vector<int> arr;

int currNum;
//short memo[5005][5005];

bitset<5005> memo[5005], isSet[5005];
short dp(int currN, int currSum)
{
	if(isSet[currN].test(currSum))
		return memo[currN][currSum];

	if(currN == 0)
	{
		memo[currN][currSum] = (K - currNum <= currSum && currSum < K);
		isSet[currN][currSum] = 1;
		return memo[currN][currSum];
	}

	memo[currN][currSum] = dp(currN - 1, currSum);
	if(currSum + arr[currN] < K)
		memo[currN][currSum] = memo[currN][currSum] | dp(currN - 1, currSum + arr[currN]);

	isSet[currN][currSum] = 1;
	return memo[currN][currSum];
}

short isNecessary(int pos)
{
	currNum = arr[pos];
	arr.erase(arr.begin() + pos);

	for(int i = 0; i < N + 5; i++)
	{
		for(int j = 0; j < K + 5; j++)
			isSet[i][j] = 0;
	}

	short ans = dp( (int)(arr.size()) - 1, 0);
	arr.insert(arr.begin() + pos, currNum);
	return ans;
}

int main()
{
	scanf("%d%d", &N, &K);

	arr.push_back(0);

	long long sum = 0;
	for(long long i = 1; i <= N; i++)
	{
		int ai;
		scanf("%d", &ai);
		arr.push_back(ai);

		sum += ai;
	}

	if(sum < (long long)(K) )
	{
		printf("%d", N);
		return 0;
	}

	sort(arr.begin(), arr.end());

	int startPtr = 1, endPtr = N, ans = 0;
	while(startPtr <= endPtr)
	{
		int mid = startPtr + (endPtr - startPtr) / 2;
		int necessary = isNecessary(mid);

		if(necessary)
			endPtr = mid - 1;

		else
		{
			startPtr = mid + 1;
			ans = mid;
		}
	}

	printf("%d", ans);
}

