int A[MAX_N];
bool DP[MAX_K];

void solve() {
  sort(A, A + N);
  ll sum = 0;
  for (int i = 0; i < N; i++) sum += A[i];
  for (int j = 0; j < K; j++) DP[j] = false;
  DP[0] = true;

  int ans = 0;
  for (int i = N - 1; i >= 0; i--) {

    bool no_need = true;
    for (int j = 0; j < K; j++) {
      if (DP[j] && j + sum >= K) {
        no_need = false;
        break;
      }
    }
    if (no_need) ans++;

    for (int j = K - 1; j >= 0; j--) {
      int k = j + A[i];
      if (k < K) DP[k] |= DP[j];
    }
    sum -= A[i];

    debug_printf("sum = %lld, a = %d\n", sum, A[i]);
    for (int j = 0; j < K; j++) debug_printf("%s ", DP[j]? "o": "x");
    debug_printf("\n");
  }
  printf("%d\n", ans);
}

int main() {
  scanf("%d %d", &N, &K);
  for (int i = 0; i < N; i++) scanf("%d", &A[i]);

  solve();

  return 0;
}

