bool fp[5005][5005], fr[5005][5005];
int sr[5005][5005];
int n, k, a[5005], an;

int main(){
	scanf("%d%d",&n,&k);
	for(int i = 1; i <= n; ++i) scanf("%d",&a[i]), a[i] = min(a[i], k);
	fp[0][0] = 1;
	for(int i = 0; i < n; ++i){
		for(int j = 0; j <= k; ++j){
			fp[i + 1][j] |= fp[i][j];
			fp[i + 1][min(j + a[i + 1], k)] |= fp[i][j];
		}
	}
	fr[n + 1][0] = 1;
	for(int i = n + 1; i > 1; --i){
		for(int j = k; j >= 0; --j){
			fr[i - 1][j] |= fr[i][j];
			fr[i - 1][min(j + a[i - 1], k)] |= fr[i][j];
		}
	}
	for(int i = 1; i <= n + 1; ++i){
		sr[i][0] = 1;
		for(int j = 1; j <= k; ++j)
			sr[i][j] = sr[i][j - 1] + fr[i][j];
	}
	an = n;
	for(int i = 1; i <= n; ++i){
		bool ok = 0;
		for(int j = 0; j < k; ++j){
			int l = k - a[i] - j, r = k - 1 - j;
			l = max(l, 0);
			ok |= (fp[i - 1][j] & (sr[i + 1][r] - (l ? sr[i + 1][l - 1] : 0) > 0));
		}
		an -= ok;
	}
	printf("%d", an);
	return 0;
}

