#define REP(i,x,y) for(ll i=x;i<=y;i++)
typedef long long ll;
using namespace std;
ll const MAX = 5005;
ll a[MAX];
bitset<MAX> b[MAX];
bitset<MAX> c[MAX];
ll d[MAX];

int main() {
	ll n, k;
	cin >> n >> k;
	ll ans = 0;
	REP(i, 1, n) {
		cin >> a[i];
		if (a[i] >= k) {
			i--;
			n--;
		}
	}
	b[0][0] = 1;
	c[n + 1][0] = 1;
	REP(i, 1, n-1) {
		b[i] = b[i - 1] | (b[i - 1] << a[i]);
		c[n + 1 - i] = c[n - i + 2] | (c[n - i + 2] << a[n + 1 - i]);
	}
	REP(i, 1, n) {
		bool flag = 1;
		d[0] = 1;
		REP(j, 1, k) {
			d[j] = d[j - 1] + (c[i+1][j] == 1);
		}
		REP(j, 0, k) {
			if (b[i-1][j] == 1) {
				ll x, y;
				x = k - a[i] - j;
				y = k - 1 - j;
				//cにx以上y以下の元があるかどうかを調べたい
				if (y < 0) {
					flag = 1;
					break;
				}
				if (x <= 0) {
					flag = 0;
					break;
				}
				else {
					if (d[y] - d[x - 1] != 0) {
						flag = 0;
						break;
					}
				}
			}
		}
		ans += flag;
	}
	cout << ans << endl;
}

