int solve(int mid){
	if(a[mid] >= k)return 1;
	bitset<5010> dp;
	dp = dp2[mid+1];
	for(int i = 1;i <= k;i++){
		if(dp1[mid-1][i] == 0)continue;
		dp = dp | dp2[mid+1]<<i;
	}
	dp[k] = 0;
	for(int i = k-1;i >= 1;i--)
	if(dp[i+1])dp[i] = 1;
	if(dp[k-a[mid]])return 1;
	return 0;
}

