bool pre[5010][5010];
bool suf[5010][5010];

void mainmain(){
	int n;
	cin>>n;
	int K;
	cin>>K;
	vll v(n);
	rep(i,n) cin>>v[i];
	sort(ALL(v));
	int ans = 0;
	// int m = 100010;
	pre[0][0] = true;
	suf[n-1][0] = true;
	rep(i,n){
		if(i) rep(j,5010){
			pre[i][j] = pre[i-1][j];
		}
		if(v[i]>=K) continue;
		for(int j = K; j >= v[i]; j--){
			pre[i][j] |= pre[i][j-v[i]];
		}
	}
	for(int i = n-1; i>=0; i--){
		if(i!=n-1){
			rep(j,5010){
				suf[i][j] = suf[i+1][j];
			}
		}
		if(v[i]>=K) continue;
		for(int j = K; j >= v[i]; j--){
			suf[i][j] |= suf[i][j-v[i]];
		}
	}
	vvint aa(n);
	vvint bb(n);
	rep(i,n){
		rep(j,5010){
			if(pre[i][j]) aa[i].PB(j);
			if(suf[i][j]) bb[i].PB(j);
		}
	}
	rep(i,n){
		bool ok = false;
		if(i==0){
			for(cauto x: bb[i+1]){
				if(x>=K) break;
				if(x + v[i] >= K) ok = true;
			}
		}
		else if(i==n-1){
			for(cauto x: aa[i-1]){
				if(x>=K) break;
				if(x + v[i] >= K) ok = true;
			}
		}
		else{
			for(cauto x: aa[i-1]){
				// cout<<i<<" "<<x<<endl;
				if(K-x-v[i]<0) continue;
				auto it = lower_bound(ALL(bb[i+1]), K-x-v[i]);
				if(it==bb[i+1].end()) continue;
				// cout<< *it << endl;
				if(*it + x < K){
					ok=true;
					// cout<<"hh "<<i<<" "<< *it << x << endl;
				}
			}
		}
		if(v[i] >= K) ok=true;
		if(!ok){
			ans++;
			// cout<<i<<" "<<v[i]<<endl;
		}
	}
	cout<<ans<<endl;
}


signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout<<fixed<<setprecision(20);
    mainmain();
}

