const int N = 5000;
bool dp[N][N];
int vis[N][N];
int arr[N];
int VIS;
int l, r, n, s, k;
bool calc(int idx, int sum) {
	if (sum >= l && sum <= r)
		return true;
	if (sum > r)
		return false;
	if (idx == n)
		return false;
	bool &ret = dp[idx][sum];
	if (vis[idx][sum] == VIS)
		return ret;
	vis[idx][sum] = VIS;
	if (idx == s)
		return ret = calc(idx + 1, sum);
	return ret = calc(idx + 1, sum) || calc(idx + 1, sum + arr[idx]);
}
bool can(int idx) {
	++VIS;
	s = idx;
	l = k - arr[idx];
	r = k - 1;
	return !calc(0, 0);
}
int main() {

	//freopen("myfile.in", "r", stdin);
	scanf("%d%d", &n, &k);
	for (int i = 0; i < n; ++i)
		scanf("%d", arr + i);
	sort(arr, arr + n);
	int l = 0, r = n - 1, ans = 0;
	while (r >= l) {
		int mid = (r + l) / 2;
		if (can(mid)) {
			ans = mid+1;
			l = mid + 1;
		}
		else
			r = mid - 1;
	}
	printf("%d\n", ans);
	return 0;
}

