using namespace std;
#define REP(i,a,n) for(int i=(a); i<(int)(n); i++)
#define rep(i,n) REP(i,0,n)
#define FOR(it,c) for(__typeof((c).begin()) it=(c).begin(); it!=(c).end(); ++it)
#define ALLOF(c) (c).begin(), (c).end()
typedef long long ll;
typedef unsigned long long ull;

bool solve(ll K, ll X, const vector<ll>& v){
  ll mn = 1000000000000000LL;
  ll sum = 0;
  int s = 0, t = 0;
  while(true){
    while(t<v.size() && X+sum < K){
      sum += v[t];
      t++;
    }
    if(X+sum >= K) mn = min(mn, X+sum);
    if(t == v.size()) break;
    if(X+sum < K) break;
    sum -= v[s];
    s++;
  }

  if(mn-X >= K) return true;
  return false;
}


int main(){
  int N;
  ll K;
  vector<ll> v;
  cin >> N >> K;

  ll sum = 0;
  rep(i,N){
    ll x;
    cin >> x;
    v.push_back(x);
    sum += x;
  }

  ll ret = 0;
  rep(i,v.size()){
    vector<ll> w;
    rep(j,v.size()){
      if(i==j) continue;
      w.push_back(v[j]);
    }
    sort(ALLOF(w));
    if(solve(K, v[i], w)) ret++;
  }

  cout << ret << endl;

  return 0;
}

