using namespace std;
int n, K, D1[5010][5010], D2[5010][5010];
int w[5010], cnt;
bool Exist(int a, int b, int e){
    if(b <= 0){
        return D2[a][e] >= 1;
    }
    return D2[a][e] - D2[a][b-1] >= 1;
}
int main(){
    int i, j;
    scanf("%d%d",&n,&K);
    for(i=1;i<=n;i++){
        scanf("%d",&w[i]);
    }
    D1[0][0]=D2[n+1][0]=1;
    for(i=1;i<=n;i++){
        for(j=0;j<=K;j++){
            D1[i][j] = D1[i-1][j];
            if(j>=w[i] && D1[i-1][j-w[i]])D1[i][j] = 1;
        }
    }
    for(i=n;i>=1;i--){
        for(j=0;j<=K;j++){
            D2[i][j] = D2[i+1][j];
            if(j>=w[i] && D2[i+1][j-w[i]])D2[i][j] = 1;
        }
    }
    for(i=1;i<=n;i++){
        for(j=1;j<=K;j++)D2[i+1][j] += D2[i+1][j-1];
        if(w[i] > K){
            cnt++;
            continue;
        }
        for(j=0;j<K;j++){
            if(D1[i-1][j] && Exist(i+1,K-w[i]-j, K-j-1)){
                cnt++;
                break;
            }
        }
    }
    printf("%d\n",n-cnt);
}

