int main(){
	cin>>N>>K;
	REP(i,N)cin>>a[i];
	bef[0].set(0);
	REP(i,N){
		bef[i+1] = (bef[i] | (bef[i]<<a[i]));
//		cout<<bef[i+1]<<endl;
	}
	aft[N].set(0);
	for(int i=N-1;i>=0;i--){
		aft[i] = (aft[i+1] | (aft[i+1]<<a[i]));
//		cout<<aft[i]<<endl;
	}
	int ans = 0;
	REP(i,N){
		bool found = false;
		//judge bef[i] and aft[i+1]
		//using a[i]
		//K-a[i] <= b < K
		int mini = max(K-a[i],0);
		//start: [mini, K)
		int l = mini, r = K;
		int c = 0;
		for(int t = mini;t<K;t++){
			if(aft[i+1].test(t))c++;
		}
		for(int j=0;j<K;j++){
			if(bef[i].test(j) and c>0){
				found = true;
