const int MAX_N = 5001;
int N, K;
int A[MAX_N];
bool Necessary[MAX_N];

uint64_t Traverse(int cur, uint64_t sum)
{
    if( sum < K && K <= sum + A[cur])
    {
        Necessary[cur] = true;
        return sum + A[cur];
    }
    sum += A[cur];

    uint64_t min_sum = 0;
    for(int take = cur + 1; take <= N; ++take)
    {
        const uint64_t v = Traverse(take, sum);
        if((min_sum == 0 || v < min_sum) && v != 0)
            min_sum = v;
    }
    if(min_sum - A[cur] < K && K <= min_sum)
        Necessary[cur] = true;

    return min_sum;
}

int main(int, char *[])
{
    cin >> N >> K;
    for(int i = 1; i <= N; ++i)
        cin >> A[i];

    sort(A + 1, A + 1 + N, greater<int>());

    Traverse(0, 0);

    int result = 0;
    for(int i = 1; i <= N; ++i)
    {
        if(!Necessary[i])
            ++result;
    }

    cout << result << endl;

    return 0;
}

