    dpl[i+1][j] = true;
    if(j+vec[i]<=k) dpl[i+1][j+vec[i]] = true;
  }
  dpr[n][0] = true;
  for(int i=n; i>0; i--) rep(j,k) if(dpr[i][j]){
    dpr[i-1][j] = true;
    if(j+vec[i-1]<=k) dpr[i-1][j+vec[i-1]] = true;
  }

  auto isneed = [&](int i){
    vector<int> cntr(k+1,0);
    rep(j,k) cntr[j+1] = cntr[j] + dpr[i+1][j+1]; // trueの個数の累積和
//    dbg(i); dbg(cntr);
    rep(j,k) if(dpl[i][j]){
      // 和が k-vec[i] ~ k-1 の中に値があるとtrue
      // つまりcntrでk-vec[i]-j ~ k-1-j
      if(k-vec[i]<=j && j<=k-1) return true;
      if(cntr[max(k-1-j,0)] - cntr[max(k-vec[i]-j-1,0)]>0) return true;
    }
    return false;
  };

  int ans=0;
  rep(i,n){
    if(!isneed(i)) ans++;
  }

  cout << ans << endl;

  return 0;
}

