const int SIZEN = 5000 + 10;
bitset <SIZEN> b;
int N,K,a[SIZEN] = {0},n = 0;

bool Judge(int x){
	for(int i = 0;i <= K;i++)b[i] = 0;
	b |= 1;
	for(int i = 1;i <= n;i++)if(i!=x){
		b = (b<<a[i]);
		b |= 1;
	}
	for(int i = 1;i < K;i++)if(b[i]){
		if(i + a[x] >= K)return false;
	}
	return true;
}

void work(){
	for(int i = 1;i <= N;i++){
		if(a[i] >= K)continue;
		a[++n] = a[i];
	} 
	sort(a+1,a+1+n);
	int l = 1,r = n,mid;
	while(l <= r){
		mid = (l+r)>>1;
		if(Judge(mid))l = mid+1;
		else r = mid-1;
	}
	printf("%d\n",r);
	return; 
}
int main(){ 
	scanf("%d%d",&N,&K);
	for(int i = 1;i <= N;i++)scanf("%d",&a[i]);
	work();
	return 0;
}

