void solve(){
	int N;//カード枚数
	int K;//閾値
	cin >> N >> K;
	vector<LL> A(N);
	LL AllSum = 0;
	for(int i=0;i<N;++i){
		cin>>A[i];
		AllSum += A[i];
	}
	if( AllSum < K ){
		cout << N << endl;
		return;
	}
	sort(A.begin(),A.end());
	int ans = 0;
	int L=0,R=0;
	LL sum=A[0];

	while(L<N){
		while( sum<K){
			++R;
			if( R >= N ){
				cout << ans << endl;
				return;
			}
			sum += A[R];
		}

		while( L < N && sum >= K ){
			if( sum-A[L] >= K ){
				++ans;
			}
			++L;
		}
	}
	cout << ans << endl;
}

