const int MOD = 1000000007;
#define MAX_N 5010

bool dp1[MAX_N][MAX_N] = {};    // 0 から見て、 i を使う前の時点で j が作れているなら true
bool dp2[MAX_N][MAX_N] = {};    // N-1 から見て、 i を使う前の時点で j が作れているなら true
int N, K;
int A[MAX_N];

void dfs1(int i, int j) {
    if(i >= N) { return; }
    if(dp1[i][j]) { return; }
    dfs1(i+1, j);
    if(j + A[i] < K) {
        dfs1(i+1, j + A[i]);
    }
    dp1[i][j] = true;
}
void dfs2(int i, int j) {
    if(i < 0) { return; }
    if(dp2[i][j]) { return; }
    dfs2(i-1, j);
    if(j + A[i] < K) {
        dfs2(i-1, j + A[i]);
    }
    dp2[i][j] = true;
}

signed main()
{
    cin >> N >> K;
    REP(i, N) { cin >> A[i]; }
    ZERO(dp1); ZERO(dp2);
    dfs1(0, 0);
    dfs2(N-1, 0);
    ll ans = N;
    REP(i, N) {
        for(int j = K - A[i]; j < K; ++j) {
            if(j <= 0) {
                ans--;
                break;
            }
            bool isFind = false;
            for(int x = 0; x <= j; ++x) {
                if(dp1[i][x] && dp2[i][j - x]) {
                    ans--;
                    isFind = true;
                    break;
                }
            }
            if(isFind) { break; }
        }
    }
    printf("%lld\n", ans);
    return 0;
}

