int main(){
    int n,k;
    scanf("%d%d",&n,&k);
    vector<int> a(n,0),b(k+k,0);
    for(int i = 0; i<n; i++)
        scanf("%d",&a[i]);
    sort(a.begin(),a.end());
    ll sum = 0;
    for(int i = 0; i<n; i++)
        sum+=a[i];
    if(sum<k)
        printf("%d\n",n);
    else{
        int s = 0,e=n-1,ans = -1;
        while(s<=e){
            int m = (s+e)/2;
            if(a[m]>=k){
                ans = m;
                e = m-1;
                continue;
            }
            fill(b.begin(),b.end(),0);
            b[0] = 1;
            for(int i = 0; i<n; i++){
                if(i==m||a[i]>=k)
                    continue;
                for(int j = k+k-1; j>=0; j--){
                    if(b[j]&&j+a[i]<k+k)
                        b[j+a[i]] = 1;
                }
            }
            bool found = false;
            for(int i = k-a[m]; i<k; i++){
                if(b[i]){
                    found = true;
                    break;
                }
            }
            if(found){
                ans = m;
                e = m-1;
            }else
                s = m+1;
        }
        printf("%d\n",ans);
    }
    return 0;
}

