using VV = vector<vector<int>>;
using V = vector<int>;
using P = pair<int, int>;
using IP = pair<int, P>;

template<typename T>
inline void input(vector<T>& v) { for (auto& x : v) cin >> x; }

void calc() {
	int n, k; cin >> n >> k;
	V v(n); input(v);
	int sum = accumulate(all(v), 0ll);
	int ans = 0;
	rep(i, n) {
		int x = v[i];
		if (sum < k) {
			ans++;
			continue;
		}
		if (x >= k) {
			continue;
		}

		V dp(k * 2 + 1);
		dp[0] = 1;
		rep(j, n) {
			if (i == j) continue;
			rrep(p, 2 * k) if (p - v[j] >= 0) {
				dp[p] += dp[p - v[j]] > 0;
			}
		}
		bool ok = true;
		rep(j, k) if(x + j >= k && dp[j]){
			ok = false;
			break;
		}
		ans += ok;
	}
	cout << ans << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	calc();
#ifdef _MSC_VER
	system("pause");
#endif
}

