 * some subset whose sum < k and sum + 4 >= k
 * _ _ _ _ _ _ _ _ k _
 */
int main() {
	int n, k;
	cin >> n >> k;
	vector <int> A(n + 1);
	for (int i = 1; i <= n; i++) {
		cin >> A[i];
	}
	// Store dp[i][j], where i denotes till which index and j is the sum
	vector <vector<bool>> pre(n + 1, vector<bool>(k + 1, false));
	pre[0][0] = true;
	for (int i = 1; i <= n; i++) {
		for (int j = 0; j <= k; j++) {
			if (j >= A[i]) {
				pre[i][j] = pre[i][j] | pre[i - 1][j - A[i]];
			}
			pre[i][j] = pre[i][j] | pre[i - 1][j];
		}
	}
	vector <vector<bool>> suf(n + 2, vector<bool>(k + 1, false));
	suf[n + 1][0] = true;
	for (int i = n; i >= 1; i--) {
		for (int j = 0; j <= k; j++) {
			if (j >= A[i]) {
				suf[i][j] = suf[i][j] | suf[i + 1][j - A[i]];
			}
			suf[i][j] = suf[i][j] | suf[i + 1][j];
		}
	}
	int ans = 0;
	for (int i = 1; i <= n; i++) {
		if (A[i] >= k)	continue;
		bool ok = false;
		int l = k;
		for (int j = 0; j < k; j++) {
			if (pre[i - 1][j]) {
				// you want any sum posible from k - A[i] - j to k - 1 - j
				while(l > k - 1 - j) l--;
				while(l >= max(k - A[i] - j, 0) && !suf[i + 1][l]) l--;
				//cout << i << " " << j << " " << l << "\n";
				if (l >= max(k - A[i] - j, 0)) {
					//cout << i << "\n";
					ok = true;
					break;
				}
			}
		}
		ans += !ok;
	}
	cout << ans;
}

