#define MAX_N 5001
#define MAX_K 5001

using namespace std;

typedef long long ll;
typedef pair<int,int> P;

ll N, K, a[MAX_N];
bool s[MAX_K];

bool C(ll i) {
  // カードiが必要かどうかを判定
  fill(s, s + MAX_K, false);
  s[0] = true;
  for (ll j = 0; j < N; j++) {
    if (i == j) {
      continue;
    }
    for (ll k = K-1; k >= 0; k--) {
      s[k + a[j]] = s[k + a[j]] || s[k];
    }
  }

  for (ll k = max((ll)0, K - a[i]); k < K; k++) {
    if (s[k]) {
      return true;
    }
  }
  return false;
}

ll binary() {
  ll lb = -1, ub = N;

  while (ub - lb > 1) {
    ll mid = (lb + ub) / 2;
    if (C(mid)) {
      ub = mid;
    } else {
      lb = mid;
    }
  }
  return ub;
}

int main() {

  cin >> N >> K;
  for (ll i = 0; i < N; i++) {
    cin >> a[i];
  }
  sort(a, a + N);

  cout << binary() << endl;

  return 0;
}

