#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define rep(i,n) FOR(i,0,n)
#define RFOR(i,a,b) for(int i=(a)-1;i>=(b);i--)
#define rrep(i,n) RFOR(i,n,0)

using namespace std;

typedef long long ll;
typedef unsigned long long ull;


ll n,k;
const ll max_n = 5005;
ll a[max_n];

bool cond(ll x){

	// dp[a][b] : a-1番目(0-index)までのカードで総和dができるか。ただしカードxは使わない。
	bool dp[n+1][k+1];
	rep(i,n+1) rep(j,k+1) dp[i][j] = false;
	dp[0][0] = true;

	rep(i,n){
		rep(j,k+1){
			if(i == x){
				dp[i+1][j] = dp[i][j];
			} 
			else{
				if(j-a[i] < 0) dp[i+1][j] = dp[i][j];
				else dp[i+1][j] = dp[i][j-a[i]];
			}	
 		}
	}

	/*
	cout << x << ":" << endl;
	rep(i,n+1){
		rep(j,k+1){
			cout << dp[i][j] << " ";
		}
		cout << endl;
	}
	*/

	FOR(i,k-a[x],k){
		if(dp[n][i]) return true;
	}
	return false;
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> n >> k;
	rep(i,n) cin >> a[i];

	sort(a,a+n);
	if(!cond(n-1)){
		cout << n << endl;
		return 0;
	}

	if(cond(0)){
		cout << 0 << endl;
		return 0;
	}

	ll lb = -1, ub = n-1;

	while(ub - lb > 1){
		int mid = (lb + ub) / 2;

		if(cond(mid)) ub = mid; // Answer is in (lb, mid]
		else lb = mid;            // Answer is in (mid, ub]

		// cout << lb << " " << mid << " " << ub << endl;
	}

	cout << ub << endl;
}

