		cin >> A[i];
	}
	// Store dp[i][j], where i denotes till which index and j is the sum
	vector <vector<bool>> pre(n + 1, vector<bool>(k + 1, false));
	pre[0][0] = true;
	for (int i = 1; i <= n; i++) {
		pre[i][0] = true;
		for (int j = 1; j <= k; j++) {
			if (j >= A[i]) {
				pre[i][j] = pre[i][j] | pre[i - 1][j - A[i]];
			}
		}
	}
	vector <vector<bool>> suf(n + 2, vector<bool>(k + 1, false));
	suf[n + 1][0] = true;
	for (int i = n; i >= 1; i--) {
		suf[i][0] = true;
		for (int j = 1; j <= k; j++) {
			if (j >= A[i]) {
				suf[i][j] = suf[i][j] | suf[i + 1][j - A[i]];
			}
		}
	}
	int ans = 0;
	for (int i = 1; i <= n; i++) {
