				while(l > k - 1 - j) l--;
				while(l >= k - A[i] - j && l >= 0 && !suf[i + 1][l]) l--;
				if (l >= k - A[i] - j) {
					ok = true;
					break;
				}
			}
		}
		ans += !ok;
	}
	cout << ans;
