int n, s;
int a[N], k[N][N], k2[N];

int main() {
    scanf("%d%d", &n, &s);
    for(int i = 1; i <= n; i++)
        scanf("%d", a + i);
    sort(a + 1, a + n + 1);
    while(n > 0 && a[n] >= s) n --;

    if(!n) {puts("0");return 0;}

    k[n + 1][0] = 1;
    for(int i = n; i >= 1; i--)
        for(int j = 0; j <= s; j++){
            k[i][j] = k[i + 1][j];
            if(j >= a[i])
                k[i][j] |= k[i + 1][j - a[i]];
        }

    k2[0] = 1;

    for(int i = 1; i <= n; i++) {
        int l = 0, r = 0, c = 1;
        for(int j = s - 1; j >= 0; j--){
            while(l < max(0, s - a[i] - j))
                c -= k[i + 1][l], l ++;
            while(r < max(0, s - 1 - j))
                r ++, c += k[i + 1][r];
            if(!k2[j]) continue;
            if(c) {
                printf("%d\n", i - 1);
                return 0;
            }
        }
        for(int j = s; j >= a[i]; j --)
            k2[j] |= k2[j - a[i]];
    }
    printf("%d\n", n);
}

