using namespace std;

const int mod = 1e9 + 7;

int dp[5001];
int dp2[5001];

int add(int x, int y) {
	x += y;
	if (x >= mod) {
		x -= mod;
	}
	return x;
}

void upd(int &x, int y) {
	x += y;
	if (x >= mod) {
		x -= mod;
	}
}

int main() {
	int n, K;
	cin >> n >> K;
	vector<int> a(n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
	}
	dp[0] = 1;
	for (int i = 0; i < n; i++) {
		for (int j = K - 1; j >= a[i]; j--) {
			upd(dp[j], dp[j - a[i]]);
		}
	}
	// dp[i+1][j] = dp[i][j-a[i]]+dp[i][j]
	// dp[i][j]=dp[i+1][j]-dp[i][j-a[i]]
	int ans = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < min(K, a[i]); j++) {
			dp2[j] = dp[j];
		}
		for (int j = a[i]; j < K; j++) {
			dp2[j] = add(dp[j], mod - dp2[j - a[i]]);
		}
		bool any = false;
		for (int j = 0; j < K; j++) {
			if (dp2[j] != 0 && j + a[i] >= K) {
				any = true;
			}
		}
		if (!any) {
			ans++;
		}
	}
	cout << ans << endl;
}

