int main() {
  int n, k;
  scanf("%d %d", &n, &k);
  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
  }
  for (int j = 1; j <= 5000; j++) {
    bool skipped = false;
    bitset<10001> bs;
    bs[0] = 1;
    for (int i = 1; i <= n; i++) {
      if (a[i] == j && !skipped) {
        skipped = true;
        continue;
      }
      bs |= (bs << a[i]);
    }
    for (int i = k - 1; i >= max(0, k - j); i--) {
      ans[j] |= bs[i];
    }
  }
  int cnt = 0;
  for (int i = 1; i <= n; i++) {
    cnt += ans[a[i]];
  }
  printf("%d\n", n - cnt);
  return 0;
}

