	while(r-l>1)
	{ 
		int i = (r + l) / 2;
		if (a[i] >= k) { r = i; }
		else {
			vector<ijt> b;
			for (int j = 0; j < n; j++)
			{
				if (j != i and a[j] < k) b.pb(a[j]);
			}
			ijt m = b.size();
			vector<vector<bool>> dp(m + 1, vector<bool>(k + 2, false));
			/*
			ある部分集合の和がk-a[i]以上であると，a[i]を付け加えた和がk以上になってしまいかつa[i]をのぞいたときk未満になってしまうので，NG
			この判定をナップザックDPによって行う。
			*/
			//初期化は，dp[0][0] = true,dp[0][b[0]] = true
			dp[0][0] = dp[0][b[0]] = true;
			for (int j = 1; j < m; j++)
			{
				for (int l = 0; l < k + 2; l++)
				{
					if (l - b[j] >= 0) {
