	FOE(i, 0, n + 1) dpl[i][0] = dpr[i][0] = 1;

	FOE(i, 1, n) {
		FOE(j, 0, k) {
			if (dpl[i - 1][j]) {
				to = j + a[i];
				if (to > k) to = k;

				dpl[i][to] = 1;
			}
		}
	}

