		FOE(j, 0, k) {
			if (dpr[i + 1][j]) {
				to = j + a[i];
				if (to > k) to = k;

				dpr[i][to] = 1;
			}
		}
	}

	FOE(i, 1, n + 1) {
		ps[i][0] = dpr[i][0];
		FOE(j, 1, k) ps[i][j] = ps[i][j - 1] + dpr[i][j];
	}

	FOE(i, 1, n) {
		bool flag = 0;

		FOR(j, 0, k) if (dpl[i - 1][j]) {
			if (sum(i + 1, k - j - a[i], k - 1 - j) > 0)
				flag = 1;
		}

		if (flag) ans++;
	}

	printf("%d\n", n - ans);

	return 0;

}

