int DPT[405][405];

int howclose(int i, int K, int nope) {
	if (K <= 0)
		return 1e9+10;
	if (i == N) {
		return K;
	}
	if (DPT[i][K] != -1) {
		return DPT[i][K];
	}
	if (i == nope) {
		return howclose(i+1, K, nope);
	}
	int ans = min(howclose(i+1, K-vals[i], nope), howclose(i+1, K, nope));
	return DPT[i][K] = ans;
}

vector<vector<bool>> dp_possl(5005, vector<bool>(5005)), isset = dp_possl;
bool possl(int i, int K) {
	if (K == 0)
		return 1;
	if (i < 0 || K < 0)
		return 0;
	if (isset[i][K])
		return dp_possl[i][K];
	isset[i][K] = 1;
	return dp_possl[i][K] = possl(i-1, K) || possl(i-1, K-vals[i]);
}

