int T[10000];
int DPL[10000][5005], DPR[10000][5005];

int main() {
  int N,K;
  scanf("%d%d", &N, &K);
  REP(i,N) scanf("%d", &T[i]);
  DPL[0][0] = 1;
  REP(i,N-1)REP(j,5005)if(DPL[i][j]) {
    DPL[i+1][j] = 1;
    DPL[i+1][min(5000,j+T[i])] = 1;
  }
  DPR[N-1][0] = 1;
  FORD(i,N,1) REP(j,5005) if (DPR[i][j]) {
    DPR[i-1][j] = 1;
    DPR[i-1][min(5000,j+T[i])] = 1;
  }

  int result = 0;
  REP(i,N) {
    if (T[i] >= K) continue;

    FOR(j,1,5005) DPR[i][j] += DPR[i][j-1];
    int A = K - T[i], B = K - 1;

    // printf("%d %d %d\n", i, A, B);
    // REP(j,K+1) printf("%d %d %d %d\n", i, j, DPL[i][j], DPR[i][j]);
    bool necessary = false;
    FOR(j,A,B+1) if (DPL[i][j]) necessary = true;
    REP(l,A) if (DPL[i][l]) {
      if (DPR[i][B-l] > DPR[i][A-l-1]) {
        necessary = true;
      }
    }
    if (!necessary) ++result;
  }

  printf("%d\n", result);
}

