int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N, K;
    cin >> N >> K;

    vector<long long> a(N);
    for (int i=0; i<N; ++i) cin >> a[i];

    if (accumulate(a.begin(), a.end(), 0LL) < (long long)K) {
        cout << N << endl;
        return 0;
    }

    dp[0][0][0] = true;
    dp[1][N][0] = true;
    for (int i=0; i<N; ++i) {
        for (int j=0; j<=K; ++j) {
            dp[0][i+1][j] |= dp[0][i][j];
            if (j+a[i] <= K) {
                dp[0][i+1][j+a[i]] |= dp[0][i][j];
            }

            dp[1][N-i-1][j] |= dp[1][N-i][j];
            if (j+a[N-1-i] <= K) {
                dp[1][N-i-1][j+a[N-1-i]] |= dp[1][N-i][j];
            }
        }
    }

    for (int i=0; i<=N; ++i) {
        ac[i][0] = 0;
        for (int j=0; j<=K; ++j) {
            ac[i][j+1] = ac[i][j] + (dp[0][i][j] ? 1 : 0);
        }
    }

    int need = 0;
    for (int i=0; i<N; ++i) {
        if (K <= a[i]) {
            need ++;
            continue;
        }
        for (int j=0; j<=K; ++j) {
            if ( ! dp[1][i+1][j]) continue;

            // [K-a[i]-j, K-j)
            int cnt = ac[i][K-j] - ac[i][max(0LL, K-a[i]-j)];
            if (cnt > 0) {
                need ++;
                break;
            }
        }
    }

    cout << N - need << endl;

    return 0;
}

