vector<vector<bool> > f(int N, int K, vector<int> a) {
	vector<vector<bool> > dp(N + 1, vector<bool>(K));
	dp[0][0] = true;
	rep(i, N) rep(x, K) if (dp[i][x]) {
		dp[i + 1][x] = true;
		if (x + a[i] < K) dp[i + 1][x + a[i]] = true;
	}
	return dp;
}

int main() {
	int N, K; cin >> N >> K;
	vector<int> a;
	while (N--) {
		int x; cin >> x;
		if (x < K) a.pb(x);
	}
	N = a.size();
	vector<vector<bool> > dp1 = f(N, K, a);
	reverse(a.begin(), a.end());
	vector<vector<bool> > dp2 = f(N, K, a);
	reverse(dp2.begin(), dp2.end());
	reverse(a.begin(), a.end());
	int ans = 0;
	rep(i, N) {
		vector<int> unko(K + 1);
		unko[0] = -1;
		rep(x, K) {
			unko[x + 1] = unko[x];
			if (dp2[i + 1][x]) unko[x + 1] = x;
		}
		bool ok = false;
		rep(x, K) if (dp1[i][x]) {
			int y = K - 1 - x;
			if (y >= 0 && x + unko[y + 1] + a[i] >= K) ok = true;
		}
		if (!ok) ans++;
	}
	cout << ans << endl;
}

