bool solve(ll K, ll X, const vector<ll>& v){
  ll mn = 1000000000000000LL;
  ll sum = 0;
  int s = 0, t = 0;
  while(true){
    while(t<v.size() && X+sum < K){
      sum += v[t];
      t++;
    }
    if(X+sum >= K) mn = min(mn, X+sum);
    if(X+sum < K) break;
    sum -= v[s];
    s++;
  }

  if(mn-X >= K) return true;
  return false;
}


