}

#include<iostream>
#include<cstdio>
#include<vector>
#include<string>
#include<algorithm>
using namespace std;

int N, K;
vector<int> a;
vector<bool> isNecessary;

bool solve(int i, int exclude_index, long long sum)
{
	if (i == N) { //終わり
		if (i == exclude_index) { //Nが飛ばす番号だったらsumをそのまま見る
			if (K - a[exclude_index] <= sum && sum < K) return true;
		} else { //そうでなかったらa[N]を含める、含めないの二通りを考える
			//含める
			if (K - a[exclude_index] <= sum + a[N] && sum + a[N] < K) return true;
			//含めない
			if (K - a[exclude_index] <= sum && sum < K) return true;
		}
	} else if (i == exclude_index) {
		//飛ばす
		if (solve(i + 1, exclude_index, sum)) return true;
	} else {
		//a[i]を含める
		if (solve(i + 1, exclude_index, sum + a[i])) return true;
		//[a[i]を含めない
		if (solve(i + 1, exclude_index, sum)) return true;
	}

	//exclude_indexは不必要
	return false;
}

int main()
{
	cin >> N >> K;
	a.resize(N + 1);
	for (int i = 1; i <= N; i++) cin >> a[i];

	isNecessary.resize(N + 1);
	for (int i = 1; i <= N; i++) {
		//a[i]が不必要か判断
		//a[i]を含む集合(悪い集合も含む)のうち、a[i]以外の和sumが(K - a[i] <= sum <= K)となるものがあれば必要
		//結局a[i]以外について全探索してsum出してやれば部分点いけるやろ
		isNecessary[i] = solve(1, i, 0);
	}
	int ans = 0;
	for (int i = 1; i <= N; i++) {
		if (!isNecessary[i]) ans++;
	}
	cout << ans << endl;
}

