        template <typename V, typename It>
        struct matrix_helper<V, It, 0> {
            static Matrix<V, 0> create(const It &begin __attribute__((unused)),
                                       const It &end __attribute__((unused)),
                                       const V &default_value) {
                return default_value;
            }
        };
