inline bool ck(int v) {
    if(a[v] >= k) return 0;
    f.reset(); f[0] = 1;
    for(ri i = 1; i <= n; i ++) {
        if(i == v) continue;
        f |= (f << a[i]);
    }
    for(ri i = k - 1; i >= k - a[v]; i --)
    if(f[i]) return 0; return 1;
}

