inline long long recur(int at, int left){
	if(left <= 0) return 0;
	if(at == n + 1) return oo;
	if(vp[at][left] == t) return dp[at][left];
	vp[at][left] = t;
	long long ret = oo;
	ret = min(ret, recur(at+1, left));
	ret = min(ret, a[at] + recur(at+1, left-a[at]));
	return dp[at][left] = ret;
}

bool OK(int pos){
	if(a[pos] >= k) return false;
	int val = a[pos];
	a[pos] = 0; ++t;
	long long mn = recur(1, k - val);
	bool ret = false;
	if(mn >= k) ret = true;
	a[pos] = val;
	return ret;
}

