  sort(a.begin(),a.end());

  //put the id of left side into 'mi'
  int mi = n;
  for (int i = n-1; i >= 0; i--) {
    //if a[i] is greater than k -> see next number
    if (a[i] >= k) {
      mi = min(mi,i);
      continue;
    }

    //if a[i] is not greater than k -> get next number until the sum is greater than k
    int sum = a[i];
    int tmp_id = i;
    while (tmp_id - 1 >= 0 && sum + a[tmp_id - 1] < k) {
      sum += a[--tmp_id];
    }

    //if the pointer is at the end and sum is still less than k -> end the program
    if (tmp_id == 0 && sum < k) break;

    // -> else find the left minimal
    //the minimal number to be added
    int diff = k - sum;
    while (tmp_id - 1 >= 0 && a[tmp_id - 1] >= diff) {
      tmp_id--;
    }

    mi = min(mi,tmp_id);
  }

  cout << mi << endl;
  return 0;
