            a.push_back(a_sub);
        }
    }
    int M=a.size()-1;
    if(M<=0){
        cout << ans << endl;
        return 0;
    }
    int dp[M+1][2*K+1], dp_rev[M+1][K+1];
    dp[0][0]=1;
    for(j=1; j<=2*K; j++){
        dp[0][j]=0;
    }
    for(i=1; i<=M; i++){
        for(j=0; j<=2*K; j++){
            if(j-a[i]<0){
                dp[i][j]=dp[i-1][j];
            }else{
                dp[i][j]=dp[i-1][j]+dp[i-1][j-a[i]];
                dp[i][j]%=MOD;
            }
        }
    }
    for(i=1; i<=M; i++){
        for(j=0; j<=K; j++){
            if(j-a[i]<0){
                dp_rev[i][j]=dp[M][j];
            }else{
                dp_rev[i][j]=dp[M][j]+(MOD-dp_rev[i][j-a[i]]);
                dp_rev[i][j]%=MOD;
            }
        }
