	int cnt = 0;
	for (int i = 1; i <= n; i++) {
		// pref[i - 1][...], suff[i + 1][...]
		if (a[i] >= k) continue;
		int flag = 0;
		for (int j = 0; j < k; j++) {
			if (pref[i - 1][j] == 0) continue;
			int t = suff[i + 1][k - 1 - j] - (k - a[i] - j > 0 ? suff[i + 1][k - a[i] - 1 - j] : 0);
			if (t > 0) {
				flag = 1;
			}
		}
		if (!flag) cnt++;
	}

	printf("%d\n", cnt);
	return 0;
}

