uint64_t buf[80];
void shift_or(int n) {
	int big = n >> 6;
	int small = n & 63;
	if (small) {
		int ismall = 64 - small;
		for (int i = 78 - big; i >= 0; i--) {
			uint64_t cur = buf[i];
			buf[i + big] |= cur << small;
			buf[i + big + 1] |= cur >> ismall;
		}
	} else {
		for (int i = 78 - big; i >= 0; i--)
			buf[i + big] |= buf[i];
	}
}

int main() {
	int n = ri(), k = ri();
	int a[n];
	for (int i = 0; i < n; i++) a[i] = ri();
	int cnt = 0;
	uint64_t bak[80];
	buf[0] = 1;
	for (int j = 0; j < n / 2; j++) shift_or(a[j]);
	memcpy(bak, buf, sizeof(buf));
	for (int i = 0; i < n; i++) {
		if (i >= n / 2) {
			memcpy(buf, bak, sizeof(buf));
			for (int j = n / 2; j < n; j++) {
				if (i == j) continue;
				shift_or(a[j]);
			}
		} else {
			memset(buf, 0, sizeof(buf));
			buf[0] = 1;
			for (int j = 0; j < n; j++) {
				if (i == j) continue;
				shift_or(a[j]);
			}
		}
		for (int j = std::max(0, k - a[i]); j < k; j++) if (buf[j >> 6] >> (j & 63) & 1) {
			cnt++;
			break;
		}
	}
	std::cout << n - cnt << std::endl;
	return 0;
}

