	int tmp;
	for (int i = 0; i < N; ++i) {
		cin >> tmp;
		if (tmp < K) {
			a.push_back(tmp);
		}
	}
	sort(a.begin(), a.end());
	int n = a.size();
	vector<vector<bool>> lower(n, vector<bool>(K+1));
	lower[0][0] = true;
	lower[0][K] = true;// 番兵
	for (int i = 0; i < n-1; ++i) {
		for (int j = 0; j < a[i]; ++j) {
			lower[i + 1][j] = lower[i][j];
		}
		for (int j = a[i]; j <= K; ++j) {
			lower[i + 1][j] = (lower[i][j] || lower[i][j-a[i]]);
		}
	}
	vector<vector<bool>> grter(n, vector<bool>(K+1));
	grter[n - 1][0] = true;
	grter[n - 1][K] = true;
	for (int i = n-1 ; i > 0; --i) {
		for (int j = 0; j < a[i]; ++j) {
			grter[i - 1][j] = grter[i][j];
		}
		for (int j = a[i]; j <= K; ++j) {
			grter[i - 1][j] = (grter[i][j] || grter[i][j - a[i]]);		   
		}
	}
	int ans = 0;
	// a[i]を取り除いた場合はlower[i]とgrter[i]を見れば良い
	for (int i = 0; i < n; ++i) {
		int lj = 0, gj = K;
		while (lj + gj >= K || lj + gj <= K-a[i]) {
			if (lj + gj >= K) {
				if (gj == 0) {
					++ans;
					break;
				}
				do { --gj; } while (!grter[i][gj]);
			}
			else {
				if (lj == K) {
					++ans;
					break;
				}
				do { ++lj; } while (!lower[i][lj]);
			}
		}
	}
	cout << ans << endl;

	return 0;
}

