void backtrack (int bad, int pos, long long sum) {
	if (sum >= k) return;
	big = max(big, sum);
	if (pos > n) return;
	backtrack(bad, pos + 1, sum);
	if (pos != bad) backtrack(bad, pos + 1, sum + a[pos]);
}

int main (int argc, char const *argv[]) {
	scanf("%d %d", &n, &k);
	for (int i = 1; i <= n; ++i) {
		scanf("%lld", a + i);
	}
	sort(a + 1, a + n + 1);
	int ans = 0;
	for (int i = 1; i <= n; ++i) {
		long long curr = a[i];
		big = -1;
		backtrack(i, 1, 0);
		if (big + curr >= k) {
			++ans;
		}
	}
	printf("%d\n", n - ans);
  return 0;
}

