bool is_needed(int x){
    for(int k = 0; k < K; k++){
            dp[0][k] = false;
    }
    dp[0][0] = true;
    for(int i = 0; i < N+2; i++){
        for(int k = 0; k < K; k++){
            dp[i+1][k] = dp[i][k];
        }
        if(i != x){
           for(int k = 0; k < K; k++){
               if(a[i] + k < K){
                   dp[i+1][a[i]+k] = dp[i][k] || dp[i+1][a[i]+k];
               }
           }
        }
    }
    bool ret = false;
    for(int k = K - a[x]; k < K; k++){
        ret = ret || dp[N+2][k];
    }
    return ret;
}

