void dfs(int pos, int sum, bool f) {
	if (sum >= k) return;

	int npos = pos;
	if (!f) {
		if (dp1[pos][sum]) return;
		dp1[pos][sum] = true;
		npos++;
	}
	else {
		if (dp2[pos][sum]) return;
		dp2[pos][sum] = true;
		npos--;
	}

	if (npos == 0 || npos == n + 1) return;

	dfs(npos, sum + a[npos], f);
	dfs(npos, sum, f);
}

int main() {
	cin >> n >> k;
	REP(i, n) scanf("%d", a + i + 1);

	dfs(0, 0, false);
	dfs(n + 1, 0, true);

	int ans = n;
	FOR(i, 1, n + 1) {
		if (a[i] >= k) {
			ans--;
			continue;
		}

		BIT<int> bit(k);
		REP(j, k) if (dp2[i + 1][j]) bit.add(j, 1);

		bool ok = false;

		REP(j, k) if (dp1[i - 1][j]) {
			if (j >= k - a[i]) ok = true;

			int mi = k - a[i] - j;

			int tmp = bit.lower_bound(mi + 1);
			if (tmp != -1 && tmp < k - j) ok = true;
		}

		if (ok) ans--;
	}

	cout << ans << endl;

	return 0;
}

