	{
		cin >> a[i];
		if (k < a[i])a[i] = k;
	}
	for (int x = 0; x < k; ++x)
	{
		dp[0][0][x] = 0;
	}
	dp[0][0][0] = 1;
	for (int p = 1; p <= n; ++p)
	{
		for (int x = 0; x < k; ++x)
		{
			dp[0][p][x] = dp[0][p - 1][x];
			if (x - a[p - 1] >= 0)
				dp[0][p][x] |= dp[0][p - 1][x - a[p - 1]];
		}
	}
	for (int x = 0; x < k; ++x)
	{
		dp[1][n][x] = 0;
	}
	dp[1][n][0] = 1;
	for (int p = n - 1; p >= 0; --p)
	{
		for (int x = 0; x < k; ++x)
		{
			dp[1][p][x] = dp[1][p + 1][x];
			if (x - a[p] >= 0)
				dp[1][p][x] |= dp[1][p + 1][x - a[p]];
		}
	}
	int ans = 0;
	for (int s = 0; s < n; ++s)
	{
		int lef = s;
		int rht = s + 1;
		int bot = k - a[s];//下限
		if (bot <= 0)bot = 1;
		int range = k - bot;
		bool ismake = false;

		vector<int>rimos;
		rimos.reserve(k);
		rimos.push_back(0);
		for (int x = 0; x < k; ++x)
		{
			rimos.push_back(rimos.back() + dp[1][rht][x]);
		}
		for (int col = 0; col <= bot; ++col)
		{
			int now = dp[0][lef][col];
			if (now && (rimos[bot - col + range] - rimos[bot - col]))
			{
				ismake = true;
			}
		}
		//残り(コーナー)
		for (int col = bot + 1; col < k; ++col)
		{
			int now = dp[0][lef][col];
			if (now && (rimos[bot - col + range] - rimos[0]))
			{
				ismake = true;
			}
		}
		if (!ismake)++ans;
	}
	cout << ans << endl;
	return 0;
}

