    vector<vbool> dp2(n+1, vbool(k, false));

    dp1[0][0] = true;
    rep(i,n){
        rep(j,k){
            dp1[i+1][j] = dp1[i+1][j] || dp1[i][j]; // 選ばない
            if(j+a[i] < k){
                dp1[i+1][j+a[i]] = dp1[i+1][j+a[i]] || dp1[i][j]; // 選ぶ
            }
        }
    }
    dp2[n][0] = 1;
    repr(i,n){
        rep(j,k){
            dp2[i][j] = dp2[i][j] || dp2[i+1][j];
            if(j+a[i] < k){
                dp2[i][j+a[i]] = dp2[i][j+a[i]] || dp2[i+1][j];
            }
        }
    }




