bool isValid(int target, const std::vector<int>& a, int K, int sum) {
    // calc minimum value X which satisfies X >= K
    // if X - a[target] >= K, card[target] is invalid.

    std::vector<int> mins;
    mins.reserve(4096);
    mins.push_back(sum);

    int min = sum;
    for (int i = a.size()-1; i >= 0; i--) {
        if (i == target)
            continue;

        int size = mins.size();
        for (int j = 0; j < size; j++) {
            if (mins[j] - a[i] >= K) {
                mins.push_back(mins[j] - a[i]);
                min = std::min(mins[j] - a[i], min);
            }
        }
    }

    // std::cout << "min: " << min << std::endl;
    if (min - a[target] < K) {
        return true;
    }

    return false;
}
