	for (int i = 0; i < k; i++)
		dp[i] = 0;
	dp[0] = 1;
	for (int i = 0; i < n; i++) {
		for (int z = 0; z < (i == t ? r[i] - 1 : r[i]); z++) {
			for (int j = k; j >= v[i]; j--) {
				if (dp[j - v[i]])
