int n,k;

bool proc(vector<int> a,int l){
    vector<vector<bool>> dp(n+1,vector<bool>(k,0));
    dp[0][0] = true;
    REP(i,n){
        if(i!=l){
            REP(j,k){
                if(j>=a[i]){
                    dp[i+1][j] = (dp[i][j-a[i]]||dp[i][j]);
                }else{
                    dp[i+1][j] = dp[i][j];
                }
            }
        }else{
            REP(j,k){
                dp[i+1][j] = dp[i][j];
            }
        }
    }
    bool rtn = false;
    REP(i,min(a[l],k)){
        if(dp[n][k-1-i]){
            rtn = true;
            break;
        }
    }
    return rtn;
}

