                    dp[i + 1][s] |= dp[i][s] | dp[i][s - AA[i]];
                else
                    dp[i + 1][s] |= dp[i][s];
            }
        }
        // A[c]を選んだら到達する
        FOR(s, max(0,K - A[c]), K) {
            if(dp[n - 1][s]) {
                --ans;
                break;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

