using namespace std;

int N, K;

bool sub(vector<int> a, int m) {
	vector<vector<bool> > dp(N, vector<bool>(K, false)); //dp[x][y] : can one make y with {a[0], ..., a[x]} - {a[m]} ?
	for(int y = 0; y < K; ++y) {
		for(int x = 0; x < N; ++x) {
			if(y == 0) {
				dp[x][y] = true;
			} else if(x == 0) {
				if(x == m) {
					dp[x][y] = false;
				} else {
					dp[x][y] = (a[0] == y);
				}
			} else {
				if(x == m || y < a[x]) {
					dp[x][y] = dp[x - 1][y];
				} else {
					dp[x][y] = (dp[x - 1][y] || dp[x - 1][y - a[x]]);
				}
			}
			//cout << "dp[" << x << "][" << y << "] = " << dp[x][y] << '\n';
		}
	}
	bool is_necessary = false;
	for(int k = 1; k <= a[m] && k < K; ++k) {
		if(dp[N - 1][K - k]) {
			is_necessary = true;
		}
	}
	return is_necessary;
}

int main(void) {
	cin >> N >> K;
	vector<int> a;
