		a.push_back(t);
		s += t;
	}
	sort(a.begin(), a.end());
	if(s < K) {
		cout << N << '\n';
		return 0;
	}
	if(K <= a[0]) {
		cout << "0\n";
		return 0;
	}

	vector<pair<bool, bool> > nec(N, make_pair(false, false)); //nec[i] = (is set, is necessary);

	//for(int i = 0; i < N; ++i) {
	//	cout << i << ',' << sub(a, i) << '\n';
	//}
	//return 0;

	int L = 0, R = N - 1;
	int m = (L + R) / 2;
	nec[0].first = true;
	nec[0].second = sub(a, 0);
	if(nec[0].second) {
		cout << "0\n";
		return 0;
	}
	nec[N - 1].first = true;
	nec[N - 1].second = sub(a, N - 1);
	while(!(nec[m].first && nec[m + 1].first && !nec[m].second && nec[m + 1].second)) {
		//cout << "m = " << m << '\n';
		nec[m].first = true;
		nec[m].second = sub(a, m);
		if(nec[m].second) {
			R = m;
			m = (L + R) / 2;
		} else {
			L = m;
			m = (L + R) / 2;
