typedef long long ll;
const int maxn = 5 * 1e3 + 10;
using namespace std;

int n, m, x;
int a[maxn], k;
int dp_lift[2][maxn];
int dp_right[2][maxn];
vector<int> gl[maxn], gr[maxn];

void init() {
    memset(dp_lift, 0, sizeof dp_lift);
    memset(dp_right, 0, sizeof dp_right);
    for(int i = 0; i < maxn; i++) {
        gl[i].clear();
        gr[i].clear();
    }
}

int main() {
    while(scanf("%d %d", &n, &k) != EOF) {
        init();
        ll sum = 0;
        for(int i = 1; i <= n; i++) {
            scanf("%d", &a[i]);
            sum += a[i];
        }
        sort(a + 1, a + n + 1);
        int t1 = 1, id = 0, tal = 0;
        for(int i = 1; i <= n; i++) {
            if(a[i] < k) id = i;
        }
        if(id) {
            dp_lift[0][0] = dp_lift[0][a[1]] = 1;
            dp_right[0][0] = dp_right[0][a[id]] = 1;
            gl[0].push_back(0);
            gr[id + 1].push_back(0);
            gl[1].push_back(0);
            gl[1].push_back(a[1]);
            gr[id].push_back(0);
            gr[id].push_back(a[id]);
            for(int i = 2; i <= id; i++) {
                for(int j = 0; j <= k; j++) {
                    int il = i, ir = id - i + 1;
                    ///左边dp
                    int j1 = j - a[il];
                    if(dp_lift[t1 ^ 1][j] || (j1 >= 0 && dp_lift[t1 ^ 1][j1])) {
                        dp_lift[t1][j] = 1;
                        gl[il].push_back(j);
                    }
                    ///右边dp
                    int j2 = j - a[ir];
                    if(dp_right[t1 ^ 1][j] || (j2 >= 0 && dp_right[t1 ^ 1][j2])) {
                        dp_right[t1][j] = 1;
                        gr[ir].push_back(j);
                    }
                }
                t1 ^= 1;
            }
            for(int i = 1; i <= id; i++) {
                for(int j = 0; j < gl[i - 1].size(); j++) {
                    int lift_sum = gl[i - 1][j];
                    int min_sum = k - a[i] - lift_sum;
                    int idx = lower_bound(gr[i + 1].begin(), gr[i + 1].end(), min_sum) - gr[i + 1].begin();
                    if(idx >= gr[i + 1].size()) continue;
                    int new_sum = lift_sum + gr[i + 1][idx];
                    if(new_sum >= k - a[i] && new_sum < k) { tal++; break; }
                }
            }
            tal = id - tal;
        }
        if(sum < k) tal = n;
        printf("%d\n", tal);
    }
    return 0;
}

