  REP(i, N){
    for(int j=0; j<K; ++j){
      Left[i+1][j] = (Left[i+1][j] | Left[i][j]);
    }
    for(int j=0; j+a[i]<K; ++j){
      Left[i+1][j+a[i]] = (Left[i+1][j+a[i]] | Left[i][j]);
    }
  }

  //Right.assign(N+1, vb(K, false));
  Right[N][0] = true;

  for(ll i=N-1; i>=0; --i){
    for(int j=0; j<K; ++j){
      Right[i][j] = (Right[i][j] | Right[i+1][j]);
    }
    for(int j=0; j+a[i]<K; ++j){
      Right[i][j+a[i]] = (Right[i][j+a[i]] | Right[i+1][j]);
