    //without a[i]
    //Left[i] + Right[i+1]
    ll left_i = 0;
    ll right_i = K-1;
    while(!Left[i][left_i]){
      left_i++;
      if(left_i >= K) break;
    }
    while(!Right[i+1][right_i]){
      right_i--;
      if(right_i < 0) break;
    }
    if(left_i>=K || right_i<0){
      ans++;
      continue;
    }

    ll max_sum = min(left_i + right_i, K);

    while(right_i<K && right_i>=0){
      if(left_i + right_i >= K){
        right_i--;
        while(!Right[i+1][right_i]){
          right_i--;
          if(right_i < 0) break;
        }
      }else{
        left_i++;
        while(!Left[i][left_i]){
          left_i++;
          if(left_i >= K) break;
        }
      }
      if(left_i >= K || right_i<0){
        break;
      }

      if(max_sum >= K) max_sum = min(left_i + right_i, K);
      else if(left_i + right_i < K) max_sum = max(max_sum, left_i + right_i);
    }

    //cout << i << ":" << max_sum << "\n";
    if(max_sum + a[i] < K) ans++;
  }

  cout << ans << "\n";

  return 0;
}

