typedef long long int LLI;

int N;
int K;
int as[114514];
bool ldp[5002][5002];
int rdp[5002][5002];
LLI sum;

int main() {
  scanf("%d%d", &N, &K);
  for (int i=1; i<=N; i++) {
    scanf("%d", &as[i]);
    sum += as[i];
  }

  if (sum < (LLI)K) {
    puts("0");
    return 0;
  }

  ldp[0][0] = true;
  if (as[1] <= K) ldp[1][as[1]] = true;
  for (int i=2; i<=N; i++) {
    ldp[i-1][0] = true;
    for (int j=as[i]; j<=K; j++) {
      ldp[i][j] |= ldp[i-1][j-as[i]];
    }
  }

  rdp[N+1][0] = 1;
  if (as[N] <= K) rdp[N][as[N]] = 1;
  for (int i=N-1; i>=1; i--) {
    rdp[i+1][0] = 1;
    for (int j=as[i]; j<=K; j++) {
      rdp[i][j] |= rdp[i+1][j-as[i]];
    }
  }

  for (int i=0; i<=N+1; i++) {
    for (int j=1; j<=K; j++) {
      rdp[i][j] += rdp[i][j-1];
    }
  }

  int ans = 0;
  for (int i=1; i<=N; i++) {
    for (int j=0; j<K; j++) {
      if (ldp[i-1][j]) {
        int l = max(K-j-as[i], 0);
        int cnt = rdp[i+1][K-j-1];
        if (l > 0) cnt -= rdp[i+1][l-1];
        if (cnt > 0) {
          ans++;
          break;
        }
      }
    }

  }
  printf("%d\n", N-ans);
}

