int main(void) {
	using namespace std;

	int N, K;
	cin >> N >> K;
	vector<int> a;
	for(int i = 0; i < N; ++i) {
		int t;
		cin >> t;
		a.push_back(t);
	}
	sort(a.begin(), a.end());

	vector<int> s; //s[i] = a[0] + ... + a[i - 1]
	s.push_back(0);
	for(int i = 0; i < N; ++i) {
		s.push_back(s.back());
		s.back() += a[i];
	}
	if(s.back() < K) {
		cout << N << '\n';
		return 0;
	}
	if(K <= s[0]) {
		cout << "0\n";
		return 0;
	}

	int m;
	int L = 0;
	int R = N - 1;
	m = (R + L) / 2;
	while(!(s[m - 1] < K && K <= s[m])) {
		if(s[m] < K) {
			L = m;
			m = (R + L) / 2 + 1;
		} else {
			R = m;
			m = (R + L) / 2;
		}
	}

	int n;
	L = 0, R = m;
	n = (R + L) / 2;
	while(!(s[m] - s[n + 1] < K && K <= s[m] - s[n])) {
		if(s[m] - s[n + 1] < K) {
			R = n;
			n = (R + L) / 2;
		} else {
			L = n;
			n = (R + L) / 2 + 1;
		}
	}

	int result = n - 1;
	while(0 < result && a[result] == a[result - 1]) {
		--result;
	}
	cout << result << '\n';

	return 0;
}

