	for (int i = n - 1; i >= n / 2; i--) shift_or(a[i]);
	std::set<int> all;
	for (int i = 0; i < k; i++) if (buf[i >> 6] >> (i & 63) & 1) all.insert(i);
	int cnt = 0;
	uint64_t bak[80] = { 0 };
	bak[0] = 1;
	for (int i = 0; i < n; i++) {
		if (i) {
			memcpy(buf, bak, sizeof(buf));
			shift_or(a[i - 1]);
			memcpy(bak, buf, sizeof(buf));
		}
		memcpy(buf, bak, sizeof(buf));
		int min = std::max(0, k - a[i]);
		int max = k;
		if (i >= n / 2) {
			for (int j = i + 1; j < n; j++) shift_or(a[j]);
			for (int j = min; j < max; j++) if (buf[j >> 6] >> (j & 63) & 1) {
				cnt++;
				break;
			}
		} else {
			for (int j = i + 1; j < n / 2; j++) shift_or(a[j]);
			for (int j = 0; j < k; j++) {
				if (buf[j >> 6] >> (j & 63) & 1) {
					auto itr = all.lower_bound(min - j);
					if (itr != all.end() && *itr < max - j) {
						cnt++;
						break;
					}
				}
			}
		}
	}
	std::cout << n - cnt << std::endl;
	return 0;
}

