ll n, k;
void visit(int v, int l, int r) {
    tree[v] = bits;
    for (auto cur : psh[v]) {
        bits |= (bits << cur);
    }
    if (l == r - 1) {
        bool flag = false;
        for (int j = k - 1; j >= 0; j--) {
            if (bits[j] && (vec[l] + j >= k)) {
                flag = true;
            }
        }

        cnt += !flag;
    }
    else {
        int mid = (l + r) / 2;
        visit(v * 2 + 1, l, mid);
        visit(v * 2 + 2, mid, r);

    }
    bits = tree[v];
}

void add(int v, int l, int r, int askl, int askr, int val) {
    if (l >= askr || r <= askl) return;

    if (l >= askl && r <= askr) {
        psh[v].push_back(val);
        return;
    }

    int mid = (l + r) / 2;
    add(v * 2 + 1, l, mid, askl, askr, val);
    add(v * 2 + 2, mid, r, askl, askr, val);
}

