using namespace std;

int solve(){
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    REP(i, N)cin >> A[i];
    REP(i, N)A[i] = min(A[i], 2*K);

    int L = 4*K+1;
    vector<vector<int> > dp(3, vector<int>(L));
    dp[0][0] = 1;
    REP(i, N){
        int a = A[i];
        for(int p = L-1; p>=a; p--){
            dp[2][p] |= dp[1][p-a] > 0 || dp[2][p-a] > 0;
        }
        for(int p = L-1; p>=a; p--){
            dp[1][p] = dp[0][p-a] > 0;
        }
    }
    int noneed = 0;
