        int a = A[i];
        if(a>=K)continue;
        bool is_noneed = true;
        for(int k=K; k<L; k++){
            int b = k-a;
            if(dp[2][k] && b<K)is_noneed = false;
        }
        if(is_noneed){
            noneed++;
        }
    }
    return noneed;
}

