int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    a[i] = min(a[i], k);
  }
  sort(a.begin(), a.end());
  pref[0][0] = 1;
  for (int i = 0; i < n; i++) {
    pref[i + 1] = pref[i] | (pref[i] << a[i]);
  }
  suf[0][0] = 1;
  for (int i = 0; i < n; i++) {
    suf[i + 1] = suf[i] | (suf[i] << a[n - 1 - i]);
  }
  int low = 0, high = n;
  while (low < high) {
    int mid = (low + high) >> 1;
    int y = k - 1;
    bool has = false;
    if (pref[mid].count() > suf[n - 1 - mid].count()) {
      for (int x = 0; x <= k - 1; x++) {
        if (suf[n - 1 - mid][x]) {
          y = max(y, k - 1 - x);
          while (!pref[mid][y]) {
            --y;
          }
          if (x + y >= k - a[mid]) {
            has = true;
            break;
          }
        }
      }
    } else {
      for (int x = 0; x <= k - 1; x++) {
        if (pref[mid][x]) {
          y = max(y, k - 1 - x);
          while (!suf[n - 1 - mid][y]) {
            --y;
          }
          if (x + y >= k - a[mid]) {
            has = true;
            break;
          }
        }
      }
    }
    if (!has) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  cout << low << '\n';
  return 0;
}

