                dp1[i + 1][j + a[i]] = dp1[i + 1][j + a[i]] | dp1[i][j];
            }
            if(j + b[i] < k){
                dp2[i + 1][j + b[i]] = dp2[i + 1][j + b[i]] | dp2[i][j];
            }
        }
    }
    rep(i, n + 1){
        REP(j, 1, k){
            dp1[i][j] += dp1[i][j - 1];
            dp2[i][j] += dp2[i][j - 1];
        }
    }

    int ans = 0;
    rep(i, n){
        if(a[i] >= k){
            continue;
        }
        bool flag = false;
        flag |= (dp1[i][0] > 0 && dp2[n - i - 1][k - 1] - dp2[n - i - 1][k - a[i] - 1] > 0);
        flag |= (dp2[n - i - 1][0] > 0 && dp1[i][k - 1] - dp1[i][k - a[i] - 1] > 0);
        REP(j, 1, k - a[i]){
            flag |= (dp1[i][j] - dp1[i][j - 1] > 0 && dp2[n - i - 1][k - j - 1] - dp2[n - i - 1][k - a[i] - j - 1] > 0);
            flag |= (dp2[n - i - 1][j] - dp2[n - i - 1][j - 1] > 0 && dp1[i][k - j - 1] - dp1[i][k - a[i] - j - 1] > 0);
        }
        REP(j, k - a[i], k){
            flag |= (dp1[i][j] - dp1[i][j - 1] > 1 && dp2[n - i - 1][k - j - 1] > 0);
            flag |= (dp2[n - i - 1][j] - dp2[n - i - 1][j - 1] > 0 && dp1[i][k - j - 1] > 0);
        }
        ans += !flag;
    }

    cout << ans << endl;

    return 0;
}

