                if(k-A[j]<0)continue;
                dp[j][k] = (dp[j-1][k]||dp[j-1][k-A[j]]);
                //cout<<j<<" "<<k<<" "<<dp[j][k]<<endl;
            }
        }
        int res=0;
        for(int j=0;j<N-1;++j){
            for(int k=K-a[i];k<K;++k){
                if(dp[j][k])res=1;
            }
        }
        //cout<<res<<endl;
        ans+=res;
        A.insert(A.begin()+i,a[i]);
    }
    cout<<N-ans<<endl;
}

