    prefix[0][0] = suffix[N][0] = 1;

    for (int i = 0; i < N; i++)
        prefix[i + 1] = prefix[i] | prefix[i] << A[i];

    for (int i = N - 1; i >= 0; i--)
        suffix[i] = suffix[i + 1] | suffix[i + 1] << A[i];

    int unnecessary = 0;

    for (int i = 0; i < N; i++) {
        bool necessary = false;

        for (int left = 0; left < K; left++)
            if (prefix[i][left]) {
                int low = max(K - A[i] - left, 0);
                int high = K - left;

                bitset<K_MAX> low_bitset;
                low_bitset.set();
                low_bitset >>= K_MAX - (high - low);

                if ((suffix[i + 1] >> low & low_bitset).any()) {
                    necessary = true;
                    break;
                }
            }

        if (!necessary)
            unnecessary++;
    }

