		fill(dp, dp + K, false); dp[0] = true;
		for (int j = 0; j < N; j++) {
			if (i == j) continue;
			for (int k = K; k >= 0; k--) {
				if (dp[k - a[j]]) dp[k] = true;
			}
		}
		bool flag = false;
		for (int j = K - a[i]; j < K; j++) {
			if (dp[j]) flag = true;
		}
		if (!flag) ret++;
	}
	cout << ret << endl;
	return 0;
}

