bool f(const vector<int> &A, int index, int K) {
	unordered_set<int> dp[2];
	dp[0].insert(0);
	int cur = 0;
	int tar = 1;
	for (int i = 0; i < A.size(); ++i) if (i != index) {
		dp[tar] = dp[cur];
		for (auto &a : dp[cur]) {
			dp[tar].insert(a + A[i]);
			if (K - A[index] <= a + A[i] and a + A[i] <= K - 1) {
				return true;
			}
		}
		swap(cur, tar);
	}
	return false;
}

void solve() {
	int N, K; cin >> N >> K;
	vector<int> A(N); for (auto &a : A) cin >> a;
	sort(A.begin(), A.end());
	int low = 0;
	int high = N;
	while (high - low > 1) {
		int mid = (high + low) / 2;
		if (f(A, mid, K)) high = mid;
		else low = mid;
	}
	cout << high << endl;
}

