bool cond(int x){
	if(a[x] >= k) return true;

	// dp[a][b] : a-1番目(0-index)までのカードで総和dができるか。ただしカードxは使わない。
	bool dp[n+1][k+1];
	rep(i,n+1) rep(j,k+1) dp[i][j] = false;
	dp[0][0] = true;

	rep(i,n){
		rep(j,k+1){
			if(i == x){
				dp[i+1][j] = dp[i][j] || dp[i+1][j];
			} 
			else{
				if(j-a[i] < 0) dp[i+1][j] = dp[i][j] || dp[i+1][j];
				else dp[i+1][j] = dp[i][j] || dp[i][j-a[i]] || dp[i+1][j];
			}	
 		}
	}

	FOR(i,k-a[x],k){
		if(dp[n][i]) return true;
	}
	return false;
}

