inline bool unnecessary(int x)
{
	if(a[x]>=k)return false;
	memset(dp,0,sizeof(dp));
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<=k;j++)
		{
			if(!i)
			{
				if(i!=x)dp[i][j]=(j==a[i]);
				else if(j)dp[i][j]=false;
				else dp[i][j]=true;
			}
			else if(j>=a[i] && i!=x)dp[i][j]=(dp[i-1][j]||dp[i-1][j-a[i]]);
			else dp[i][j]=dp[i-1][j];
		}
	}
    for(int i=k-a[x];i<k;i++)if(dp[n-1][i])return false;
	return true;
}
