            if(k-A[j]<0)dp[j][k] = dp[j-1][k];
            else dp[j][k] = (dp[j-1][k]||dp[j-1][k-A[j]]);
        }
    }
    for(int k=max(0ll,K-a[i]);k<=K;++k){
        if(dp[n-1][k])res=1;
    }
    A.insert(A.begin()+i,a[i]);
    if(res)return true;
    else return false;
}

