int N, K, A[5050];
//-----------------------------------------------------------------------------------
int L[5050][5050], R[5050][5050];
int RR[5050][5050];
void pre() {
	L[0][0] = 1;
	rep(i, 0, N) rep(j, 0, K) if (L[i][j]) {
		L[i + 1][j] = 1;
		if (j + A[i] < K) L[i + 1][j + A[i]] = 1;
	}

	R[N + 1][0] = 1;
	rrep(i, N, 1) rep(j, 0, K) if (R[i + 1][j]) {
		R[i][j] = 1;
		if (j + A[i - 1] < K) R[i][j + A[i - 1]] = 1;
	}

	rep(i, 0, N + 2) {
		RR[i][0] = R[i][0];
		rep(j, 1, K) RR[i][j] = RR[i][j - 1] + R[i][j];
	}

	/*rep(i, 0, N + 1) {
	rep(j, 0, 30) printf("%d ", L[i][j]);
	printf("\n");
	}

	printf("\n");

	rrep(i, N+1, 1) {
	rep(j, 0, 30) printf("%d ", R[i][j]);
	printf("\n");
	}*/
}
//-----------------------------------------------------------------------------------
int main() {
	cin >> N >> K;
	rep(i, 0, N) scanf("%d", &A[i]);
	sort(A, A + N);

	pre();

	int ans = 0;
	rep(i, 0, N) {
		if (K <= A[i]) continue;

		bool ok = true;

		/* // Naive
		rep(j, 0, K) rep(k, 0, K) if (L[i][j] && R[i + 2][k]) {
			if (K <= j + k + A[i] && j + k < K) ok = false;
		} */

		// Optimized
		rep(j, 0, K) if (L[i][j]) {
			int lo = max(K - j - A[i], 0);
			int hi = min(K - 1, K - j - 1);

			int sm = RR[i + 2][hi];
			if (0 < lo) sm -= RR[i + 2][lo - 1];
			if (sm != 0) ok = false;
		}

		if (ok) ans++;
	}

	cout << ans << endl;
}

