using namespace utils;

bool jdg(const int x){
	static int sum[N];
	sum[0]=1;
	for(int i=1; i<=q; ++i){
		sum[i]=sum[i-1]+suf[x+1][i];
	}
	for(int i=1; i<q; ++i){
		if(pre[x-1][i]&&sum[q-1-i]-(i>=q-val[x]?0:sum[q-val[x]-i-1])) return 1;
	}
	return sum[q]-sum[q-val[x]];
}

int main(){
	n=nxi(),q=nxi();
	for(int i=1; i<=n; ++i){
		val[i]=std::min(q+1,nxi());
	}
	pre[0][0]=1;
	for(int i=1; i<=n; ++i){
		pre[i]=pre[i-1]|pre[i-1]<<val[i];
	}
	suf[n+1][0]=1;
	for(int i=n; i>=1; --i){
		suf[i]=suf[i+1]|suf[i+1]<<val[i];
	}
	int ans=0;
	for(int i=1; i<=n; ++i){
		ans+=val[i]>=q?0:!jdg(i);
	}
