using namespace std;
typedef long long ll;

const ll MOD = 1e9 + 7;
const ll INF = 1e17;

ll n, k, a[5010], dp[5010][5010], ti, ret;;

void solve(ll pos, ll sum){
	//cout<<pos<<" "<<sum<<endl;
	if(sum<k&&sum>=k-a[ti]){
		ret=1;
		return;
	}
	if(sum>k||pos>n)
		return;
	if(dp[pos][sum]!=-1)
		return;
	if(sum<k&&sum>=k-a[ti]){
		ret=1;
		return;
	}
	dp[pos][sum]=1;
	solve(pos+1, sum);
	if(pos!=ti)
		solve(pos+1, sum+a[pos]);
}

ll is_necessary(ll x){
	ti=x;
	ret=0;
	solve(1, 0);
	return ret;
}

int main()
{
	cin>>n>>k;
	for(int i=1; i<=n; i++)
		cin>>a[i];
	sort(a+1, a+n+1);
	ll l=1, r=n;
	for(int i=0; i<=n+5; i++)
			for(int j=0; j<=k+5; j++)
				dp[i][j]=-1;
	while(l<r-1){
		ll mid = (l+r)/2;
		if(is_necessary(mid)){
			r=mid-1;
		//	cout<<mid<<" nec\n";
		}
		else{
			l=mid+1;
		//	cout<<mid<<" not\n";
		}

		for(int i=0; i<=n+5; i++)
			for(int j=0; j<=k+5; j++)
				dp[i][j]=-1;
	}
	if(!(is_necessary(l+1)))
		l+=1;
	for(int i=0; i<=n+5; i++)
			for(int j=0; j<=k+5; j++)
				dp[i][j]=-1;
	if(is_necessary(l))
		l--;
	//cout<<l<<" "<<r<<endl;
	cout<<l;
	return 0;
}

