int N, K;
bool dp[5010][5010];
vector<int> a(5010);
bool need(int idx, vector<int> & v) {
  for(int i=0;i<K;i++) {
    dp[0][i] = false;
  }
  dp[0][0] = true;

  for(int i=1;i<N;i++) {
    for(int j=0;j<K;j++) {
      if(j-v[i] < 0)
        dp[i][j] = dp[i-1][j];
      else
        dp[i][j] = dp[i-1][j] || dp[i-1][j-v[i]];
    }
  }
  for(int i=K-a[idx];i<K;i++) {
    if(dp[N-1][i])
      return true;
  }
  return false;
}
int main() {
  int ans=0;
  cin >> N >> K;
  for(int i=0;i<N;i++) {
    cin >> a[i];
    if(a[i] >= K){
      N--;
      i--;
    }
  }

  for(int i=0;i<N;i++) {
    vector<int> acopy;
    acopy.push_back(-1);
    for(int j=0;j<N;j++) if(i!=j) acopy.push_back(a[j]); 
    if(!need(i, acopy))
      ans++;
  }

  cout << ans << endl;
}

