    {
        for (int x = 10000; x >= 0; x--)
        {
            if(dp_left[i][x]) dp_left[i+1][x] = true;
            if(dp_left[i][x] && x+A[i]<=10000) dp_left[i+1][x+A[i]] = true;
        }
    }

    for (int i = N; i > 0; i--)
    {
        for (int x = 10000; x >= 0; x--)
        {
            if(dp_right[i][x]) dp_right[i-1][x] = true;
            if(dp_right[i][x] && x+A[i]<=10000) dp_right[i-1][x+A[i-1]] = true;
