            }
        }

        for(long long i = 1; i <= n; i++)
        {
            long long r = n, sum = 0;
            for(long long j = n; j > 0; j--)
            {
                if(r > j)
                {
                    r = j;
                    sum = 0;
                }
                while((r > j) || (r > 0 && sum < k))
                {
                    sum += ar[r];
                    r--;
                }

                if(i <= j && j > r && sum >= k)
                    if(sum - ar[i] < k)
                        u[i] = 1;
                //cout << j << " " << r << endl;
                sum -= ar[j];
            }
        }

        long long ans = 0;
        for(long long i = 1; i <= n; i++)
            ans += u[i];

        cout << n - ans;
    }
    return 0;//
}

