int main() {
	cin >> N >> K;
	for (int i = 0; i < N; i++)
		cin >> A[i];
	sort(A, A+N);
	int n = 0;
	for (; n < N; n++) {
		if (A[n] >= K) break;
	}
	N = n;
	dp[0][0] = 1;
	for (int i = 0; i < N; i++) {
		int cur = i%2, tar = cur^1;
		memset(dp[tar], 0, sizeof(dp[tar]));
		for (int j = K; j >= 0; j--) {
			(dp[tar][j] += dp[cur][j]) %= MOD;
			if (j+A[i] > K) continue;
			(dp[tar][j+A[i]] += dp[cur][j]) %= MOD;
		}
	}
	int ans = 0;
	for (int i = 0; i < N; i++) {
		int cur = N%2, tar = cur^1;
		memset(dp[tar], 0, sizeof(dp[tar]));
		for (int j = 0; j <= K; j++) {
			dp[tar][j] = dp[cur][j];
		}
		for (int j = 0; j <= K; j++) {
			if (j+A[i] <= K) {
				(dp[tar][j+A[i]] += MOD - dp[tar][j]) %= MOD;
			}
		}
		bool need = false;
		for (int j = K-A[i]; j < K; j++) {
			need |= dp[tar][j] > 0;
		}
		if (!need) ++ans;
	}
	cout << ans << endl;
	return 0;
}

