int bubble_sort(vector<long int> &vec, int N)
{

    long int i, j, temp;

    for (i = 0; i < N - 1; i++) {
        for (j = N - 1; j > i; j--) {
            if (vec[j - 1] > vec[j]) {
                temp = vec[j];
                vec[j] = vec[j - 1];
                vec[j - 1]= temp;
            }
        }
    }
  return 0;
}


