bool judge(int c){
    for(int i = 0; i <= N; i++){
        memset(dp[i], false, K+1);
        dp[i][0] = true;
    }
    for(int i = 0; i < N; i++){

        for(int j = 0; j <= K; j++){
            dp[i+1][j] = dp[i][j];
        }
        if(i != c){
            for(int j = 0; j <= K; j++){
                if(dp[i][j]){
                    if(j+a[i] < K-a[c]) dp[i+1][j+a[i]] = true;
                    else if(j+a[i] < K) return false;
                }
            }
        }
    }
    return true;
}

