const int mod = 1000000000 + 7;

int ar[5002];
int br[5002];
int N;
int K;
ll dp[5002];
int cnt;

void runDP()
{
	dp[0] = 1;
	cnt = 0;

	for(int i = 0; i < N; i++)
	{
		if(ar[i] >= K)
		{
			cnt++;
			continue;
		}
		for(int j = K - ar[i]; j >= 0; j--)
		{
			if(dp[j])
			{
				dp[j + ar[i]] = (dp[j + ar[i]] + dp[j]) % mod;
			}
		}
	}

	for(int i = 0; i < N; i++)
	{
		if(ar[i] >= K)
		{
			break;
		}
		for(int j = 1; j < K; j++)
		{
			if(dp[j])
			{
				if(j + ar[i] >= K)
				{
					int x = j - ar[i];
					if(x < 0)
					{
						cnt++;
						break;
					}
					if(dp[x] != dp[j])
					{
						cnt++;
						break;
					}
				}
			}
		}
	}
}

int main()
{
	//freopen("0.in", "r", stdin);

	scanf("%d %d", &N, &K);

	ll sum = 0;

	for(int i = 0; i < N; i++)
	{
		scanf("%d", &ar[i]);
		sum = sum + ar[i];
	}

	sort(ar, ar + N);

	if(sum < K)
	{
		cout<<N<<endl;
		return 0;
	}

	cnt = 0;
	runDP();

	cout<<N - cnt<<endl;


	return 0;
}

