int N, K;
int a[11000];
bool dp1[5100][5100];
bool dp2[5100][5100];
int sum[5100][5100];

int main() {
  while (cin >> N >> K) {
	for (int i = 0; i < N; ++i) cin >> a[i];
	memset(dp1, 0, sizeof(dp1));
	memset(dp2, 0, sizeof(dp2));

	dp1[0][0] = true;
	dp2[N][0] = true;
	for (int i = 0; i < N; ++i) {
	  for (int w = 0; w <= K; ++w) {
		if (!dp1[i][w]) continue;
		dp1[i+1][w] = true;
		if (w + a[i] <= K) dp1[i+1][w+a[i]] = true;
	  }
	}
	for (int i = N; i > 0; --i) {
	  for (int w = 0; w <= K; ++w) {
		if (!dp2[i][w]) continue;
		dp2[i-1][w] = true;
		if (w + a[i-1] <= K) dp2[i-1][w+a[i-1]] = true;
	  }
	}

	for (int i = 0; i <= N; ++i) {
	  sum[i][0] = 0;
	  for (int j = 0; j <= K; ++j) {
		sum[i][j+1] = sum[i][j] + (dp2[i][j] ? 1 : 0);
	  }
	}

	int res = 0;
	for (int i = 0; i < N; ++i) {
	  bool need = false;
	  for (int w = 0; w <= K; ++w) {
		if (!dp1[i][w]) continue;
		int left = max(0, K - a[i] - w);
		int right = max(0, K - w);

		//cout << i << ", " << w << ";; " << left << ", " << right << ": " << sum[i+1][right] << ", " <<  sum[i+1][left] << endl;

		if (sum[i+1][right] - sum[i+1][left] >= 1) need = true;
	  }
	  if (!need) ++res;
	}

	cout << res << endl;
  }
}

