int a[5005], n, k, go[5005];
bool nece[5005];

void dfs(int cur, int sum, int used) {
    if (sum >= k) {
        for (int i = 0; i < used; i++) nece[go[i]] = true;
        return ;
    }
    if (cur == n) return ;
    go[used] = cur;
    dfs(cur + 1, sum + a[cur], used + 1);
    dfs(cur + 1, sum, used);
}

int main() {
    scanf("%d%d", &n, &k);
