using namespace std;

typedef long long int ll;

const int MAXN = 6000;

int N, K;
int a[MAXN];
bool dp[MAXN][MAXN];

bool check(int p) {
    for (int j = 0; j <= K; ++j) {
        dp[0][j] = false;
    }

    for (int i = 0; i < N; ++i) {
        if (i != p) {
            for (int j = 0; j < K; ++j) {
                if (j == a[i]) {
                    dp[i][j] = true;
                } else if (i) {
                    dp[i][j] = dp[i-1][j];
                    if (j > a[i]) {
                        dp[i][j] = dp[i][j] || dp[i-1][j-a[i]];
                    }
                } else {
                    dp[i][j] = false;
                }

                if (K - a[p] <= j && dp[i][j]) {
                    return true;
                }
            }
        }
    }

    return false;
}

int main() {
    scanf("%d %d", &N, &K);

    ll sum = 0;
    for (int i = 0; i < N; ++i) {
        scanf("%d", &a[i]);
        sum += a[i];
    }

    sort(a, a + N);

    int lb = 0, rb, md;
    for (rb = 0; rb < N && a[rb] < K; ++rb) {}
    while (lb < rb) {
        md = (lb + rb) / 2;

        if (check(md)) {
            rb = md;
        } else {
            lb = md + 1;
        }
    }

    printf("%d", lb);

    return 0;
}

