signed main() {
	INIT;
	VAR(int, n, k);
	VEC(int, a, n);
	int sum = std::accumulate(ALL(a), 0);
	if (sum < k) {
		OUT(n)BR;
		return 0;
	}

	a.emplace_back(0);
	std::sort(ALL(a));
	++n;
	std::function<bool(int)> check = [&](int p) {
		if (p == n) return true;
		if (a[p] >= k) return true;
		std::vector<std::vector<bool>> dp(n + 1, std::vector<bool>(k, false));
		dp[0][0] = true;
		REP(i, n) {
			REP(j, k) dp[i + 1][j] = dp[i][j];
			if (i == p) continue;
			REP(j, k) {
				if (!dp[i][j]) continue;
				if (j + a[i] < k) {
					dp[i + 1][j + a[i]] = dp[i][j];
				}
			}
		}
		FOR(i, k - a[p], k) {
			if (dp[n][i]) return true;
		}
		return false;
	};
	int t = bisection(0, n - 1, check);
	t = std::max(0LL, t - 3);
	while (!check(t)) ++t;
