			if (dp[i][j]) {
				if (dpR[N-i-1][K-j-1] > dpR[N-i-1][max(0, K - A[i]-j-1)]) {
					ans++;
					break;
				}
			}
		}
	}
	cout << N - ans <<  endl;
	return 0;
}

