int main() {
	cin >> N >> K;
	REP(i, 1, N + 1) {
		cin >> card[i];
	}
	sort(card + 1, card + N + 1);
	int l = 1, r = N, m;
	while (l <= r) {
		m = (l + r) >> 1;
		if (card[m] > K) {
			r = m - 1;
			continue;
		}
		memset(dp, 0, sizeof dp);
		REP(i, 1, N + 1) {
			REP(j, 0, i) {
				if (i == m || dp[j] + card[i] > K) {
					dp[i] = max(dp[i], dp[j]);
				} else {
					dp[i] = max(dp[i], dp[j] + card[i]);
				}
			}
		}
		REP(i, 1, N + 1) {
			if (K - card[m] <= dp[i] && dp[i] < K) {
				r = m - 1;
				goto next;
			}
		}
		l = m + 1;
		next:
		continue;
	}
	cout << r << '\n';
	return 0;
