const int max_N = 5005;

int N, K;
int ar[max_N];
int memo_l[max_N][max_N] = {}, memo_r[max_N][max_N] = {};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> N >> K;
    for (int i = 1; i <= N; ++i) {
        cin >> ar[i];
        ar[i] = min(ar[i], K);
    }

    for (int k = 0; k <= K; ++k) for (int n = 0; n <= N; ++n) {
        if (k == 0) memo_l[n][k] = 1;
        else if (n == 0) memo_l[n][k] = 0;
        else {
            memo_l[n][k] = memo_l[n-1][k];
            if (ar[n] <= k) memo_l[n][k] = max(memo_l[n][k], memo_l[n-1][k-ar[n]]);
        }
    }

    for (int k = 0; k <= K; ++k) for (int n = N+1; n >= 1; --n) {
        if (k == 0) memo_r[n][k] = 1;
        else if (n == N+1) memo_r[n][k] = 0;
        else {
            memo_r[n][k] = memo_r[n+1][k];
            if (ar[n] <= k) memo_r[n][k] = max(memo_r[n][k], memo_r[n+1][k-ar[n]]);
        }
    }

    for (int n = 1; n <= N+1; ++n) for (int k = 1; k <= K; ++k)
        memo_r[n][k] += memo_r[n][k-1];

    int ans = 0;
    for (int n = 1; n <= N; ++n) {
        int flag = 1;
        for (int k = 0; k < K; ++k) {
            if (memo_l[n-1][k] && (k+ar[n] >= K || memo_r[n+1][K-k-1] != memo_r[n+1][K-k-1-ar[n]])) {
                flag = 0;
            }
        }
        ans += flag;
    }

    cout << ans << endl;

    return 0;
}

