bool isGood(int mid) {
    if (a[mid] >= k) return true;

    f.reset();
    f[0] = 1;

    FOR(i,1,n) if (i != mid)
        f = f | (f << a[i]);

    FOR(i,k-a[mid],k-1)
        if (f[i] == 1) return true;
    return false;
}

