int main() {
    int n, k; cin >> n >> k;
    int a[n]; for (int i = 0; i < n; i++) cin >> a[i];
    L[0][0] = true; if (a[0] < k) L[0][a[0]] = true;
    R[n-1][0] = true; if (a[n-1] < k) R[n-1][a[n-1]] = true;
    for (int i = 1; i < n-1; i++) {
        L[i][0] = true;
        for (int s = 1; s < k; s++)
            L[i][s] = L[i-1][s] || s >= a[i] && L[i-1][s-a[i]];
    }
    for (int i = n-2; i > 0; i--) {
        R[i][0] = true;
        for (int s = 1; s < k; s++) 
            R[i][s] = R[i+1][s] || s >= a[i] && R[i+1][s-a[i]];
    }
    int ans = 0;
    int v = max(0, k - a[0]);
    while (v < k) { if (R[1][v]) break; v++; }
    if (v == k) ans++;
    v = max(0, k - a[n-1]);
    while (v < k) { if (L[n-2][v]) break; v++; }
    if (v == k) ans++;
    for (int i = 1; i < n-1; i++) {
        v = k - a[i];
        int ls = 0, rs = k-1;
        while (rs >= 0 && !R[i+1][rs]) rs--;
        bool found = false;
        while (ls < k && rs >= 0) {
            if (v <= ls + rs && ls + rs < k) { found = true; break; }
            if (v >= ls + rs) do ls++; while (ls < k && !L[i-1][ls]);
            else do rs--;  while (rs >= 0 && !R[i+1][rs]);
        }
        if (!found) ans++;
    }
    cout << ans << endl;
}

