bool solve(vector<int>V, int p) {
	for (int i = 0; i <= V.size(); i++) { for (int j = 0; j <= 3 * K; j++)dp2[i][j] = false; }
	dp2[0][0] = true;
	for (int i = 0; i < V.size(); i++) {
		for (int j = 0; j <= 3 * K - V[i]; j++) {
			if (dp2[i][j] == false)continue;
			dp2[i + 1][j] = true;
			dp2[i + 1][j + V[i]] = true;
		}
	}
	for (int i = max(0, K - p); i < K; i++) {
		if (dp2[V.size()][i] == true)return false;
	}
	return true;
}
