    pref[0][0] = 1;
    suff[n+1][0] = 1;
    for(int i=1;i<=n;i++){
        for(int j=0;j<=k;j++){
            if(pref[i-1][j]){
                pref[i][min(k, j+a[i])] = 1;
                pref[i][j] = 1;
            }
        }
    }
    for(int i=n;i>=1;i--){
        for(int j=0;j<=k;j++){
            if(suff[i+1][j]){
                suff[i][min(k, j+a[i])] = 1;
                suff[i][j] = 1;
            }
        }
    }
    for(int i=1;i<=n+1;i++){
        sum[i][0] = suff[i][0];
        for(int j=1;j<=k;j++){
            sum[i][j] = sum[i][j-1] + suff[i][j];
        }
    }

    int ans = 0;
    for(int i=1;i<=n;i++){
        bool ok = 1;
        for(int j=0;j<=k-1;j++){
