                    break;
                }
                int l = k-(j+a[i]);
                int r = k-j-1;
                if(l <= r && sum[i+1][r] - sum[i+1][l-1] > 0) ok = 0;
            }
        }
        for(int j=max(0, k-a[i]);j<=k-1;j++){
            if(pref[i-1][j]) ok = 0;
            if(suff[i+1][j]) ok = 0;
        }
        ans += ok;
    }
    printf("%d\n", ans);
}

