signed main() {
	int a, b; scanf("%d%d", &a, &b);
	int sum = 0;//個数
	for (int d = 0; d < a; d++) {
		int e; scanf("%d", &e);
		if (e<b) {
			c[sum] = e;
			sum++;
		}
	}
	sort(c, c + sum);
	int s = 0, g = sum;//[s,g) ぎりぎり必要なカード
	while (g - s > 1) {
		int d = (s + g) / 2;
		memset(dp, false, sizeof(dp));
		dp[0] = true;
		for (int e = 0; e < sum; e++) {
			if (d == e)continue;
			for (int f = b; f >= c[e]; f--) {
				if (dp[f - c[e]])dp[f] = true;
			}
		}
		bool K = false;
		for (int i = b - c[d]; i < b; i++) {
			if (dp[i])K = true;
		}
		if (!K) {//不必要
			s = d;
		}
		else {
			g = d;
		}
	}
	printf("%d\n", g);
}

