bool isNec(int pos, int n, int k)
{
    fill(poss, poss + k, false);
    poss[0] = true;
    for (int i = 0; i < n; i++)
    {
        if (i == pos)
            continue;
        for (int j = k - 1; j >= 0; j--)
        {
            if (poss[j] && j + a[i] <= k - 1)
                poss[j + a[i]] = true;
        }
    }
    for (int i = k - a[pos]; i < k; i++)
    {
        if (poss[i])
            return true;
    }
    return false;
}

