        if (L[i][j])
        {
            L[i+1][j] = true;
            if (j+a[i]<K)
                L[i+1][j+a[i]] = true;
        }
    }
    vector<vector<bool>> R(N, vector<bool>(K));
    R[N-1][0] = true;
    for (int i=N-1; i>0; i--)
    {
        for (int j=0; j<K; j++)
        if (R[i][j])
        {
            R[i-1][j] = true;
            if (j+a[i]<K)
                R[i-1][j+a[i]] = true;
        }
    }

    int ans = 0;
    for (int i=0; i<N; i++)
    {
        bool ok = true;

        if (a[i]>=K)
        {
            ok = false;
        }
        else
        {
            int c = 0;
            for (int j=K-1; j>=K-a[i]; j--)
                if (R[i][j])
                    c++;
            if (c>0)
                ok = false;
            for (int j=1; j<K-1; j++)
            {
                if (R[i][K-j])
                    c--;
                if (K-a[i]-j>=0 && R[i][K-a[i]-j])
                    c++;
                if (L[i][j] && c>0)
                    ok = false;
            }
        }
        if (ok)
            //cout<<a[i]<<endl,
            ans++;
    }

    cout<<ans<<endl;
}

