bool isNoNeed(const vector<int>& a, int K, int x) {
  int N = a.size();
  vector<int> b(a);
  b.erase(b.begin() + x);
  vector<vector<ll>> dp(N, vector<ll>(K + 1, 0));
  dp[0][0] = 1;
  REP(i,N - 1)REP(j,K + 1) {
    dp[i + 1][j] += dp[i][j];
    dp[i + 1][min(j + b[i], K)] += dp[i][j];
  }
  for(int i = K - a[x]; i < K; ++i) {
    if(dp[N - 1][i]) return false;
  }
  return true;
}

int main(){
  int N, K;
  cin >> N >> K;
  vector<int> a(N);
  REP(i,N) cin >> a[i];
  sort(ALL(a));

  if(!isNoNeed(a, K, 0)) {
    cout << 0 << endl;
  }else {
    int lb = 0, ub = N;
    while(ub - lb > 1) {
      int mid = (lb + ub) / 2;
      if(!isNoNeed(a, K, mid)) ub = mid;
      else lb = mid;
    }
    cout << lb + 1 << endl;
  }
  return 0;
}

