  rep(i, N) {
    rep(j, K + 1) {
      if (!L[i][j])
        continue;

      L[i + 1][j] = true;
      if (j + a[i] <= K)
        L[i + 1][j + a[i]] = true;
    }
  }

  vector<vector<bool>> R(N + 1, vector<bool>(K + 1, false));
  R[N][0] = true;
  repr(i, N, 1) {
    rep(j, K + 1) {
      if (!R[i][j])
        continue;

      R[i - 1][j] = true;
      if (j + a[i - 1] <= K)
        R[i - 1][j + a[i - 1]] = true;
    }
  }

  int ans = 0;
  rep(i, N) {
    vector<int> l, r;
    repp(j, 0, K) {
      if (L[i][j])
        l.pb(j);
      if (R[i + 1][j])
