bool check(int p) {
    for (int j = 0; j <= K; ++j) {
        dp[0][j] = false;
    }

    for (int i = 0; i < N; ++i) {
        if (i != p) {
            for (int j = 0; j <= K; ++j) {
                if (j == a[i]) {
                    dp[i][j] = true;
                } else if (i) {
                    dp[i][j] = dp[i-1][j];
                    if (j > a[i]) {
                        dp[i][j] = dp[i][j] || dp[i-1][j-a[i]];
                    }
                } else {
                    dp[i][j] = false;
                }
            }
        }
    }

    for (int i = K - a[p]; i < K; ++i) {
        if (dp[N-1][i]) {
            return true;
        }
    }
    return false;
}

