    scanf("%d %d", &N, &K);

    for (int i = 0; i < N; ++i) {
        scanf("%d", &a[i]);
    }

    sort(a, a + N);

    int lb = 0, rb, md;
    for (rb = 0; rb < N && a[rb] < K; ++rb) {}
    while (lb < rb) {
        md = (lb + rb) / 2;

        if (check(md)) {
            rb = md;
        } else {
            lb = md + 1;
        }
    }

    printf("%d", lb);

