/* monkukui 競技プログラミング用のテンプレート (ここまで)*/

bool C(vector<lint> &a, lint k, lint id) {
  // カード a[id] が必要かどうか (必要なら true)
  // a[id] が必要 <=> a[id] 以外で部分和 x (k - a[i] <= x < k) が作れるか

  lint n = a.size();
  vector<vector<lint>> dp(n + 1, vector<lint> (k + 1, false));
  dp[0][0] = 1;
  for(int i = 0; i < n; i++) {
    for(int j = 0; j <= k; j++) {
      if(dp[i][j] == 0) continue;

      // 取らない
      dp[i + 1][j] = 1;

      if(i == id) continue;
      lint nj = j + a[i];
      if(nj > k) continue;
      dp[i + 1][nj] = 1;
    }
  }

  bool ret = false;
  for(int x = max(0LL, k - a[id]); x < k; x++) {
    if(dp[n][x]) ret = true;
  }

  return ret;
}

int main(){

  int n, k; cin >> n >> k;
  vector<lint> a(n);
  for(int i = 0; i < n; i++) cin >> a[i];

  sort(ALL(a));

  // 区間 [0, lb] が不必要
  lint lb = -1;
  lint ub = n;

  while(ub - lb > 1) {
    lint mid = (ub + lb) / 2;

    if(!C(a, k, mid)) { // もしa[lb] が不必要なら
      lb = mid;
    } else {
      ub = mid;
    }
  }

  cout << (lb + 1) << endl;
  return 0;
}

