const ll MOD = 1000000007;

bool check(ll min,ll max,ll ignore,ll index,std::vector<ll>& a){
    if(index==0){
        if(ignore==0){
            return (min==0)&&(max==0);
        }else{
            return (min<=a[0])&&(a[0]<max);
        }
    }else{
        if(index==ignore){
            return check(min,max,ignore,index-1,a);
        }else{
            return check(min,max,ignore,index-1,a)||check(min-a[index],max-a[index],ignore,index-1,a);
        }
    }
}

bool isNeed(ll index,ll key,std::vector<ll>& a){
    return check(key-a[index],key,index,a.size()-1,a);
}

