bool solve(int x,int r)
{
	if(pr[x]<r)return false;
	bool ff=false;
	for(int i=x;i>=1;i--)
	{
		if(a[i]>=r)
		{
			if(!f[i])
			{
				f[i]=true;
			}
			return true;
		}
		else
		{
			if(solve(i-1,r-a[i]))
			{
				ff=true;
				f[i]=true;
			}
		}
	}
	return ff;
}
