int const N = 5e3 + 41;
int const K = 1e4 + 41;

bool pr[N][K];
short sf[N][K];
vector<int> a;
int n, k;

void solve(){
	scanf("%d %d",&n,&k);
	fi(0, n){
		int v;
		scanf("%d",&v);
		if(v >= k) continue;
		a.pb(v);
	}
	n = sz(a);

	pr[0][0] = 1;
	fi(1, n + 1){
		fj(0, K){
			if(pr[i-1][j]) pr[i][min(j + a[i-1], K - 1)] = true;
		}
	}

	sf[n+1][0] = 1;
	for(int i=n;i>=1;--i){
		for(int j=0;j<K;++j){
			if(sf[i+1][j]) sf[i][min(j + a[i-1], K-1)] = 1;
		}
		for(int j=K-2;j>0;--j){
			if(sf[i][j]) sf[i][j] = j;
			else sf[i][j] = sf[i][j+1];
		}
	}

	int ans = 0;
	int sum;
	fi(1, n+1){
		bool f = false;
		fj(0, K){
			if(pr[i][j]){
				sum = j + a[i-1];
				if(sum >= k){
					if(j < k){
						f = true;
						break;
					}
				}else{
					sum = j + sf[i+1][(k - j - a[i-1])];
					if(sum < k){
						f = true;
						break;
					}
				}
			}
		}
		if(f) ++ans;
	}
	printf("%d\n",ans);
}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();


	return 0;
}

