				if (to > k) to = k;
				dpr[i][to] = 1;
			}
		}
	}

	FOE(i, 1, n + 1) {
		ps[i][0] = dpr[i][0];
		FOE(j, 1, k) ps[i][j] = ps[i][j - 1] + dpr[i][j];
	}

	FOE(i, 1, n) {
		bool flag = 0;

		FOR(j, 0, k) if (dpl[i - 1][j]) {
