typedef bitset<N> bit;
int n, k, A[N], ans;

bit Add(bit b, int l, int r) {
	for (int i = l; i < r; i++) b |= (b << A[i]);
	return b;
}
void Build(int l, int r, bit b) {
	if (r - l < 2) {
		bool flag = false;
		for (int i = k - A[l]; i < k; i++) flag |= b[i];
		ans += !flag;
		return;
	}
	int md = (l + r) / 2;
	bit b1 = Add(b, l, md);
	bit b2 = Add(b, md, r);
	Build(l, md, b2);
	Build(md, r, b1);
}

