ll dp[5010][5100];

ll dfs(int idx, ll sum) {
    if(sum >= k) {
        return sum;
    }
    if(idx >= n) {
        return 0;
    }
    if(dp[idx][sum] != -1) {
        return dp[idx][sum];
    }

    ll min = 1e18;
    auto r = dfs(idx + 1, sum + a[idx]);

    if(r != 0) {
        if(r - a[idx] < k) {
            stat[idx] = true;
        }
        min = std::min(min, r);
    }
    dfs(idx + 1, sum);

    if(min == 1e18) {
        return dp[idx][sum] = 0;
    }
    return dp[idx][sum] = min;
}

