void calc() {
  for(int i=0;i<K;i++) {
    dp[0][i] = 0;
  }
  dp[0][0] = 1;

  for(int i=0;i<K;i++) {
    dp2[0][i] = 0;
  }
  dp2[0][0] = 1;

  for(int i=1;i<=N;i++) {
    for(int j=0;j<=K;j++) {
      if(j-a[i] >= 0)
        dp[i][j] |= dp[i-1][j-a[i]];
      dp[i][j] |= dp[i-1][j];
    }
  }

  for(int i=1;i<=N;i++) {
    for(int j=0;j<=K;j++) {
      if(j-a[N-i+1] >= 0)
        dp2[i][j] |= dp2[i-1][j-a[N-i+1]];
      dp2[i][j] |= dp2[i-1][j];
    }
  }
}
