typedef long long ll;

using namespace std;

int N, K;
const int MAX_N = 5000;
const int MAX_K = 5000;
vector<int> a(MAX_N);

int solve() {
    int ans = 0;
    sort(a.begin(),a.begin() + N);
    int accum[MAX_N + 1];
    accum[0] = a[0];
    REP(i,1,N){
        if(a[i] > K) break;
        accum[i] = accum[i-1] + a[i];
    }
    int L = -1;
    REP(i,0,N){
        eprintf("accum:%d\n",accum[i]);
        eprintf("a:%d\n",a[i]);
    }
    eprintf("K=%d\n",K);
    RREP(i,N-1,-1){
        eprintf("ai=%d,i=%d\n",a[i],i);
        if(a[i] > K) continue;
        else if(L == -1){
            L = a[i];
            eprintf("%d\n",i);
        }else{
            eprintf("%d\n",i);
        }

        if(max(L,accum[i+1]) > K - a[i]) continue;
        ans++;
    }
    eprintf("L:%d\n",L);
    return ans;
}

int main() {
    // to shorten execution time for iostream
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K;
    REP(i,0,N){
        cin >> a[i];
    }
    cout << solve() << "\n";
    return 0;
}

