typedef long long ll;

int const N = 200 * 1000 + 16;
int const M = 1000 * 1000 * 1000 + 7;
int const inf = 1000 * 1000 * 1000;

typedef pair<int,int> type;

int n, k;
int a[5120];

typedef pair<ll, int> ty;

int f(int i) {
  ll mn = 1e18;
  priority_queue<ty, vector<ty>, greater<ty>> q;

  q.push(make_pair(ll(a[i]), 0));

  while(q.size()) {
    auto cur = q.top(); q.pop();

    ll x = cur.first;
    int idx = cur.second;

    if(x >= k) {
      mn = min(mn, x);
      continue;
    }

    if(idx == n)
      continue;

    if(idx == i) {
      q.push(make_pair(x, idx+1));
      continue;
    }

    q.push(make_pair(x, idx+1));
    q.push(make_pair(x+a[idx], idx+1));
  }

  return (mn-a[i] >= k);
}

int main() {
  cin.tie(0);
  cin.sync_with_stdio(0);

  cin >> n >> k;

  for(int i = 0; i < n; ++i)
    cin >> a[i];

  sort(a, a+n);

  int cnt = 0;
  for(int i = 0; i < n; ++i)
    cnt += f(i);

  cout << cnt << endl;
}

