using ll = long long;

int main() {
    int N, K;
    cin >> N >> K;

    const int MAXN = 5010;

    static ll a[MAXN];

    REP (i, N) {
        cin >> a[i];
    }
    sort(a, a + N);

    int M = 0;
    REP (i, N) {
        if (a[i] < K) M++;
    }
    int nes = N - M;    // 必要なもの

    static int dp[5010][10010];
    const int INF = (1 << 28);

    REP (i, 5010) REP (j, 10010) dp[i][j] = INF;
    dp[0][0] = 1;
    REP (i, M) {
        REP (j, 2 * K) {
            dp[i + 1][j] = dp[i][j];
            if (j - a[i] >= 0) {
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j - a[i]]);
            }
        }
    }

    REP (i, 2 * K) {
        dp[M][i] = (i >= K and dp[M][i] < INF ? i : INF);
    }

    RREP (i, M) {
        int x = INF;
        REP (j, K) {
            if (dp[i][j] >= INF) continue;
            x = min(x, dp[i + 1][j + a[i]]);
        }
        if (x - a[i] < K) nes++;

        REP (j, 2 * K) {
            dp[i][j] = dp[i + 1][j];
            if (j + a[i] < 2 * K) {
                dp[i][j] = min(dp[i][j], dp[i + 1][j + a[i]]);
            }
        }
    }

    cout << N - nes << endl;

    return 0;
}

