        scanf("%d", &v[i]);
    }
    bool Ans[N];

    for (int m = 0; m < N; ++m) {
        std::vector <int> vv(N);
        std::copy(v.begin(), v.end(), vv.begin());
        vv.erase(vv.begin() + m);

        std::vector<std::vector<bool>> ok;
    ok.resize(N - 1);
        for (int n = 0; n < N - 1; ++n) {
            ok[n].resize(K);
        }
    for (int l = 0; l < K; ++l) {
        if(vv[0] == l)
            ok[0][l] = true;
        else
            ok[0][l] = false;
    }
        for (int j = 1; j < N - 1; ++j) {
        for (int k = 0; k < K; ++k) {
            if (k >= vv[j]) {
                ok[j][k] = ok[j - 1][k] || ok[j - 1][k - vv[j]];
            } else {
                if (ok[j - 1][k])
                    ok[j][k] = true;
                else
                    ok[j][k] = false;
            }
        }
    }
        if(v[m] > K)
            Ans[m] = true;
        else {
            for (int i = K - v[m]; i < K; ++i) {
                if (ok[N - 2][i])
                    Ans[m] = true;
            }
        }
