#define N 5005
int n,k,a[N];

bool dp(int t){
    int b[n];int iii=0;
    for(int i=0;i<=n-2;i++){
        if(iii==t)iii++;
        b[i]=a[iii];
        iii++;
    }
    bool d[k];
    d[0]=true;
    for(int i=1;i<=k-1;i++)d[i]=false;
    for(int i=0;i<=n-2;i++){
        for(int j=k-1;j>=0;j--){
            if(d[j]==true&&j+b[i]<=k-1)d[j+b[i]]=true;
        }
    }
    bool flag=true;
    for(int i=k-a[t];i<=k-1;i++){
        if(d[i]==true)flag=false;
    }
    if(a[t]>=k)flag=false;
    return flag;/*true=1は不要という意味*/
}

int main() {
    cin>>n>>k;for(int i=0;i<=n-1;i++)cin>>a[i];
    sort(a,a+n);
    int left=0,right=n,mid=0,ans=-100;
    while(left<right){
        mid=(left+right)/2;
        if(dp(mid)==true)
            if(dp(mid+1)==false){
                left=right=mid;
                ans=mid;
            }else{
                left=mid+1;
        }else{
            right=mid;
        }
    }
    if(ans==-100)ans=left-1;
    printf("%d",ans+1);
    return 0;
}

