using namespace std;

int a[5000];
int dp1[5001][5001];
int dp2[5001][5001];

int main() {
    int n, k, ans, i, j;

    scanf("%d %d", &n, &k);

    for (i = 0; i < n; i++) scanf("%d", &a[i]);

    dp1[0][0] = 1;

    for (i = 0; i < n; i++) {
        for (j = 0; j <= k; j++) {
            if (dp1[i][j] == 0) continue;

            dp1[i + 1][j] = 1;
            dp1[i + 1][min(j + a[i], k)] = 1;
        }
    }

    for (i = 0; i <= n; i++) {
        for (j = 1; j <= k; j++) dp1[i][j] += dp1[i][j - 1];
    }

    dp2[n][0] = 1;

    for (i = n; i > 0; i--) {
        for (j = 0; j <= k; j++) {
            if (dp2[i][j] == 0) continue;

            dp2[i - 1][j] = 1;
            dp2[i - 1][min(j + a[i - 1], k)] = 1;
        }
    }

    for (i = 0; i <= n; i++) {
        for (j = 1; j <= k; j++) dp2[i][j] += dp2[i][j - 1];
    }

    ans = n;

    for (i = 0; i < n; i++) {
        if (a[i] >= k) {
            ans--;

            continue;
        }

        for (j = 0; j < k; j++) {
            if (j > 0 && dp1[i][j] == dp1[i][j - 1]) continue;

            if (j >= k - a[i]) {
                ans--;

                break;
            }

            if (dp2[i + 1][k - j - 1] - dp2[i + 1][k - j - a[i] - 1] > 0) {
                ans--;

                break;
            }
        }
    }

    printf("%d\n", ans);

    return 0;
}

