	for (int i = 1; i <= N; i++) {
		for (int j = K; j >= 0; j--) {
			if (dp[i - 1][j]) {
				dp[i][j] = 1;
				dp[i][min(j + a[i - 1], K)] = 1;
			}
		}
	}
	for (int i = 1; i <= N; i++) {
		for (int j = K; j >= 0; j--) {
			if (rdp[i - 1][j]) {
				rdp[i][j] = 1;
				rdp[i][min(j + a[N - i], K)] = 1;
			}
		}
	}
	for (int i = 0; i <= N; i++) {
		for (int j = 1; j <= K; j++) {
			rdp[i][j] += rdp[i][j - 1];
		}
	}
