int solve(){
    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    REP(i, N)cin >> A[i];

    int L = 10*K+1;
    vector<vector<int> > dp(2, vector<int>(L));
    dp[0][0] = 1;
    REP(i, N){
        int a = A[i];
        for(int p = L-1; p>=a; p--){
            dp[1][p] += dp[0][p-a] + dp[1][p-a];
            if(dp[1][p]>10)dp[1][p]=10;
        }
    }
    int noneed = 0;
    REP(i, N){
        int a = A[i];
        if(a>=K)continue;
        bool is_noneed = true;
        for(int k=K; k<L; k++){
            int b = k-a;
            if(dp[1][k] && 0<=b && b<K)is_noneed = false;
        }
        if(is_noneed){
            noneed++;
        }
    }
    return noneed;
}

