ll N, K;
ll a[5050];

bool judge(ll x) {
	// 不必要ならtrue, 必要ならfalse
	ll const bs_size = 5050;
	bitset<bs_size> bs;
	bs.set(0);
	repi(i, 0, N) {
		if (i == x) continue;
		bitset<bs_size> temp;
		temp |= bs;
		bs <<= a[i];
		bs |= temp;
	}
	repi(i, max(K - a[x], 0LL), K) {
		if (bs[i]) return false;
	}
	return true;
}

ll solv() {
	// 不必要な枚数を返す
	if (judge(0) == false) {
		return 0;
	}
	if (judge(N - 1) == true) {
		return N;
	}
	ll left = 0, right = N - 1;
	ll next = -1, prev = -1;
	while (1) {
		next = (left + right) / 2;
		if (prev == next) {
			return next + 1;
		}
		if (judge(next)) left = next;
		else right = next;
		prev = next;
	}
}

