using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    REP(i, N) cin >> a[i];

    unordered_map<int, cpp_int> d;
    d[0] = 1;
    for (int x: a) {
        RFOR(i, 1, K) {
            if (i >= x) {
                d[i] += d[i - x];
            }
        }
    }

    int need = 0;
    for (int x: a) {
        if (x >= K) {
            ++need;
        } else {
            FOR(s, K - x, K) {
                if (d[s] > 0) {
                    cpp_int alt_sum = 0;
                    int i = s;
                    bool plus = true;
                    while (i >= 0) {
                        if (plus) {
                            alt_sum += d[i];
                        } else {
                            alt_sum -= d[i];
                        }
                        i -= x;
                        plus ^= 1;
                    }
                    if (alt_sum > 0) {
                        ++need;
                        break;
                    }
                }
            }
        }
    }
    int no_need = N - need;
    cout << no_need << endl;
    return 0;
}

