using namespace std;

int ar[5002];
int N;
int K;
bool dp[5002];

void runDP()
{
	for(int i = 0; i <= K; i++)
	{
		dp[i] = false;
	}
	dp[0] = true;

	for(int i = N - 2; i >= 0; i--)
	{
		if(ar[i] >= K)
		{
			continue;
		}
		for(int j = K - ar[i]; j >= 0; j--)
		{
			if(dp[j])
			{
				if(j + ar[N - 1] >= K)
				{
					return;
				}
				dp[j + ar[i]] = true;

				if(j + ar[i] < K && j + ar[i] + ar[N - 1] >= K)
				{
					return;
				}
			}
		}
	}
}

int main()
{


	scanf("%d %d", &N, &K);

	ll sum = 0;

	for(int i = 0; i < N; i++)
	{
		scanf("%d", &ar[i]);
		sum = sum + ar[i];
	}

	sort(ar, ar + N);

	if(sum < K)
	{
		cout<<N<<endl;
		return 0;
	}

	int cnt = 0;

	for(int i = 0; i < N; i++)
	{
		if(ar[i] >= K)
		{
			cnt++;
			continue;
		}
		swap(ar[i], ar[N - 1]);
		runDP();
		swap(ar[i], ar[N - 1]);

		for(int j = 1; j < K; j++)
		{
			if(dp[j])
			{
				if(j + ar[i] >= K)
				{
					//cout<<ar[i]<<" is necessary"<<endl;
					cnt++;
					break;
				}
			}
		}
	}
	cout<<N - cnt<<endl;

	return 0;
}

