bool is_needed(vl& v, int n, int k, int i)
{
    bool dp[8128] = {true};

    REP(j, n){
        if (i == j) continue;
        RREP(l, k - v[j] + 1){
            if (dp[l]){
                dp[l + v[j]] = true;
                if (k <= l + v[j] + v[i]) return true;
            }
        }
    }
    // DEBUG(v[i]);
    return false;
}

signed main()
{
    int n = in(), k = in();
