    REP(i, n) v[i] = inl();
    SORT(v);

    if (accumulate(ALL(v), 0LL) < k){
        print(n);
        return 0;
    }

    int cnt = 0;
    REP(i, n) cnt += is_needed(v, n, k, i);
    print(n - cnt);

    return 0;
}

