bool needed(int N, int K, int* a, int c) {
  if (c >= N) return true;
  bool dp[N][K+1];
  REP(i, N) REP(j, K+1) dp[i][j] = false;

  REP(i, N) {
    dp[i][0] = true;
    for(int j = 1;j <= K;j++) {
      if (i != c && j == a[i]) dp[i][j] = true;
      else if (i != 0) {
	if (dp[i-1][j]) dp[i][j] = true;
	if (i != c && j >= a[i] && dp[i-1][j-a[i]]) dp[i][j] = true;
      }
    }
  }

  for (int i = max(K - a[c], 0);i < K;i++) {
    if (dp[N-1][i]) return true;
  }
  return false;
}


int bs(int N, int K, int* a) {
  int u = N, l = 0;
  while(u != l) {
    int c = (u + l) / 2;
    if (needed(N, K, a, c)) u = c - 1;
    else l = c;
    if (u - l <= 3) break;
  }
  for (int i = l;i <= u;i++) {
    if (needed(N, K, a, i)) return i;
  }
  return u + 1;
}


