bool can_sum(int sum, int i, int id) {
    if(id < 0 || sum < 0) return false;
    if(id < i && dp[id][sum]) return true;
    if(id < i) return false;
    if(id == i) return can_sum(sum, i, id - 1);
    if(can_sum(sum, i, id - 1)) return true;
    if(can_sum(sum - a[id], i, id - 1)) return true;
    return false;
}

