int dpl[5005][5005];
int dpr[5005][5005];
int A[5005];
int rs, n, k;

int solve(){
  cin>>n>>k;
  for(int i=1; i<=n; ++i)
    cin>>A[i];

  dpl[0][0]=1;
  for(int i=1; i<=n; ++i){
    dpl[i][0] = 1;
    for(int j=0; j<k; ++j) 
    {
      dpl[i][j] |= dpl[i-1][j];
      if(j + A[i] < k)
        dpl[i][j+A[i]] |= dpl[i-1][j];
    }
  }

  dpr[n+1][0]=1;
  for(int i=n; i>=1; --i){
    dpr[i][0] = 1;
    for(int j=0; j<k; ++j) 
    {
      dpr[i][j] |= dpr[i+1][j];
      if(j + A[i] < k)
        dpr[i][j+A[i]] |= dpr[i+1][j];
    }
  }
  for(int i=n; i>=1; --i){
    for(int j=0; j<k; ++j) 
    {
      if(j >= 1)
      dpr[i][j] += dpr[i][j-1];
    }
  }
  rs = n;

  for(int i=1; i<=n; ++i){
    bool qh = 0;
    for(int j=0; j<k; ++j){
      if(dpl[i-1][j]) {
        if(k-j-1>=0){
          int q = dpr[i+1][k-j-1];
          if(k-A[i]-j-1 >= 0){
            q -= dpr[i+1][k-A[i]-j-1];
          }
          if(q > 0){
            qh = 1;
          }
        }
      }
    } 

    rs-=qh;
  }
  cout<<rs<<"\n";
  return 0;
}

int main()
{
	cout<<setprecision(6)<<fixed;
	ios_base::sync_with_stdio(0);
	cin.tie(0);

  solve();

	return 0;
}

