// Begin FFT Library

typedef complex<double> CD;
const double PI = 4 * atan(1);

const int LOG = 14;
const int S = 1 << LOG;

CD w[S]; int rev[S];

void initFFT() {
    for (int i = 0; i < S; i++) w[i] = CD(cos(2 * PI * i / S), sin(2 * PI * i / S));

    rev[0] = 0;

    for (int mask = 1; mask < S; mask++) {
        int k = 0;
        while(((mask >> k) & 1) == 0) k++;
        rev[mask] = rev[mask ^ (1 << k)] ^ (1 << (LOG - 1 - k));
    }
}

CD F[2][S];

void FFT(CD* A, int k) {
    int L = 1 << k;
    for (int i = 0; i < L; i++) F[0][rev[i] >> (LOG - k)] = A[i];

    int t = 0, nt = 1;
    for (int lvl = 0; lvl < k; lvl++) {
        int len = 1 << lvl;
        for (int st = 0; st < L; st += (len << 1)) {
            for (int i = 0; i < len; i++) {
                CD ad = F[t][st + len + i] * w[i << (LOG - 1 - lvl)];
                F[nt][st + i] = F[t][st + i] + ad;
                F[nt][st + len + i] = F[t][st + i] - ad;
            }
        }
        swap(t, nt);
    }

    for (int i = 0; i < L; i++) A[i] = F[t][i];
}

// End FFT Library

CD x[S], y[S];

const int MAXN = 5050;
LL a[MAXN];

const int MAXK = 5050;
int prefix[MAXN][MAXK], suffix[MAXN][MAXK];

int n, k;

int main() {
    GI(n); GI(k);

    FOR1(i, n) GLL(a[i]);

    memset(prefix, 0, sizeof prefix); prefix[0][0] = 1;

    FOR1(i, n) FORN(j, MAXK) {
        prefix[i][j] = prefix[i-1][j];
        if (j - a[i] >= 0 && prefix[i-1][j - a[i]]) prefix[i][j] = 1;
    }

    memset(suffix, 0, sizeof suffix); suffix[n+1][0] = 1;

    for (int i = n; i >= 1; i--) FORN(j, MAXK) {
        suffix[i][j] = suffix[i+1][j];
        if (j - a[i] >= 0 && suffix[i+1][j - a[i]]) suffix[i][j] = 1;
    }

    initFFT();

    int res = 0;

    FOR1(i, n) {
        FORN(j, S) {
            if (j < MAXK) x[j] = prefix[i-1][j];
            else x[j] = 0;

            if (j < MAXK) y[j] = suffix[i+1][j];
            else y[j] = 0;
        }

        FFT(x, LOG);
        FFT(y, LOG);
        FORN(j, S) x[j] *= y[j];
        FFT(x, LOG);
        reverse(x+1, x+S);

        bool ok = true;

        for (int j = max(0LL, k - a[i]); j <= k-1; j++) {
            if ((int)round(x[j].real() / S) == 1) {
                ok = false;
                break;
            }
        }

        res += ok;
    }

    cout << res << "\n";

    return 0;
}

