int main() {
  ios_base::sync_with_stdio(false);

  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }

  auto get_dp = [&]() {
    vector<vector<bool>> dp(n + 1, vector<bool>(k));
    dp[0][0] = true;
    for (int i = 0; i < n; i++) {
      if (a[i] < k) {
        dp[i + 1][a[i]] = true;
      }
      dp[i + 1] = dp[i];
      for (int j = a[i]; j < k; j++) {
        dp[i + 1][j] = dp[i + 1][j] || dp[i][j - a[i]];
      }
    }
    return dp;
  };

  auto pref = get_dp();
  reverse(a.begin(), a.end());
  auto suff = get_dp();
  reverse(a.begin(), a.end());
  vector<vector<int>> suff_sum(n + 1, vector<int>(k + 1));
  for (int i = 0; i <= n; i++) {
    for (int j = 0; j < k; j++) {
      suff_sum[i][j + 1] = suff_sum[i][j] + suff[i][j];
    }
  }

  debug(pref);
  int num = 0, l, r;
  for (int i = 0; i < n; i++) {
    if (a[i] >= k) {
      num++;
      continue;
    }
    // [L, R] = [k - a[i], k - 1]
    for (int j = 0; j < k; j++) {
      if (pref[i][j] == false) continue;
      l = k - a[i] - j;
      r = k - 1 - j;
      l = max(l, 0);
      if (r < 0) break;
      if (suff_sum[n - 1 - i][r + 1] - suff_sum[n - 1 - i][l] > 0) {
        num++;
        break;
      }
    }
  }

  cout << n - num << '\n';

  return 0;
}

