bool check(int remove) {
	memset(dp, 0, sizeof(dp));
	for (int i = 1; i <= N; i++) {
		for (int j = 0; j < i; j++) {
			if (i == remove || dp[j] + a[i] >= K) {
				dp[i] = max(dp[i], dp[j]);
			} else {
				dp[i] = max(dp[i], dp[j] + a[i]);
			}
		}
	}
	for (int i = 1; i <= N; i++) {
		if (dp[i] >= K - a[remove] && dp[i] < K) {
			return false;
		}
	}
	return true;
}

