int lower_bound(int i0, int i1, V v, F f) {
    while (i0 != i1) {
        int i = (i0 + i1) / 2;
        if (f(i) < v) {
            i0 = i + 1;
        } else {
            i1 = i;
        }
    }
    return i0;
