bool can[maxn];

inline bool need(int x)
{
	if(x>=k) return 1;

	MC(can);
	can[0]=1;

	int skip;
	rep(i,n) if(a[i]==x) {skip=i;break;}
	rep(i,n) if(i!=skip) repd(j,k) if(can[j]&&j+a[i]<k) can[j+a[i]]=1;

	rep(i,k) if(can[i]&&i+x>=k) return 1;
	return 0;
}

int main()
{
	rep(i,n) a[i]=Read();
	sort(a,a+n);

	int l=-1,r=n;
	while(l+1<r)
	{
		int m=l+(r-l)/2;
//		cerr<<l<<' '<<r<<' '<<m<<' '<<need(a[m])<<endl;
		if(need(a[m])) r=m; else l=m;
	}

	Write(r);

	return 0;
}
