int dp[5010][5010];
template<typename A, size_t N, typename T>
void Fill(A (&array)[N], const T &val){
    std::fill( (T*)array, (T*)(array+N), val );
}
int main(){
	int n,x,mid,s,k;
	cin>>n>>k;
	for(int i=0;i<n;i++){
		cin>>x;
		if(x<k)a.push_back(x);
	}
	sort(a.begin(),a.end());
	s=a.size();
	int left=-1,right=s;
	while(right-left>1){
		v.clear();
		Fill(dp,-1);
		mid = (left+right)/2;
		for(int i=0;i<s;i++){
			if(i!=mid)v.push_back(a[i]);
		}
		for(int i=s-1;i>=0;i--){
			for(int j=0;j<=k-1;j++){
				if(j<v[i]){
					dp[i][j]=dp[i+1][j];
				}else{
					dp[i][j] = max(dp[i+1][j],dp[i+1][j-v[i]]+v[i]);
				}
			}
		}
		if(dp[0][k-1]>=k-a[mid]){right=mid;}else{left=mid;}
	}
	cout<<right<<endl;
	return 0;
}

