bool C( int idx )
{
  clr( dp, false );

  dp[0][0] = true;
  rep( i, N ) rep( k, K+1 )
  {
    dp[i+1][k] |= dp[i][k];

    if( k-a[i] >= 0 && i != idx )
      dp[i+1][k] |= dp[i][k-a[i]];
  }

  for( int k = std::max( K-a[idx], 0 ); k < K; ++k ) if( dp[N][k] )
    return true;

  return false;
}

int main()
{
  scanf( "%d%d", &N, &K );
