const int M = 10001;

bitset<M> f(bitset<M> &x, bitset<M> &y)
{
	bitset<M> z;
	for (int i = 0; i < M; ++i)
	{
		if (x[i])
		{
			z |= (y << i);
		}
	}
	return z;
}

inline ANDREIKKAA_RETURN_TYPE mainFunction(ANDREIKKAA_PARAMETERS)
{
	int n, k;
	cin >> n >> k;
	vector<bitset<M>> suf(n + 1);

	vector<int> a(n);
	cin >> a;

	suf[n][0] = 1;
	for (int i = n - 1; i >= 0; --i)
	{
		suf[i] = suf[i + 1] | (suf[i + 1] << a[i]);
		if (a[i] <= M)
		{
			suf[i] |= (suf[i + 1] << a[i]);
		}
	}

	bitset<M> now;
	now[0] = 1;
	int ans = 0;
	for (int i = 0; i < n; ++i)
	{
		auto x = f(now, suf[i + 1]);
		if (a[i] < k)
		{
			for (int j = k; j < M; ++j)
			{
				if (x[j])
				{
					++ans;
					break;
				}
			}
		}


		if (a[i] <= M)
		{
			now |= (now << a[i]);
		}
	}
	cout << ans << endl;
}

