      for(int k = 0; k < K; k++)  dp[j][k] = 0;
    }
    int result = 1;
    if(a[i] >= K) result = 0;
    dp[0][0] = 1;
    if(i != 0) {
      dp[0][a[0]] = 1;
      if(a[0] >= K - a[i] && a[0] < K) result = 0;
    }
    for(int j = 1; j < N; j++){
      if (result == 0)  break;
      for(int k = 0; k < K; k++){
        if(i != j && (k-a[j] >= 0 && dp[j-1][k-a[j]] == 1)){
           dp[j][k] = 1;
           if(k >= K - a[i] && k < K){
             result = 0;
             //j = N; k = K;
             break;
           }
         }
        else if(dp[j-1][k] == 1)  dp[j][k] = 1;
      }
    }
    res += result;
    //if(result == 1) cout << a[i] << endl;
  }
  cout << res << endl;

  return 0;
}

