vector<ll> a;
int n, K;
bool judge(int x)
{
    if(K-a[x] <= 0) return true;
    vector<vector<bool>> dp(5010, vector<bool>(5010));
    dp[0][0] = true;
    for(int i = 1; i <= n; i++)
    {
        for(int j = 0; j <= K; j++)
        {
            if(i == x)
            {
                dp[i][j] = dp[i][j] || dp[i-1][j];
            }
            else
            {
                dp[i][j] = dp[i][j] || dp[i-1][j];
                if(dp[i-1][j] && j + a[i] <= K)
                {
                    dp[i][j+a[i]] = true;
                }
            }
        }
    }
    bool flag = false;
    for(int i = K-a[x]; i <= K - 1; i++)
    {
        if(dp[n][i])
        {
            flag = true;
        }
    }
    return flag;
}
int main()
{
    cin >> n >> K;
    a.push_back(0);
    for(int i = 0; i < n; i++)
    {
        ll b;
        cin >> b;
        a.push_back(b);
    }
    sort(a.begin(), a.end());
    int lb = 0;
    int ub = n+1;
    while(ub - lb > 1)
    {
        int mid = (lb+ub) / 2;
        if(judge(mid))
        {
            ub = mid;
        }
        else
        {
            lb = mid;
        }
    }
    cout << lb << endl;
}

