			dp[i + 1][j] = dp[i][j];
			rdp[N - i - 1][j] = rdp[N - i][j];
			if (j - a[i] >= 0) {
				dp[i + 1][j] |= dp[i][j - a[i]];
			}
			if (j - a[N - i - 1] >= 0) {
				rdp[N - i - 1][j] |= rdp[N - i][j - a[N - i - 1]];
			}
		}
	}
	for(int i = 0; i <= N; ++i) {
		for(int j = 1; j <= K; ++j) {
			rdp[i][j] += rdp[i][j - 1];
		}
		for(int j = K + 1; j > 0; --j) {
			rdp[i][j] = rdp[i][j - 1];
		}
		rdp[i][0] = 0;
	}
	int cnt = 0;
	for(int i = 0; i < N; ++i) {
		bool f = false;
