bool check(const vector<int>& a, int ignore, int M){
	if(a[ignore] >= M) return true;
	vector<int> reach(M-a[ignore], 0);
	reach[0] = 1;
	for(int i=0;i<a.size();i++){
		if(i == ignore) continue;
		for(int j=reach.size()-1;j>=0;j--){
			if(!reach[j]) continue;
			int nxt = j + a[i];
			if(M - a[ignore] <= nxt && nxt < M) return true;
			if(nxt < reach.size()) reach[nxt] = 1;
		}
	}
	return false;
}

int main(){
