#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int N = 5001;

bitset<N> pref[N], suf[N];

int fen[N][N];

void add(int v, int pos) {
    for (; pos < N; pos |= pos + 1) {
       ++fen[v][pos];
    }
}

int get(int v, int pos) {
    int s = 0;
    for (; pos >= 0; pos = (pos & (pos + 1)) - 1) {
        s += fen[v][pos];
    }
    return s;
}

int get(int v, int l, int r) {
    return get(v, r) - get(v, l - 1);
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        a[i] = min(a[i], N);
    }
    pref[0].set(0);
    for (int i = 0; i < n - 1; ++i) {
        pref[i + 1] = (pref[i] << a[i]) | pref[i];
    }
    suf[n - 1].set(0);
    for (int i = n - 1; i > 0; --i) {
        suf[i - 1] = (suf[i] << a[i]) | suf[i];
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < k; ++j) {
            if (suf[i][j]) {
                add(i, j);
            }
        }
    }
    int ans = n;
    for (int i = 0; i < n; ++i) {
        bool f = false;
        for (int j = 0; j < k; ++j) {
            if (pref[i][j] && get(i, k - a[i] - j, k - j - 1)) {
                f = true;
                break;
            }
        }
        if (f) {
            --ans;
        }
    }
    cout << ans;
    return 0;
}

