#define REP(i,n) for(int i=0;i<(int)(n);i++)
#define ALL(x) (x).begin(), (x).end()

typedef long long ll;
typedef long double ld;

const int INF = 1e9;
const ld EPS = 1e-8;

bool isNoNeed(const vector<int>& a, int K, int x) {
  //cout << x << endl;
  int N = a.size();
  vector<int> b(a);
  b.erase(b.begin() + x);
  vector<vector<ll>> dp(N, vector<ll>(K + 1, 0));
  dp[0][0] = 1;
  REP(i,N - 1)REP(j,K + 1) {
    dp[i + 1][j] += dp[i][j];
    dp[i + 1][min(j + b[i], K)] += dp[i][j];
  }
  for(int i = K - a[x]; i < K; ++i) {
    if(dp[N - 1][i]) return false;
  }
  return true;
}

int main(){
  int N, K;
  cin >> N >> K;
  vector<int> a(N);
  REP(i,N) cin >> a[i];
  sort(ALL(a));

  int res = 0;
  if(isNoNeed(a, K, N - 1)) {
    res = N;
  }else {
    for(int p = 1<<30; p; p >>= 1) {
      if(res + p <= N && isNoNeed(a, K, res + p)) res += p;
    }
    ++res;
  }
  cout << res << endl;
  return 0;
}

