const int N = 5010;

int n, K, a[N];
bool c[N];

bool f(int p) {
    for (int i = 0; i <= K; i++) {
        c[i] = false;
    }
    c[0] = true;
    for (int i = 0; i < n; i++) {
        if (i != p) {
            for (int j = K; j >= a[i]; j--) {
                c[j] |= c[j - a[i]];
            }
        }
        for (int j = 0; j < K; j++) {
            if (c[j] && j + a[p] >= K) {
                return true;
            }
        }
    }
    return false;
}

int main() {

    scanf("%d %d", &n, &K);

    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        a[i] = min(a[i], K);
    }

    sort(a, a + n);

    int l = 0;
    int r = n - 1;

    while (l <= r) {
        int m = (l + r) / 2;
        if (f(m)) {
            r = m - 1;
        } else {
            l = m + 1;
        }
    }

    printf("%d\n", l);

    return 0;

}

