typedef std::pair<std::int64_t, std::int64_t> int64pair;

bool check(std::vector<int>const& vec, std::size_t index, std::size_t K, std::size_t N)
{
	std::vector<int> memo(K);
	for (std::size_t i : boost::irange<std::size_t>(0, N))
	{
		if (i == index)
		{
			continue;
		}
		if (vec[i] + vec[index] >= K)
		{
			return true;
		}
		for (std::size_t n = K - vec[i] - 1; n >= K - vec[i] - vec[index]; --n)
		{
			if (memo[n])
			{
				return true;
			}
		}
		for (std::size_t n = K - vec[i] - vec[index] - 1; n > 0; --n)
		{
			memo[n + vec[i]] |= memo[n];
		}
		memo[vec[i]] = true;
	}
	return false;
}

