bool isok(int idx) {
	if (sa[idx] >= k)return false;
	memset(dp, 0, sizeof(dp));
	dp[idx][0] = true;
	FOR(i, idx, n) {
		REP(j, k + 1) {
			if (dp[i][j] == false)continue;
			dp[i + 1][j] = true;
			if (j + a[i] <= k)dp[i + 1][j + a[i]] = true;
		}
	}
	FOR(i, k - sa[idx], k) {
		if (dp[n][i])return false;
	}
	return true;
}

