template <typename T>
class SegmentTreeSum
{
private:
    int m_n;
    vector<T> m_dat;
public:
    SegmentTreeSum(int n) {
        m_n = 1;
        while (m_n < n) m_n *= 2;
        m_dat.resize(2 * m_n - 1, 0);
    }
    // k番目に値valを加算
    void update(int k, T val) {
        k += m_n - 1;
        m_dat[k] += val;
        while (k > 0) {
            k = (k - 1) / 2;
            m_dat[k] = m_dat[k * 2 + 1] + m_dat[k * 2 + 2];
        }
    }
    // [a, b)の範囲で合計を返す
    T query(int a, int b) {
        return queryInternal(a, b, 0, 0, m_n);
    }

private:
    T queryInternal(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b) return m_dat[k];
        else {
            T vl = queryInternal(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = queryInternal(a, b, k * 2 + 2, (l + r) / 2, r);
            return vl + vr;
        }
    }
};

bool is_i_needed(ll N, ll K, vector<ll>& As, int i) {
    // 任意のカードの組み合わせで作成可能な数を列挙
    // ただしK未満
    set<int> possible;
    possible.insert(0);
    REP(j, N) {
        if (i == j) continue;
        auto a = As[j];
        set<int> added;
        for(auto v: possible) {
            if ((v + a) < K) {
                added.insert(v + a);
            }
        }
        for(auto v: added) possible.insert(v);
    }

    FOR(j, max(1LL, K - As[i]), K) {
        if (possible.count(j)) {
            return true;
        }
    }
    return false;
}


int main(void)
{
    cin.sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<ll> As(N);
    REP(n, N) cin >> As[n];

    int no_need = 0;
    REP(i, SIZE(As)) {
        no_need += !is_i_needed(N, K, As, i);
    }
    cout << no_need << endl;
    return 0;
}

