				dl[i + 1][k + a[i]] = 1;
			dl[i + 1][k] = max(dl[i + 1][k], dl[i][k]);
		}
	}
	dr[N][0] = 1;
	for (int i = N - 1; i >= 0; i--) {
		for (int k = K - 1; k >= 0; k--) {
			if (dr[i + 1][k] && k + a[i] <= K)
				dr[i][k + a[i]] = 1;
			dr[i][k] = max(dr[i][k], dr[i + 1][k]);
		}
	}
