	int p = 0, k = K;
	while (p + 1 < k)
	{
		int m = (p + k) / 2;

		// zobacz, czy m jest niezbedne - mozliwe, ze musisz troche poprawic
		// bo szukasz granicy, a nie wiesz, ktora wartosc wystepuje
		int wsk = m;
		FOR(i, m, K)
			if (ile[i])
			{
				wsk = i;
				break;
			}

		// wyrzuc ta wartosc
		ile[wsk]--;

		memset(dp, 0, K);

		dp[0] = 1;

		int mx = 0;
		FOR(j, 1, K)REP(k, ile[j])
		{
			FORD(v, mx + 1, 0)
				if (dp[v] && v + j < K)
					dp[v + j] = 1;

			mx = min(K, mx + j);
		}

		// dodaj z powrotem
		ile[wsk]++;

		bool ok = 0;
		FOR(v, K - wsk, K)
			if (dp[v])
			{
				ok = 1;
				break;
			}

		if (!ok)	//m nie jest niezbedne
			p = m;
		else
			k = m;
	}

	// policz wszystkie niezbedne wartosci
	FOR(i, k, K)
		res += ile[i];

	printf("%d\n", N - res);
	return 0;
}

