			if(a1[j]<k){
				int r=upper_bound(a2.begin(),a2.end(),k-1)-a2.begin();
				int l=lower_bound(a2.begin(),a2.end(),max(0,k-a[i]))-a2.begin();
				sum+=r-l;
				int t=upper_bound(a2.begin(),a2.end(),max(0,k-1-a1[j]))-a2.begin();
				int m=lower_bound(a2.begin(),a2.end(),max(0,k-a[i]-a1[j]))-a2.begin();
				sum+=t-m;
			}	
		}	
		if(sum==0)ans++;
	}	
	c(ans)
}

