int main() {
    int n, k;
    cin >> n >> k;
    vector<int> v(n);
    for (auto &&i : v) scanf("%d", &i);
    vector<bitset<5050>> dp(n+1), idp(n+1);
    dp[0].set(0);
    for (int i = 0; i < n; ++i) {
        dp[i+1] = dp[i] | (dp[i] << v[i]);
    }
    idp[n].set(0);
    for (int i = n-1; i >= 0; --i) {
        idp[i] = idp[i+1] | (idp[i+1] << v[i]);
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        int l = max(0, k-v[i]), r = k - 1;
        int c = 0;
        for (int j = l; j <= r; ++j) {
            c += idp[i+1][j];
        }
        bool need = false;
        for (int j = 0; j < k; ++j) {
            if(dp[i][j] && c > 0){
                need = true;
                break;
            }
            if (l > 0) {
                c += idp[i+1][--l];
            }

            if (r > 0){
                c -= idp[i+1][--r+1];
            }
        }
        if (not need) ++ans;
    }
    cout << ans << "\n";
    return 0;
}

