	auto check = [&](int i) {
		if (a[i] >= k) return true;
		std::set<int> set;
		bool in = false;
		REP(j, n) {
			if (i == j) continue;
			if (a[j] >= k) continue;
			if (k - a[i] <= a[j]) {
				in = true;
				break;
			}
			std::set<int> toset;
			toset.insert(a[j]);
			for (const auto& x : set) {
				if (a[j] + x >= k) continue;
				if (k - a[i] <= a[j] + x) {
					in = true;
					break;
				}
				toset.insert(a[j] + x);
			}
			if (in) break;
			for (const auto& x : toset) {
				set.insert(x);
			}
		}
		return in;
	};
	OUT(bisection(0, n-1, check))BR;
	return 0;
