ll bisection(ll low, ll high, std::function<bool(ll)> check) {
	if (high - low == 1) return low;
	ll mid = (high + low) / 2;
	if (!check(mid)) return bisection(mid, high, check);
	else             return bisection(low, mid, check);
}

signed main() {
	INIT;
	VAR(int, n, k);
	VEC(int, a, n);
	a.emplace_back(0);
	std::sort(ALL(a));
	++n;
	ll sum = 0;
	REP(i, n) {
		sum += a[i];
	}
	if (sum < k) {
		OUT(n-1)BR;
		return 0;
	}
	auto check = [&](int i) {
		if (a[i] >= k) return true;
		std::set<int> set;
		bool in = false;
		REP(j, n) {
			if (i == j) continue;
			if (a[j] >= k) continue;
			if (IN(k - a[i], a[j], k)) {
				in = true;
				break;
			}
			std::set<int> toset;
			toset.insert(std::min(a[j], k));
			for (const auto& x : set) {
				if (IN(k - a[i], a[j] + x, k)) {
					in = true;
					break;
				}
				if (a[j] + x >= k) continue;
				toset.insert(std::min(a[j] + x, k));
			}
			if (in) break;
			for (const auto& x : toset) {
				set.insert(x);
			}
		}
		return in;
	};
	OUT(bisection(0, n-1, check))BR;
	return 0;
}

