bool C(int mid, vector<int> v){
    if(mid >= n) return true;
    else if(mid < 0) return false;
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;

    rep(i,n){
        for(int j = k; j >= 0; j--){
            dp[i + 1][j] |= dp[i][j];
            if(i != mid) dp[i + 1][min(k, j + v[i])] |= dp[i][j];
        }
    }

    range(i,k - v[mid],k){
        if(dp[n][i]) return true;
    }
    return false;
}

