using namespace std;
int n,k;
int a[5005],dp[20][5005];
int ans;
void solve(int l,int r, int pos)
{
	if(l==r)
	{
		int tmp=0;
		for(int i=max(0,k-a[l]);i<k;i++)
		{
			tmp|=dp[pos][i];
		}
		ans+=1-tmp;
		return;
	}
	else
	{
		int mid=(l+r)/2;
		for(int i=0;i<k;i++)
		{
			dp[pos+1][i]=dp[pos][i];
		}
		for(int i=l;i<=mid;i++)
		{
			for(int j=k-1;j>=a[i];j--)
			{
				dp[pos+1][j]|=dp[pos+1][j-a[i]];
			}
		}
		solve(mid+1,r,pos+1);
		for(int i=0;i<k;i++)
		{
			dp[pos+1][i]=dp[pos][i];
		}
		for(int i=mid+1;i<=r;i++)
		{
			for(int j=k-1;j>=a[i];j--)
			{
				dp[pos+1][j]|=dp[pos+1][j-a[i]];
			}
		}
		solve(l,mid,pos+1);
	}
}
