                if(!(dp[i][j]=dp[i-1][j])
                    &&i!=mid&&j>=a[i])
                    dp[i][j]=dp[i-1][j-a[i]];
            }
        }

        if(C(a[mid]))
            ub=mid;
        else
            lb=mid;
    }

