set<ll> dp[5010];
vector<ll> buf;
int n,k;
vector<ll> as;

bool removable(int i)
{
    dp[i].insert(0);
    for(int j = 0; j < n;j++)
    {
        buf.clear();
        for(auto e : dp[i])
        {
            buf.push_back(e);
            if(i != j)
            {
                auto next = e + as[j];
                if(next < k - as[i])
                {
                    buf.push_back(e+as[j]);
                }
                else if(next >= k - as[i] && next < k)
                {
                    return false;
                }
            }
        }
        for(auto e : buf)
        {
            dp[i].insert(e);
        }
    }

    //for(auto e : dp[i]) cout << e << ",";
    //cout << endl;

    auto l = std::lower_bound(dp[i].begin(), dp[i].end(), k - as[i]);
    if(l == dp[i].end())
    {
        return true;
    }
    else if(*l >= k)
    {
        return true;
    }
    return false;
}

int main(){
    cin >> n >> k;
    as.resize(n);
    for(int i = 0;i < n;i++)
    {
        cin >> as[i];
    }
    sort(as.begin(), as.end());
    if(!removable(0))
    {
        cout << 0 << endl;
        return 0;
    }
    int left = 0;
    int right = n;
    while(right - left > 1)
    {
        int middle = (left + right) / 2;
        if(removable(middle))
        {
            left = middle;
        }
        else
        {
            right = middle;
        }
    }
    cout << (left + 1) << endl;
    return 0;
}

