#define FOR(i, a, b) for(int (i) = (a); (i) < (b); ++(i))
#define REP(i, n) FOR(i, 0, n)

std::vector<int> A;
std::vector<std::vector<bool>> P;
std::vector<std::vector<int>>  Q;
/*
    P[i][j] = 先頭 i 枚を使った時に合計 j にできるか
    Q[i][j] = 後半 i 枚を使った時に合計 j にできるか
    ====> Qについて累積和をとれば区間に属するかがO(1)で判定可能
*/


int main(void){
    int n, k; scanf("%d%d", &n, &k);
    A.resize(n); REP(i, n) scanf("%d", &A[i]);
    P.resize(n+1, std::vector<bool>(k, false));
    Q.resize(n+1, std::vector<int>(k+1, 0));
    P[0][0] = true;
    REP(i, n){
        REP(j, k) if(P[i][j]){
            P[i+1][j] = true;
            if(j + A[i] < k) P[i+1][j+A[i]] = true;
        }
    }
    Q[0][0] = 1;
    REP(i, n){
        REP(j, k) if(Q[i][j]){
            Q[i+1][j] = 1;
            if(j + A[n-i-1] < k) Q[i+1][j+A[n-i-1]] = 1;
        }
    }
    for(int i=0;i<=n;++i) REP(j,k) Q[i][j+1] += Q[i][j];
    int res = 0;
    REP(i, n){
        bool need = false;
        REP(j, k) if(P[i][j]){
            int u = k - j - 1;
            int vu = Q[n-i-1][u];
            int l = k - A[i] - j - 1;
            int vl = l < 0 ? 0 : Q[n-i-1][l];
            if(vu != vl){
                need = true; break;
            }
        }
        if(not need) res++;
    }
    printf("%d\n", res);
    return 0;
}

