int dp1ss[MAX_N + 1][MAX_K], dp2ss[MAX_N + 1][MAX_K], dp3ss[MAX_N][MAX_K + 1];

int main(int argc, char *argv[]) {
  // read inputs
  int N, K, as[MAX_N];
  scanf("%d %d", &N, &K);
  for (int i = 0; i < N; i++) {
    scanf("%d", &as[i]);
  }

  // calculate dp1ss
  // initialize
  for (int k = 0; k < K; k++) {
    dp1ss[0][k] = k == 0 ? 1 : 0;
  }
  // update
  for (int i = 0; i < N; i++) {
    const int a = as[i];
    for (int k = 0; k < K; k++) {
      int dp = 0;
      dp = dp || dp1ss[i][k];
      dp = dp || (k - a >= 0 && dp1ss[i][k - a]);
      dp1ss[i + 1][k] = dp;
    }
  }
  // printf("dp1ss\n");
  // for (int i = 0; i <= N; i++) {
  //   printf("i = %d:", i);
  //   for (int k = 0; k < K; k++) {
  //     printf(" %d", dp1ss[i][k]);
  //   }
  //   printf("\n");
  // }
  // calculate dp2ss
  // initialize
  for (int k = 0; k < K; k++) {
    dp2ss[N][k] = k == 0 ? 1 : 0;
  }
  // update
  for (int i = N - 1; i >= 0; i--) {
    const int a = as[i];
    for (int k = 0; k < K; k++) {
      int dp = 0;
      dp = dp || dp2ss[i + 1][k];
      dp = dp || (k - a >= 0 && dp2ss[i + 1][k - a]);
      dp2ss[i][k] = dp;
    }
  }
  // printf("dp2ss\n");
  // for (int i = 0; i <= N; i++) {
  //   printf("i = %d:", i);
  //   for (int k = 0; k < K; k++) {
  //     printf(" %d", dp2ss[i][k]);
  //   }
  //   printf("\n");
  // }
  // calculate dp3ss
  for (int i = 1; i < N; i++) {
    const int a = as[i - 1];
    int cnt = 0;
    for (int k = 0; k <= K; k++) {
      // printf("i = %d, k = %d\n", i, k);
      if (k - 1 >= 0 && dp2ss[i][k - 1]) {
        // printf("increment\n");
        cnt++;
      }
      if (k - a - 1 >= 0 && dp2ss[i][k - a - 1]) {
        // printf("decrement\n");
        cnt--;
      }
      dp3ss[i][k] = cnt;
    }
  }
  // printf("dp3ss\n");
  // for (int i = 0; i < N; i++) {
  //   printf("i = %d:", i);
  //   for (int k = 0; k <= K; k++) {
  //     printf(" %d", dp3ss[i][k]);
  //   }
  //   printf("\n");
  // }

  // solve
  int ans = N;
  for (int i = 0; i < N; i++) {
    const int a = as[i];
    for (int k = 0; k < K; k++) {
      if (dp1ss[i][k] && (dp3ss[i + 1][K - k] > 0)) {
        // printf("as[%d] = %d is needed, k = %d\n", i, as[i], k);
        ans--;
        break;
      }
    }
  }
  printf("%d\n", ans);

  return 0;
}

