bool C(int n) {
    for(int i=0; i<=N; ++i) {
        for(int j=0; j<=K; ++j) dp[i][j] = 0;
    }
    dp[0][0] = 1;
    for(int i=1; i<=N; ++i) {
        for(int j=0; j<=K; ++j) {
            dp[i][j] = dp[i-1][j];
            if(i - 1 != n && j - a[i-1] >= 0) dp[i][j] |= dp[i - 1][j - a[i - 1]];
        }
    }

    for(int k=max(0, K - a[n]); k<K; ++k) {
        if(dp[N][k]) return true;
    }
    return false;
}

