bool DP(int n,int k,vector<int> &a,int x){//xがいるかどうかの判定→x+1~n-1までを使う
    vector<vector<bool>> dp(n-x,vector<bool> (k+1,false));
    dp[0][0]=true;
    for(int i=0;i<n-x-1;i++){
        for(int j=0;j<=k;j++){
            dp[i+1][j]=dp[i+1][j]||dp[i][j];
            dp[i+1][min(k,j+a[i+x+1])]=dp[i+1][min(k,j+a[i+x+1])]||dp[i][j];
        }
    }
    for(int j=max(0,k-a[x]);j<k;j++){
        if(dp[n-x-1][j]){
            return true;
        }
    }
    return false;
}
