        auto itr=lower_bound(a.begin(),a.end(),a[mid]);
        if(DP(n,k,a,itr-a.begin()))need=itr-a.begin();
        else noneed=upper_bound(a.begin(),a.end(),a[mid])-a.begin()-1;
    }
