bool judge(int mid){
    int mit=mid-1;
    if(A[mit]>=K) return true;

    bool dp[N+1][K+1]={};
    dp[0][0]=true;
    int n=0;
    for(int i=0;i<N;i++){
        if(A[i]>=K) break;

        n++;
        if(i==mit){
            for(int j=0;j<K;j++){
                dp[i+1][j]=dp[i][j];
            }
            continue;
        }

        for(int j=0;j<K;j++){
            if(dp[i][j]){
                if(j+A[i]<K) dp[i+1][j+A[i]]=true;
                dp[i+1][j+A[i]]=true;
            }
        }
    }

    for(int j=0;j<K;j++){
        if(dp[n][j]){
            if(j+A[mit]>=K) return true;
        }
    }
    return false;
}

