struct Solver {
  void solve() {
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
      cin >> a[i];
    }
    vector<vector<bool>> dp_pref(n + 1, vector<bool>(k + 1, false));
    vector<vector<bool>> dp_suf(n + 2, vector<bool>(k + 2, false));

    dp_pref[0][0] = true;
    for (int i = 0; i < n; i++) {
      for (int s = k; s >= 0; s--) {
        if (!dp_pref[i][s]) {
          continue;
        }
        dp_pref[i + 1][s] = true;
        dp_pref[i + 1][min(s + a[i], k)] = true;
      }
    }

    dp_suf[n][0] = true;
    for (int i = n - 1; i >= 0; i--) {
      dp_suf[i][0] = true;
      for (int s = k; s >= 0; s--) {
        if (!dp_suf[i + 1][s]) {
          continue;
        }
        dp_suf[i][s] = true;
        dp_suf[i][min(s + a[i], k)] = true;
      }
    }

    int ans = 0;
    for (int i = 0; i < n; i++) {
      vector<int> max_index(k);
      for (int j = 0; j < k; j++) {
        if (dp_suf[i + 1][j]) {
          max_index[j] = j;
        } else {
          max_index[j] = max_index[j - 1];
        }
      }

      for (int j = 0; j < k; j++) {
        if (!dp_pref[i][j]) {
          continue;
        }
        int l = max_index[k - 1 - j];
        CHECK(dp_suf[i + 1][l]);
        CHECK(j + l < k);
        if (a[i] + j + l >= k) {
//          cout << i << " " << j << " " << l << endl;
          ++ans;
          break;
        }
      }
    }

    cout << n - ans << "\n";
  }
};

