signed main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	int n, k;
	cin >> n >> k;

	if (n > 400 || k > 400)return 0;

	//ai が 必要 => aiを除いて 総和xが (k - ai) <= x < k を満たす集合が存在する
	// => aiを含めて k <= x < k + aiを満たす集合が存在する

	//ai >= k は絶対必要　<= 取り除いてよい

	vector<int> a;
	for (int i = 0; i < n; i++) {
		int t;
		cin >> t;
		if (t < k) {
			a.push_back(t);
		}
	}

	n = a.size();

	int ans = 0;

	rep(i, n) {

		vector<int> vis(k * 2, 0);

		vector<vector<int>> dp(n, vector<int>(k * 2, -1));

		function<void(int, int)> dfs = [&](int t, int sum) {
			if (t == n) {
				return;
			}
			if (t == i) {
				dfs(t + 1, sum);
				return;
			}
			if (sum >= k * 2)return;
			if (dp[t][sum] != -1)return;
			dp[t][sum] = 1;

			if (sum < k * 2) {
				vis[sum] = 1;
				dfs(t + 1, sum);
			}
			if (sum + a[t] < k * 2) {
				vis[sum + a[t]] = 1;
				dfs(t + 1, sum + a[t]);
			}

		};

		dfs(0, a[i]);

		bool need = false;
		for (int j = k; j < k + a[i]; j++) {
			if (vis[j]) need = true;
		}
		if (need == false) ans++;
	}

	cout << ans << endl;


	return 0;
}

