bool check(int dust){
  bool dp[a.size()+1][k+1]={};
  dp[0][0]=true;
  for(int i=0;i<a.size();i++){
    for(int j=0;j<=k;j++){
      if(i==dust){
	dp[i+1][j]=dp[i][j];
      }else{
	if(dp[i][j]){
	  dp[i+1][j]=true;
	  if(j+a[i]<=k)
	    dp[i+1][j+a[i]]=true;
	}
      }
    }
  }
  return dp[a.size()][k];
}
