  vector<vector<int>> dpr(n,vector<int>(k+1,0));
  dpl[0][0]=true;
  if(a[0]<=k) dpl[0][a[0]]=true;
  for(int i=1;i<n;i++){
    for(int j=0;j<k+1;j++){
      dpl[i][j]=dpl[i-1][j];
      if(j-a[i]>=0){
	dpl[i][j]=(dpl[i][j]||dpl[i-1][j-a[i]]);
      }
    }
  }
  dpr[n-1][0]=true;
  if(a[n-1]<=k) dpr[n-1][a[n-1]]=true;
  for(int i=n-2;i>=0;i--){
    for(int j=0;j<k+1;j++){
      dpr[i][j]=dpr[i+1][j];
      if(j-a[i]>=0){
	dpr[i][j]=(dpr[i][j] || dpr[i+1][j-a[i]]);
      }
    }
  }

  int lb=-1,ub=n;
  while(ub-lb>1){
    int mid=(ub+lb)/2;
    bool isok=false;
    for(int val=max(k-a[mid],0LL);val<k;val++){
      for(int x=0;x<k;x++){
	int y=val-x;
	if(y<0) continue;
	if(mid==0){
	  isok=isok||dpr[mid+1][val];
	}
	else if(mid==n-1){
	  isok=isok||dpl[mid-1][val];
	}
	else{
	  isok=(isok||(dpl[mid-1][x] && dpr[mid+1][y]));
	}
      }
    }
    if(isok){
      ub=mid;
    }
    else{
      lb=mid;
    }
  }
  cout<<ub<<endl;
  return 0;
}

