    memset(dp,0,sizeof(dp));
    for(int i=0;i<n;i++){
        dp[i][0]=1;
        if(i==0)
            continue;
        if(i==l){
            for(int j=1;j<k;j++)
                dp[i][j]|=dp[i-1][j];
            continue;
