        for(int j=1;j<k;j++){
            if(j>=x[l])
                dp[i][j]|=(dp[i-1][j] | dp[i-1][j-x[l]]);
            else
                dp[i][j]|=dp[i-1][j];
            if(j<k && j>=k-x[l] && dp[i][j])
                    return 0;
        }
    }
    return 1;
