bool is_needed(vl& v, int n, int k, int i)
{
    if (k <= v[i]) return true;

    bool dp[8128] = {true};

    REP(j, n){
        if (i == j) continue;
        RREP(l, k - v[j] + 1){
            if (dp[l]){
                int next = l + v[j];
                dp[next] = true;
                if (next < k && k <= next + v[i]) return true;
            }
        }
    }
    // DEBUG(v[i]);
    return false;
}

signed main()
{
    int n = in(), k = in();
    vl v(n);
    REP(i, n) v[i] = inl();
    SORT(v);

    if (accumulate(ALL(v), 0LL) < k){
        print(n);
        return 0;
    }

    int cnt = 0;
    REP(i, n) cnt += is_needed(v, n, k, i);
    print(n - cnt);

    return 0;
}

