bool cal(int mid)
{
    if(a[mid]>=k) return false;
    memset(dp,0,sizeof(dp));
    dp[0]=true;
    for(int i=1;i<=n;i++)
    {
        if(i==mid) continue;
        for(int j=k;j>=0;j--){
            if(!dp[j]) continue;
            if(j+a[i]<=k) dp[j+a[i]]=true;
        }
    }
    for(int i=max(k-a[mid],0);i<k;i++)
        if(dp[i]) return false;
    return true;
}
