#define rrep(i,a,b) for(int i=a;i>=b;i--)
int N, K, A[5050];
//-----------------------------------------------------------------------------------
int L[5010][5010], R[5010][5010];
void pre() {
	L[0][0] = 1;
	rep(i, 0, N) rep(j, 0, K) if (L[i][j]) {
		L[i + 1][j] = 1;
		if (j + A[i] < K) L[i + 1][j + A[i]] = 1;
	}

	R[N + 1][0] = 1;
	rrep(i, N, 1) rep(j, 0, K) if (R[i + 1][j]) {
		R[i][j] = 1;
		if (j + A[i - 1] < K) R[i][j + A[i - 1]] = 1;
	}

	// For optimized solution
	rep(i, 0, N + 2) {
		rep(j, 1, K) R[i][j] += R[i][j - 1];
	}
}
//-----------------------------------------------------------------------------------
int main() {
	cin >> N >> K;
	rep(i, 0, N) scanf("%d", &A[i]);
	sort(A, A + N);

	pre();

	int ans = 0;
	rep(i, 0, N) {
		if (K <= A[i]) continue;

		bool ok = true;

		/* // Naive
		rep(j, 0, K) rep(k, 0, K) if (L[i][j] && R[i + 2][k]) {
			if (K <= j + k + A[i] && j + k < K) ok = false;
		} */

		// Optimized
		rep(j, 0, K) if (L[i][j]) {
			int lo = max(K - j - A[i], 0);
			int hi = min(K - 1, K - j - 1);

			int sm = R[i + 2][hi];
			if (0 < lo) sm -= R[i + 2][lo - 1];
			if (sm != 0) ok = false;
		}

		if (ok) ans++;
	}

	cout << ans << endl;
}

