using namespace std;

typedef long long ll;
typedef pair<int, int> pii;

const int N = 505;
const ll oo = 1e18;

long long dp[N][N];
int vp[N][N], t;
int n, a[N], k;

long long recur(int at, int left){
	if(left <= 0) return 0;
	if(at == n + 1) return oo;
	if(vp[at][left] == t) return dp[at][left];
	vp[at][left] = t;
	long long ret = oo;
	ret = min(ret, recur(at+1, left));
	ret = min(ret, a[at] + recur(at+1, left-a[at]));
	return dp[at][left] = ret;
}

int main(){
	scanf("%d %d", &n, &k);
	repn(i, n) scanf("%d", &a[i]);
	sort(a+1, a+1+n);
	int ret = 0;
	repn(i, n){
		if(a[i] >= k){
			continue;
		}
		int val = a[i];
		a[i] = 0;
		++t;
		long long mn = recur(1, k - val);
		if(mn >= k){
			ret++;
		}
		a[i] = val;
	}
	cout << ret << endl;
	return 0;
}

