int n;
ll k;
ll a[5001];
bool dp[5001][5001];
bool dp2[5001][5001];
int cnt[5001];
ll sum2[5001];

bool func(int v){
	if(sum2[v+1]>=k)return false;
	memset(dp,false,sizeof(dp));
	memset(dp2,false,sizeof(dp2));
	dp[0][0]=true;
	dp2[0][0]=true;
	for(int i=0;i<n;i++){
		for(int j=0;j<k;j++){
			if(dp[i][j]){
				dp[i+1][j]=true;
				if(j+a[i]<k && i>v)dp[i+1][j+a[i]]=true;
			}
		}
	}
	for(int i=0;i<=v;i++){
		for(int j=0;j<k;j++){
			if(dp2[i][j]){
				dp2[i+1][j]=true;
				if(j+a[i]<k)dp2[i+1][j+a[i]]=true;
			}
		}
	}
	for(int j=k-1;j>=1;j--){
		if(dp2[v+1][j])dp2[v+1][j-1]=true;
	}
	for(int i=k-1;i>=1;i--){
		if(dp[n][i] && dp2[v+1][k-i])return false;
	}
	return true;
}

int main(void){
	scanf("%d%lld",&n,&k);
	if(n>=401 || k>=401)return 0;
	ll sum=0;
	for(int i=0;i<n;i++){
		scanf("%lld",&a[i]);
		sum+=a[i];
		if(a[i]<k)cnt[a[i]]++;
		else cnt[k]++;
	}
	for(int i=0;i<k;i++){
		cnt[i+1]+=cnt[i];
	}
	for(int i=0;i<n;i++){
		sum2[i+1]=sum2[i]+a[i];
	}
	sort(a,a+n);
	if(sum<k){
		printf("%d\n",n);
		return 0;
	}
	if(a[0]>=k){
		printf("%d\n",0);
		return 0;
	}
	int l=-1,r=n;
	while(r-l>1){
		int mid=(l+r)/2;
		if(func(mid))l=mid;
		else r=mid;
	}
	printf("%d\n",l+1);
	return 0;
}

