bool check(ll x)
{
    if(a[x] >= k) return true;
    for(int i = 1; i <= k; i ++)
            dp[i] = 0;
    for(int i = 1; i <= n; i ++)
    {
        if(a[i] != x && a[i] < k)
        {
            for(int j = k - 1; j - a[i] >= 0; j --)
            {
                if(dp[j - a[i]])
                {
                    dp[j] = 1;
                    if(j > (k - a[x])) return true;
                }
            }
        }
    }
    return false;
}

