struct PrefixSum {
  vector<lli> sum;
  PrefixSum(vector<lli> v) {
    sum.push_back(0);
    each (i, v) {
      sum.push_back(sum.back() + i);
    }
  }
  lli query(size_t begin, size_t end) {
    return sum[end] - sum[begin];
  }
};

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n;
  lli k;
  while (cin >> n >> k) {
    vector<lli> a(n);
    cin >> a;
    vector<lli> b = a;
    reverse(b.begin(), b.end());

    const int N = 5000 + 5;
    const int K = 5000 + 5;
    static bool dp1[N][K];
    static bool dp2[N][K];

    fill(&dp1[0][0], &dp1[N - 1][K - 1] + 1, false);
    fill(&dp2[0][0], &dp2[N - 1][K - 1] + 1, false);
    dp1[0][0] = dp2[0][0] = true;

    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < K; ++j) {
        dp1[i + 1][j] |= dp1[i][j];
        dp2[i + 1][j] |= dp2[i][j];
        if (j + a[i] < K) dp1[i + 1][j + a[i]] |= dp1[i][j];
        if (j + b[i] < K) dp2[i + 1][j + b[i]] |= dp2[i][j];
      }
    }

    int cnt = 0;
    for (int i = 0; i < n; ++i) {
      vector<lli> v1, v2;
      for (int j = 0; j < K; ++j) {
        v1.push_back(dp1[i][j]);
        v2.push_back(dp2[n - i - 1][j]);
      }
      PrefixSum ps1(v1);
      PrefixSum ps2(v2);
      bool f = false;
      for (int j = k - a[i]; j < K; ++j) {
        f = f || (dp1[i][j]         && ps1.query(k - a[i], k));
        f = f || (dp2[n - i - 1][j] && ps2.query(k - a[i], k));
      }
      cnt += f;
    }
    cout << n - cnt << endl;
  }

  return 0;
}

