typedef long long int64;

const int nmax = 5005;

int n, k;
int64 v[nmax];
int64 pre[nmax][nmax];
int64 suf[nmax][nmax];
vector<int64> sufv[nmax];

int main() {
  cin >> n >>  k;
  int64 s = 0;
  for (int i = 1; i <= n; i++) {
    cin >> v[i];
    s += v[i];
  }

  if (s < k) {
    cout << n << '\n';
    return 0;
  }

  pre[0][0] = 1;
  suf[n + 1][0] = 1;
  sufv[n + 1].push_back(1);

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= k; j++) {
      pre[i][j] = pre[i - 1][j] |
        (j >= v[i] ? pre[i - 1][j - v[i]] : 0);
    }
  }

  for (int i = n; i >= 1; --i) {
    for (int j = 0; j <= k; j++) {
      suf[i][j] = suf[i + 1][j] |
        (j >= v[i] ? suf[i + 1][j - v[i]] : 0);
      if (suf[i][j])
        sufv[i].push_back(j);
    }
  }

  int ans = 0;

  for (int i = 1; i <= n; i++) {
    if (v[i] >= k && n != 1) {
      ans++;
      continue;
    }

    bool legit = 0;
    for (int x = 1; x <= k && !legit; x++) {
      if (!pre[i - 1][x]) continue;
      int64 yleft = k - v[i] - x;
      int64 yright = k - v[i];

      yleft = max(yleft, 1LL);

      vector<int64>::iterator itl = lower_bound(sufv[i + 1].begin(), sufv[i + 1].end(), yleft);
      vector<int64>::iterator itr = lower_bound(sufv[i + 1].begin(), sufv[i + 1].end(), yright - 1);
      if (itl == sufv[i + 1].end() || (itl == itr && *itr >= yright)) {
        legit = 1;
      }
    }

    if (!legit) {
      ans++;
    }
  }

  cout << ans << '\n';

  return 0;
}

