ll bin(ll x,ll y){
    ll p=(x+y)/2;
    if(y-x==1) return x;
    bit.reset();
    bit[0]=1;
    for(ll i=0;i<len;i++) {
        if(i==p) bit=(bit<<a[i]);
        else bit=(bit<<a[i])|bit;
    }
    bit=bit>>k;
    for(ll i=0;i<a[p];i++) {
        if(bit[i]) return bin(x,p);
    }
