int dp2[5010][5010];
vector<int> a(5010);
void calc() {
  for(int i=0;i<K;i++) {
    dp[0][i] = 0;
  }
  dp[0][0] = 1;

  for(int i=0;i<K;i++) {
    dp2[0][i] = 0;
  }
  dp2[0][0] = 1;

  for(int i=1;i<=N;i++) {
    for(int j=0;j<=K;j++) {
      if(j-a[i] >= 0)
        dp[i][j] |= dp[i-1][j-a[i]];
      dp[i][j] |= dp[i-1][j];
    }
  }

  for(int i=1;i<=N;i++) {
    for(int j=0;j<=K;j++) {
      if(j-a[N-i+1] >= 0)
        dp2[i][j] |= dp2[i-1][j-a[N-i+1]];
      dp2[i][j] |= dp2[i-1][j];
    }
  }
}
int main() {
  int ans=0;
  cin >> N >> K;
  a.push_back(-1);
  for(int i=0;i<N;i++) {
    cin >> a[i];
  }
  calc();


  for(int i=0;i<=N;i++) {
    for(int j=1;j<=K;j++) {
      dp2[i][j] += dp2[i][j-1];
    }
  }
  for(int i=1;i<=N;i++) {
    for(int j=0;j<K;j++) {
      if(dp[i][j] == 0) continue;
      int x = K-1-j;
      int y = K-a[i]-j;
      int low;
      if(x-1 < 0)
        low = 0;
      else
        low = dp2[i][x-1];
      if(dp2[i][y] - low == 0) continue;
      ans++;
      break;
    }
  }

  cout << N-ans << endl;
}

