using namespace std;

int N, K;

bool sub(vector<int> &a, int m) {
	vector<vector<bool> > dp(N, vector<bool>(K, false)); //dp[x][y] : can one make y with {a[0], ..., a[x]} - {a[m]} ?
	for(int y = 0; y < K; ++y) {
		for(int x = 0; x < N; ++x) {
			if(y == 0) {
				dp[x][y] = true;
			} else if(x == 0) {
				if(x == m) {
					dp[x][y] = false;
				} else {
					dp[x][y] = (a[0] == y);
				}
			} else {
				if(x == m || y < a[x]) {
					dp[x][y] = dp[x - 1][y];
				} else {
					dp[x][y] = (dp[x - 1][y] || dp[x - 1][y - a[x]]);
				}
			}
			//cout << "dp[" << x << "][" << y << "] = " << dp[x][y] << '\n';
		}
	}
	bool is_necessary = false;
	for(int k = 1; k <= a[m] && k < K; ++k) {
		if(dp[N - 1][K - k]) {
			is_necessary = true;
		}
	}
	return is_necessary;
}

int main(void) {
	cin >> N >> K;
	vector<int> a;
	int s = 0;
	for(int i = 0; i < N; ++i) {
		int t;
		cin >> t;
		a.push_back(t);
		s += t;
	}
	sort(a.begin(), a.end());
	if(s < K) {
		cout << N << '\n';
		return 0;
	}
	if(K <= a[0]) {
		cout << "0\n";
		return 0;
	}

	vector<pair<bool, bool> > nec(N, make_pair(false, false)); //nec[i] = (is set, is necessary);

	//for(int i = 0; i < N; ++i) {
	//	cout << i << ',' << sub(a, i) << '\n';
	//}
	//return 0;

	int L = 0, R = N - 1;
	int m = (L + R) / 2;
	nec[0].first = true;
	nec[0].second = sub(a, 0);
	if(nec[0].second) {
		cout << "0\n";
		return 0;
	}
	nec[N - 1].first = true;
	nec[N - 1].second = sub(a, N - 1);
	while(!(nec[m].first && nec[m + 1].first && !nec[m].second && nec[m + 1].second)) {
		//cout << "m = " << m << '\n';
		nec[m].first = true;
		nec[m].second = sub(a, m);
		if(nec[m].second) {
			R = m;
			m = (L + R) / 2;
		} else {
			L = m;
			m = (L + R) / 2;
		}
	}
	cout << R << '\n';

	return 0;
}

