template<typename T>
vector<vector<T>> MakeVector2D(int d1, int d2, T default_value) {
  return vector<vector<T>>(d1, vector<T>(d2, default_value));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n, k;
  cin >> n >> k;
  vector<int> xs(n);
  for (int i = 0; i < n; i++) {
    cin >> xs[i];
  }

  auto dp1 = MakeVector2D<int8>(n + 1, 2 * k + 1, 0);
  dp1[0][0] = 1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j <= 2 * k; j++) {
      dp1[i + 1][j] |= dp1[i][j];
      dp1[i + 1][min(j + xs[i], 2 * k)] |= dp1[i][j];
    }
  }

  auto dp2 = MakeVector2D<int8>(n + 2, 2 * k + 1, 0);
  dp2[n][0] = 1;
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j <= 2 * k; j++) {
      dp2[i][j] |= dp2[i + 1][j];
      dp2[i][min(j + xs[i], 2 * k)] |= dp2[i + 1][j];
    }
  }

  int ans = 0;
  for (int i = 0; i < n; i++) {
    if (xs[i] >= k) continue;
    vector<int> as;
    for (int j = 0; j <= 2 * k; j++) {
      if (dp1[i][j]) {
        as.push_back(j);
      }
    }
    vector<int> bs;
    for (int j = 0; j <= 2 * k; j++) {
      if (dp2[i + 1][j]) {
        bs.push_back(j);
      }
    }

    if (DEBUG) {
      cout << "i: " << i << endl;
      cout << "as: " << as << endl;
      cout << "bs: " << bs << endl;
    }

    bool required = false;
    for (int a : as) {
      if (lower_bound(bs.begin(), bs.end(), k - xs[i] - a) !=
              lower_bound(bs.begin(), bs.end(), k - a)) {
        required = true;
      }
    }

    if (!required) {
      if (DEBUG) cout << "not required! i: " << i << endl;
      ans++;
    }
  }
  cout << ans << endl;
}

