  int a[n]; for(int i=0;i<n;i++) cin>>a[i];

  bool u[n][k]={}, u2[n][k]={};

  for(int i=0;i<n;i++) u[i][0]=true;
  for(int i=0;i<n;i++) u2[i][0]=true;

  for(int i=0;i<n;i++) {
    if (i!=0) {
      for(int j=0;j<k;j++) u[i][j]=u[i-1][j];
    }
    for(int j=k-1;j>=0;j--) {
      if (!u[i][j]) continue;
      if (j+a[i]>k) continue;
      u[i][j+a[i]]=true;
    }
  }

  for(int i=n-1;i>=0;i--) {
    if (i!=n-1) {
      for(int j=0;j<k;j++) u2[i][j]=u2[i+1][j];
    }
    for(int j=k-1;j>=0;j--) {
      if (!u2[i][j]) continue;
      if (j+a[i]>k) continue;
      u2[i][j+a[i]]=true;
    }
  }

  vector<int> v[n], v2[n];
  for(int i=0;i<n;i++) {
    for(int j=0;j<k;j++) {
      if (u[i][j]) v[i].push_back(j);
      if (u2[i][j]) v2[i].push_back(j);
    }
  }

  int an=n;
  for(int i=0;i<n;i++) {
    if (i==0) {
      auto it = lower_bound(v2[i+1].begin(), v2[i+1].end(), k-a[i]);
      //cout<<*it<<endl;
      if (it != v2[i+1].end() && *it <= k-1) an--;
    } else if (i==n-1) {
      auto it = lower_bound(v[i-1].begin(), v[i-1].end(), k-a[i]);
      if (it != v[i-1].end() && *it <= k-1) an--;
    } else {
      for(int x:v[i-1]) {
        auto it = lower_bound(v2[i+1].begin(), v2[i+1].end(), k-a[i]-x);
        if (it != v2[i+1].end() && *it <= k-1-x) {an--; break;}
      }
    }
  }
  cout<<an<<endl;
}

