int DPT[405][405][405];

int howclose(int i, int K, int nope) {
	if (K <= 0)
		return 1e9+10;
	if (i == N) {
		return K;
	}
	if (DPT[i][K][nope] != -1) {
		return DPT[i][K][nope];
	}
	if (i == nope) {
		return howclose(i+1, K, nope);
	}
	int ans = min(howclose(i+1, K-vals[i], nope), howclose(i+1, K, nope));
	return DPT[i][K][nope] = ans;
}

