#include <bits/stdc++.h>
using namespace std;

const int MAXN = 5123;

int n, k;
int v[MAXN];
bool memo[MAXN];

bool solve (int x) {
	memset (memo, 0, sizeof memo);
	memo[0] = true;

	for (int i = 0; i < n; ++i) {
		if (i == x) continue;
		for (int j = k; j >= v[i]; --j)
			memo[j] |= memo[j - v[i]];
	}

	for (int i = max (k - v[x], 0); i < k; ++i)
		if (memo[i]) return false;

	return true;
}

int main () {

	cin >> n >> k;

	int ans = 0;
	for (int i = 0; i < n; ++i)
		scanf ("%d", v + i);

	sort (v, v + n);

	if (!solve (0)) {
		cout << ans << endl;
		return 0;
	}

	int l = 0, r = n;
	while (r - l > 1) {
		int mid = (l + r) >> 1;
		if (solve (mid))
			l = mid;
		else
			r = mid;
	}

	cout << ans + l + 1 << endl;

	return 0;
}

