template <typename T> 
void merge_set(std::set<T> &a,std::set<T> &b){
    a.insert(b.begin(),b.end());
}


int main(){
    ll N,K;
    cin >> N >> K;
    vector<ll> a(N);
    rep(i,N) cin >> a[i];
    sort(all(a));

    int ans=0;
    rep(i,N){   // not use a[i]
        set<ll> st;
        st.insert(0);
        rep(j,N) if(i!=j){
            set<ll> tmp;
            for(auto it=st.rbegin();it!=st.rend();it++){
                ll v = *it;
                if(v+a[j]>K) continue;
                tmp.insert(v+a[j]);
            }
            merge_set(st,tmp);
        }
        auto itr = st.lower_bound(K-a[i]);
        if(itr==st.end()){
            ans++;
            continue;
        }
        ll t = *itr;
        if(t>=K) ans++;
    }
    cout << ans << endl;
}

