//WA

ll N,K,a[5010],ans=0;
bool dp[5010],dp2[5010];

bool can(int x){
	reg(i,0,K)dp[i]=false;
	dp[0]=true;
	reg(i,1,N){//i枚目までで
		if(i==x)continue;//midは使わない
		reg(j,0,K)dp2[j]=false;
		reg(j,0,K){
			if(dp[j]){
				dp2[j]=true;
				if(j+a[i]<=K)dp2[j+a[i]]=true;
			}
		}
		reg(j,0,K)dp[j]=dp2[j];
	}
	bool ok=true;//不要
	int begin = 0;
	if(begin<K-a[x])begin = K-a[x];
	reg(i,begin,K-1){
		if(dp[i]){//条件を満たすような和が１つでもあれば
			ok=false;//必要
			break;
		}
	}
	return ok;
}

int main(void){
	cin>>N>>K;
	reg(i,1,N)cin>>a[i];
	sort(a,a+N+1);
	if(can(N)){
		printf("%lld\n",N);
	}else{
		ll l=1,r=N;
		while(r-l>1){
			ll mid = (r+l)/2;
			if(can(mid)){
				l=mid;//不要
			}else{
				r=mid;
			}
		}
		if(can(r)){
			printf("%lld\n",r);
		}else{
			printf("%lld\n",l);
		}
	}
