bool dp[MAX_N+1][MAX_K+1];

void solve(){
	ll sum=0;
	REP(i,N){
		sum+=A[i];
	}
	if (sum<K){
		cout<<N<<endl;
		return;
	}
	int ans=0;
	REP(i,N){
		fill(dp[0],dp[0]+K+1,false);
		dp[0][0]=true;
		REP(j,N){
			fill(dp[j+1],dp[j+1]+K+1,false);
			int a;
			if (i==j){
				a=0;
			}else{
				a=A[j];
			}
			REP(k,K+1){
				dp[j+1][k]|=dp[j][k];
				dp[j+1][min(k+a,K)]|=dp[j][k];
			}
		}
		int x=-1;
		FOR(j,max<ll>(K-A[i],0LL),K+1){
			if (dp[N][j]){
				x=j;
				break;
			}
		}
		if (x>=K){
			ans++;
		}
	}
	cout<<ans<<endl;
