signed main() {
	int i, j;

	cin >> n >> k;
	for (i = 0; i < n; i++) { cin >> a[i]; }

	dp_l[0][0] = true;
	for (i = 0; i < n; i++) {
		for (j = 0; j <= k; j++) {
			if (!dp_l[i][j]) continue;
			dp_l[i + 1][j] = true;
			if (j + a[i] <= k) {
				dp_l[i + 1][j + a[i]] = true;
			}
		}
	}

	dp_r[0][0] = true;
	for (i = 0; i < n; i++) {
		for (j = 0; j <= k; j++) {
			if (!dp_r[i][j]) continue;
			dp_r[i + 1][j] = true;
			if (j + a[n - 1 - i] <= k) {
				dp_r[i + 1][j + a[n - 1 - i]] = true;
			}
		}
	}

	int ans = n;

	for (i = 0; i < n; i++) {
		vector<int> u, v;

		for (j = 0; j <= k; j++) {
			if (dp_l[i][j]) {
				u.push_back(j);
			}
			if (dp_r[n - 1 - i][j]) {
				v.push_back(j);
			}
		}

		for (j = 0; j < u.size(); j++) {
			int low =  k - a[i] - u[j];
			int high = k - u[j];

			vector<int>::iterator it = lower_bound(v.begin(), v.end(), low);
			if (it == v.end()) { continue; }

			int value = (*it);

			if (value < high) {
				break;
			}
		}
		if (j < u.size()) {
			ans--;
		}
	}

	cout << ans << endl;
	return 0;
}

