        for(int j=0; j<=k; j++) {
            int v = suffix[i+1][j];
            if(v == 1) {
                suffix[i][j] = 1;
                if(j+a[i]<=k) {
                    suffix[i][j+a[i]] = 1;
                }
            }
        }
