            if(pre[i-1][j]) pre[i][j+a[i]] = true;
        }
        for(int j = 0; j <= k; j++){
            if(pre[i-1][j]) pre[i][j] = true;
        }
    }
    suf[n+1][0] = true;
    for(int i = n; i > 0; i--){
        for(int j = k-a[i]; j >= 0; j--){
            if(suf[i+1][j]) suf[i][j+a[i]] = true;
        }
        for(int j = 0; j <= k; j++){
            if(suf[i+1][j]) suf[i][j] = true;
        }
    }
    int ans = 0;
    for(int i = 1; i <= n; i++){
        cur[i][0] = suf[i+1][0] ? 1 : 0;
