const int MAX_K = 5005;
const int MAX_LEN = 5005;
const int INF = 1023456789;

using namespace std;

int arr [MAX_LEN], last [MAX_K];

bool unnecessary (int number, int k, int length) {
  if (arr[number] >= k) {
    return false;
  }

  for (int i = 0; i < MAX_K; i++) {
    last[i] = INF;
  }
  last[0] = -1;

  for (int i = 0; i < k; i++) {
    for (int j = last[i] + 1; j < length; j++) {
      if (j != number && i + arr[j] < k) {
        last[i + arr[j]] = min(last[i + arr[j]], j);
      }
    }
  }

  bool flag = false;
  for (int i = k - arr[number]; i < k; i++) {
    if (last[i] < INF) {
      flag = true;
    }
  }

  return !flag;
}

int main () {
  int length, k;
  cin >> length >> k;

  for (int i = 0; i < length; i++) {
    cin >> arr[i];
  }

  sort(arr, arr + length, greater<int>());

  if (unnecessary(0, k, length)) {
    cout << length << endl;
  } else {
    int ans = 0;
    for (int i = 1 << 13; i > 0; i /= 2) {
      int cur = ans + i;
      if (cur < length && !unnecessary(cur, k, length)) {
        ans = cur;
      }
    }
    cout << length - (ans + 1) << endl;
  }
}

