    for(long long i = 1; i <= n; i++)
        scanf("%lld", &ar[i]);

    for(long long i = 1; i <= n; i++)
    {
        long long r = 1, sum = 0;
        for(long long j = 1; j <= n; j++)
        {
            if(r < j)
            {
                r = j;
                sum = 0;
            }
            while((r < j) || (r <= n && sum < k))
            {
                sum += ar[r];
                r++;
            }

            if(i >= j && j < r && sum >= k)
                if(sum - ar[i] < k)
                    u[i] = 1;
            //cout << j << " " << r << endl;
            sum -= ar[j];
        }
    }

    for(long long i = 1; i <= n; i++)
    {
        long long r = n, sum = 0;
        for(long long j = n; j > 0; j--)
        {
            if(r > j)
            {
                r = j;
                sum = 0;
            }
            while((r > j) || (r > 0 && sum < k))
            {
                sum += ar[r];
                r--;
            }

            if(i <= j && j > r && sum >= k)
                if(sum - ar[i] < k)
                    u[i] = 1;
            //cout << j << " " << r << endl;
            sum -= ar[j];
        }
