const int N = 5005;
const int K = 5005;

int n, k;
int a[N];
int dp1[N][N], dp2[N][N];

int main() {
  scanf("%d %d", &n, &k);
  for (int i = 0; i < n; i++) scanf("%d", a + i);
  dp1[0][0] = 1;
  dp2[0][0] = 1;
  for (int i = 0, j = n - 1; i < n; i++, j--) for (int s = 0; s < K; s++) {
    if (s + a[i] < K) dp1[i + 1][s + a[i]] |= dp1[i][s];
    dp1[i + 1][s] |= dp1[i][s];
    if (s + a[j] < K) dp2[i + 1][s + a[j]] |= dp2[i][s];
    dp2[i + 1][s] |= dp2[i][s];
  }
  for (int i = 0; i < n; i++) for (int j = 1; j < K; j++) dp2[i][j] += dp2[i][j - 1];
  int ans = 0;
  for (int i = 0; i < n; i++) for (int j = 0; j < K; j++) {
    if (dp1[i][j] == 0) continue;
    int x = k - a[i] - j;
    int y = k - 1 - j;
    if (y < 0) break;
    if (dp2[n - i - 1][y] - (x - 1 >= 0 ? dp2[n - i - 1][x - 1] : 0) == 0) continue;
    ans++;
    break;
  }
  printf("%d\n", n - ans);
  return 0;
}

