bool core(int key) {
	if (a[key] >= k) return true;
	vector<bool> dp(k, false), dp2(k, false);
	dp[0] = true;
	Loop(i, n) {
		Loop(j, k) {
			if (dp[j]) {
				dp2[j] = true;
				if (i != key && j + a[i] < k) {
					dp2[j + a[i]] = true;
				}
			}
		}
		dp = dp2;
	}
	for (int j = k - a[key];j < k;++j) {
		if (dp[j]) return true;
	}
	return false;
}

int binary_search(int left, int right) {
	if (left + 1 >= right) return left;
	int judge = false;
	int mid = (left + right) / 2;
	judge = core(mid);
	if (judge) return binary_search(left, mid);
	else return binary_search(mid, right);
}

