    for(auto &x : a){
        vector<int> ndp(k+1);
        for (int i = 0; i <= k; ++i){
            ndp[i] += dp[i];
            ndp[min(k,i+x)] += dp[i];
        }
        dp = ndp;
    }
    return dp;
