inline bool check(int x) {
    b.reset();
    b[0] = 1;
    for (int i = 1; i <= cnt; i++) {
        if (i == x) continue;
        b |= b << a[i];
    }
    for (int i = k - a[x]; i < k; i++)
        if (b[i])
            return true;
    return false;
}
int main() {
    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; i++) {
