            a[++cnt] = t;
    }
    std::sort(a + 1, a + cnt + 1);
    l = 0;
    r = cnt;
    while (l < r) {
        int m = (l + r) / 2;
        if (check(m + 1))
            r = m;
        else
            l = m + 1;
    }
    printf("%d\n", r);
    return 0;
}

