ll N, K;
vector<ll> A;
bool dp[5010][5010];

bool J(ll x){
  if(A[x] >= K) return 1;

  rep(i, 5010)rep(j, 5010) dp[i][j] = 0;
  dp[0][0] = 1;
  for(int i = 1; i <= N+2; i++){
    if(i-1 == x){
      for(int j = 0; j <= K; j++){
        dp[i][j] = dp[i-1][j];
      }
    }else{
      for(int j = 0; j <= K; j++){
        dp[i][j] = dp[i-1][j];
        if(j-A[i-1] < 0) continue;
        dp[i][j] |= dp[i-1][j-A[i-1]];
      }
    }
  }

  for(int i = K - A[x]; i < K; i++){
    if(dp[N+2][i]) return 1;
  }
  return 0;
}

int main(void){
  cin >> N >> K;
  A.resize(N);
  rep(i, N) cin >> A[i];
  A.pb(INFL);
  A.pb(0);
  sort(A.begin(), A.end());
  ll NoNeed = 0, Need = N+2;
  while(Need - NoNeed > 1){
    ll mid = (NoNeed + Need) / 2;
    if(J(mid)) Need = mid;
    else NoNeed = mid;
  }

  cout << NoNeed << endl;
}

