					// cout<<"hh "<<i<<" "<< *it << x << endl;
				}
			}
		}
		if(v[i] >= K) ok=true;
		if(!ok){
			ans++;
			// cout<<i<<" "<<v[i]<<endl;
		}
	}
	cout<<ans<<endl;
}


