bool check(int pos)
{
//	cout<<"check "<<pos<<" : ";

	if(a[pos]>=k) return false;
	bitset<5050> sumwk(1);
	for(int i=0;i<N;i++)
	{
		if(i!=pos) sumwk|=(sumwk<<a[i]);
	}
//	cout<<sumwk<<endl;
	for(int i=k-a[pos];i<k;i++)
	{
		if(sumwk[i]) return false;
	}
	return true;
