int main () {
  cin.tie(0);
  cout << fixed << setprecision(10);

  int n, k; cin >> n >> k;
  vector<int> a(n);
  for(int i=0;i<n;++i) {
    cin >> a[i];
  }

  sort(a.begin(), a.end());
  reverse(a.begin(), a.end());
  vector<vector<bool>> dp(n, vector<bool> (k+1));
  if(a[0] < k) dp[0][a[0]] = true;
  for(int i=0;i<n-1;++i) {
    if(a[i+1] < k) dp[i+1][a[i+1]] = true;
    for(int j=0;j<k;++j) {
      if(j+a[i] < k) dp[i+1][j+a[i]] = dp[i+1][j+a[i]] | dp[i][j];
      dp[i+1][j] = dp[i+1][j] | dp[i][j];
    }
  }

  return 0;

  vector<int> s(n+1);
  for(int i=n-1;i>=0;--i) {
    s[i] = s[i+1] + a[i];
  }

