    bool noneed = true;
    for(int j=0;j<k;++j) {
      if(dp[i][j] && j + s[i] >= k) {
        noneed = false;
        break;
      }
    }
    if(noneed) cnt++;
  }
  cout << cnt << endl;

}

#include <cstdio>

typedef long long int lli;
int N, K;
lli arr[5005];
int frontMake[5005][5005];		//frontMake[i][sum] : can make "sum" using arr[1] ~ arr[i]
int backMake[5005][5005];		//backMake[i][sum   : can make "sum" using arr[i] ~ arr[N]
int pSum[5005];

int main(){
	int ans=0, a, b;
	scanf("%d %d", &N, &K);
	for(int i=1; i<=N; ++i)
		scanf("%lld", arr+i);
	++frontMake[0][0];
	for(int i=1; i<=N; ++i){
		for(int sum=0; sum <= 5000; ++sum){
			if(frontMake[i-1][sum]){
				++frontMake[i][sum];
			    if(sum + arr[i] <= 5000)
					++frontMake[i][sum + arr[i]];
			}
		}
	}
	++backMake[N+1][0];
	for(int i=N; i>0; --i){
		for(int sum=0; sum <= 5000; ++sum){
			if(backMake[i+1][sum]){
				++backMake[i][sum];
				if(sum + arr[i] <= 5000)
					++backMake[i][sum + arr[i]];
			}
		}
	}
	for(int i=1; i<=N; ++i){
		if(arr[i] >= K){
			++ans;
		} else{
			pSum[0] = backMake[i+1][0];
			for(int j=1; j<=N; ++j)
				pSum[j] = pSum[j-1] + backMake[i+1][j];
			for(int j=0; j<=K; ++j){
				a = K-j-1>=0 ? pSum[K-j-1] : 0;
				b = K-j-arr[i]-1>=0 ? pSum[K-j-arr[i]-1] : 0;
				if(frontMake[i-1][j] && a != b){
					++ans;
					break;
				}
			}
		}
	}
	printf("%d\n", N - ans);
}

