/*
<url:https://arc070.contest.atcoder.jp/tasks/arc070_b>
問題文============================================================
 シカのAtCoDeerくんは正整数が書かれたカードを N 枚持っています。i(1≦i≦N) 枚目に書かれている数は ai です。
 AtCoDeerくんは大きい数が好きなので、
 カードに書かれた数の総和が K 以上になるようなカードの部分集合をよい集合と呼びます。

 そして、各カード i に対して、そのカードが不必要かどうかを次のように判定します。

 「カード i を含む任意のよい集合に対して、その集合からカード i を除いたものもよい集合」ならカード i は不必要
 それ以外の場合は、不必要でない

 不必要なカードの枚数を求めてください。
 ただし、それぞれの判定は独立に行われ、不必要だからと言ってカードが途中で捨てられたりすることはありません。

 入力は全て整数
 1≦N≦5000
 1≦K≦5000
 1≦ai≦10^9(1≦i≦N)
=================================================================

解説=============================================================

================================================================
*/
ll N,K;
vector<ll> a;
ll solve(){
    ll res = 0;
    cin >> N >> K;
    a.resize(N); for(auto &in:a) cin >> in;
    sort(a.begin(),a.end()); a.push_back(INF);
    vector<int> f(N,true);
    int l = 0,r = 0;
    ll sum = 0;
    while(true){
        while(r < N && sum < K){ sum += a[r++];}
        if(sum < K){ break; }
        if(sum - a[l] < K){
            for(int i = l; i <= r;i++) f[i] = false;
        }
        sum -= a[l++];
    }
    res = accumulate(f.begin(),f.end(),0);
    return res;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    cout << solve() << endl;
	return 0;
}

