bool sub(int m) {
	if(K <= a[m]) return true;
	dp.reset();
	for(int i = 0; i < N; ++i) {
		if(i != m) dp |= dp << a[i];
	}
	for(int b = K - a[m]; b < K; ++b) {
		if(dp[b]) return true;
	}
	return false;
}

