        for(int i=0; i<n-1; i++){
            for(int j=0; j<=m; j++){
                if(!f[i][j])continue;
                UPDMAX(f[i+1][j], f[i][j]);
                if(j+a[i]<=m)
                    UPDMAX(f[i+1][j+a[i]], f[i][j]);
            }
        }
        memset(g, 0, sizeof(g));
        g[n-1][0]=1;
        for(int i=n-1; i; i--){
            for(int j=0; j<=m; j++){
                if(!g[i][j])continue;
                UPDMAX(g[i-1][j], g[i][j]);
                if(j+a[i]<=m)
                    UPDMAX(g[i-1][j+a[i]], g[i][j]);
            } 
        }
        ans=0;
        for(int i=0; i<n; i++){
            g[i][m+1]=inf;
            for(int j=m; ~j; j--){
                g[i][j]=(g[i][j])?j:g[i][j+1];
            }
            int sol=inf;
            for(int j=0; j<=m; j++){
                if(!f[i][j])continue;
                int cur=j+a[i];
                if(cur<m){
                    cur+=g[i][m-cur];
                }
                UPDMIN(sol, cur);
            }
            if(sol-a[i]>=m)ans++;
        }
        printf("%d\n", ans);
    }
