            sum[j + 1] = sum[j] + dp[index(1, target, j)];
        }
        bool add = true;
        REP(j, 0, k + 1) {
            if (dp[index(0, i, j)]) {
                int l = max(0, k - a[i] - j), r = k - j;
                if (sum[r] > sum[l]) {
                    add = false;
                }
            }
        }
        dump(i, a[i], add);
        ans += add;
    }

    print(ans);

    return 0;
}

