	f[0][0]=1;
	if (0>=k-a[x]&&0<k) return true;
	for (int i=1;i<=n;i++) {
		int tmp=a[i];
		if (i==x) tmp=0;
		f[i][0]=1;
		for (int j=1;j<k;j++) {
			if (j>=tmp) f[i][j]=f[i-1][j]|f[i-1][j-tmp];
			else f[i][j]=f[i-1][j];
			if (j>=k-a[x]&&j<k&&f[i][j]) return true;
		}
	}
	return false;
}

