int rec(int i,int j){
	if(dp[0][k-1]>=0){return dp[0][k-1];}
	if(dp[i][j] >= 0){return dp[i][j];}
	int res;
	if(i==s-1){
		res = 0;
	}
	else if(j<v[i]){
		res = rec(i+1,j);
	}
	else{
		res = max(rec(i+1,j),rec(i+1,j-v[i])+v[i]);
	}
	if(res>=k-a[mid])dp[0][k-1]=res;
	return dp[i][j] = res;
