ll Mod = 1000000007;
bool R1[5021][5021];
bool R2[5021][5021];
int main() {
  ll N,K;
  cin >> N >> K;
  ll a[N];
  for (int i = 0; i < N; i++) {
    cin >> a[i];
  }
  ll ans = 0;
  R1[0][0] = true;
  if (a[0] <= K) R1[0][a[0]] = true;
  for (ll i = 1; i < N; i++) {
    for (ll j = 0; j <= K; j++) {
      R1[i][j] = R1[i-1][j];
      if (0 <= j-a[i] && j-a[i] <= K) {
        if (R1[i-1][j-a[i]]) {
          R1[i][j] = true;
        }
      }
    }
  }
  R2[N-1][0] = true;
  if (a[N-1] <= K) R2[N-1][a[N-1]] = true;
  for (ll i = N-2; i >= 0; i--) {
    for (ll j = 0; j <= K; j++) {
      R2[i][j] = R2[i+1][j];
      if (0 <= j-a[i] && j-a[i] <= K) {
        if (R2[i+1][j-a[i]]) {
          R2[i][j] = true;
        }
      }
    }
  }
  // R1[i][j]はi番目までにjぴったりが作れるか R2[i][j]は逆順
  // i = 0,N-1の時は例外処理
  for (ll i = 1; i < N-1; i++) {
    if (a[i] >= K) {
      continue;
    }
    ll Can[K - a[i] + 1];
    for (ll j = 0; j < K - a[i] + 1; j++) {
      Can[j] = 0;
    }
    for (ll j = 0; j < a[i]; j++) {
      if (R1[i-1][j]) {
        Can[0]++;
      }
    }
    for (ll j = 1; j < K - a[i] + 1; j++) {
      Can[j] = Can[j-1];
      if (R1[i-1][j+a[i]-1]) Can[j]++;
      if (R1[i-1][j-1]) Can[j]--;
    }
    bool need = false;
    for (ll j = 0; j < K - a[i] + 1; j++) {
      if (Can[j] != 0 && R2[i+1][K-a[i]-j]) {
        need = true;
      }
    }
    if (!need) {
      ans++;
    }
  }

  if (a[0] < K) {
    bool need = false;
    for (ll i = K-a[0]; i < K; i++) {
      if (R2[1][i]) {
        need = true;
      }
    }
    if (!need) {
      ans++;
    }
  }
  if (a[N-1] < K) {
    bool need = false;
    for (ll i = K-a[N-1]; i < K; i++) {
      if (R1[N-2][i]) {
        need = true;
      }
    }
    if (!need) {
      ans++;
    }
  }
