        cerr << a[i] << pre[i] << post[N-1-i] << endl;
        fprintf(stderr, " looking for [%d-%d, %d)\n", K,a[i],K);
#endif
        // for (int p : pre_[i]){
        vi post_;
        for (int p=0; p<=cap; ++p) {
            if (post[N-1-i][p]) post_.pb(p);
        }

        for (int p=0; p<=cap; ++p) {
            if (!pre[i][p]) continue;
            // [k-ai, k) を探してて
            // pを引くから
            // [k-p-ai, k-p)
            auto it = lower_bound(ALL(post_), K-p-a[i]);
            auto jt = lower_bound(ALL(post_), K-p);
            if (it != jt) { needed = true; break; }
        }
        if (!needed) ++ans;
    }

    return ans;
}

