struct BIT{
  vector<ll> bit;
  int size;
  void init( int n ){
    size = 1;
    while( size < n ) size *= 2;
    bit = vector<ll>( size , 0 );
  }
  void add( int k , ll v ){
    for( int i = k+1; i <= size; i += i & -i ) bit[i-1] += v;
  }
  ll sum( int k ){ // [0,k)
    ll res = 0;
    for( int i = k; i > 0; i -= i & -i ) res += bit[i-1];
    return res;
  }
  ll sum( int l , int r ){ // [l,r)
    return sum( r ) - sum( l );
  }
  ll get( int k ){
    return sum( k+1 ) - sum( k );
  }
  void update( int k , ll x ){
    add( k , x - get(k) );
  }
} bit;


int main(){

  ll n = in();
  ll k = in();
  vector<ll> a(n);
  REP(i, n){
    a[i] = in();
  }
  ll sum = 0;
  REP(i, n){
    sum += a[i];
  }
  if(sum < k){
    cout << n << endl;
    return 0;
  }
  vector<vector<bool>> dp(n + 1, vector<bool>(k + 1, false));
  dp[0][0] = true;
  REP(i, n){
    REP(j, k + 1){
      if(dp[i][j]){
        dp[i+1][j] = true;
        if(j + a[i] <= k){
          dp[i+1][j + a[i]] = true;
        }
      }
    }
  }
  vector<vector<bool>> rdp(n + 1, vector<bool>(k + 1, false));
  rdp[n][0] = true;
  for(int i = n-1; i >= 0; i--){
    REP(j, k + 1){
      if(rdp[i+1][j]){
        rdp[i][j] = true;
        if(j + a[i] <= k){
          rdp[i][j + a[i]] = true;
        }
      }
    }
  }
  ll ans = 0;
  REP(i, n){
    bit.init(k + 1);
    REP(j, k+1){
      if(rdp[i+1][j]){
        bit.add(j, 1);
      }
    }
    ll p = k - a[i];
    if(p < 0){
      ans++;
    }
    REP(j, p+1){
      if(dp[i][j] && bit.sum(p - j, k - j) >= 1){
        ans++;
        break;
      }
    }
  }
  cout << ans << endl;

  return 0;
}

