static const int K_MAX = 5000;

bool subsetSum[K_MAX];

bool isValid(int idx, const std::vector<long>& a, int K) {
    // calc minimum value X which satisfies X >= K
    // if X - a[i] >= K, card i is invalid.

    std::memset(subsetSum, false, K_MAX);

    subsetSum[0] = true;

    int thresh = std::max<long>(0, K - a[idx]);
    for (int i = a.size()-1; i >= 0; i--) {
        if (i == idx) {
            continue;
        }

        // printf("a[i]: %d\n", a[i]);
        for (int j = K-1; j >= a[i]; j--) {
            // printf("j: %d, subsetSum[j]: %d, subsetSum[j - a[i]]: %d\n",
            //        j, subsetSum[j], subsetSum[j - a[i]]);
            subsetSum[j] |= subsetSum[j - a[i]];

            if (j >= thresh && subsetSum[j]) {
                return true;
            }
        }
    }

    // for (int i = std::max<long>(0, K - a[idx]); i < K; i++) {
    //     if (subsetSum[i]) {
    //         return true;
    //     }
    // }

    return false;
}

int main(void) {
    int N, K;
    std::vector<long> a;

    std::cin >> N;
    std::cin >> K;

    long sum = 0;
    a.resize(N);
    for (int i = 0; i < N; i++) {
        std::cin >> a[i];
        sum += a[i];
    }

    std::sort(a.begin(), a.end());

    if (sum < K) {
        std::cout << N << std::endl;
        return 0;
    }

    int ninvalid = 0;
    for (int i = 0; i < N; i++) {
        if (isValid(i, a, K)) {
            break;
        } else {
            ninvalid++;
        }
    }

    std::cout << ninvalid << std::endl;
}

