using ll = long long;

ll solve() {
    ll N, K;
    cin >> N >> K;
    vector<ll> A(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> A[i];
    }
    // sort(A.begin(), A.end());
    vector<vector<bool>> sl(N+1, vector<bool>(K+1,false)), sr(N+1, vector<bool>(K+1,false));
    sl[0][0] = true;
    for ( int i = 0; i < N ; i++ ) {
        for ( int k = 0; k <= K ; k++ ) {
            sl[i+1][k] = sl[i][k];
        }
        for ( int k = 0; k <= K ; k++ ) {
            if ( k + A[i] <= K ) {
                sl[i+1][k + A[i]] = sl[i+1][k + A[i]] || sl[i][k + A[i]] || sl[i][k];
            }
        }
    }
    sr[N][0] = true;
    for ( int i = N-1; i >= 0 ; i-- ) {
        for ( int k = 0; k <= K ; k++ ) {
            sr[i][k] = sr[i+1][k];
        }
        for ( int k = 0; k <= K ; k++ ) {
            if ( k + A[i] <= K ) {
                sr[i][k + A[i]] = sr[i][k + A[i]] || sr[i+1][k + A[i]] || sr[i+1][k];
            }
        }
    }
    ll ans = 0;
    for ( int i = 0; i < N; i++ ) {
        ll k_max = 0;
        vector<ll> nl, nr;
        for ( int k = 0; k < K; k++ ) {
            if ( sl[i][k] ) nl.push_back(k);
            if ( sr[i+1][k] ) nr.push_back(k);
        }
        ll il = nl.size()-1, ir = 0;
        while ( true ) {
            while ( il >= 0 && nl[il] + nr[ir] >= K ) {
                il--;
            }
            if ( il < 0 ) break;
            while ( ir < nr.size() && nl[il] + nr[ir] < K )  {
                if ( k_max < nl[il] + nr[ir] ) k_max = nl[il] + nr[ir];
                ir++;
            }
            if ( ir >= nr.size() ) break;
        }
        if ( k_max + A[i] < K ) ans++;
    }

    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

