LL n, k, a[5000];
bool sum[5000];

bool f(LL x) {
	if(a[x] >= k) { return true; }

	inc(i, k) { sum[i] = false; }
	sum[0] = true;
	inc(i, n) {
		if(i == x) { continue; }
		dec(j, k) {
			if(sum[j] && j + a[i] < k) { sum[j + a[i]] = true; }
		}
	}

	incID(j, k - a[x], k) {
		if(sum[j]) { return true; }
	}
	return false;
}

int main() {
	cin >> n >> k;
	inc(i, n) { cin >> a[i]; }

	sort(a, a + n);

	LL L = 0, R = n;
	while(R - L > 1) {
		LL M = (L + R) / 2;
		(f(M) ? R : L) = M;
	}

	cout << R << endl;

	return 0;
}

