        int t;
        cin >> t;
        if(t < k)a.push_back(t);
    }
    n = a.size();
    sort(a.begin(), a.end());
    need = n;
    while(noneed + 1 < need){
        int mid = (noneed + need) / 2;
        vector<int> b;
        vector< vector<bool> > dp;
        for(int i=0;i<n;i++){
            if(i != mid){
                b.push_back(a[i]);
            }
        }
        dp.assign(2, vector<bool>());
        dp[0].assign(k+1, false);
        dp[1].assign(k+1, false);
        dp[1][0] = true;
        for(int i=0;i<n-1;i++){
            for(int j=0;j<=k;j++){
                dp[i%2][j] = dp[(i+1)%2][j];
                if(j-b[i]>=0)dp[i%2][j] = dp[i%2][j] || dp[(i+1)%2][j-b[i]];
            }
        }
        bool flg = false;
        for(int i=k-a[mid];i<=k;i++){
            if(dp[n%2][i]){
                flg = true;
                break;
            }
        }
        if(flg)need = mid;
        else noneed = mid;
    }
