using namespace std;

int N, K;
vector<int> a;
bitset<5001> dp;

//is m necessary?
bool sub(int m) {
	if(K <= a[m]) return true;
	dp.reset();
	for(int i = 0; i < N; ++i) {
		if(i != m) dp |= dp << a[i];
	}
	for(int b = K - a[m]; b < K; ++b) {
		if(dp[b]) return true;
	}
	return false;
}

int main(void) {
	cin >> N >> K;
	int s = 0;
	for(int i = 0; i < N; ++i) {
		int t;
		cin >> t;
		a.push_back(t);
		s += t;
	}
	sort(a.begin(), a.end());
	if(s < K) {
		cout << N << '\n';
		return 0;
	}

	if(sub(0)) {
		cout << "0\n";
		return 0;
	}
	int L = 0, R = N;
	while(1 < R - L) {
		int m = (L + R) / 2;
		//cout << m << '\n';
		(sub(m) ? R : L) = m;
	}
	cout << R << '\n';
	return 0;
}

