using namespace std;
int n,k;
int a[5000];

bool solve(int c){
  int dp[2][5010]={};
  dp[0][0]=1;
  for(int i=0;i<n;i++){
    int nw=i%2,nt=(i+1)%2;
    for(int j=0;j<5010;j++)dp[nt][j]=0;
    for(int j=0;j<5010;j++){
      if(dp[nw][j]){
	dp[nt][j]=1;
	if(j+a[i]<5010&&i!=c)dp[nt][j+a[i]]=1;
      }
    }
  }
  for(int i=max(k-a[c],0);i<k;i++)
    if(dp[n%2][i])return true;
  return false;
}

int main(){
  cin>>n>>k;
  for(int i=0;i<n;i++)cin>>a[i];
  sort(a,a+n);
  int lb=0,ub=n,mid;
  //for(int i=0;i<n;i++)cout<<solve(i)<<endl;
  while(ub-lb>1){
    mid=(lb+ub)/2;
    (!solve(mid)?lb:ub)=mid;
  }
  cout<<lb+1<<endl;
  return 0;
}

