	{
		int limit=0;
		rep(i,n) if(a[i]<=k) limit=i;
		n=limit+1;
	}

	per[0][0]=true;
	rep(i,n)rep(j,k+1){
		if(per[i][j]==false) continue;
		per[i+1][j]=true;
		if(j+a[i]<=k) per[i+1][j+a[i]]=true;
	}

	rev[n][0]=true;
	rrep(i,n)rep(j,k+1){
		if(rev[i+1][j]==false) continue;
		rev[i][j]=true;
		if(j+a[i]<=k) rev[i][j+a[i]]=true;
	}


	int ans=0;
	rep(i,n){
		set<int> s;
		rep(j,k+1) if(rev[i+1][j]) s.insert(j);
		bool ok=false;

		//[k-a[i],k-1] 
		//[small,large]
		//[small-j,large-j] 
		rep(j,k+1){
			if(per[i][j]==false) continue;
			auto it=s.lower_bound(k-a[i]-j);
			if(it!=end(s) and *it<=k-1-j) ok=true;
		}

		if(ok==false) ans++;
	}

	cout << ans << endl;

	return 0;
}

