using namespace std;
const int N = 5005;
int dp[N][N], n, k, a[N], tmp, x, z[N];
int sol(int i, int cur)
{
	if(i == n) return cur;
	int &ret = dp[i][cur];
	if(ret != -1) return ret;
	ret = sol(i+1, cur);
	if(cur + a[i] < k) return max(ret, sol(i+1, cur+a[i]));
	return ret;
}
bool check(int i)
{
	x = a[i];
	if(z[x] != -1) return z[x];
	if(x >= k) return z[x] = 1;
	memset(dp, -1, sizeof dp);
	i = lower_bound(a, a+n, x)-a + 1;
	if(sol(i, 0) >= k-x) return z[x] = 1;
	return z[x] = 0;
}
int main()
{
	memset(z, -1, sizeof z);
	cin >> n >> k;
	for(int i=0; i<n; i++) scanf("%d", &a[i]);
