	while(a[n-1] >= k) n--;
	int s = 0, e = n-1;
	while(s <= e)
	{
		int mid = (s+e)>>1;
		if(check(mid)) e = mid-1;
		else s = mid+1;
	}
	cout << s << endl;
}

