#include<bits/stdc++.h>
#define INF ((1e9)+10000)
#define N 5005
using namespace std;
int n,k,a[N],memo[N][N],minsum[N],ans;
bool used[N][N],used2[N];

int dfs(int x,int sum){
  if(sum>=k)return sum;
  if(x==n)return INF;
  if(used[x][sum])return memo[x][sum];
  used[x][sum]=1;
  int res=INF;
  res=min(res,dfs(x+1,sum+a[x]));
  minsum[x]=min(minsum[x],res);
  res=min(res,dfs(x+1,sum));
  return memo[x][sum]=res;
}

int main(){
  cin>>n>>k;
  for(int i=0;i<n;i++){
    cin>>a[i];
    minsum[i]=INF;
  }
  dfs(0,0);
  for(int i=0;i<n;i++)
    if(minsum[i]-a[i]>=k)ans++;
  cout<<ans<<endl;
  return 0;
}

