// no need
bool noneed(int x){

    // fprintf(stderr, "x:%d A[x]:%d ", x, A[x]);

    if(A[x] >= K) return false;

    // check 5000-10000
    rep(i, N+1){
        rep(j, 10001) dp[i][j] = 0;
    }

    dp[0][0] = 1;
    for(int i = 1; i<=N; i++){
        int a = A[i];
        rep(j, 10001){
            dp[i][j] = max(dp[i][j], dp[i-1][j]);
            if(i != x && j-a >= 0) {dp[i][j] = max(dp[i][j], dp[i-1][j-a]);}
        }
    }

    for(int j = K-A[x]; j<K; j++){
        // fprintf(stderr, "%d", dp[N][j]);
        if(dp[N][j] == 1) {
            // fprintf(stderr, " F\n");
            return false;
        }
    }

    // fprintf(stderr, "T\n");
    return true;

}

// good most left = bad most right + 1
int binarySearch(){
    int left = 0;
    int right = N;

    if(!noneed(0)) return 0;
    if(noneed(N-1)) return N;

    while (left + 1 < right){
        int mid = (left + right) / 2;
        if(noneed(mid)) {
            left = mid;
        }
        else{
            right = mid;
        }
    }
    return right;
}

