        for (int j = 0; j <= k; j++) {
            d_rev[i][j] = d_rev[i - 1][j];
            if (j >= v[i]) d_rev[i][j] = max(d_rev[i - 1][j - v[i]], d_rev[i - 1][j]);

        }
    }

    std::reverse(v.begin(), v.end());
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        int l = i - 1;
        int r = n - i;
        int cur = v[i];
        if (cur >= k) {
            continue;
        }
        int sum_r = 0;
        for (int j = k - 1; j > k - cur; j--) {
            sum_r += d_rev[r][j];
        }

        bool ok = false;
        for (int cur_l = 0; cur_l <= k - 1; cur_l++) {
            if (sum_r && d[l][cur_l]) {
                ok = true;
                break;
            }
            int id_add = k - cur_l - 1 - cur;
            int id_del = k - cur_l - 1;
            if (id_add >= 0) {
                sum_r += d_rev[r][id_add];
            }
            if (id_del >= 0) {
                sum_r -= d_rev[r][id_del];
            }
        }
        if (!ok) ans++;
    }
    cout << ans << endl;
    return 0;
}

