bool is_needed(int x){
    for(int k = 0; k < K; k++){
            dp[0][k] = false;
    }
    dp[0][0] = true;
    for(int i = 0; i < N; i++){
        for(int k = 0; k < K; k++){
            dp[i+1][k] = dp[i][k];
        }
        if(i != x){
           for(int k = 0; k < K; k++){
               if(a[i] + k < K){
                   dp[i+1][a[i]+k] = dp[i][k] || dp[i+1][a[i]+k];
               }
           }
        }
    }
    bool ret = false;
    for(int k = max(0LL, K - a[x]); k < K; k++){
        ret = ret || dp[N][k];
    }
    return ret;
}

// is_needed(begin) == false, is_needed(end) == true
int find(int begin, int end){
    if(end - begin == 1){
        return begin;
    }
    int mid = (begin + end)/2;
    if(is_needed(mid)){
        return find(begin, mid);
    }else{
        return find(mid, end);
    }
}

