int rec(int x,int y){
    if(dp[x][y]>=0){
        return dp[x][y];
    }
    if(x==0){
        if(a[0]==y) return 1;
        else return 0;
    } else {
        int res = 0;
        if(rec(x-1,y)==1){
            res = 1;
        }
        if(y>=a[x]){
            if(rec(x-1,y-a[x])==1){
                res = 1;
            }
        }
        dp[x][y] = res;
        return res;
    }
}


