    for(i=0;i<n;i++){
        cin >> x;
        a.push_back(x);
    }
    sort(a.rbegin(),a.rend());
    for(i=0;i<k;i++){
        dp[0][i] = false;
    }
    dp[0][0] = true;

    for(i=1;i<=n;i++){
        for(j=0;j<k;j++){
            if(j-a[i-1]>=0){
                if(dp[i-1][j] || dp[i-1][j-a[i-1]]){
                    dp[i][j] = true;
                }else{
                    dp[i][j] = false;
                }
