    REP(i, n){
        for(int j=k; j>0; j--){
            if(j-a[i]<0){
                break;
            } else if(dp[j-a[i]]){
                dp[j] = true;
                bitset<5001> cbi(1);
                cbi = cbi << i;
                nec[j] = nec[j] & (nec[j-a[i]] | cbi);
            }
        }
    }

    ll c = 0;
    REP(l, n){
        bool flag = true;
        if(a[l]>=k){
            flag = false;
        } else {
            bitset<5001> one(1);
            for(int i=k-a[l]; i<k; i++){
                if(!(nec[i]>>l)[0]){
                    flag = false;
                    break;
                }
            }
        }
        if(flag) c += 1;
    }

    cout << c << endl;
}

