int main() {
  cin.tie(0);
  cin.sync_with_stdio(0);

  cin >> n >> k;
  ll sum = 0;
  for(int i = 0; i < n; ++i) {
    cin >> a[i];
    sum += a[i];
  }

  if(sum < k) {
    cout << n << endl;
    return 0;
  }

  prefix[0][0] = 1;
  for(int i = 1; i < n; ++i) 
    for(int j = 0; j < k; ++j) {
      if(not prefix[i][j])
        prefix[i][j] = prefix[i-1][j];

      if(prefix[i-1][j] && a[i-1] + j <= k)
        prefix[i][j+a[i-1]] = 1;
    }

  suffix[n][0] = 1;
  for(int i = n-1; i >= 0; --i) 
    for(int j = 0; j < k; ++j) {
      if(not suffix[i][j])
        suffix[i][j] = suffix[i+1][j];

      if(suffix[i+1][j] && a[i] + j <= k)
        suffix[i][j+a[i]] = 1;
    }

  int cnt = 0;
  reverse(a, a+n);
  for(int i = 0; i < n; ++i) {
    int l = i;
    int r = i + 1;

    int x = a[i];

    bool need = true;

    for(int j = 0; j <= k; ++j) {
      if(not prefix[l][j])
        continue;

      for(int v = max(0, k - j - x); v < k - j; ++v) {
        if(suffix[r][v]) {
          need = false;
          break;
        }
      }

      if(not need) {
        cnt++;
        break;
      }
    }
  }

