bool check(int T)
{
	if(a[T]>=k) return 0;
	n=0;
	memset(dp,0,sizeof dp);
	for(int i=0;i<N;i++)
	{
		if(i==T) continue;
		b[n++]=a[i];
	}
	dp[0][0]=1;
	if(b[0]<k)dp[0][b[0]]=1;
	bool flag=1;
	for(int i=1;i<n;i++)
	{
		if(b[i]>=k) continue;

		for(int j=0;j<k;j++)
		{
			dp[i][j]=dp[i-1][j];
			if(j>=b[i])dp[i][j]|=dp[i-1][j-b[i]];
			if(dp[i][j]&&k-a[T]<=j&&k>j)
			{
				flag=0;
