#include <array>
template<size_t N>
class INDEX {
    array<size_t, N> arr;

public:
    template<typename... T>
    INDEX(T... _arr)
        : arr({{static_cast<size_t>(_arr)...}}) {}
    template<typename... T>
    size_t operator()(T... _arr) {
        size_t position[] = {static_cast<size_t>(_arr)...};
        static_assert(N == size(position));
        size_t res = 0, width = 1;
        for (int i = N - 1; i >= 0; i--) {
            res += width * position[i];
            width *= arr[i];
        }
        return res;
    }
};
template<typename... T>
auto Index(T... args) {
    unsigned int arr[] = {static_cast<unsigned int>(args)...};
    constexpr size_t N = size(arr);
    return INDEX<N>(args...);
}
template<typename T, typename... Args>
auto make_v_flat(T init, Args... args) {
    return vector<T>((1 * ... * args), init);
}

