bool no_need(int m, const vec<int>& a, int K)
{
  vec<bool> s(K);
  s[0] = true;
  rep(i, 0, SZ(a)) {
    if (i == m) {
      continue;
    }
    rrep(j, 0, K) {
      if (s[j] && j + a[i] < K) {
        s[j + a[i]] = true;
      }
    }
  }

  int MAX = 1e9;
  rrep(i, 0, K) {
    if (s[i]) {
      MAX = i;
      break;
    }
  }

  return MAX + a[m] < K;
}



