bool isValid(int idx, const std::vector<int>& a, int K, long sum) {
    // calc minimum value X which satisfies X >= K
    // if X - a[i] >= K, card i is invalid.

    long X = sum;
    for (int i = a.size()-1; i >= 0; i--) {
        if (i == idx)
            continue;

        if (X - a[i] >= K) {
            X -= a[i];
