signed main() {
	INIT;
	VAR(int, n, k);
	VEC(int, a, n);
	std::sort(ALL(a));
	ll sum = 0;
	REP(i, n) {
		sum += a[i];
	}
	if (sum < k) {
		OUT(n)BR;
		return 0;
	}
	int cnt = 0;
	REP(i, n) {
		if (a[i] >= k) continue;
		int psum = 0;
		bool in = false;
		int p = 0;
		REP(j, n) {
			if (i == j) continue;
			psum += a[j];
			if (IN(k - a[i], psum, k)) in = true;
			while (psum >= k) {
				psum -= a[p++];
				p += p == i;
			}
			if (IN(k - a[i], psum, k)) in = true;
		}
		if (!in) ++cnt;
	}
	OUT(cnt)BR;
	return 0;
}

