ll n,k;

bool use(ll ind,vector<ll> v){

  vector<vector<int>> dp(n,vector<int>(k+1,false));
  if(n-1!=ind)swap(v.at(ind),v.at(n-1));

  dp[0][0]=1;
  rep(i,0,n-1){
    rep(j,0,k+1){
      if(j+v.at(i)>=k)dp[i+1][k]^=dp.at(i)[j];
      else dp[i+1][j+v.at(i)]^=dp.at(i)[j];

      dp[i+1][j]^=dp.at(i)[j];

    }
  }
  //swap(v.at(ind),v.at(n-1));

  rep(j,k-v.at(n-1),k){
    if(dp.at(n-1)[j])return true;
  }

  return false;
}

signed main(){
  cin>>n>>k;
  vector<ll> a(n);
  rep(i,0,n){
    cin>>a.at(i);
  }
  sort(all(a));

  ll need=n,no=-1;

  while(abs(need-no)>1){
    ll mid=(need+no)/2;

    if(use(mid,a)){
      need=mid;
    }else{
      no=mid;
    }
    //sort(all(v));
  }

  cout<<no+1<<endl;
}

