#include <bits/stdc++.h>
using namespace std;

#define MAX_N 5003

int n ,k;
int a[MAX_N];

int main()
{
    scanf("%d%d",&n,&k);
    for(int i=0; i<n; i++)
        scanf("%d",&a[i]);
    sort(a ,a+n);
    n = lower_bound(a ,a+n ,k)-a;

    int ans = n;
    bitset <MAX_N> bs ,all; bs[0] = 1;
    for(int i=0; i<n; i++){
        bool bad = false;
        for(int j=k-a[i]; j<k; j++)
            if(bs[j])
                bad = true;
        if(bad){
            ans--;
            bs |= (bs<<a[i]);
            continue;
        }

        all = bs;
        for(int j=i+1; j<n; j++)
            all |= (all<<a[j]);

        for(int j=k-a[i]; j<k; j++)
            if(all[j]){
                ans--;
                break;
            }

        bs |= (bs<<a[i]);
    }

    printf("%d\n",ans);
}

#include<bits/stdc++.h>
using namespace std;

const int maxn = 5009;
bitset<maxn> suf[maxn], pre[maxn], x;
int a[maxn], n, K, ans = 0, flag;

inline int read(){
	char ch = getchar(); int x = 0;
	while (ch < '0' || '9' < ch) ch = getchar();
	while ('0' <= ch && ch <= '9') { x = x*10+ch-'0'; ch = getchar(); }
	return x;
}

int main(){
	n = read(); K = read();
	for (int i=1; i<=n; i++) a[i] = read();
	pre[0][0] = 1; for (int i=1; i<=n; i++) pre[i] = pre[i-1] | (pre[i-1] << a[i]);
	suf[n+1][0] = 1; for (int i=n; i>=1; i--) suf[i] = suf[i+1] | (suf[i+1] << a[i]);
	for (int i=1; i<=n; i++){
		x = pre[i-1] | suf[i+1]; flag = 1;
		for (int j=max(0, K-a[i]); j<=K-1; j++)
			if (x[j]) { flag = 0; break; }
		ans += flag;
	}
	printf("%d\n", ans);
	return 0;
}

