using namespace std;

long long n, ar[1000001], k, u[1000001];

int main()
{
    cin >> n >> k;
    for(long long i = 1; i <= n; i++)
        scanf("%lld", &ar[i]);

    for(long long i = 1; i <= n; i++)
    {
        long long r = 1, sum = 0;
        for(long long j = 1; j <= n; j++)
        {
            if(r < j)
            {
                r = j;
                sum = 0;
            }
            while((r <= n && sum < k))
            {
                sum += ar[r];
                r++;
            }

            if(i >= j && i < r && sum >= k)
                if(sum - ar[i] < k)
                    u[i] = 1;
            //cout << j << " " << r << endl;
            sum -= ar[j];
            if(i > j && i < r && sum >= k)
                if(sum - ar[i] < k)
                    u[i] = 1;
        }
    }

    for(long long i = 1; i <= n; i++)
    {
        long long r = n, sum = 0;
        for(long long j = n; j > 0; j--)
        {
            if(r > j)
            {
                r = j;
                sum = 0;
            }
            while((r > 0 && sum < k))
            {
                sum += ar[r];
                r--;
            }

            if(i <= j && i > r && sum >= k)
                if(sum - ar[i] < k)
                    u[i] = 1;
            //cout << j << " " << r << endl;
            sum -= ar[j];
            if(i < j && i > r && sum >= k)
                if(sum - ar[i] < k)
                    u[i] = 1;
        }
    }

    long long ans = 0;
    for(long long i = 1; i <= n; i++)
        ans += u[i];

    cout << n - ans;
    return 0;
}

