#define int long long

int N,k;
int a[5050];

bool check(int pos)
{
//	cout<<"check "<<pos<<" : "<<endl;

	if(a[pos]>=k) return false;
	bitset<5050> sumwk(1);
	for(int i=0;i<N;i++)
	{
		if(i!=pos) sumwk|=(sumwk<<a[i]);
	}
//	cout<<sumwk<<endl;
	for(int i=k-a[pos];i<k;i++)
	{
		if(sumwk[i]) return false;
	}
	return true;
}

signed main()
{
//	freopen(".txt","r",stdin);
//	freopen(".out","w",stdout);
	ios::sync_with_stdio(false);

	cin>>N>>k;
	for(int i=0;i<N;i++)
	{
		cin>>a[i];
	}
	sort(a,a+N);

	int sum=0;
	for(int i=0;i<N;i++) sum+=a[i];
	if(sum<k)
	{
		cout<<N<<endl;
		return 0;
	}
	else if(sum==k)
	{
		cout<<0<<endl;
		return 0;
	}

	int L=0,R=N-1,mid;
	while(R-L>=5)
	{
		mid=(L+R)/2;
		if(check(mid)) L=mid; // a[mid] is useless
		else R=mid;
	}
	for(int i=min(R+5,N-1);i>=0;i--)
	{
		if(check(i))
		{
			cout<<i+1<<endl;
			return 0;
		}
	}
	cout<<0<<endl;
}

