ll dfs(int pos,ll sum){
  if(sum>=K) return sum;
  if(Sum[pos+1]+sum<K)return 1LL<<55;
  if(Sum[pos+1]+sum==K) return K;
  if(used[pos][sum]++) return mem[pos][sum];
  ll res=0;
  res=dfs(pos-1,sum+A[pos]);
  if(res>=K&&res-A[pos]<K)ans[pos]=1;
  res=min(res,dfs(pos-1,sum));
  return mem[pos][sum]=res;
}

