void dc(int l, int r, const BS& bs) {
  if (l == r) {
    if (a[l] < k) {
      bool f = true;
      for (int j = k - a[l]; j < k; ++j)
        f &= !bs[j];
      ans += f;
    }
    return;
  }
  int mid = (l + r) >> 1;
  BS rs = bs;
  for (int i = r; i > mid; --i)
    if (a[i] <= k)
      rs |= rs << a[i];
  dc(l, mid, rs);
  BS ls = bs;
  for (int i = l; i <= mid; ++i)
    if (a[i] <= k)
      ls |= ls << a[i];
  dc(mid + 1, r, ls);
}

