	int cnt = 0;

	for(int i = 0; i < N; i++)
	{
		if(ar[i] >= K)
		{
			cnt++;
			continue;
		}
		swap(ar[i], ar[N - 1]);
		runDP();
		swap(ar[i], ar[N - 1]);

		for(int j = 1; j < K; j++)
		{
			if(dp[j])
			{
				if(j + ar[i] >= K)
				{
					//cout<<ar[i]<<" is necessary"<<endl;
					cnt++;
					break;
				}
			}
		}
	}
	cout<<N - cnt<<endl;

	return 0;
}

