using namespace std;

const int MAXN = 5000;
int a[MAXN];
bool poss[MAXN + 1];

bool isNec(int pos, int n, int k)
{
    if (a[pos] >= k)
        return true;
    fill(poss, poss + k, false);
    poss[0] = true;
    for (int i = 0; i < n; i++)
    {
        if (i == pos)
            continue;
        for (int j = k - 1; j >= 0; j--)
        {
            if (poss[j] && j + a[i] <= k - 1)
                poss[j + a[i]] = true;
        }
    }
    for (int i = k - a[pos]; i < k; i++)
    {
        if (poss[i])
            return true;
    }
    return false;
}

int main()
{
    int n, k;
    cin >> n >> k;
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
    }
    sort(a, a + n);
    int ans = -1;
    for (int jump = n / 2 + 1; jump > 0; jump /= 2)
    {
        while (ans + jump < n && !isNec(ans + jump, n, k))
            ans += jump;
    }
    cout << ans + 1 << endl;
    return 0;
}

