    cin >> A[i];
  }

  dp1[0][0] = true;
  for(int i = 0; i < N; i++) {
    for(int j = 0; j <= K; j++) {
      dp1[i + 1][min(j + A[i], K)] |= dp1[i][j];
      dp1[i + 1][j] |= dp1[i][j];
    }
  }
  dp2[N][0] = true;
  for(int i = N; i > 0; i--) {
    for(int j = 0; j <= K; j++) {
      dp2[i - 1][min(j + A[i - 1], K)] |= dp2[i][j];
      dp2[i - 1][j] |= dp2[i][j];
    }
  }

  int ret = N;
