s64 N;
s64 K;

vector<s64> A;

vector<deque<bool>> dp;

bool need(int k)
{
    s64 n = SIZE(A);

    vector<s64> v(A);
    v.erase(begin(v)+k);

    // i枚目までで総和jを作れるか
    for(auto& row : dp) {
        ALL(fill, row, false);
    }
    dp[0][0] = true;

    FOR(i, 1, n) REP(j, K+1) {
        s64 a = v[i-1];
        dp[i][j] = dp[i][j] || dp[i-1][j];
        if(j >= a) {
            dp[i][j] = dp[i][j] || dp[i-1][j-a];
        }
    }

    FOR(j, max<s64>(0,K-A[k]), K) {
        if(dp[n-1][j]) return true;
    }

    return false;
}

void solve()
{
    // 必ず不要なものと必ず必要なものを加える(二分探索を簡明にするため)
    A.emplace_back(0);
    A.emplace_back(INF);
    ALL(sort, A);

    s64 n = SIZE(A);

    dp.assign(n, deque<bool>(K+1, false));

    s64 hi = n-1; // 常に必要
    s64 lo = 0;   // 常に不要
    while(hi - lo > 1) {
        s64 mid = (hi+lo) / 2;
        if(need(mid)) {
            hi = mid;
        }
        else {
            lo = mid;
        }
    }
    s64 ans = lo;

    PRINTLN(ans);
}

