int ans;

inline void precalc() {
	dp[0][0][0] = dp[1][n+1][0] = true;
	for(int i = 1; i <= n; ++i)
		dp[0][i] = dp[0][i-1] | (dp[0][i-1] << a[i]);
	for(int i = n; i; --i)
		dp[1][i] = dp[1][i+1] | (dp[1][i+1] << a[i]);
	for(int i = 1; i <= n; ++i) {
		p[i][0] = 1;
		for(int j = 1; j <= k; ++j)
			p[i][j] = p[i][j-1] + dp[0][i][j];
	}
}

inline int get(int i, int l, int r) {
	if(!l)
		return p[i][r];
	if(l > r)
		return 0;
	return p[i][r] - p[i][l-1];
}

main() {
	scanf("%d %d", &n, &k);
	for(int i = 1; i <= n; ++i)
		scanf("%d", &a[i]);
	precalc();
	for(int i = 1; i <= n; ++i) {
		bool flag = false;
		for(int j = 0; j < k; ++j) {
			if(dp[1][i+1][j] && (j + a[i] >= k || get(i - 1, max(0, k - j - a[i]), k - j - 1))) {
				flag = true;
				break;
			}
		}
		flag |= get(i - 1, max(0, k - a[i]), k - 1) != 0;
		ans += !flag;
	}
	printf("%d\n", ans);
    return 0;
}

