int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, K;
    cin >> n >> K;
    vector<ll> a;
    for (int i = 0; i < n; i++) {
        ll x;
        cin >> x;
        if (x >= K) continue;
        a.push_back(x);
    }
    sort(a.begin(), a.end());

    n = a.size();
    vector< vector<int> > dpl(n + 1, vector<int>(K, false));
    dpl[0][0] = true;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < K; j++) {
            dpl[i + 1][j] = dpl[i][j];
            if (j >= a[i] && dpl[i][j - a[i]]) dpl[i + 1][j] = true;
        }
    }

    vector< vector<int> > dpr(n + 1, vector<int>(K, false));
    dpr[n][0] = true;
    for (int i = n - 1; i >= 0; i--) {
        for (int j = 0; j < K; j++) {
            dpr[i][j] = dpr[i + 1][j];
            if (j >= a[i] && dpr[i + 1][j - a[i]]) dpr[i][j] = true;
        }
    }

    int ans = 0;
    for (int i = 0; i < n; i++) {
        int k = K - 1;
        int cnt = 0;
        while (k >= 0) {
            cnt += dpr[i + 1][k];
            if (k + a[i] == K) break;
            k--;
        }
        //cerr << k << " " << cnt << endl;
        if (cnt > 0 && dpl[i][0]) break;
        bool f = true;
        for (int j = 1; j < K; j++) {
            cnt -= dpr[i + 1][K - j];
            while (k >= 0) {
                if (j + a[i] + k == K) break;
                cnt += dpr[i + 1][k];
                k--;
            }
            if (k < 0) break;
            if (cnt > 0 && dpl[i][j]) {
                //cerr << j << " " << k << endl;
                f = false;
                break;
            }
        }
        ans += f;
    }
    cout << ans << "\n";
    return 0;
}

