bool isValid(int idx, const std::vector<long>& a, int K) {
    // calc minimum value X which satisfies X >= K
    // if X - a[i] >= K, card i is invalid.

    std::memset(subsetSum, false, K_MAX);
    subsetSum[0] = true;

    for (int i = 0; i < a.size(); i++) {
        if (i == idx) {
            continue;
        }

        // printf("a[i]: %d\n", a[i]);
        for (int j = K-1; j >= a[i]; j--) {
            // printf("j: %d, subsetSum[j]: %d, subsetSum[j - a[i]]: %d\n",
            //        j, subsetSum[j], subsetSum[j - a[i]]);
            subsetSum[j] |= subsetSum[j - a[i]];
        }
    }

    for (int i = std::max<long>(0, K - a[idx]); i < K; i++) {
        if (subsetSum[i]) {
            return true;
        }
    }

    return false;
}

