int N, K;
vector<ll> a;
bool dp[5050] = {};

bool ok(ll in){
	if(in >= N) return true;
	memset(dp, 0, sizeof(dp));
	dp[0] = true;
	REP(i, N){
		if(i == in) continue;
		for(int j = K+1;j >= a[i];j--){
			if(dp[j-a[i]]) dp[j] = true;
		}
	}
	FOR(i, max(0, (int)K-(int)a[in]), K){
		if(dp[i]){
			return true;
		}
	}
	return false;
}

int main(void){
	cin >> N >> K;
	REP(i, N){
		int A;
		cin >> A;
		a.push_back(A);
	}
	int l = 0, r = N, m;
	sort(all(a));
	while(r-l > 1){
		m = (l+r)/2;
		if(ok(m)){
			r = m;
		}else{
			l = m;
		}
	}
	if(ok(l)){
		cout << l << endl;
	}else if(ok(r)){
		cout << l+1 << endl;
	}else{
		cout << r+1 << endl;
	}
}

