int dp(int i, int k) {
    if(i==0) return 0;
    int &cache = dp_cache[i][k];
    if(cache!=-1) return cache;
    int ans=dp(i-1, k);

    if(k>a[i]) {
        int xx = dp(i-1, k-a[i]);
        if(xx>0){
	        ans+=xx;
