	            v[k][i]=1;
	            use[k].push_back(i);
	        }
    	}
    }
    if(a[i]>=k) {
        ans++;
        if(!v[k][i]) {
            v[k][i]=1;
            use[k].push_back(i);
        }
    }
    return cache=ans;
}

