int n, k, w[5010];
bool pref[5010][5010], suff[5010][5010];
int cnt[5010];

int main()
{
	ios_base::sync_with_stdio(0);
	//cin.tie(0);
#ifdef MYDEBUG
	freopen("input.txt", "r", stdin);
	freopen("output.txt", "w", stdout);
#else
	/*freopen(TASK".in", "r", stdin);
	freopen(TASK".out", "w", stdout);*/
	/*freopen("pie_progress.txt", "r", stdin);
	freopen("pie_progress_output.txt", "w", stdout);*/
#endif

	scanf("%d %d", &n, &k);
	for (int i = 1; i <= n; ++i)
	{
		scanf("%d", &w[i]);
	}

	pref[0][0] = true;
	for (int i = 1; i <= n; ++i)
	{
		for (int j = 0; j <= k; ++j)
		{
			pref[i][j] = pref[i - 1][j];
			if (w[i] <= j)
				pref[i][j] |= pref[i - 1][j - w[i]];
		}
	}
	suff[n + 1][0] = true;
	for (int i = n; i >= 1; --i)
	{
		for (int j = 0; j <= k; ++j)
		{
			suff[i][j] = suff[i + 1][j];
			if (w[i] <= j)
				suff[i][j] |= suff[i + 1][j - w[i]];
		}
	}

	int ans = 0;
	for (int x = 1; x <= n; ++x)
	{
		for (int j = 0; j <= k; ++j)
			cnt[j] = suff[x + 1][j] ? 1 : 0;
		for (int j = 1; j <= k; ++j)
			cnt[j] += cnt[j - 1];
		bool good = true;
		for (int val = 0; val <= k; ++val)
		{
			if (pref[x - 1][val])
			{
				int ll = k - w[x] - val, rr = k - 1 - val;
				ll = max(0, ll);
				rr = min(rr, k - 1);
				if (ll <= rr)
				{
					if (ll == 0 && cnt[rr] > 0)
						good = false;
					else if (ll > 0 && cnt[rr] - cnt[ll - 1] > 0)
						good = false;
				}
			}
		}
		if (good)
			++ans;
	}
	printf("%d\n", ans);

	my_return(0);
}

