bool cmp(int u, int v) {
  return u > v;
}

int main(int argc, char const *argv[]) {
  int n, k;
  scanf("%d%d", &n, &k);
  long long sum = 0;
  for (int i = 1; i <= n; ++i) {
    scanf("%lld", &a[i]);
    sum += a[i];
  }
  sort(a + 1, a + n + 1, cmp);
  int ans = 0;
  dp[0] = 1;
  for (int i = 1; i <= n; ++i) {
    bool flag = false;
    for (int j = 0; j < k; ++j) {
      if (dp[j] == 1 && j + sum >= k) {
        flag = true;
        break;
      } 
    }
    if (!flag) {
      ans = n - i + 1;
      break;
    }
    sum -= a[i];
    for (int j = k - 1; j >= a[i]; --j) {
      dp[j] |= dp[j - a[i]];
    }
  }
  printf("%d\n", ans);
  return 0;
}

