const int M = 10001;

inline ANDREIKKAA_RETURN_TYPE mainFunction(ANDREIKKAA_PARAMETERS)
{
	int n, k;
	cin >> n >> k;
	vector<bitset<M>> suf(n + 1);

	vector<int> a(n);
	cin >> a;

	suf[n][0] = 1;
	for (int i = n - 1; i >= 0; --i)
	{
		suf[i] = suf[i + 1] | (suf[i + 1] << a[i]);
		if (a[i] <= M)
		{
			suf[i] |= (suf[i + 1] << a[i]);
		}
	}

	bitset<M> now;
	now[0] = 1;
	int ans = 0;
	for (int i = 0; i < n; ++i)
	{
		if (a[i] < k)
		{
			int sum = 0;
			for (int j = k - a[i]; j < k; ++j)
			{
				sum += now[j];
			}
			for (int j = 0; j < k; ++j)
			{
				if (suf[i + 1][j] && sum > 0)
				{
					++ans;
					break;
				}
				sum -= now[k - j - 1];
				if (k - j - a[i] - 1 >= 0)
				{
					sum += now[k - j - a[i] - 1];
				}
			}
		}
		else
		{
			++ans;
		}

		if (a[i] <= M)
		{
			now |= (now << a[i]);
		}
	}
	cout << n - ans << endl;
}

