int n, k;
vector<int> v;

bool test(int id){

	if(v[id] >= k) return true;

	vector<bool> possible(5010);
	possible[0] = true;

	for(int i = 0 ; i < n ; i ++){
		if(i == id) continue;
		for(int j = k - 1 ; j >= 0 ; j --){
			if(possible[j] && j + v[i] < k)
				possible[j + v[i]] = true;
		}
	}

	for(int i = k - v[id] ; i < k ; i ++)
		if(possible[i]) return true;

	return false;
}

int main(){

	ios_base :: sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> k;
	v.resize(n);

	for(int i = 0 ; i < n ; i ++)
		cin >> v[i];

	sort(v.begin(), v.end());

	int ans = 0;
	int l = 0, r = n - 1;

	while(l <= r){
		int mid = (l + r)/2;
		if(test(mid)){
			r = mid - 1;
		} else {
			ans = mid + 1;
			l = mid + 1;
		}
	}

	cout << ans << "\n";

	return 0;
}

