int A[5050];
set<int>L[5050];
set<int>R[5050];

int main(){

    int N, K;
    cin >> N >> K;
    for(int i = 1; i <= N; i++){
        cin >> A[i];
    }

    L[0].insert(0);
    L[0].insert(K);
    for(int i = 1; i <= N; i++){
        for(set<int>::iterator it = L[i-1].begin(); it != L[i-1].end(); it++){
            L[i].insert(*it);
            int nxt = (*it) + A[i];
            if(nxt <= K)L[i].insert(nxt);
        }
    }
    R[N + 1].insert(0);
    R[N + 1].insert(K);
    for(int i = N; i >= 1; i--){
        for(set<int>::iterator it = R[i+1].begin(); it != R[i+1].end(); it++){
            R[i].insert(*it);
            int nxt = (*it) + A[i];
            if(nxt <= K)R[i].insert(nxt);
        }
    }

    int ans = 0;
    for(int i = 1; i <= N; i++){
        if(A[i] >= K)continue;
        int f = 1;
        for(set<int>::iterator it = L[i-1].begin(); it != L[i-1].end(); it++){
            int l = *it;
            int r = *R[i + 1].lower_bound(K - A[i] - l);
            if(r < K - l)f = 0;
        }
        if(f)ans++;
    }
    cout << ans << endl;

    return 0;
}

