    for(int i=0; i < n; ++i) {
        auto tmp = dp[i / width];
        for(int j = i / width * width; j < min(n, (i / width + 1) * width); ++j) {
            if(j == i) continue;
            tmp |= tmp << a[j];
        }

        bool add = true;
        for(int k = K - a[i]; k < K; ++k) {
            if(tmp[k] == 1) {
                add = false;
                break;
            }
        }
        if(add) ++ans;
    }

    cout << ans << '\n';
    return 0;
}

