bool is_i_needed(ll N, ll K, vector<ll>& As, int i) {
    // 任意のカードの組み合わせで作成可能な数を列挙
    // ただしK未満
    bool flip = true;
    vector<vector<int>> possible(K, vector<int>(2));
    possible[0][flip] = 1;
    REP(j, N) {
        if (i == j) continue;
        flip = !flip;
        auto a = As[j];
        vector<int> added(K);
        REP(j, K) {
            if (possible[j][!flip]) {
                possible[j][flip] = 1;
            }
            if (possible[j][!flip] && (j + a) < K) {
                possible[j + a][flip] = 1;
            }
        }
    }

    FOR(j, max(0LL, K - As[i]), K) {
        if (possible[j][flip]) {
            return true;
        }
    }
    return false;
}


int main(void)
{
    cin.sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<ll> As(N);
    REP(n, N) cin >> As[n];

    // 単調性を利用
    // x: no need
    // o: need
    //
    // 1 3 4, K = 6
    // x o o
    //
    // 1 1 3 4 5, K = 400
    // x x x x x
    // この場合例外なので別途処理が必要
    //
    // 2 3 4 10 10 25, K = 6
    // x x x o  o  o
    //

    if (!is_i_needed(N, K, As, N - 1)) {
        cout << N << endl;
        return 0;
    }

    int lo = 0;
    int hi = N - 1;
    while (lo < hi) {
        auto k = (lo + hi) / 2;
        if (is_i_needed(N, K, As, k)) {
            hi = k;
        } else {
            lo = k + 1;
        }
    }

    cout << lo << endl;
    return 0;
}

