bool check(int x) {
  for (int i = 0; i <= N; i++) 
    for (int j = 0; j < K; j++) DP[i][j] = false;
  DP[0][0] = true;

  for (int i = 0; i < N; i++) {
    for (int j = 0; j < K; j++) {
      bool flag = DP[i][j];
      int k = j - A[i];
      if (i != x && k >= 0) flag |= DP[i][k];
      DP[i + 1][j] = flag;
    }
  }

