        for(int j = 0; j < 5002; j++) {
            dpb[i][j] = dpb[i + 1][j];
            if(j - a[i - 1] >= 0 && dpb[i + 1][j - a[i - 1]]) {
                dpb[i][j] = true;
            }
        }
    }
    vector<vector<int>> front(n + 2), back(n + 2);
    for(int i = 1; i <= n; i++) {
        for(int k = 0; k < 5002; k++) {
            if(dpf[i][k]) {
                front[i].push_back(k);
            }
