    if(itr != back[2].end() && *itr < k) {
        ans++;
    }
    // n番目が必要かどうか
    itr = lower_bound(all(front[n - 1]), k - a[n - 1]);
    if(itr != front[n - 1].end() && *itr < k) {
        ans++;
    }
    for(int i = 2; i < n; i++) {
        int tmp = 0;
        for(auto x : front[i - 1]) {
            auto itr2 = lower_bound(all(back[i + 1]), k - a[i - 1] - x);
            if(itr2 != back[i + 1].end() && *itr2 < k - x) {
                tmp = 1;
            }
        }
        ans += tmp;
    }
    cout << n - ans << endl;
}

