/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

void solve(){
    // generate_array(size, min, max);
    ll n, k; vl as;
    in2(n, k);
    read_vector(n, as);
    vb3 dp(2, vb2(n + 1, vb(k, false)));
    rep(i, n + 1) dp[0][i][0] = dp[1][i][0] = true;
    For(i, 1, n + 1) For(v, 1, k){
        ll v1 = as[i - 1], v2 = as[n - i];
        dp[0][i][v] = dp[0][i - 1][v];
        dp[1][i][v] = dp[1][i - 1][v];
        if (v - v1 >= 0 && !dp[0][i][v]) dp[0][i][v] = dp[0][i - 1][v - v1];
        if (v - v2 >= 0 && !dp[1][i][v]) dp[1][i][v] = dp[1][i - 1][v - v2];
    }

    ll answer = n;
    rep(i, n){
        vl vs; ll v0 = as[i];
        if (v0 >= k) {answer--; continue;}
        rep(v, k) if (dp[0][i][v]) vs.pb(v);
        rep(v, k){
            if (!dp[1][n - 1 - i][v]) continue;
            // k - v - v0 <= x <= k - v - 1
            auto lb = lower_bound(all(vs), k - v - v0);
            if (lb != vs.end() && *lb <= k - v - 1){
                answer--; break;
            }
        }
    }

    prl(answer);
    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

void test(ll num = 0, bool verbose = false){
    rep(i, max(1LL, num)){
        ll t = clock();
        if (verbose) prl4("\n#####", i + 1, "#####", "\n## Answer ##");
        solve();
        if (verbose) {prl(""); prl_time(t);}
    }
}

