ll bisection(ll low, ll high, std::function<bool(ll)> check) {
	if (high - low == 1) return low;
	ll mid = (high + low) / 2;
	if (check(mid)) return bisection(mid, high, check);
	else            return bisection(low, mid, check);
}

signed main() {
	INIT;
	VAR(int, n, k);
	VEC(int, a, n);
	int sum = 0;
	REP(i, n) sum += a[i];
	if (sum < k) {
		OUT(n)BR;
		return 0;
	}
	a.emplace_back(0);
	std::sort(ALL(a));
	++n;
	auto check = [&](int i) { // no need -> true, need -> false
		if (a[i] >= k) return false;
		std::vector<std::vector<bool>> used(2, std::vector<bool>(k, false));
		int p = 0;
		REP(j, n) {
			if (i == j) continue;
			if (a[j] >= k) continue;
			if (a[j] >= k - a[i]) return false;
			int now = p % 2;
			int next = (p + 1) % 2;
			REP(l, k) used[next][l] = used[now][l];
			used[next][a[j]] = true;
			REP(l, k) {
				if (!used[now][l]) continue;
				if (l + a[j] < k) {
					if (l + a[j] >= k - a[i]) return false;
					used[next][l + a[j]] = used[now][l];
				}
			}
			++p;
		}
		return true;
	};
	int t = bisection(0, n - 1, check);
	while (check(t)) ++t;
	OUT(t - 1)BR;
	return 0;
}

