#include<stdio.h>

void QSort(int x[ ], int left, int right);
void Swap(int x[ ], int i, int j);
void reverse(int array[], int length);

void QSort(int x[ ], int left, int right)
{
    int i, j;
    int pivot;
    i = left;                      
    j = right;
    pivot = x[(left + right) / 2]; 
    while (1) {                    
        while (x[i] < pivot)       
            i++;

        while (pivot < x[j])       
            j--;                 
        if (i >= j)              
            break;              

        Swap(x, i, j);            
        i++;                       
        j--;
    }

    if (left < i - 1)              
        QSort(x, left, i - 1);    
    if (j + 1 <  right)            
        QSort(x, j + 1, right);    
}

void Swap(int x[ ], int i, int j)
{
    int temp;
    temp = x[i];
    x[i] = x[j];
    x[j] = temp;
}

void reverse(int array[], int length)
{
    int i, j;
    int temp;

    for( i = 0, j = length - 1; i < j; i++, j-- )
    {
        temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

