int calc(int *a,int n,int k,char *dp){
  if(n==1){
    if(a[0]>=k) return 0;
    for(int i=k-1;i>=k-a[0];i--) if(dp[i]) return 0;
    return 1;
  }
  int m=n/2;
  char *save=(char *)calloc(k,sizeof(char));
  memcpy(save,dp,k);
  int i,j;
  for(i=m;i<n;i++){
    if(a[i]>=k) continue;
    for(j=k-1;j>=a[i];j--) dp[j]|=dp[j-a[i]];
  }
  int cnt=calc(a,m,k,dp);
  memcpy(dp,save,k);
  free(save);
  for(i=0;i<m;i++){
    if(a[i]>=k) continue;
    for(j=k-1;j>=a[i];j--) dp[j]|=dp[j-a[i]];
  }
  cnt+=calc(a+m,n-m,k,dp);
  return cnt;
}

