void sort(unsigned long *a, int N) {
    int i, j, min;
    for (i = 0; i < N - 1; i++) {
        min = i;
        for (j = i + 1; j < N; j++) {
            if (a[min] > a[j]) min = j;
        }
        if (min != i) {
            unsigned long tmp = a[i];
            a[i] = a[min];
            a[min] = tmp;
        }
    }
}

int minGoodSet(unsigned long *a, int N, int K, int except) {
    int i, j;
    int *p;
    p = malloc(K * sizeof(int));
    p[0] = 0;
    for (i = 1; i < K; i++) {
        p[i] = -1;
    }
    i = N - 1;
    while(a[i] > K) i--;
//    printf("except:%d i:%d\n", except, i);
    while(i >= 0) {
        if (i == except) {
            i--;
            continue;
        }
        for (j = 0; j < K - a[i]; j++) {
            if (p[j] != -1 && p[j] != (int)a[i] && p[j + a[i]] == -1) {
                p[j + a[i]] = (int)a[i];
            }
        }
        i--;
    }
//    for (i = 0; i < K; i++) {
//        printf("%d ", p[i]);
//    }
//    printf("\n");
    for (i = K - (int)a[except]; i < K; i++) {
        if (p[i] != -1) return 1;
    }
    return 0;
}

