typedef int32_t i32;

int cmp (const void *a, const void *b) {
  i32 d = *(i32 *)a - *(i32 *)b;
  return d == 0 ? 0 : d < 0 ? -1 : 1;
}

void run (void) {
  i32 n, k;
  scanf ("%" SCNi32 "%" SCNi32, &n, &k);
  i32 *a = (i32 *) calloc (n, sizeof (i32));
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, a + i);
  }
  qsort (a, n, sizeof (i32), cmp);
  const i32 bit_num = 8 * sizeof (uint64_t);
  i32 len = (k + bit_num - 1) / bit_num;
  uint64_t *dp = (uint64_t *) calloc (len + 1, sizeof (uint64_t));
  i32 l = -1;
  i32 r = n;
  while (r - l > 1) {
    i32 m = (l + r) / 2;
    memset (dp, 0, sizeof (uint64_t) * len);
    dp[0] = 1;
    for (i32 i = 0; i < n; ++i) {
      if (i == m) continue;
      i32 p = a[i] / bit_num;
      i32 q = a[i] % bit_num;
      if (q == 0) {
        for (i32 i = len - 1 - p; i >= 0; --i) {
          dp[i + p] |= dp[i];
        }
        continue;
      }
      for (i32 i = len - 1 - p; i >= 0; --i) {
        uint64_t x = dp[i];
        dp[i + p] |= x << q;
        dp[i + p + 1] |= x >> (bit_num - q);
      }
    }
    i32 i = k - 1;
    for (; !(1 & (dp[i / bit_num] >> (i % bit_num))); --i);
    if (i + a[m] >= k) {
      r = m;
    } else {
      l = m;
    }
  }
  printf ("%" PRIi32 "\n", r);
}

int main (void) {
  run();
  return 0;
}

