    int i, j, min;
    for (i = 0; i < N - 1; i++) {
        min = i;
        for (j = i + 1; j < N; j++) {
            if (a[min] > a[j]) min = j;
        }
        if (min != i) {
            unsigned long tmp = a[i];
            a[i] = a[min];
            a[min] = tmp;
        }
    }
}

