		TreeSet<Integer> set = new TreeSet<>();
		ArrayList<TreeSet<Integer>> a1 = new ArrayList<>();
		ArrayList<TreeSet<Integer>> a2 = new ArrayList<>();
		for(int i = 0; i < N; i++){
			a1.add(null);
			a2.add(null);
		}

		set.add(0);
		a1.set(0, set);
		for(int i = 0; i < N - 1; i++){
			TreeSet<Integer> ns = new TreeSet<>();
			for(int v : a1.get(i)){
				ns.add(v);
				if(v + A[i] < K){
					ns.add(v + A[i]);
				}
			}
			a1.set(i + 1, ns);
		}

		set = new TreeSet<>();
		set.add(0);
		a2.set(N - 1, set);
		for(int i = N - 1; i > 0; i--){
			TreeSet<Integer> ns = new TreeSet<>();
			for(int v : a2.get(i)){
				ns.add(v);
				if(v + A[i] < K){
					ns.add(v + A[i]);
				}
			}
			a2.set(i - 1, ns);
		}


		for(int i = 0; i < N; i++){
