    l[0] = BigInteger.ONE;
    r[n + 1] = BigInteger.ONE;

    for (int i = 0; i < n; i++) {
      for (int j = 0; j <= k; j++) {
        l[i + 1] = a[i] > k ? l[i] : l[i].or(l[i].shiftLeft(a[i])).and(mask);
      }
    }

    for (int i = n + 1; i >= 2; i--) {
      for (int j = 0; j <= k; j++) {
        r[i - 1] = a[i - 2] > k ? r[i] : r[i].or(r[i].shiftLeft(a[i - 2])).and(mask);
