		int moreK = 0;
		while (n > 0 && a[n-1] >= K) {
			moreK++;
			n--;
		}
		if (n == 0) {
			System.out.println(0);
			return;
		}
		/*
		long sum = 0;
		for (int x : a) sum += x;
		if (sum < K) {
			System.out.println(moreK + n);
			return;
		}
		*/

		a = Arrays.copyOf(a, n);

		// from left
		boolean[] dpL = new boolean[K+1];
		ArrayList<Integer>[] listL = new ArrayList[n];
		for (int i = 0; i < n; i++) {
			listL[i] = new ArrayList<>();
		}
		dpL[0] = true;
		for (int i = 0; i < n; i++) {
			for (int j = K; j >= 0; j--) {
				if (!dpL[j]) continue;
				listL[i].add(j);
				if (j + a[i] <= K)
					dpL[j+a[i]] = true;
			}
		}

		// from right
		boolean[] dpR = new boolean[K+1];
		ArrayList<Integer>[] listR = new ArrayList[n];
		for (int i = 0; i < n; i++) {
			listR[i] = new ArrayList<>();
		}
		dpR[0] = true;
		for (int i = n - 1; i >= 0; i--) {
			for (int j = K; j >= 0; j--) {
				if (!dpR[j]) continue;
				listR[i].add(j);
				if (j + a[i] <= K)
					dpR[j+a[i]] = true;
			}
		}

		// search
		int res = 0;
		for (int i = 0; i < n; i++) {
			res++;
			// listL[i], listR[i]
			for (int next : listL[i]) {
				int d = K - next;

				int lo = -1, hi = listR[i].size() - 1;
				while (hi - lo > 1) {
					int mid = (lo + hi) / 2;
					if (listR[i].get(mid) >= d)
						lo = mid;
					else
						hi = mid;
				}
				int s = next + listR[i].get(hi);
				if (s + a[i] >= K) {
					// System.out.println("need :" + a[i] + ", " + s + " " + next + " " + listR[i].get(hi));
					res--;
					break;
				}
			}
		}
		System.out.println(res);
	}

