import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            new Main().solve(in);
        }
    }

    private int N, K;
    private long[] a;
    private boolean[] nes;
    private boolean[] use;

    private void solve(Scanner in) {
        N = in.nextInt();
        K = in.nextInt();
        a = new long[N];
        nes = new boolean[N];
        use = new boolean[N];
        for (int i = 0; i < N; i++) {
            a[i] = in.nextInt();
        }
        dfs(0, 0);
        int ans = 0;
        for (int i = 0; i < N; i++) {
            if (!nes[i]) {
                ans++;
            }
        }
        System.out.println(ans);
    }

    void dfs(int i, long k) {
        if (k >= K) {
            for (int j = 0; j < N; j++) {
                if (use[j]) {
                    if (k - a[j] < K) {
                        nes[j] = true;
                    }
                }
            }
        }
        if (i == N) {
            return;
        }
        use[i] = true;
        dfs(i + 1, k + a[i]);
        use[i] = false;
        dfs(i + 1, k);
    }
}

