public class Main {
  private static void solve() {
    int n = ni();
    int k = ni();
    int[] a = na(n);

    BitSet[] l = new BitSet[n + 2];
    BitSet[] r = new BitSet[n + 2];
    for (int i = 0; i < n + 2; i ++) {
      l[i] = new BitSet();
      r[i] = new BitSet();
    }

    l[0].set(0);;
    r[n + 1].set(0);

    for (int i = 0; i < n; i++) {
      for (int j = 0; j <= k; j++) {
        if (l[i].get(j) || j >= a[i] && l[i].get(j - a[i])) {
          l[i + 1].set(j);
        }
      }
    }

    for (int i = n + 1; i >= 2; i--) {
      for (int j = 0; j <= k; j++) {
        if (r[i].get(j) || j >= a[i - 2] && r[i].get(j - a[i - 2])) {
          r[i - 1].set(j);
        }
      }
    }

    int[][] rsum = new int[n + 2][k + 2];
    for (int i = 1; i <= n + 1; i++) {
      for (int j = 0; j <= k; j++) {
        rsum[i][j + 1] = (r[i].get(j) ? 1 : 0) + rsum[i][j];
      }
    }

    int ret = 0;
    for (int i = 1; i <= n; i++) {
      int v = a[i - 1];

      for (int s = 0; s <= k; s++) {
        if (l[i - 1].get(s)) {
          if (rsum[i + 1][Math.max(k - v - s, 0)] != rsum[i + 1][k - s]) {
            ret ++;
            break;
          }
        }
      }
    }
    System.out.println(n - ret);
  }

