	public void solve() {
		int N = in.nextInt();
		int K = in.nextInt();
		int[] a = in.nextIntArray(N);

		Arrays.sort(a);

		int n = N;
		int moreK = 0;
		while (n > 0 && a[n-1] >= K) {
			moreK++;
			n--;
		}
		if (n == 0) {
			System.out.println(0);
			return;
		}
		/*
		long sum = 0;
		for (int x : a) sum += x;
		if (sum < K) {
			System.out.println(moreK + n);
			return;
		}
		*/

		a = Arrays.copyOf(a, n);

		// from left
		boolean[] dpL = new boolean[K+1];
		int[][] listL = new int[K+1][];
		dpL[0] = true;
		for (int i = 0; i < n; i++) {
			int size = 0;
			for (int j = K; j >= 0; j--) {
				if (dpL[j]) size++;
			}
			listL[i] = new int[size];
			for (int ptr = 0, j = K; j >= 0; j--) {
				if (!dpL[j]) continue;

				listL[i][ptr++] = j;
				if (j + a[i] <= K)
					dpL[j+a[i]] = true;
			}
		}

		// from right
		boolean[] dpR = new boolean[K+1];
		int[][] listR = new int[K+1][];
		dpR[0] = true;
		for (int i = n - 1; i >= 0; i--) {
			int size = 0;
			for (int j = K; j >= 0; j--) {
				if (dpR[j]) size++;
			}

			listR[i] = new int[size];
			for (int ptr = 0, j = K; j >= 0; j--) {
				if (!dpR[j]) continue;
				listR[i][ptr++] = j;
				if (j + a[i] <= K)
					dpR[j+a[i]] = true;
			}
		}

		// search
		int res = 0;
		for (int i = 0; i < n; i++) {
			res++;
			// listL[i], listR[i]
			for (int next : listL[i]) {
				int d = K - next;

				int lo = -1, hi = listR[i].length- 1;
				while (hi - lo > 1) {
					int mid = (lo + hi) / 2;
					if (listR[i][mid] >= d)
						lo = mid;
					else
						hi = mid;
				}
				int s = next + listR[i][hi];
				if (s + a[i] >= K) {
					// System.out.println("need :" + a[i] + ", " + s + " " + next + " " + listR[i].get(hi));
					res--;
					break;
				}
			}
		}
		System.out.println(res);
	}

