    static class DNoNeed {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            IntegerArrayList list = new IntegerArrayList(n);
            int k = in.readInt();

            int ans = 0;
            for (int i = 0; i < n; i++) {
                int x = in.readInt();
                if (x >= k) {
                    ans++;
                    continue;
                }
                list.add(x);
            }

            int[] data = list.toArray();
            int[] revData = data.clone();
            SequenceUtils.reverse(revData);

            BitSet[] l2r = gen(data, k);
            BitSet[] r2l = gen(revData, k);
            SequenceUtils.reverse(r2l, 0, r2l.length - 1);
            for (int i = 0; i < data.length; i++) {
                BitSet left = l2r[i];
                BitSet right = r2l[i + 1];
                int min = find(left, right, k - data[i]);
                if (min < k) {
                    ans++;
                }
            }

            out.println(n - ans);
        }

        public int find(BitSet a, BitSet b, int threshold) {
            int m = a.capacity();
            int l = 0;
            int r = m - 1;
            int ans = m;
            while (l < m && r >= 0) {
                if (!a.get(l)) {
                    l++;
                    continue;
                }
                if (!b.get(r)) {
                    r--;
                    continue;
                }
                if (l + r >= threshold) {
                    ans = Math.min(ans, l + r);
                    r--;
                } else {
                    l++;
                }
            }

            return ans;
        }

        public BitSet[] gen(int[] data, int k) {
            int n = data.length;
            BitSet[] ans = new BitSet[n + 1];
            ans[0] = new BitSet(k);
            ans[0].set(0);
            for (int i = 0; i < n; i++) {
                ans[i + 1] = new BitSet(ans[i]);
                ans[i + 1].rightShift(data[i]);
                ans[i + 1].or(ans[i]);
            }
            return ans;
        }

    }

    static class IntegerArrayList implements Cloneable {
        private int size;
        private int cap;
        private int[] data;
        private static final int[] EMPTY = new int[0];

        public IntegerArrayList(int cap) {
            this.cap = cap;
            if (cap == 0) {
                data = EMPTY;
            } else {
                data = new int[cap];
            }
        }

        public IntegerArrayList(IntegerArrayList list) {
            this.size = list.size;
            this.cap = list.cap;
            this.data = Arrays.copyOf(list.data, size);
        }

        public IntegerArrayList() {
            this(0);
        }

        public void ensureSpace(int req) {
            if (req > cap) {
                while (cap < req) {
                    cap = Math.max(cap + 10, 2 * cap);
                }
                data = Arrays.copyOf(data, cap);
            }
        }

        public void add(int x) {
            ensureSpace(size + 1);
            data[size++] = x;
        }

        public void addAll(int[] x, int offset, int len) {
            ensureSpace(size + len);
            System.arraycopy(x, offset, data, size, len);
            size += len;
        }

        public void addAll(IntegerArrayList list) {
            addAll(list.data, 0, list.size);
        }

        public int[] toArray() {
            return Arrays.copyOf(data, size);
        }

        public String toString() {
            return Arrays.toString(toArray());
        }

        public boolean equals(Object obj) {
            if (!(obj instanceof IntegerArrayList)) {
                return false;
            }
            IntegerArrayList other = (IntegerArrayList) obj;
            return SequenceUtils.equal(data, 0, size - 1, other.data, 0, other.size - 1);
        }

        public int hashCode() {
            int h = 1;
            for (int i = 0; i < size; i++) {
                h = h * 31 + Integer.hashCode(data[i]);
            }
            return h;
        }

        public IntegerArrayList clone() {
