				dp1[i + 1][cur] += dp1[i][cur];
			}
		}
		int res = 0;
		for (int i = 0 ; i < n ; ++i) {
			for (int cur = 0 ; cur <= maxSum ; ++cur) {
				dp2[i][cur] = dp1[n - 1][cur];
				if (cur - a[i] >= 0) {
					dp2[i][cur] -= dp2[i][cur - a[i]];

				}

			}

		}
		for (int i = 0 ; i < n ; ++i) {
			boolean ok = false;
			for (int cur = 0 ; cur < k ; ++cur) {
				if (dp2[i][cur] > 0 && cur + a[i] >= k) {
