	private static void solve() {
		int n = sc.nextInt();
		int k = sc.nextInt();

		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}

		BitSet bs[] = new BitSet[n + 1];
		BitSet bsr[] = new BitSet[n + 1];
		BitSet bstmp = new BitSet(k + 1);
		bstmp.set(0);
		bs[0] = (BitSet)bstmp.clone();
		for (int i = 0; i < n; i++) {
			for (int j = k - 1 - a[i]; j >= 0; j--) {
				if (bstmp.get(j)) {
					bstmp.set(j + a[i]);
				}
			}

			bs[i + 1] = (BitSet)bstmp.clone();
		}

		bstmp.clear();
		bstmp.set(0);
		bsr[n] = (BitSet) bstmp.clone();
		for (int i = n - 1; i >= 0; i--) {
			for (int j = k - 1 - a[i]; j >= 0; j--) {
				if (bstmp.get(j)) {
					bstmp.set(j + a[i]);
				}
			}

			bsr[i] = (BitSet)bstmp.clone();
		}

		int ans = 0;
		out:
		for (int i = 0; i < n; i++) {
			BitSet l = bs[i];
			BitSet r = bsr[i + 1];

			int ls = 0;
			int rs = 0;
			for (int ll = ls, rr = r.previousSetBit(k - 1); ll >= 0; ll = l.nextSetBit(ll + 1)) {
				int nrr;
				while ((nrr = r.previousSetBit(rr - 1)) >= rs && ll + nrr >= k - a[i]) {
//					int nrr = r.previousSetBit(rr - 1);
//					if (nrr < rs || ll + nrr < k - a[i]) {
//						break;
//					}

					rr = nrr;
				}

				if (ll + rr > 0 && ll + rr >= k - a[i] && ll + rr < k) {
					continue out;
				}
			}

			ans++;
//			pr.println(a[i]);
		}

		pr.println(ans);
	}

