	private static void solve() {
		int n = sc.nextInt();
		int k = sc.nextInt();

		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}
		Arrays.sort(a);

		int l = -1;
		int r = n - 1;
		while (r - l > 1) {
			int mid = l + (r - l) / 2;
			if (isNeed(mid, a, k)) {
				r = mid;
			} else {
				l = mid;
			}
		}

		if (!isNeed(r, a, k)) {
			r++;
		}

		pr.println(r);
	}

	// a[mid] を除いたものでk-a[mid<=S<kとなる部分集合が作れるか
	private static boolean isNeed(int mid, int[] a, int k) {
		int n = a.length;

		if (a[mid] >= k) {
			return true;
		}

		boolean[] dp = new boolean[k];

		dp[0] = true;
		for (int i = 0; i < n; i++) {
			if (i == mid) {
				continue;
			}

			for (int j = k - 1; j >= 0; j--) {
				if (dp[j] && j + a[i] < k) {
					dp[j + a[i]] = true;
				}
			}
		}

		for (int i = k - a[mid]; i < k; i++) {
			if (dp[i]) {
				return true;
			}
		}

		return false;
	}

