    static int T = 1; // T \in {0,1}. If T=0, it will be read from the input.
    static String inputFilename = null; // if 'null', it reads data from std-in.

    static boolean largeFakeTest = false; // Check if you generate data on fly
    static int largeFakeTest_T = 1;

    //--------------------------------------------------------------------

    public static class Solver extends  SolverAbstract{

        int MAX_SMALL = 400;
        int MAX = MAX_SMALL;

        int N; //5 * 10^3 , small 400
        int K; //5 * 10^3
        int[] A;

        @Override
        public void readInput() throws IOException {
            N = scanner.nextInt();
            K = scanner.nextInt();
            A = scanner.loadIntArray(N); // 10^9
        }

        @Override
        protected void solve() throws IOException {
            Arrays.sort(A);

            int cnt_unnes = 0;
            for (int i = 0; i < N; i++) {
                if (A[i]>=K){
                    continue;
                }
                int[] vis = new int[2 * MAX + 1];
                for (int j = 0; j < N; j++) if (i!=j){
                    for (int k = vis.length-1; k > 0; k--) {
                        if (vis[k]!=0 && k+A[j] < vis.length){
                            vis[k+A[j]] = 1;
                        }
                    }
                    vis[A[j]] = 1;
                }
                boolean unnes = true;
                for (int j = K-1; j >= K-A[i]; j--) {
                    if (vis[j]!=0){
                        unnes = false;
                    }
                }
                if (unnes){
                    cnt_unnes++;
                }
            }
            out.println(cnt_unnes);
        }
    }

    //--------------------------------------------------------------------

    private void solveAll() throws IOException {
        long timeStart = System.currentTimeMillis();
        if (T==0) {
            if (largeFakeTest) {
                T = largeFakeTest_T;
            } else {
                T = scanner.nextInt();
            }
        }
        final String[] results = new String[T+1];
        for (int test = 0; test < T; test++) {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            PrintStream outLocal = new PrintStream(baos);
            Solver solver = new Solver(){
                @Override
                public void callback() {
                    results[testNo] = answer;
                }
            };
            solver.out = outLocal;
            solver.testNo = test+1;
            if (largeFakeTest) {
                solver.readFakeInput();
            }else{
                solver.readInput();
            }
            solver.solveWrapped(baos);
        }

        long timeEnd = System.currentTimeMillis();
        if (isInputFromFile())
            System.out.println("All tasks are solved! Elapsed time "+(timeEnd-timeStart)/1000.0+" sec.");

        // write all responses in the proper order
        for (int i = 1; i <= T; i++) {
            if (eventType == EventType.GOOGLE_CODE_JAM){
                outGlobal.printf("Case #%d: %s", i, results[i]);
