public class Main {


  private static void solve() {
    int n = ni();
    int k = ni();
    int[] a = na(n);

    int cnt = 0;
    for (int i = 0; i < n; i ++) {
      if (check(a, i, k)) {
        cnt ++;
      }
    }
    System.out.println(cnt);
  }

  private static boolean check(int[] a, int m, int k) {
    if (a[m] >= k) {
      return false;
    }
    BigInteger b = BigInteger.ONE;
    int n = a.length;
    BigInteger mask = BigInteger.ONE.shiftLeft(k + 1).subtract(BigInteger.ONE);

    for (int i = 0; i < n; i ++) {
      if (i == m) continue;
      b = b.shiftLeft(Math.min(a[i], k)).and(mask).or(b);
    }
    for (int i = k - a[m]; i < k; i ++) {
      if (b.testBit(i)) {
        return false;
      }
    }
    return true;
  }

