			}
		}
		int res = 0;
		for (int i = 0 ; i < n ; ++i) {
			for (int cur = 0 ; cur <= maxSum ; ++cur) {
				dp2[i][cur] = dp1[n - 1][cur];
				if (cur - a[i] >= 0) {
					dp2[i][cur] -= dp2[i][cur - a[i]];

