/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskD solver = new TaskD();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskD {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int k = in.nextInt();
			int[] a = new int[n + 1];
			for (int i = 1; i <= n; i++) {
				a[i] = in.nextInt();
			}
			boolean[][] pref = new boolean[n + 2][k + 1];
			boolean[][] suff = new boolean[n + 2][k + 1];
			pref[0][0] = true;
			for (int i = 1; i <= n; i++) {
				add(pref[i], pref[i - 1], a[i]);
			}
			suff[n + 1][0] = true;
			for (int i = n; i >= 1; i--) {
				add(suff[i], suff[i + 1], a[i]);
			}
			int ans = n;
			int[] s = new int[k + 1];
			outer:
			for (int i = 1; i <= n; i++) {
				for (int j = 0; j < k; j++) {
					s[j + 1] = s[j] + (suff[i + 1][j] ? 1 : 0);
				}
				for (int x = 0; x < k; x++) {
					if (!pref[i - 1][x]) {
						continue;
					}
					int l = k - a[i] - x;
					int r = k - x - 1;
					l = fix(l, k - 1);
					r = fix(r, k - 1);
					if (l <= r && s[r + 1] - s[l] > 0) {
						--ans;
						continue outer;
					}
				}
			}
			out.println(ans);
		}

		private int fix(int x, int m) {
			if (x < 0) {
				return 0;
			}
			if (x > m) {
				return m;
			}
			return x;
		}

		private void add(boolean[] nf, boolean[] f, int x) {
			for (int i = 0; i < f.length; i++) {
				if (!f[i]) {
					continue;
				}
				nf[i] = true;
				if (i + x < f.length) {
					nf[i + x] = true;
				}
			}
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

