				l = mid + 1;
				res = mid;
			}
		}

		res += 1;

	}

	boolean judge(int index) {

		if (nums[index] >= K) {
			return true;
		}

		BigInteger sum = BigInteger.ONE;

		for (int i = 0; i < N; i ++) {

			if (i == index) {
				continue;
			}

			sum = sum.or(sum.shiftLeft(nums[i]));
		}


		for (int i = K-1; i >= K - nums[index]; i --) {

			if (sum.testBit(i)) {
				return true;
			}
		}

		return false;
	}

}

