		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        new Main().solve();
    }

    void solve() {
        try (Scanner in = new Scanner(System.in)) {
            int n = in.nextInt();
            int k = in.nextInt();
            int a[] = new int[n];
            long sum = 0;
            for (int i = 0; i < n; ++i) {
                a[i] = in.nextInt();
                sum += a[i];
            }
            if (sum < k) {
                System.out.println(n);
                return;
            }
            Arrays.sort(a);
            for (int i = 0; i < n; ++i) {
                if (a[i] >= k) {
                    a = Arrays.copyOf(a, i);
                }
            }
            int min = -1, max = a.length;
            while (max - min > 1) {
                int mid = (max + min) / 2;
                if (ok(a, mid, k)) max = mid;
                else min = mid;
            }
            System.out.println(max);
        }
    }

    boolean ok(int a[], int b, int k) {
        boolean ok[] = new boolean[k];
        ok[0] = true;
        for (int i = 0; i < a.length; ++i) {
            if (i == b) continue;
            for (int j = k - 1 - a[i]; j >= 0; --j) {
                if (ok[j]) ok[j + a[i]] = true;
            }
        }
        for (int i = k - a[b]; i < k; ++i) {
            if (ok[i]) return true;
        }
        return false;
    }

    void tr(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.io.IOException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
	public static void main(String[] args) throws IOException {
		Main main = new Main();
		main.solveD();
	}

	private void solveD() throws IOException {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int[] a = new int[N];
		for (int i = 0; i < N; i++) {
			a[i] = sc.nextInt();
		}
		Arrays.sort(a);
		int left = 0;
		int right;
		for (right = N - 1; right >= 0 && a[right] >= K; right--);
		right++;
		while (left < right) {
			int current = (left + right) / 2;
			if (judge(current, a, K)) {
				left = current + 1;
			} else {
				right = current;
			}
		}
		System.out.println(left);
	}

	private boolean judge(int current, int[] a, int K) {
		Set<Integer> set = new HashSet<>();
		set.add(0);
		for (int i = 0; i < a.length; i++) {
			if (current == i) {
				continue;
			}
			Set<Integer> newSet = new HashSet<>(set);
			for (int num : set) {
				if (num + a[i] < K) {
					newSet.add(num + a[i]);
				}
			}
			set = newSet;
		}
		for (int i = K - 1; i >= K - a[current]; i--) {
			if (set.contains(i)) {
				return false;
			}
		}
		return true;
	}
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int K = sc.nextInt();
        List<Integer> a = new ArrayList<>();

        int ans = N;
        for(int i = 0; i < N; i++){
            int v = sc.nextInt();
            a.add(v);
        }

        a.sort(null);

        boolean[][] preSum = new boolean[N + 1][K + 9];
        boolean[][] postSum = new boolean[N + 1][K + 9];

        preSum[0][0] = postSum[0][0] = true;

        int len = a.size();

        for(int i = 1; i <= len; i++){
            preSum[i][0] = true;
            int v = a.get(i - 1);
            for(int j = K; j >= 0; j--){
                preSum[i][j] = preSum[i - 1][j];
                if(j - v >= 0){
                    preSum[i][j] |= preSum[i - 1][j - v];
                }
            }
        }

        Collections.reverse(a);

        for(int i = 1; i <= len; i++){
            postSum[i][0] = true;
            int v = a.get(i - 1);
            for(int j = K; j >= 0; j--){
                postSum[i][j] = postSum[i - 1][j];
                if(j - v >= 0){
                    postSum[i][j] |= postSum[i - 1][j - v];
                }
            }
        }

        Collections.reverse(a);

        for(int i = 1; i <= len; i++){

            int v = a.get(i - 1);
            if(v >= K){
                ans -= 1;
                continue;
            }

            boolean[] isExists = new boolean[K + 1];
            for(int j = K - 1; j >= 0; j--){
                isExists[j] = postSum[N - i][j] || isExists[j + 1];
            }

            for(int j = 0; j <= K - 1; j++){
                if(preSum[i - 1][j] && ((K - v - j) < 0 || isExists[K - v - j])){
                    ans -= 1;
                    break;
                }
            }

        }

        System.out.println(ans);
    }
}

