using System;
using System.Linq;
using static System.Math;

class Program
{
    static int n, k;
    static long[] a;
    static bool[,] dp;
    static int before = 0;

    static void Main()
    {
        string[] s = Console.ReadLine().Split();
        n = int.Parse(s[0]);
        k = int.Parse(s[1]);
        a = Console.ReadLine().Split().Select(long.Parse).ToArray();
        Array.Sort(a);
        dp = new bool[n + 1, k];
        dp[0, 0] = true;
        int l = -1;
        int r = n;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (Need(m))
            {
                r = m;
                continue;
            }
            l = m;
        }
        Console.WriteLine(r);
    }

    static bool Need(int x) // カードxが必要か
    {
        if (x == n) return true;
        if (x == -1) return false;
        for (int i = Min(before + 1, x + 1); i <= n; i++)
        {
            for (long j = 0; j < k; j++)
            {
                if (j >= a[i - 1] && i - 1 != x)
                    dp[i, j] = dp[i - 1, j] || dp[i - 1, j - a[i - 1]];
                else
                    dp[i, j] = dp[i - 1, j];
            }
        }
        bool f = false;
        for (long j = Max(0, k - a[x]); j < k; j++)
            f = f || dp[n, j];
        before = x;
        return f;
    }
}

