    static long BinarySearch()
    {
        var ok = (long)nk[0];
        var ng = -1L;
        while (Abs(ok - ng) > 1)
        {
            var mid = (ok + ng) / 2;
            if (isOk(mid)) ok = mid;
            else ng = mid;
        }
        return ok;
    }
    static bool isOk(long mid)
    {
        var dp = new bool[nk[1]];
        dp[0] = true;
        for (var j = 0; j < nk[0]; j++)
        {
            if (mid == j) continue;
            var newdp = new bool[nk[1]];
            for (var k = 0; k < nk[1]; k++)
                if (k - ar[j] >= 0)
                    newdp[k] = dp[k - ar[j]] | dp[k];
                else newdp[k] = dp[k];
            dp = newdp;
        }
        return !dp.Skip(Max(0, nk[1] - ar[mid])).All(b => !b);
    }
}

