    static void Solve()
    {
        var nk = Input.ar;
        var ar = Input.ar;
        if (nk[0] >= 401) throw new Exception();
        if (ar.Select(v=>(long)v).Sum() < nk[1]) { WriteLine(nk[0]);return; }
        if (ar.Min() >= nk[1]) { WriteLine(nk[0]);return; }
