                        newdp[k] = dp[k - ar[j]] | dp[k];
                    else newdp[k] = dp[k];
                dp = newdp;
            }
            if (dp.Skip(Max(0,nk[1] - ar[i])).All(b => !b))
                ct++;
        }
        WriteLine(ct);
    }
