namespace Atcoder070_D_NoNeed
{
    class Program
    {
        static void Main(string[] args)
        {
            var inputFirstLine = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            int N = inputFirstLine[0], K = inputFirstLine[1];
            var cards = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToList();

            Console.WriteLine(new NoNeed().GetNoNeedCardsCount(K, cards));
            //Console.ReadKey();
        }
    }

    class NoNeed
    {
        public int GetNoNeedCardsCount(int target, List<int> cards)
        {
            var orderCards = cards.OrderByDescending(x => x).ToArray();

            int sum = 0, index = -1;

            for (int i = 0; i < orderCards.Length; i++)
            {
                sum += orderCards[i];
                if (sum >= target)
                {
                    sum -= orderCards[i];
                    index = i;
                }
            }

            if (index == -1) return orderCards.Length;

            return orderCards.Length - index - 1;
        }
    }
}

using System;
using static System.Math;

class Program
{
    static int n, k;
    static int[] a;
    static bool[,] dp;
    static int before = 0;

    static void Main()
    {
        string[] s = Console.ReadLine().Split();
        n = int.Parse(s[0]);
        k = int.Parse(s[1]);
        a = new int[n];
        s = Console.ReadLine().Split();
        for (int i = 0; i < n; i++) a[i] = int.Parse(s[i]);
        Array.Sort(a);
        dp = new bool[n + 1, k];
        dp[0, 0] = true;
        int l = -1;
        int r = n;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (Need(m))
            {
                r = m;
                continue;
            }
            l = m;
        }
        Console.WriteLine(r);
    }

    static bool Need(int x) // カードxが必要か
    {
        if (x == n) return true;
        if (x == -1) return false;
        for (int i = Min(before, x) + 1; i <= n; i++)
        {
            for (long j = 0; j < k; j++)
            {
                if (j >= a[i - 1] && i - 1 != x)
                    dp[i, j] = dp[i - 1, j] || dp[i - 1, j - a[i - 1]];
                else
                    dp[i, j] = dp[i - 1, j];
            }
        }
        bool f = false;
        for (long j = Max(0, k - a[x]); j < k; j++)
            f = f || dp[n, j];
        before = x;
        return f;
    }
}

