[System.Diagnostics.DebuggerDisplay("Data={ToString()}")]
public class SegmentTree
{
    public int n;
    public Number[][] data;
    int[] L, R;
    static T[] Enumerate<T>(int n, Func<int, T> f) { var a = new T[n]; for (int i = 0; i < n; ++i) a[i] = f(i); return a; }


    public SegmentTree(int size, int m, int[] a)
    {
        n = 1;
        while (n < size)
            n <<= 1;
        data = new Number[n << 1][];
        data[1] = new Number[m + 1];
        data[1][0] = 1;
        L = new int[n << 1];
        L[1] = 0;
        R = new int[n << 1];
        R[1] = n;
        for (int _ = 1; _ < n; _++)
        {
            {
                L[_ << 1] = L[_];
                R[(_ << 1)] = L[(_ << 1) + 1] = (L[_] + R[_]) >> 1;
                R[(_ << 1) + 1] = R[_];
            }

            {
                var l = L[(_ << 1) + 1]; var r = Math.Min(size, R[(_ << 1) + 1]);
                var ret = data[_].ToArray();
                for (int k = l; k < r; k++)
                {
                    var v = a[k];
                    for (int j = m - v; j >= 0; j--)
                    {
                        if (ret[j] <= 0) continue;
                        ret[j + v] |= ret[j];
                    }
                }
                data[_ << 1] = ret;
            }
            {
                var l = L[(_ << 1)]; var r = Math.Min(size, R[(_ << 1)]);
                var ret = data[_].ToArray();
                for (int k = l; k < r; k++)
                {
                    var v = a[k];
                    for (int j = m - v; j >= 0; j--)
                    {
                        if (ret[j] <= 0) continue;
                        ret[j + v] |= ret[j];
                    }
                }
                data[(_ << 1) + 1] = ret;
            }

        }
    }
}
