        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int N, int K, long[] A)
        {
            int count = 0;
            for (int i = 0; i < N; ++i)
            {
                var set = new HashSet<int> { 0 };
                for (int j = 0; j < N; ++j)
                {
                    if (i != j)
                    {
                        foreach (int n in set.Select(n => n + A[j]).Where(n => n < K).ToArray())
                        {
                            set.Add(n);
                        }
                    }
                }
                if (set.All(n => n + A[i] < K)) { ++count; }
            }
            return count;
        }
