        void Solve() {
            //input
            io.i(out N, out K);
            io.ini(out a, N);
            //cal            
            Func<int, bool> check = (index) => {
                if (a[index] >= K) return true;
                var dp = new bool[K];
                dp[0] = true;
                for (int i = 0; i < N; ++i) {
                    if (i == index) continue;
                    for (int j = K - 1; j >= 0; --j) {
                        var ti = j + a[i];
                        if (dp[j] && ti < K)
                            dp[ti] = true;
                    }
                }
                for (int i = K - a[index]; i < K; ++i) if (dp[i]) return true;
                return false;
            };
            a.Sort();
            var ans = a.BinarySearch(-1, N, check);
            //ret
            io.o(ans);
        }

