	static void Main(){
		Sc sc=new Sc();
		int[] s=sc.Ia;
		int[] a=sc.Ia;
		int ans=0;
		if(s[0]>400||s[1]>400){return;}
		for(int i=0;i<s[0];i++){
			if(a[i]>=s[1]){ans++;continue;}
			bool[] dp=new bool[s[1]+1];
			dp[0]=true;
			for(int j=0;j<s[0];j++){
				if(j!=i){
					for(int k=s[1];k>=a[j];k--){
						if(dp[k-a[j]]){dp[k]=true;}
					}
				}
			}
			for(int j=s[1]-a[i];j<s[1];j++){
				if(dp[j]){ans++;break;}
			}
		}
		Console.WriteLine("{0}",s[0]-ans);
	}
}

