    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            K = consoleReader.Int;
            var a = consoleReader.Split.Int.Where(i => i < K).ToArray();
            Array.Sort(a);
            if (a.Sum() < K) return a.Length;
            int count = 0;
            var canLeft = new bool[a.Length][];
            var canRight = new bool[a.Length][];

            var left = new bool[K];
            var right = new bool[K];
            left[0] = right[0] = true;

            for (int i = 0; i < a.Length; i++)
            {
                canLeft[i] = (bool[])left.Clone();
                canRight[a.Length - i - 1] = (bool[])right.Clone();
                for (int j = K - 1; j >= a[i]; j--)
                    left[j] = left[j] || left[j - a[i]];

                for (int j = K - 1; j >= a[a.Length - i - 1]; j--)
                    right[j] = right[j] || right[j - a[a.Length - i - 1]];
            }

            for (int i = 0; i < a.Length; i++)
            {
                var max = 0;
                int ri = K - 1;
                for (int li = 0; li < K; li++)
                {
                    if (!canLeft[i][li]) continue;
                    while (!canRight[i][ri] || li + ri >= K) ri--;
                    max = Math.Max(max, li + ri);
                }
                if (max + a[i] < K) count++;
            }
            return count;
        }
        int K;

