class Program
{
    private static int Solve(int N, int K, long[] a)
    {
        int count = N;
        for (int i = 0; i < N; ++i)
        {
            bool[][] dp = new bool[N][];
            for (int j = 0; j < N; ++j)
            {
                dp[j] = new bool[K];
                for (int k = 0; k < K; ++k)
                {
                    if (k == 0 || (j > 0 && dp[j - 1][k]))
                    {
                        dp[j][k] = true;
                        if (i != j && k + a[j] < K) { dp[j][k + a[j]] = true; }
                    }
                }
            }
            int min = Math.Max((int)(K - a[i]), 0);
            if (dp[N - 1].Skip(min).Any(x => x)) { --count; }
        }
        return count;
    }
