    {
        int[] values = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
        Console.WriteLine(Solve(values[0], values[1], a));
    }
}

