#region Divide and Conquer
public class DCDP
{
    public int k;
    public int[] a;
    public int ans = 0;
    static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
    public void dfs(int l, int r, Number[] dp)
    {
        if (l + 1 == r) { query(l, dp); return; }
        var m = (l + r) / 2;
        var L = l;
        var LL = m;
        var R = m;
        var RR = r;
        for (int _ = 0; _ < 2; _++)
        {
            var tmp = dp.ToArray();
            for (int i = R; i < RR; i++)
            {
                //ここにDP部分を書く
                for (int j = k - 1; j >= 0; j--)
                    if (tmp[j] && j + a[i] < k)
                        tmp[j + a[i]] = true;
            }
            dfs(L, LL, tmp);
            Swap(ref L, ref R);
            Swap(ref LL, ref RR);

        }

    }


    void query(int i, Number[] dp)
    {
        for (int j = 0; j < k; j++)
            if (dp[j] && j + a[i] >= k)
                return;
        ans++;
    }

}
