    class Program {
        int N, K;
        int[] A;
        bool[,] DP;
        public Program(int K, int[] A) {
            this.N = A.Length;
            this.K = K;
            this.A = A;
            Array.Sort(A);
            this.DP = new bool[N + 1, K];
        }

        public bool NoNeed(int x) {
            // Console.WriteLine("A[{0}] = {1}", x, A[x]);

            for (int i = 0; i < N; i++) 
                for (int j = 0; j < K; j++) DP[i, j] = false;
            DP[0, 0] = true;

            for (int i = 0; i < N; i++) {
                int a = A[i];
                for (int j = 0; j < K; j++) {
                    DP[i + 1, j] = DP[i, j];
                    if (i != x && j - a >= 0) DP[i + 1, j] |= DP[i, j - a];
                }
            }

            // for (int i = 0; i <= N; i++) {
            //     for (int j = 0; j < K; j++) {
            //         Console.Write(DP[i, j]? "o": "x");
            //     }
            //     Console.WriteLine();
            // }
            // Console.WriteLine();

            for (int j = Math.Max(0, K - A[x]); j < K; j++) {
                if (DP[N, j]) return false;
            }
            return true;
        }
