        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (Need(m))
            {
                r = m;
                continue;
            }
            l = m;
        }
        Console.WriteLine(r);
    }

    static bool Need(int x) // カードxが必要か
    {
        if (x == n) return true;
        if (x == -1) return false;
        for (int i = Min(before + 1, x); i <= n; i++)
        {
