    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            K = consoleReader.Int;
            var a = consoleReader.Split.Int.Where(i => i < K).ToArray();
            Array.Sort(a);
            if (a.Sum() < K) return a.Length;
            int count = 0;
            var canLeft = new int[a.Length][];
            var canRight = new int[a.Length][];

            var left = new HashSet<int> { 0 };
            var right = new HashSet<int> { 0 };

            for (int i = 0; i < a.Length; i++)
            {
                canLeft[i] = left.ToArray();
                Array.Sort(canLeft[i]);
                canRight[a.Length - i - 1] = right.ToArray();
                Array.Sort(canRight[a.Length - i - 1]);
                var nexts = new List<int>();
                foreach (var item in left)
                {
                    var next = item + a[i];
                    if (next >= K) break;
                    nexts.Add(next);
                }
                left.UnionWith(nexts);

                nexts = new List<int>();
                foreach (var item in right)
                {
                    var next = item + a[a.Length - i - 1];
                    if (next >= K) break;
                    nexts.Add(next);
                }
                right.UnionWith(nexts);
            }

            for (int i = 0; i < a.Length; i++)
            {
                var max = 0;
                int ri = canRight[i].Length - 1;
                for (int li = 0; li < canLeft[i].Length; li++)
                {
                    while (ri >= 0 && canLeft[i][li] + canRight[i][ri] >= K) ri--;
                    if (ri < 0) break;
                    max = Math.Max(max, canLeft[i][li] + canRight[i][ri]);
                }
                if (max + a[i] < K) count++;
            }
            return count;
        }
