public class Solver
{
    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadIntArray();

        if (a.Sum(aa => (long)aa) < m || a.Min() >= m)
        {
            Write(n);
            return;
        }

        var pdp = new bool[n + 1][];
        pdp[0] = new bool[m];
        pdp[0][0] = true;
        for (int i = 0; i < n; i++)
        {
            pdp[i + 1] = (bool[])pdp[i].Clone();
            for (int j = 0; j + a[i] < m; j++)
                if (pdp[i][j])
                    pdp[i + 1][j + a[i]] = true;
        }

        var sdp = new bool[n + 1][];
        sdp[n] = new bool[m];
        sdp[n][0] = true;
        for (int i = n - 1; i >= 0; i--)
        {
            sdp[i] = (bool[])sdp[i + 1].Clone();
            for (int j = 0; j + a[i] < m; j++)
                if (sdp[i + 1][j])
                    sdp[i][j + a[i]] = true;
        }

        int ans = 0;
        for (int i = 0; i < n; i++)
            if (a[i] < m)
            {
                bool f = true;
                var ldp = pdp[i];
                var rdp = sdp[i + 1];
                int l = m - a[i];
                int r = m - 1;
                int c = 0;
                for (int j = l; j <= r; j++)
                    if (rdp[j])
                        c++;
                for (int j = 0; f && j < m; j++)
                {
                    if (ldp[j] && c > 0)
                        f = false;
                    if (l > 0)
                    {
                        if (rdp[--l])
                            c++;
                    }
                    if (rdp[r--])
                        c--;
                }
                if (f)
                    ans++;
            }

        Write(ans);
    }

