class Program
{
    static int n, k;
    static long[] a;

    static void Main()
    {
        string[] s = Console.ReadLine().Split();
        n = int.Parse(s[0]);
        k = int.Parse(s[1]);
        a = Console.ReadLine().Split().Select(long.Parse).ToArray();
        Array.Sort(a);
        int l = -1;
        int r = n;
        while (r - l > 1)
        {
            int m = l + (r - l) / 2;
            if (Need(m))
            {
                r = m;
                continue;
            }
            l = m;
        }
        Console.WriteLine(r);
    }

    static bool Need(int x) // カードxが必要か
    {
        if (x == n) return true;
        if (x == -1) return false;
        bool[,] dp = new bool[n + 1, k]; // カードiまで見て和jを作れるか
        dp[0, 0] = true;
        for (int i = 1; i <= n; i++)
        {
            for (long j = 0; j < k; j++)
            {
                if (j >= a[i - 1] && i - 1 != x)
                    dp[i, j] = dp[i - 1, j] || dp[i - 1, j - a[i - 1]];
                else
                    dp[i, j] = dp[i - 1, j];
            }
        }
        bool f = false;
        for (long j = Max(0, k - a[x]); j < k; j++)
            f = f || dp[n, j];
        return f;
    }
}

