    auto dp2 = new bool[][](n + 1, k + 1);

    dp1[0][0] = 1;

    foreach (i ; 1 .. n + 1) {
        foreach (j ; 0 .. k + 1) {
            dp1[i][j] = dp1[i-1][j];

            if (j - a[i-1] >= 0) dp1[i][j] |= dp1[i-1][j-a[i-1]];
        }
    }

    dp2[n][0] = 1;

    foreach_reverse (i ; 0 .. n) {
        foreach (j ; 0 .. k + 1) {
            dp2[i][j] = dp2[i+1][j];

            if (j - a[i] >= 0) dp2[i][j] |= dp2[i+1][j-a[i]];
        }
    }

    int ans;

    foreach (i ; 0 .. n) {
        auto c = iota(0, k).filter!(j => dp1[i][j]);
