#define mid ((l+r)>>1)
#define N 5010
using namespace std;

int n,k,dp[20][N],num[N],ans;

void sol(int l,int r,int now)
{
	if(l==r)
	{
		int i;
		for(i=k-num[l]; i<k; i++)
		{
			if(dp[now][i]) break;
		}
		if(i<k) ans++;
		return;
	}
	int i,j;
	memcpy(dp[now+1],dp[now],sizeof(dp[now]));
	for(j=l; j<=mid; j++)
	{
		for(i=k-1; i>=num[j]; i--)
		{
			dp[now+1][i]|=dp[now][i-num[j]];
		}
	}
	sol(mid+1,r,now+1);
	memcpy(dp[now+1],dp[now],sizeof(dp[now]));
	for(j=mid+1;j<=r;j++)
	{
		for(i=k-1;i>=num[j];i--)
		{
			dp[now+1][i]|=dp[now][i-num[j]];
		}
	}
	sol(l,mid,now+1);
}

