from itertools import accumulate

def solve():
    N, K = map(int, input().split())
    As = list(map(int, input().split()))

    As.sort()
    i = bisect_left(As, K)
    Bs = As[:i]
    M = len(Bs)

    setSums = [{0}]
    setSum = {0}
    for B in Bs:
        for s in list(setSum):
            if s+B < K:
                setSum.add(s+B)
        setSums.append(setSum.copy())
    setSumRevs = [{0}]
    setSum = {0}
    for B in reversed(Bs):
        for s in list(setSum):
            if s+B < K:
                setSum.add(s+B)
        setSumRevs.append(setSum.copy())
    setSumRevs.reverse()

    def isOK(x):
        B = Bs[x]
        numRevs = [0] * K
        for s in setSumRevs[x+1]:
            numRevs[s] = 1
        accNumRevs = list(accumulate([0]+numRevs))
        for s in setSums[x]:
            if accNumRevs[K-s] - accNumRevs[max(0, K-s-B)] > 0:
                return True
        return False

    ng, ok = -1, M
    while abs(ok-ng) > 1:
        mid = (ng+ok) // 2
        if isOK(mid):
            ok = mid
        else:
            ng = mid

    print(ok)


