from bisect import bisect_left, bisect_right

def solve():
    N, K = map(int, input().split())
    As = list(map(int, input().split()))

    As.sort()
    i = bisect_left(As, K)
    Bs = As[:i]
    M = len(Bs)

    def isOK(x):
        isFounds = [False] * K
        isFounds[0] = True
        for i, B in enumerate(Bs):
            if i == x: continue
            for s in reversed(range(K-B)):
                if isFounds[s]:
                    isFounds[s+B] = True
        return any(isFounds[K-Bs[x]:])

    ng, ok = -1, M
    while abs(ok-ng) > 1:
        mid = (ng+ok) // 2
        if isOK(mid):
            ok = mid
        else:
            ng = mid

    print(ok)


