def solve(f):
    n, k = f.read_int_list()
    a = f.read_int_list()
    a.sort(reverse=True)

    # if n > 400: return 0

    def check(ai):
        aa = a[:]
        aa.remove(ai)
        # dp = [False] * k
        dp = [False] * (2*k)
        dp[0] = dp[k] = True

        for i in xrange(n-1):
            ofs0 = (i % 2) * k
            ofs1 = ((i+1)%2) * k
            for j in xrange(k):
                if dp[ofs0+j] and aa[i] + j < k:
                    dp[ofs1+aa[i]+j] = True

        if (n-1)%2 == 0:
            return any(dp[k-ai:k])
        else:
            return any(dp[2*k-ai:])

    au = list(set(a))
    au.sort(reverse=True)

    mi = -1
    ma = len(au)

    while ma - mi > 1:
        mid = (ma+mi)/2
        if check(au[mid]):
            mi = mid
        else:
            ma = mid

    a.sort()
    return bisect.bisect_right(a, au[ma])

