def solve(f):
    n, k = f.read_int_list()
    a = f.read_int_list()
    a.sort(reverse=True)

    # if n > 400: return 0

    def check(ind):
        aa = a[:]
        aa.pop(ind)
        dp = [False] * k
        dp[0] = True

        for i in xrange(n-1):
            dp2 = dp[:]
            for j in xrange(k):
                if not dp[j]: continue
                if aa[i] + j < k:
                    dp2[aa[i]+j] = True
            dp = dp2

        return any(dp[k-a[ind]:])

    mi = -1
    ma = n

    while ma - mi > 1:
        mid = (ma+mi)/2
        if check(mid):
            mi = mid
        else:
            ma = mid

    return n-ma

