import bisect


def preliminary(k, aaa):
    dp = [False] * k
    dp[0] = True
    curr_max = 0
    fwd = {}
    pa = aaa[0]
    pdp, ppdp = dp[:], None
    for a in aaa:
        if pa != a:
            fwd[pa] = ppdp
        for i in range(min(curr_max, k - a - 1), -1, -1):
            if dp[i]:
                dp[i + a] = True
        curr_max += a
        pa = a
        ppdp = pdp
        pdp = dp[:]
    fwd[pa] = ppdp

    dp = [False] * k
    dp[0] = True
    curr_max = 0
    bwd = {}
    pa = 0
    pdp = []
    for a in reversed(aaa):
        if pa != a:
            bwd[a] = [i for i, v in enumerate(pdp) if v][1:]
        for i in range(min(curr_max, k - a - 1), -1, -1):
            if dp[i]:
                dp[i + a] = True
        curr_max += a
        pa = a
        pdp = dp[:]

    return fwd, bwd


def get_judge(k, aaa):
    fwd, bwd = preliminary(k, aaa)
    cache = [None] * k

    def judge(m):
        am = aaa[m]
        if cache[am] is None:
            dp = fwd[am]
            ndp = dp[:]
            for i in bwd[am]:
                for j in range(k - i - 1, -1, -1):
                    if dp[j]:
                        ndp[i + j] = True
            cache[am] = any(ndp[-am:])
        return cache[am]

    return judge


def solve(k, aaa):
    if sum(aaa) < k:
        return n

    aaa.sort()
    aaa = aaa[:bisect.bisect_left(aaa, k)]

    judge = get_judge(k, aaa)

    l = 0
    r = len(aaa) - 1
    m = (l + r) // 2
    while l <= r:
        if judge(m):
            r = m - 1
        else:
            l = m + 1
        m = (l + r) // 2

    return l


