fn check(i: usize, k: usize, aa: &[usize]) -> bool {
    let mut dp = vec![false; k];
    dp[0] = true;

    for j in 0..aa.len() {
        if j == i {
            continue;
        }

        for w in (aa[j]..k).rev() {
            dp[w] |= dp[w - aa[j]];
            if dp[w] && w + i >= k {
                return true;
            }
        }
    }
    false

}


fn main() {
    let (n, k) = get!(usize, u64);
    let mut aa: Vec<usize> = util::gets::<u64>()
        .into_iter()
        .filter(|&a| a < k)
        .map(|a| a as usize)
        .collect();
    aa.sort();


    let k = k as usize;
    let mut l = 0;
    let mut r = aa.len();

    while l != r {
        let mid = (l + r) / 2;
        if check(mid, k, &aa) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }

    println!("{}", l);

}

