    let mut lb = 0;
    let mut ub = a.len() + 1;
    while ub - lb > 1 {
        let mid = (ub + lb) / 2;
        if criterion(k, mid, &a) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    println!("{}", lb);
}

