fn solve(xs: &Vec<usize>, k: usize, a: usize, b: usize) -> usize{
    if a+1==b { b }
    else if need(xs, (a+b)/2, k) { solve(xs, k, a, (a+b)/2) }
    else { solve(xs, k, (a+b)/2, b) }
}

fn need(xs: &Vec<usize>, i: usize, k: usize) -> bool {
    let mut dp = vec![false; k*2];
    dp[0] = true;
    for j in 0..xs.len(){
        if i!=j{
            for h in (0..k).rev(){
                if dp[h as usize] {
                    dp[(h+xs[j])]=true;
                }
            }
        }
    }
    dp[k-xs[i]..k].iter().fold(false, |acc, &x|{acc || x})
}

