fn trans (dp: &mut Vec<bool>, a: usize) {
    for i in (a..dp.len()).rev() {
        dp[i] |= dp[i - a];
    }
}

fn calc (x: &Vec<usize>, l: usize, r: usize, mut dp: &mut Vec<bool>) -> usize {
    if l + 1 == r {
        let k = dp.iter().rposition(|&x| x).unwrap();
        return if x[l] + k >= dp.len() {0} else {1};
    }
    let save = dp.clone();
    let m = (l + r) / 2;
    for &a in &x[l..m] {
        trans (&mut dp, a);
    }
    let front = calc (x, m, r, &mut dp);
    dp.clone_from (&save);
    for &a in &x[m..r] {
        trans (&mut dp, a);
    }
    front + calc (x, l, m, &mut dp)
}

