#[fastout]
fn main() {
    input! {
        N: usize,
        K: usize,
        a: [usize; N],
    }
    let mut dp_l = vec![vec![false; K]; N + 1];
    let mut dp_r = vec![vec![false; K]; N + 1];
    dp_l[0][0] = true;
    for i in 0..N {
        for j in 0..K {
            if j >= a[i] {
                dp_l[i + 1][j] = dp_l[i][j] | dp_l[i][j - a[i]];
            } else {
                dp_l[i + 1][j] = dp_l[i][j];
            }
        }
    }
    dp_r[N][0] = true;
    for i in (0..N).rev() {
        for j in 0..K {
            if j >= a[i] {
                dp_r[i][j] = dp_r[i + 1][j] | dp_r[i + 1][j - a[i]];
            } else {
                dp_r[i][j] = dp_r[i + 1][j];
            }
        }
    }
    let mut dp_r_acc = vec![vec![0; K + 1]; N + 1];
    for i in 0..=N {
        for j in 0..K {
            dp_r_acc[i][j + 1] = dp_r_acc[i][j] + if dp_r[i][j] { 1 } else { 0 };
        }
    }
    let mut result = 0;
    for i in 0..N {
        let mut is_need = false;
        let sum_low = K.saturating_sub(a[i]);
        let sum_high = K;
        for l_sum in 0..sum_high {
            if dp_l[i][l_sum] {
                let r_sum_low = sum_low.saturating_sub(l_sum);
                let r_sum_high = sum_high - l_sum;
                if dp_r_acc[i + 1][r_sum_high] - dp_r_acc[i + 1][r_sum_low] > 0 {
                    is_need = true;
                    break;
                }
            }
        }
        if !is_need {
            result += 1;
        }
    }
    println!("{}", result);
}

