#![allow(unused_imports, unused_variables, dead_code)]
use std::io::*;
use std::fmt::*;
use std::str::*;
use std::cmp::*;
use std::collections::*;

trait InputValue {
    fn parse(s: &str) -> Self;
}

fn read<T: InputValue>() -> T {
    let mut buf = String::new();
    let _ = stdin().read_line(&mut buf);
    T::parse(&buf.trim())
}

fn readnc<T: InputValue>() -> Vec<T> {
    let mut vec = vec![];
    let line: String = read();
    for token in line.split_whitespace() {
        vec.push(T::parse(token));
    }
    vec
}

fn readn<T: InputValue>(n: usize) -> Vec<T> {
    let mut vec = vec![];
    for _ in 0..n {
        vec.push(read());
    }
    vec
}

macro_rules! parse_single_value {
    ($($t:ty),*) => {
        $(
            impl InputValue for $t {
                fn parse(s: &str) -> $t { s.parse().unwrap() }
            }
        )*
	}
}
parse_single_value!(i32, i64, f32, f64, usize, String);

macro_rules! parse_tuple {
	($($t:ident),*) => {
		impl<$($t),*> InputValue for ($($t),*) where $($t: InputValue),* {
			fn parse(s: &str) -> ($($t),*) {
				let mut tokens = s.split_whitespace();
				let t = ($($t::parse(tokens.next().unwrap())),*);
				t
			}
		}
	}
}
parse_tuple!(A, B);
parse_tuple!(A, B, C);

// ===

fn main() {
    let (n, k): (usize, usize) = read();
    let mut a: Vec<usize> = readnc();

    let left = dodp(&a, k);
    a.reverse();
    let right = dodp(&a, k);
    a.reverse();

    let mut ans = 0;
    for i in 0..n {
        if a[i] >= k {
            continue
        }
        let mut rsum = vec![0; k+2];
        for r in 0..k {
            rsum[r+1] = rsum[r] + if right[n-i-1][r] { 1 } else { 0 };
        }

        let mut isok = false;
        for l in 0..k+1 {
            let from = if k <= a[i] + l { 0 } else { k - a[i] - l };
            let to = k - l;
            if left[i][l] && rsum[to] - rsum[from] >= 1 {
                isok = true;
                break
            }
        }
        if !isok {
            ans += 1;
        }
    }
    println!("{}", ans);
}

fn dodp(a: &Vec<usize>, k: usize) -> Vec<Vec<bool>> {
    let n = a.len();
    let mut dp: Vec<Vec<bool>> = vec![vec![false; k+1]; n+1];
    dp[0][0] = true;
    for i in 0..n {
        for j in 0..k+1 {
            if !dp[i][j] {
                continue
            }
            dp[i+1][j] = true;

            let tj = min(k, j + a[i]);
            dp[i+1][tj] = true;
        }
    }
    dp
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        k: usize,
        v: [usize; n]
    }
    let mut w = v;
    w.sort();
    if w[0] >= k {
        println!("0");
        return;
    }
    let mut l = 0;
    let mut r = n;
    while l + 1 < r {
        let m = (l + r) / 2;
        if w[m] >= k {
            r = m;
            continue;
        }
        let mut ps: Vec<bool> = vec![false;k];
        ps[0] = true;
        for i in 0..n {
            let mut psn = ps.clone();
            if i == m {
                continue;
            }
            for j in 0..k {
                if j + w[i] >= k {
                    break;
                }
                if ps[j] == true {
                    psn[j + w[i]] = true;
                }
            }
            ps = psn;
        }
        if ps[k-w[m]..].iter().any(|&x| x) {
            r = m;
        } else {
            l = m;
        }
    }
    println!("{}",r);
}

use std::io::{self, Stdin};
use std::str::{self, FromStr};
use std::error::Error;

fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let k: usize = sc.ne();
    let mut a: Vec<usize> = (0..n).map(|_| sc.ne()).collect();
    a.sort();
    let mut dp = vec![false; k + 1];
    let mut ok = |m: usize| -> bool {
        for i in 0..k + 1 {
            dp[i] = false;
        }
        dp[0] = true;
        for i in 0..n {
            if i == m {
                continue;
            }
            for j in (0..k).rev() {
                if dp[j] == false {
                    continue;
                }
                let val = a[i] + j;
                if val <= k {
                    dp[val] = true;
                }
            }
        }
        let mi = if k < a[m] { 0 } else { k - a[m] };
        let mut res = false;
        for i in mi..k {
            if dp[i] {
                res = true;
            }
        }
        !res
    };
    let (mut lb, mut ub) = (0, n); // [lb, ub)
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        // println!("{} {}", mid, ok(mid as usize));
        if ok(mid as usize) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    println!("{}", lb + 1);
}

fn main() {
    const STACK: usize = 16 * 1024 * 1024;
    let _ = std::thread::Builder::new()
        .stack_size(STACK)
        .spawn(|| { exec(); })
        .unwrap()
        .join()
        .unwrap();
}

