    }
}

fn solve() {
    let (n, k) = get!(usize, usize);
    let mut aa = util::gets::<usize>();
    aa.sort();

    let mut l = 0;
    let mut r = n;

    while l != r {
        // debug!(l, r);
        let mid = (l + r) / 2;

        let mut bitset = BitSet::new(k);
        bitset.set(0, true);

        for i in 0..n {
            if i != mid {
                bitset |= &(bitset.clone() << aa[i]);
            }
        }

        if aa[mid] >= k || (k - aa[mid]..k).any(|i| bitset[i]) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }

    println!("{}", l);
}

use std::io::{self, Stdin};
