const MOD: i64 = 1000000007;
fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let k: usize = sc.ne();
    let mut a: Vec<usize> = (0..n).map(|_| sc.ne()).collect();
    a.sort();
    let mut dp = vec![0i64; k + 1];
    dp[0] = 1i64;
    for &x in &a {
        for i in (0..k).rev() {
            if i < x {
                break;
            }
            dp[i] = (dp[i] + dp[i - x]) % MOD;
        }
    }
    let mut cnt = 0;
    for &x in &a {
        for i in 0..k {
            if i + x > k {
                break;
            }
            dp[i + x] = (dp[i + x] + MOD - dp[i]) % MOD;
        }
        let mi = if x > k { 0 } else { k - x };
        let mut ok = false;
        for i in mi..k {
            if dp[i] > 0 {
                ok = true;
            }
        }
        if ok {
            cnt += 1;
        }
        for i in (0..k).rev() {
            if i < x {
                break;
            }
            dp[i] = (dp[i] + dp[i - x]) % MOD;
        }
    }
    println!("{}", cnt);
}

