use std::io::Read;

fn calc(a: &[usize], w: usize, mut dp: BitSet) -> usize {
    let n = a.len();
    if n == 1 {
        let mut k = w - 1;
        while !dp.get_at(k) {
            k -= 1;
        }
        return if k + a[0] >= w {0} else {1};
    }
    let save = dp.clone();
    let m = n / 2;
    for &a in &a[m..] {
        if a < w {
            let mut shift = dp.shift_left(a);
            shift.truncate(w);
            dp.bitwise_or_assign(&shift);
        }
    }
    let ans = calc(&a[..m], w, dp);
    dp = save;
    for &a in &a[..m] {
        if a < w {
            let mut shift = dp.shift_left(a);
            shift.truncate(w);
            dp.bitwise_or_assign(&shift);
        }
    }
    ans + calc(&a[m..], w, dp)
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
