    let w: usize = it.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let mut dp = BitSet::new(1);
    dp.set_at(0);
    let ans = calc(&a, w, dp);
    println!("{}", ans);
}

