#[fastout]
fn main() {
    input! {
        N: usize,
        K: usize,
        a: [usize; N],
    }
    let mut dp_l = vec![vec![0; K + 1]; N + 1];
    let mut dp_r = vec![vec![0; K + 1]; N + 1];
    dp_l[0][0] = 1;
    for i in 0..N {
        for j in 0..=K {
            dp_l[i + 1][min(j + a[i], K)] += dp_l[i][j];
            dp_l[i + 1][j] += dp_l[i][j];
        }
    }
    dp_r[N][0] = 1;
    for i in (0..N).rev() {
        for j in 0..=K {
            dp_r[i][min(j + a[i], K)] += dp_r[i + 1][j];
            dp_r[i][j] += dp_r[i + 1][j];
        }
    }
    for i in 0..=N {
        for j in (0..K).rev() {
            dp_r[i][j] += dp_r[i][j + 1];
        }
    }
    let mut result = 0;
    for i in 0..N {
        let mut n_good_sets_with_i = 0;
        let mut n_good_sets_without_i = 0;
        for j in 0..=K {
            let s = if K >= j + a[i] {
                K - j - a[i]
            } else {
                0
            };
            n_good_sets_with_i += dp_l[i][j] * dp_r[i + 1][s];
            n_good_sets_without_i += dp_l[i][j] * dp_r[i + 1][K - j];
        }
        if n_good_sets_with_i == n_good_sets_without_i {
            result += 1;
        }
    }
    println!("{}", result);
}

