fn main() {
    read!(n: usize, k: usize);
    read!(cards: [usize]);
    let mut forward = vec![vec![false; k]; n];
    let mut backward = vec![vec![false; k]; n];
    forward[0][0] = true;
    backward[n - 1][0] = true;
    for i in 0 .. n - 1 {
        let c = cards[i];
        for j in 0 .. k {
            if j >= c {
                forward[i + 1][j] = forward[i][j - c] || forward[i][j];
            }else {
                forward[i + 1][j] = forward[i][j];
            }
        }
    }
    for i in (1usize .. n).rev() {
        let c = cards[i];
        for j in 0 .. k {
            if j >= c {
                backward[i - 1][j] = backward[i][j - c] || backward[i][j];
            }else {
                backward[i - 1][j] = backward[i][j];
            }
        }
    }
    let mut count = n;
    for i in 0 .. n {
        let mut stack = Vec::new();
        let mut is_need = false;
        for j in 0 .. k {
            if forward[i][j] {
                stack.push(j);
            }
        }
        for j in 0 .. k {
            if backward[i][j] {
                while let Some(&max) = stack.last() {
                    if max + j >= k {
                        stack.pop();
                    }else {
                        break;
                    }
                }
                if let Some(&max) = stack.last() {
                    if max + j + cards[i] >= k {
                        is_need = true;
                        break;
                    }
                }
            }
        }
        if is_need {
            count -= 1;
        }
    }
    println!("{}", count);
}

