    println!("{}", ans);
}
fn solve(n: usize, k: i64, seq: &Vec<i64>) -> usize {
    let mut sum = 0;
    for i in 0..n {
        sum += seq[i];
    }
    if sum < k {
        return n;
    }

    let mut seq = seq.clone();
    seq.sort();
    let mut l = -1;
    let mut r = n as i64 - 1;
    while r - l > 1 {
        let mid = (l + r) / 2;
        if calc(k, mid as usize, &seq) {
            r = mid;
        } else {
            l = mid;
        }
    }
    return r as usize;
}

