fn trans (dp: &mut Vec<bool>, a: usize) {
    let mut i = dp.len() - 1;
    while i >= a {
        dp[i] = dp[i] || dp[i - a];
        i -= 1;
    }
}

fn calc (x: &Vec<usize>, l: usize, r: usize, mut dp: &mut Vec<bool>) -> usize {
    if l + 1 == r {
        let mut k = dp.len() - 1;
        while !dp[k] {
            k -= 1;
        }
        return if x[l] + k >= dp.len() {0} else {1};
    }
    let save = dp.clone();
    let m = (l + r) / 2;
    for i in l..m {
        trans (&mut dp, x[i]);
    }
    let front = calc (x, m, r, &mut dp);
    dp.clone_from (&save);
    for i in m..r {
        trans (&mut dp, x[i]);
    }
    front + calc (x, l, m, &mut dp)
}

fn run() {
    input! {
        n: usize,
        k: usize,
        a: [usize; n],
    }
    let mut dp = vec![false; k];
    dp[0] = true;
    let ans = calc (&a, 0, n, &mut dp);
    println! ("{}", ans);
}

fn main() {
    run();
}

