fn criterion(k: usize, i: usize, a: &Vec<usize>) -> bool {
    if i == 0 {
        return true;
    }
    if i == a.len() + 1 {
        return false;
    }
    let mut dp = vec![false; k];
    dp[0] = true;
    for j in 0..a.len() {
        if i - 1 == j {
            continue;
        }
        for ki in (0..k).rev() {
            if ki >= a[j] && dp[ki - a[j]] {
                dp[ki] = true;
            }
            if dp[ki] && ki >= k - a[i - 1] {
                return false;
            }
        }
    }
    // println!("{:?}", (i, dp));
    true
}

